window.QBANK={"2":[{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_1-01-1","t":"1919년 3 1운동을 계기로 헌병경찰제도에서 보통경찰제도로의 전환은 이루어졌으나, 일본에서 제정된 정치범처벌법을 우리 나라에 적용하는 등 일제의 탄압적 지배체제가 강화되었다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_1-01-2","t":"미군정기에 고등경찰제도가 폐지되었으며, 경찰에 정보업무를 담당하는 정보과와 경제사범단속을 위한 경제경찰이 신설되었다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_1-01-3","t":"1953년 경찰작용의 기본법인 경찰관직무집행법이 제정되어 경감 이상의 계급정년제가 도입되었고, 1969년 경찰공무원법이 제정되어 경정 및 경장 계급이 신설되었다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_1-01-4","t":"대한민국 정부 수립 이후 1974년 내무부 치안국이 치안본부로 개편되었고, 2006년 제주특별자치도 ‘자치경찰단’이 창설되었다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"경찰 공채","qn":40,"i":"PO2022_1-40","t":"오늘날 우리나라 경찰의 변화에 관한 설명 중 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"오늘날 우리나라 경찰의 변화에 관한 설명 중 가장 적절 하지 않은 것은?","d":"","o":["수사절차 전반에 걸쳐 주관적인 시각으로 사건을 살펴보고 오류를 바로잡을 수 있도록 하기 위하여 일선 지구대 및 파출소에 ‘영장심사관’, ‘수사심사관’ 제도를 도입 운영하고 있다.","집회 시위에 대한 관점을 관리 통제에서 인권존중 소통으로 근본적으로 바꾸기 위해 스웨덴 집회 시위관리 정책을 벤치마킹한 ‘대화경찰관제’를 도입 시행하고 있다.","국경을 초월하는 국제범죄에 능동적으로 대응하고 재외국민 보호를 위해 치안시스템 전수, 외국경찰 초청연수, 치안인프라 구축사업 등을 내용으로 하는 치안한류 사업을 추진하고 있다.","2020년 12월 국가정보원법 개정에 따라 국가정보원의 국가 안보 관련 수사업무가 경찰로 이관될 예정이다."],"a":1}},{"y":2022,"e":"경찰 공채","qn":11,"i":"PO2022_2-11-1","t":"고려시대 중앙에는 형부, 병부, 어사대, 금오위 등이 경찰업무를 수행하였고, 이 중 어사대는 관리의 비리를 규탄하고 풍속교정을 담당하는 등 풍속경찰의 임무를 수행하였다.","ox":"O","m":"①","c":"A","tp":"우리나라 경찰의 역사"},{"y":2022,"e":"경찰 공채","qn":11,"i":"PO2022_2-11-2","t":"이준규 서장은 보도연맹원들에 대한 총살명령이 내려오자 480명의 예비검속자 앞에서 “내가 죽더라도 방면하겠으니 국가를 위해 충성해 달라”라는 연설 후 전원 방면하였다.","ox":"X","m":"②","c":"A","tp":"우리나라 경찰의 역사"},{"y":2022,"e":"경찰 공채","qn":11,"i":"PO2022_2-11-3","t":"정부수립 이후 1991년 이전 경찰의 특징을 살펴보면, 전투경찰 업무가 경찰의 업무 범위에 추가되었고 소방업무가 경찰의 업무 범위에서 배제되는 등 경찰활동의 영역에 변화가 있었다.","ox":"O","m":"③","c":"A","tp":"우리나라 경찰의 역사"},{"y":2022,"e":"경찰 공채","qn":11,"i":"PO2022_2-11-4","t":"구 경찰법이 국가경찰과 자치경찰의 조직 및 운영에 관한 법률로 개정됨에 따라 자치경찰사무를 관장하게 하기 위하여 특별시장 광역시장 특별자치시장 도지사 특별자치도지사 소속으로 시 도자치경찰위원회를 두었다.","ox":"O","m":"④","c":"A","tp":"우리나라 경찰의 역사"},{"y":2023,"e":"경찰 공채","qn":13,"i":"PO2023_1-13","t":"다음은 자랑스러운 경찰의 표상에 관한 서술이다. 해당 인물을 바르게 나열한 것은?","c":"A","mc":{"s":"다음은 자랑스러운 경찰의 표상에 관한 서술이다. 해당 인물을 바르게 나열한 것은?","d":"㉠ 성산포경찰서장 재직 시 계엄군의 예비검속자 총살 명령에 ‘부당함으로 불이행’한다고 거부하고 주민들을 방면함 ㉡ 5･ 18 광주 민주화운동 당시 무장 강경진압 방침이 내려오자 ‘분산되는 자는 너무 추적하지 말 것, 부상자가 발생하지 않도록 할 것’ 등을 지시하여 비례의 원칙에 입각한 경찰권 행사 및 인권보호를 강조함 ㉢ 임시정부 경무국 경호원 및 의경대원으로 활동하였고 1926년 12월 식민수탈의 심장인 식산은행과 동양척식회사에 폭탄을 투척함 ㉣ 구례경찰서장 재임 당시, 재판을 받지 않고 수감된 보도 연맹원 480명을 방면하였으며, ‘내가 만일 반역으로 몰려 죽는다면 나의 혼이 여러분 각자의 가슴에 들어가 지킬 것이니 새 사람이 되어주십시오’라고 당부함 ㉠ ㉡ ㉢ ㉣","o":["문형순 안병하 차일혁 안종삼","이준규 최규식 안맥결 나석주","문형순 안병하 나석주 안종삼","이준규 최규식 정종수 나석주"],"a":3}},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_1-14-1","t":"영국의 국립범죄청(NCA)은 2013년 중대조직범죄청(SOCA)과 아동범죄대응센터(CEOPC)를 통합하여 출범하였다.","ox":"O","m":"①","c":"A","tp":"각 국의 수사기관"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_1-14-2","t":"미국의 연방수사국(FBI)은 2001년 9.11 테러 이후 테러예방과 수사에 많은 역량을 집중시키고 있다.","ox":"O","m":"②","c":"A","tp":"각 국의 수사기관"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_1-14-3","t":"독일의 연방범죄수사청(BKA)은 연방헌법기관 요인들에 대한 신변경호도 담당한다.","ox":"O","m":"③","c":"A","tp":"각 국의 수사기관"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_1-14-4","t":"한국의 국가수사본부는 고위공직자범죄등에 관한 수사를 독립적으로 수행하기 위하여 법무부장관 소속으로 설치되었다.","ox":"X","m":"④","c":"A","tp":"각 국의 수사기관"},{"y":2023,"e":"경찰 공채","qn":13,"i":"PO2023_2-13","t":"한국경찰의 역사적 사실을 과거에서부터 현재 순으로 바르게 나열한 것은?","c":"A","mc":{"s":"한국경찰의 역사적 사실을 과거에서부터 현재 순으로 바르게 나열한 것은?","d":"㉠ 경찰청 사이버테러대응센터 신설 ㉡ 경찰서비스헌장 제정 ㉢ 국가수사본부 신설 ㉣ ｢경찰법｣ 제정 ㉤ 제주특별자치도 자치경찰단 설치","o":["㉣-㉡-㉠-㉤-㉢","㉡-㉣-㉤-㉠-㉢","㉡-㉣-㉠-㉢-㉤","㉣-㉠-㉡-㉤-㉢"],"a":1}},{"y":2024,"e":"경찰 공채","qn":13,"i":"PO2024_1-13-1","t":"경찰이 담당하였던 위생사무 등 행정경찰사무가 경찰관할에서 분리되는 비경찰화 작업이 진행되었다.","ox":"O","m":"①","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":13,"i":"PO2024_1-13-2","t":"일제강점기 치안입법이 정리된 시기로 1945년 「보안법」 이 폐지 되었고, 1948년 「예비검속법」 이 순차적으로 폐지되었다.","ox":"X","m":"②","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":13,"i":"PO2024_1-13-3","t":"1946년 여자경찰제도가 신설되었다.","ox":"O","m":"③","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":13,"i":"PO2024_1-13-4","t":"1947년 6인의 위원으로 구성된 중앙경찰위원회를 설치하였다.","ox":"O","m":"④","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_1-14-1","t":"11세기경 프랑스의 앙리 1세는 파리의 치안을 유지하기 위해 법원과 경찰기능을 가진 프레보(Prévôt)를 창설하였다.","ox":"O","m":"①","c":"A","tp":"외국경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_1-14-2","t":"독일경찰은 1949년 「기본법」 의 제정으로 대부분의 주(州)에서 주(州)단위 국가경찰제도를 채택하였다.","ox":"O","m":"②","c":"A","tp":"외국경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_1-14-3","t":"영국의 지방경찰은 2011년 「경찰개혁 및 사회책임법」 제정을 통해 기존의 3원 체제(지방경찰청장, 지방경찰위원회, 내무부장관)에서 4원 체제(지역치안위원장, 지역치안평의회, 지방경찰청장, 내무부장관)로 변화하면서 자치경찰의 성격이 약화되었다.","ox":"X","m":"③","c":"A","tp":"외국경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_1-14-4","t":"미국의 20세기 초 경찰개혁을 이끈 대표적 인물로 1인 순찰제의 효과성을 연구한 윌슨(O. W. Wilson)과 대학에 경찰 관련 교육과정을 개설한 어거스트 볼머(August Vollmer)가 있다.","ox":"O","m":"④","c":"A","tp":"외국경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_2-14-1","t":"예비검속법, 치안유지법 등이 폐지되는 등 법적 정비가 이루어졌다.","ox":"O","m":"①","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_2-14-2","t":"1945년 ‘법무국 검사에 관한 훈령 제3호’가 발령되어 ‘수사는 경찰, 기소는 검사’ 체제가 도입되어 경찰의 독자적 수사권이 인정되었다.","ox":"O","m":"②","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_2-14-3","t":"1946년 경무국을 경무부로 승격시키고, 기존 경무국의 과(課)를 국(局)으로 승격시켰다.","ox":"O","m":"③","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":14,"i":"PO2024_2-14-4","t":"‘태평양미군총사령부포고 제1호’를 통해 미군정을 실시하였으며, 일제강점기 시대의 경찰 인력을 현직에서 청산함으로써 경찰의 인적 구성원을 대거 쇄신하였다.","ox":"X","m":"④","c":"A","tp":"미군정시기 경찰"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_2-15-1","t":"일본의 사법경찰(직원)은 1차적 수사기관으로 인정받고 있어, 수사를 개시·진행·종결까지 독자적으로 한 이후 검사에게 송치 하는 것이 원칙이다.","ox":"X","m":"①","c":"A","tp":"외국경찰제도"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_2-15-2","t":"프랑스에서는 수사의 주체가 수사판사 또는 검사이고, 국립경찰 소속 사법경찰뿐만 아니라 사법경찰활동을 하는 군경찰도 수사 판사 또는 검사의 수사지휘를 받아야 한다.","ox":"O","m":"②","c":"A","tp":"외국경찰제도"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_2-15-3","t":"독일에서는 주별로 법률이 독자적으로 제정·운영되고 있어 주 경찰 중심으로 일반적 경찰권을 행사하나, 수사권에 있어서는 통일적 업무수행을 위해 연방(범죄)수사청이 주 소속 수사경찰을 지휘·감독한다.","ox":"X","m":"③","c":"A","tp":"외국경찰제도"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_2-15-4","t":"미국경찰에는 기본적으로 지방경찰, 주 경찰, 연방경찰이 존재 하며, 이 중 광범위한 경찰권을 행사하여 법집행의 범위가 가장 넓은 것은 주경찰이다.","ox":"X","m":"④","c":"A","tp":"외국경찰제도"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_1-02-1","t":"블랑코 판결은 공무원에 의해 발생한 손해는 국가에 배상책임이 있다고 인정하며 행정개입청구권을 최초로 인정하였다.","ox":"X","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_1-02-2","t":"미란다 판결은 변호인선임권, 진술거부권 등을 피의자에게 고지하지 않은 상태에서 이루어진 자백의 경우에 임의성과 관계없이 증거 능력을 부정하였다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_1-02-3","t":"에스코베도 판결은 피고인 에스코베도와 변호인과의 접견교통권을 침해하여 획득한 자백의 증거능력을 부정하였다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_1-02-4","t":"크로이츠베르크 판결은 경찰관청이 일반수권 규정에 근거하여 법규명령을 발할 수 있는 분야는 위험방지 분야에 한정된다고 판시하였다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_1-39-1","t":"차일혁: 구례 화엄사 등 문화재를 수호한 인물로 ‘보관문화훈장’을 수여 받음","ox":"O","m":"①","c":"A","tp":"자랑스러운 경찰의 표상에 관하여 인물과 내용"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_1-39-2","t":"김학재: 1998년 강도강간 신고출동 현장에서 피의자로부터 좌측 흉부를 칼로 피습당한 상태에서도 격투를 벌여 범인검거 후 순직하였으며, 2018년 ‘경찰영웅’으로 선정됨","ox":"O","m":"②","c":"A","tp":"자랑스러운 경찰의 표상에 관하여 인물과 내용"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_1-39-3","t":"안종삼: 예비검속 된 보도연맹원들에 대한 총살명령에 대해 ‘내가 죽더라도 방면하겠으니 국가를 위해 충성해 달라’고 말한 후 전원 방면함","ox":"O","m":"③","c":"A","tp":"자랑스러운 경찰의 표상에 관하여 인물과 내용"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_1-39-4","t":"최중락: 1968년 무장공비 침투사건 당시 자하문검문소에서 무장 공비를 온몸으로 막아내고 청와대를 사수하였으며, 호국 경찰의 표상이 됨","ox":"X","m":"④","c":"A","tp":"자랑스러운 경찰의 표상에 관하여 인물과 내용"},{"y":2025,"e":"경찰 공채","qn":40,"i":"PO2025_1-40","t":"대한민국 경찰의 법제도 연혁에 관한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"대한민국 경찰의 법제도 연혁에 관한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["자치경찰제의 도입, 다양한 치안서비스 제공, 국민부담 경감 등을 위하여 2020년에 ｢경찰법｣ 을 ｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 로 법제명을 변경하는 등 전부개정하였다.","｢경찰법｣ 은 내무부 치안국을 경찰청으로 개편하기 위하여 1991년에 제정하였다.","｢경찰공무원법｣ 은 경찰직무의 특수성에 비추어 경찰질서의 확립과 경찰인사의 합리화를 위하여 기존 ｢국가공무원법｣ 에 포함되어 있는 경찰인사에 관한 규정을 분리하여 별도로 독립된 법으로 1969년에 제정하였다.","｢경찰관 직무집행법｣ 은 경찰관이 국민에 대한 생명·신체·재산의 보호, 범죄의 예방, 공안의 유지, 기타 법령집행등의 직무를 충실히 수행하도록 필요한 사항을 정하기 위하여 1953년에 제정하였다."],"a":2}},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_2-13-1","t":"영국에서는 로버트 필경(Sir Robert Peel)의 제안으로 1829년 수도경찰청(Metropolitan Police Service)이 설립되었다.","ox":"O","m":"①","c":"A","tp":"외국경찰제도"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_2-13-2","t":"독일에서는 제2차 세계대전 이후 연합국에 의하여 협의의 행정 경찰사무를 경찰로부터 분리하는 비(탈)경찰화가 추진되었다.","ox":"O","m":"②","c":"A","tp":"외국경찰제도"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_2-13-3","t":"일본에서는 1차적 수사기관인 경찰과 2차적 수사기관인 검사가 대등적·협력적 관계를 이루고 있다.","ox":"X","m":"③","c":"A","tp":"외국경찰제도"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_2-13-4","t":"미국에서는 중앙집권적인 경찰제도를 운영하고 있으며, 경찰 조직은 일반적으로 연방, 주, 시‧ 군 수준에 설치되어 있다.","ox":"O","m":"④","c":"A","tp":"외국경찰제도"},{"y":2025,"e":"경찰 공채","qn":14,"i":"PO2025_2-14","t":"다음은 1991년 제정된 ｢경찰법｣ 의 의의 및 평가이다. 이와 관련된 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"다음은 1991년 제정된 ｢경찰법｣ 의 의의 및 평가이다. 이와 관련된 설명으로 가장 적절하지 않은 것은?","d":"∙경찰민주화 및 정치적 중립성 확보에 대한 국민적 열망을 반영하여 제정되었으며, 이를 통하여 정부수립 이후 최초로 독립적인 경찰기구가 만들어졌다.\n∙기존보다 경찰의 독립성 및 경찰에 대한 민주적 통제가 강화 되었으며 지방행정과의 연계를 위한 여건이 조성되었으나 경찰이 선거부처로부터 완전히 독립하지는 못하였다는 평가를 동시에 받는다.","o":["경찰의 정치적 중립성 및 독립성 확보를 위하여 경찰청을 내무부의 외청으로 설치하였다.","분단국가로서 특수한 안보상황을 고려하여 보안경찰 업무는 국가안전기획부로 이양하였다.","경찰에 대한 민주적 통제를 위하여 경찰위원회 제도를 도입하였다.","치안행정과 지방행정 간의 협조를 위하여 치안행정협의회를 설치하였다."],"a":4}},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_1-12-1","t":"갑오개혁 이후 한국 최초의 경찰조직법은 「경무청관제직장」 이다.","ox":"O","m":"①","c":"A","tp":"한국경찰의 역사"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_1-12-2","t":"1919년 3‧ 1운동으로 태어난 대한민국임시정부는 우리 민족 최초의 민주공화제를 선포하였다. 따라서 임시정부의 경찰은 우리 역사상 최초의 민주공화제 경찰로서 민주경찰의 효시라는 제도사적 의의를 가진다.","ox":"O","m":"②","c":"A","tp":"한국경찰의 역사"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_1-12-3","t":"백범 김구 선생은 대한민국 임시정부의 초대 경무국장으로 취임 하였다.","ox":"O","m":"③","c":"A","tp":"한국경찰의 역사"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_1-12-4","t":"1991년에 치안국이 경찰청으로 승격되었다.","ox":"X","m":"④","c":"A","tp":"한국경찰의 역사"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_1-13-1","t":"영국의 헨리 필딩(Henry Fielding)은 ‘보우가의 주자(Bow Street Runner)’를 창설하였다.","ox":"O","m":"①","c":"A","tp":"외국경찰"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_1-13-2","t":"미국의 연방범죄수사국(Federal Bureau of Investigation)은 재무부 소속이다.","ox":"X","m":"②","c":"A","tp":"외국경찰"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_1-13-3","t":"프랑스의 국립경찰청(Police Nationale)은 내무부 소속이다.","ox":"O","m":"③","c":"A","tp":"외국경찰"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_1-13-4","t":"일본의 경찰청은 국가경찰이다.","ox":"O","m":"④","c":"A","tp":"외국경찰"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_2-13-1","t":"비경찰화 작업의 일환으로 경찰의 활동 영역이 축소되었다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_2-13-2","t":"경찰서를 1급(총경배치), 2급(경감배치)으로 분류하여 운영하던 등급제를 폐지하였다.","ox":"X","m":"②","c":"A"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_2-13-3","t":"경찰검이 경찰봉으로 대체되었다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"경찰 공채","qn":13,"i":"PO2026_2-13-4","t":"「정치범처벌법」 ‧ 「치안유지법」 ‧ 「예비검속법」 은 1945년, 「보안법」 은 1948년에 폐지되었다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"경찰 공채","qn":14,"i":"PO2026_2-14","t":"광복 이후 한국경찰의 연혁을 미군정, 치안국, 치안본부, 경찰청 시대로 분류할 때, 치안국 시대의 내용에 관한 것은 모두 몇 개인가?","c":"A","mc":{"s":"광복 이후 한국경찰의 연혁을 미군정, 치안국, 치안본부, 경찰청 시대로 분류할 때, 치안국 시대의 내용에 관한 것은 모두 몇 개인가?","d":"㉠ 최초의 여성경찰관 채용 ㉡ ｢경찰관 직무집행법｣ 제정 ㉢ 경찰관 해외주재관 제도의 신설 ㉣ 경찰윤리헌장 선포 ㉤ 소방업무가 민방위본부로 이관 ㉥ ｢청원경찰법｣ 제정 ㉦ ｢전투경찰대 설치법｣ 제정","o":["3개","4개","5개","6개"],"a":3}}],"1":[{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_1-02-1","t":"국회법상 경위(警衛)나 경찰공무원은 국회 안에 현행범인이 있을 때에는 체포한 후 국회의장의 지시를 받아야 한다. 다만, 회의장 안에서는 국회의장의 명령 없이 국회의원을 체포할 수 없다.","ox":"O","m":"①","c":"A","tp":"경찰의 관할"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_1-02-2","t":"법원조직법상 재판장은 법정에서의 질서유지를 위하여 필요 하다고 인정할 때에는 개정 전후에 상관없이 관할 경찰서장에게 경찰공무원의 파견을 요구할 수 있으며, 이에 따라 파견된 경찰 공무원은 법정 내외의 질서유지에 관하여 재판장의 지휘를 받는다.","ox":"O","m":"②","c":"A","tp":"경찰의 관할"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_1-02-3","t":"헌법상 대통령은 내란 또는 외환의 죄를 범한 경우를 제외하고는 재직중 형사상의 소추를 받지 아니한다.","ox":"O","m":"③","c":"A","tp":"경찰의 관할"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_1-02-4","t":"‘사물관할’이란 경찰권이 발동될 수 있는 지역적 범위를 말하고, 대한민국의 영역 내 모든 범위에 적용되는 것이 원칙이다.","ox":"X","m":"④","c":"A","tp":"경찰의 관할"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_1-03-1","t":"요한 쉬테판 퓌터(Johann Stephan Pütter)가 자신의 저서인 『독일공법제도』에서 주장한 “경찰의 직무는 임박한 위험을 방지하는 것이다. 복리증진은 경찰의 본래 직무가 아니다.”라는 내용은 경찰국가 시대를 거치면서 확장된 경찰의 개념을 제한하기 위한 노력의 일환으로 볼 수 있다.","ox":"O","m":"①","c":"A","tp":"실질적 의미의 경찰개념의 역사적 발전과정"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_1-03-2","t":"크로이츠베르크 판결(1882)은 승전기념비의 전망을 확보할 목적으로 주변 건축물의 고도를 제한하기 위해 베를린 경찰청장이 제정한 법규명령은 독일의 제국경찰법상 개별적 수권조항에 위반되어 무효라고 하였다.","ox":"X","m":"②","c":"A","tp":"실질적 의미의 경찰개념의 역사적 발전과정"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_1-03-3","t":"독일의 경우, 15세기부터 17세기에 이르기까지 경찰은 공동체의 질서정연한 상태 또는 공동체의 질서정연한 상태를 창설하고 유지하기 위한 활동으로 이해되었고, 이러한 공동체의 질서정연한 상태를 창설 유지하기 위하여 신민(臣民)의 거의 모든 생활영역이 포괄적으로 규제될 수 있었다.","ox":"O","m":"③","c":"A","tp":"실질적 의미의 경찰개념의 역사적 발전과정"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_1-03-4","t":"1931년 제정된 프로이센 경찰행정법 제14조 제1항은 “경찰 행정청은 현행법의 범위 내에서 공공의 안녕 또는 공공의 질서를 위협하는 위험으로부터 공중이나 개인을 보호하기 위하여 필요한 조치를 의무에 적합한 재량에 따라 취하여야 한다.”라고 규정하여 크로이츠베르크 판결(1882)에 의해 발전된 실질적 의미의 경찰 개념을 성문화시켰다.","ox":"O","m":"④","c":"A","tp":"실질적 의미의 경찰개념의 역사적 발전과정"},{"y":2022,"e":"경찰 공채","qn":4,"i":"PO2022_1-04","t":"경찰의 임무를 공공의 안녕과 공공의 질서에 대한 위험의 방지라고 정의할 때, 위험에 관한 설명 중 가장 적절하지 않은 것은?","c":"A","mc":{"s":"경찰의 임무를 공공의 안녕과 공공의 질서에 대한 위험의 방지라고 정의할 때, 위험에 관한 설명 중 가장 적절하지 않은 것은?","d":"","o":["구체적 위험은 개별사례에서 실제로 또는 최소한 경찰관의 사전적 시점에서 사실관계를 합리적으로 평가하였을 때, 가까운 장래에 공공의 안녕이나 공공의 질서에 대한 손해가 발생할 충분한 개연성이 있는 상황과 관련이 있다.","오상위험에 근거한 경찰의 위험방지조치가 위법한 경우에는 경찰관 개인에게는 민 형사상 책임이 문제되고 국가에게는 손해배상책임이 발생할 수 있다.","외관적 위험은 경찰관이 의무에 합당한 사려 깊은 상황판단을 하였음에도 위험을 잘못 긍정하는 경우이다.","위험의 혐의만 존재하는 경우에 위험의 존재가 명백해지기 전까지는 예비적 조치로서 위험의 존재 여부를 조사할 권한은 없다."],"a":4}},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_2-01-1","t":"경찰의 개념에 대한 정의는 시대 및 역사 그리고 각국의 전통과 사상을 배경으로 발달하기 때문에 일률적으로 정의를 내리기 어렵다.","ox":"O","m":"①","c":"A","tp":"경찰개념"},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_2-01-2","t":"1648년 독일은 베스트팔렌 조약을 계기로 사법이 국가의 특별 작용으로 인정되면서 경찰과 사법이 분리되었다.","ox":"O","m":"②","c":"A","tp":"경찰개념"},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_2-01-3","t":"독일은 제2차 세계대전 이후 보안경찰 이외의 행정경찰사무, 즉 영업경찰, 건축경찰, 보건경찰 등의 경찰사무를 다른 행정 관청의 분장사무로 이관하는 비경찰화 과정을 거쳤다.","ox":"O","m":"③","c":"A","tp":"경찰개념"},{"y":2022,"e":"경찰 공채","qn":1,"i":"PO2022_2-01-4","t":"독일 프로이센 고등행정법원의 크로이쯔베르크 판결을 계기로 경찰의 권한은 소극적 위험방지 분야로 한정하게 되었으며, 비로소 이 취지의 규정을 둔 경죄처벌법전 (죄와형벌법전)이 제정되었다.","ox":"X","m":"④","c":"A","tp":"경찰개념"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_1-01-1","t":"경찰이란 용어는 라틴어의 Politia에서 유래한 것으로 도시국가에 관한 일체의 정치, 특히 헌법을 지칭하였다.","ox":"O","m":"①","c":"A","tp":"대륙법계 경찰개념"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_1-01-2","t":"경찰국가시대는 국가작용의 분화현상이 나타나 경찰개념이 외교·군사·재정·사법을 제외한 내무행정 전반에 국한되었다.","ox":"O","m":"②","c":"A","tp":"대륙법계 경찰개념"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_1-01-3","t":"크로이쯔베르크(Kreuzberg) 판결에 의하면 경찰관청이 일반수권 규정에 근거하여 법규명령을 발할 수 있는 분야는 소극적 위험방지 분야에 한정된다.","ox":"O","m":"③","c":"A","tp":"대륙법계 경찰개념"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_1-01-4","t":"경찰은 시민으로부터 자치권한을 위임받은 조직체로서 시민을 위한 기능과 역할에 초점을 맞추어 형성되었다.","ox":"X","m":"④","c":"A","tp":"대륙법계 경찰개념"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_1-02-1","t":"형식적 의미의 경찰은 실정법상 개념으로 보통경찰기관에 분배되어 있는 임무를 달성하기 위하여 행하여지는 일체의 경찰작용이다.","ox":"O","m":"①","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_1-02-2","t":"형식적 의미의 경찰은 모두 실질적 의미의 경찰에 포함된다.","ox":"X","m":"②","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_1-02-3","t":"실질적 의미의 경찰은 독일의 행정법학에서 정립된 학문상 개념이다.","ox":"O","m":"③","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_1-02-4","t":"실질적 의미의 경찰은 사회공공의 안녕, 질서유지와 같은 소극적 목적을 위한 작용이다.","ox":"O","m":"④","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2023,"e":"경찰 공채","qn":3,"i":"PO2023_1-03","t":"경찰의 종류와 구별기준의 연결이 가장 적절하지 않은 것은?","c":"A","mc":{"s":"경찰의 종류와 구별기준의 연결이 가장 적절하지 않은 것은?","d":"","o":["질서경찰 - 봉사경찰 : 경찰의 목적에 따른 분류","예방경찰 - 진압경찰 : 경찰권 발동시점에 따른 분류","국가경찰 - 자치경찰 : 권한과 책임의 소재에 따른 분류","평시경찰 - 비상경찰 : 위해정도 및 담당기관, 적용법규에 따른 분류"],"a":1}},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_1-04-1","t":"자치경찰은 지역사회 특성을 반영한 치안활동이 가능하며 주민들의 지지를 받기 쉽다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_1-04-2","t":"국가경찰은 강력하고 광범위한 집행력을 행사할 수 있다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_1-04-3","t":"자치경찰은 지방세력의 간섭으로 인하여 정실주의에 대한 우려가 있다.","ox":"O","m":"③","c":"A","tp":"국가경찰과 자치경찰"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_1-04-4","t":"국가경찰은 전국단위의 통계자료 수집 및 정확성 측면에서 불리하다.","ox":"X","m":"④","c":"A","tp":"국가경찰과 자치경찰"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_1-05-1","t":"원만한 공동체 생활을 위한 불가결적 전제조건으로서 공공사회에서 각 개인의 행동에 대한 불문규범의 총체이다.","ox":"O","m":"①","c":"A","tp":"공공질서"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_1-05-2","t":"공공질서의 개념은 절대적인 것이 아니라, 시대에 따라 변화하는 상대적이고 유동적인 개념이다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_1-05-3","t":"공공질서 개념의 적용 가능분야는 점차 확대되고 있다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_1-05-4","t":"통치권 집행을 위한 개입근거로 활용될 수 있는 공공질서 개념은 엄격한 합헌성이 요구되고, 제한적인 사용이 필요하다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":6,"i":"PO2023_1-06-1","t":"사물관할이란 경찰이 처리할 수 있고 또 처리해야 하는 사무 내용의 범위를 말한다.","ox":"O","m":"①","c":"A","tp":"경찰의 관할"},{"y":2023,"e":"경찰 공채","qn":6,"i":"PO2023_1-06-2","t":"인적관할이란 광의의 경찰권이 어떤 사람에게 적용되는가의 문제이다.","ox":"O","m":"②","c":"A","tp":"경찰의 관할"},{"y":2023,"e":"경찰 공채","qn":6,"i":"PO2023_1-06-3","t":"우리나라는 대륙법계의 영향으로 범죄수사를 경찰의 사물관할로 인정하고 있다.","ox":"X","m":"③","c":"A","tp":"경찰의 관할"},{"y":2023,"e":"경찰 공채","qn":6,"i":"PO2023_1-06-4","t":"헌법상 대통령은 내란 또는 외환의 죄를 범한 경우를 제외하고는 재직 중 형사상의 소추를 받지 아니한다.","ox":"O","m":"④","c":"A","tp":"경찰의 관할"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_2-01-1","t":"경찰개념은 역사적으로 발전되고 형성된 개념이므로, 근대국가 에서의 일반적인 경찰개념을 ‘공공의 안녕과 질서유지를 위한 권력작용’이라고 할 경우, 이는 각국의 실정법상 경찰개념과 반드시 일치한다고는 할 수 없다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_2-01-2","t":"실질적 의미의 경찰을 보안경찰과 협의의 행정경찰로 구분하는 것이 일반적 견해라고 할 때, 보안경찰은 독립적인 경찰기관이 관할하지만, 협의의 행정경찰은 각종의 일반행정기관이 함께 그것을 관장하는 경우가 많다.","ox":"O","m":"②","c":"A","tp":"경찰개념"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_2-01-3","t":"18∼19세기에 등장한 법치국가는 절대주의적 경찰국가에 대항하는 의미에서 자유주의적 법치국가의 성격을 띠었고, 이와 같은 법치국가적 경찰개념이 처음으로 법제화된 경우로는 1794년의 ‘프로이센 일반란트법’을 들 수 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":1,"i":"PO2023_2-01-4","t":"경찰의 개념을 형식적 의미의 경찰과 실질적 의미의 경찰로 구분할 때, 사법경찰(수사경찰)은 실질적 의미의 경찰에 포함된다.","ox":"X","m":"④","c":"A","tp":"경찰개념"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_2-02-1","t":"경찰개입의 대상이 되는 위험은 행위책임에 기인한 것일 수도 있고 상태책임에 기인한 것일 수도 있다.","ox":"O","m":"①","c":"A","tp":"경찰의 위험방지 임무에서 말하는 ‘위험’"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_2-02-2","t":"외관상 위험이 존재할 때의 경찰개입이 적법하더라도, 원칙적으로 국가의 손해배상책임을 발생시킨다.","ox":"X","m":"②","c":"A","tp":"경찰의 위험방지 임무에서 말하는 ‘위험’"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_2-02-3","t":"경찰의 범죄예방 및 위험방지 행위의 준비는 추상적 위험이 존재하는 경우에도 가능하다.","ox":"O","m":"③","c":"A","tp":"경찰의 위험방지 임무에서 말하는 ‘위험’"},{"y":2023,"e":"경찰 공채","qn":2,"i":"PO2023_2-02-4","t":"위험혐의의 존재는 위험조사차원의 경찰개입을 정당화시킨다.","ox":"O","m":"④","c":"A","tp":"경찰의 위험방지 임무에서 말하는 ‘위험’"},{"y":2024,"e":"경찰 공채","qn":1,"i":"PO2024_1-01-1","t":"영미법계 경찰개념은 ‘시민으로부터 부여받은 자치권에 근거하여 국민의 생명·신체·재산을 보호하고 범죄를 수사하며, 다양한 공공서비스를 제공하는 작용’이라고 설명된다.","ox":"O","m":"①","c":"A","tp":"영미법계 국가의 경찰"},{"y":2024,"e":"경찰 공채","qn":1,"i":"PO2024_1-01-2","t":"영미법계 경찰개념은 국왕의 절대적 권력으로부터 유래된 경찰권을 전제로 한다.","ox":"X","m":"②","c":"A","tp":"영미법계 국가의 경찰"},{"y":2024,"e":"경찰 공채","qn":1,"i":"PO2024_1-01-3","t":"영미법계 경찰개념은 경찰과 국민을 수평적·상호협력 동반자 관계로 본다.","ox":"O","m":"③","c":"A","tp":"영미법계 국가의 경찰"},{"y":2024,"e":"경찰 공채","qn":1,"i":"PO2024_1-01-4","t":"영미법계 경찰은 비권력적 수단을 중시한다.","ox":"O","m":"④","c":"A","tp":"영미법계 국가의 경찰"},{"y":2024,"e":"경찰 공채","qn":2,"i":"PO2024_1-02","t":"다음의 ㉠, ㉡에 들어갈 내용으로 가장 적절한 것은?","c":"A","mc":{"s":"다음의 ㉠, ㉡에 들어갈 내용으로 가장 적절한 것은?","d":"(㉠)과 (㉡)의 구별은 프랑스에서 유래한 것으로, 경찰에 의하여 보호되는 법익을 기준으로 한다. 원래 (㉠)은 사회적으로 보다 우월한 가치를 지닌 법익을 보호하기 위한 경찰활동을 의미하였으나, 나중에는 사상･ 종교･ 집회･ 결사･ 언론의 자유에 대한 정보수집･ 단속과 같은 국가의 존립과 유지를 보장하기 위하여 국가적 기관 및 제도에 대한 위해를 방지하는 활동을 의미하게 되었다. 이에 비해 (㉡)은 교통의 안전, 풍속의 유지, 범죄의 예방･ 진압과 같이 일반 사회의 안녕과 질서유지를 목적으로 하는 활동을 의미한다.","o":["㉠ 행정경찰 ㉡ 사법경찰","㉠ 진압경찰 ㉡ 예방경찰","㉠ 비상경찰 ㉡ 평시경찰","㉠ 고등경찰 ㉡ 보통경찰"],"a":4}},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_1-03-1","t":"경찰활동의 전 부분을 포괄하는 용어로 가장 바람직한 모델이다.","ox":"X","m":"①","c":"A","tp":"바람직한 경찰의 역할모델 중 ‘범죄와 싸우는 경찰모델’"},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_1-03-2","t":"경찰역할을 뚜렷이 인식시켜 ‘전문직화’에 기여한다.","ox":"O","m":"②","c":"A","tp":"바람직한 경찰의 역할모델 중 ‘범죄와 싸우는 경찰모델’"},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_1-03-3","t":"수사, 형사 등 법 집행을 통한 범법자 제압 측면을 강조한 모델로서 시민들은 범인을 제압하는 것이 경찰의 주된 임무라고 인식한다.","ox":"O","m":"③","c":"A","tp":"바람직한 경찰의 역할모델 중 ‘범죄와 싸우는 경찰모델’"},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_1-03-4","t":"범법자는 적이고, 경찰은 정의의 사자라는 흑백논리에 따른 이분법적 오류에 빠질 경우 인권침해 등의 우려가 있다.","ox":"O","m":"④","c":"A","tp":"바람직한 경찰의 역할모델 중 ‘범죄와 싸우는 경찰모델’"},{"y":2024,"e":"경찰 공채","qn":1,"i":"PO2024_2-01","t":"다음에서 설명하는 경찰의 분류에 관한 내용과 가장 관계가 깊은 것은?","c":"A","mc":{"s":"다음에서 설명하는 경찰의 분류에 관한 내용과 가장 관계가 깊은 것은?","d":"보통경찰기관이 사회공공의 안녕과 질서를 유지하기 위하여 강제력을 수단으로 즉시강제, ｢경범죄 처벌법｣ 또는 ｢도로교통법｣ 위반자에 대한 통고처분 등 법집행을 행하는 경찰활동","o":["고등경찰","예방경찰","질서경찰","협의의 행정경찰"],"a":3}},{"y":2024,"e":"경찰 공채","qn":2,"i":"PO2024_2-02-1","t":"실질적 의미의 경찰은 조직보다는 작용 중심으로 경찰개념을 파악하는 것으로, 일반행정기관이 공공의 안녕과 질서 유지를 위해 일반통치권에 근거하여 국민에게 명령·강제하는 권력적 작용은 실질적 의미의 경찰로 보아야 한다.","ox":"O","m":"①","c":"A","tp":"실질적 의미의 경찰과 형식적 의미의 경찰개념"},{"y":2024,"e":"경찰 공채","qn":2,"i":"PO2024_2-02-2","t":"형식적 의미의 경찰개념에 따른 경찰활동의 범위는 국가마다 상이하고, 한 국가 내에서도 시간 변화에 따라 달라질 수 있다.","ox":"O","m":"②","c":"A","tp":"실질적 의미의 경찰과 형식적 의미의 경찰개념"},{"y":2024,"e":"경찰 공채","qn":2,"i":"PO2024_2-02-3","t":"업무의 독자성 여부로 구분되는 협의의 행정경찰은 실질적 의미의 경찰에 해당하고, 형식적 의미의 경찰에는 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"실질적 의미의 경찰과 형식적 의미의 경찰개념"},{"y":2024,"e":"경찰 공채","qn":2,"i":"PO2024_2-02-4","t":"보통경찰기관의 범죄 예방, 정보 수집·작성·배포 활동은 실질적 의미의 경찰뿐만 아니라 형식적 의미의 경찰에도 해당하지 않는다.","ox":"X","m":"④","c":"A","tp":"실질적 의미의 경찰과 형식적 의미의 경찰개념"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_2-04-1","t":"경찰은 각종 위험의 제거를 그 주요 기능으로 하고 있고, 그 수단으로서 명령·강제 등 경찰권을 발동할 수 있으며 필요한 경우 실력행사를 위하여 무기와 장구를 휴대하는데 이러한 특성을 위험성이라 한다.","ox":"O","m":"①","c":"A","tp":"경찰행정의 특수성"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_2-04-2","t":"경찰조직은 예측하기 어려운 다양한 사안에 대해 고도의 민첩성을 갖추고 타 부서 혹은 직원들과의 유기적인 공조체제를 갖추어 돌발적으로 발생하는 범죄사건과 사고에 즉시 대응하여 합리적인 방법으로해결할수있도록해야하는데이러한특성을조직성이라한다.","ox":"X","m":"②","c":"A","tp":"경찰행정의 특수성"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_2-04-3","t":"경찰 업무는 대부분 즉시 해결하지 못하면 그 피해의 회복이 영원히 불가능하거나 현저하게 어려운 경우가 많은 바, 돌발적으로 발생하는 경찰행정 수요에 즉시 대응하기 위해 기동장비 확보, 초동대처시간 단축을 위해 훈련을 해야 하는데 이러한 특성을 기동성이라 한다.","ox":"O","m":"③","c":"A","tp":"경찰행정의 특수성"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_2-04-4","t":"경찰은 본질적으로 사회공공의 안녕과 질서를 유지하기 위하여 국민에게 명령·강제하는 권력작용의 특성을 보이는데 이러한 특성을 권력성이라 한다.","ox":"O","m":"④","c":"A","tp":"경찰행정의 특수성"},{"y":2024,"e":"경찰 공채","qn":5,"i":"PO2024_2-05","t":"｢경찰관 직무집행법｣ 에 실정법상 경찰의 직무가 규정되어 있다. 이러한 직무의 범위는 사회환경 또는 범죄양상의 변화 등으로 인해서 확장될 수 있다. 다음 중 ｢경찰관 직무집행법｣ 제2조에 명시적으로 규정된 직무 중에서 가장 최근에 신설된 것은 무엇인가?","c":"A","mc":{"s":"｢경찰관 직무집행법｣ 에 실정법상 경찰의 직무가 규정되어 있다. 이러한 직무의 범위는 사회환경 또는 범죄양상의 변화 등으로 인해서 확장될 수 있다. 다음 중 ｢경찰관 직무집행법｣ 제2조에 명시적으로 규정된 직무 중에서 가장 최근에 신설된 것은 무엇인가?","d":"","o":["경비, 주요인사 경호 및 대간첩･ 대테러 작전 수행","외국 정부기관 및 국제기구와의 국제협력","교통 단속과 교통 위해의 방지","범죄피해자 보호"],"a":4}},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_2-06-1","t":"사물관할이란 경찰이 처리할 수 있고 처리해야 하는 사무내용의 범위를 말하는 것으로 「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 과 「경찰관 직무집행법」 에 규정되어 있다.","ox":"O","m":"①","c":"A","tp":"경찰의 관할"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_2-06-2","t":"재판장은 법정에서의 질서유지를 위하여 필요하다고 인정할 때에는 개정 전에 한하여 관할 경찰서장에게 경찰공무원의 파견을 요구할 수 있다.","ox":"X","m":"②","c":"A","tp":"경찰의 관할"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_2-06-3","t":"국회의원은 현행범인인 경우를 제외하고는 회기 중 국회의 동의 없이 체포 또는 구금되지 아니한다. 그리고 국회의원이 회기 전에 체포 또는 구금된 때에는 현행범인이 아닌 한 국회의 요구가 있으면 회기 중 석방된다.","ox":"O","m":"③","c":"A","tp":"경찰의 관할"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_2-06-4","t":"지역관할과 인적관할은 광의의 경찰권이 발동될 수 있는 지역적 범위와 인적 범위를 말하고, 광의의 경찰권은 협의의 경찰권, 수사권, 비권력적 활동 권한을 포함하는 개념이다.","ox":"O","m":"④","c":"A","tp":"경찰의 관할"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_1-01-1","t":"자치경찰은 국가경찰과 비교하여 조직 운영상의 개혁이 용이한 편이다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_1-01-2","t":"국가경찰은 자치경찰과 비교하여 지방세력의 간섭으로 정실에 빠질 우려가 있다.","ox":"X","m":"②","c":"A","tp":"국가경찰과 자치경찰"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_1-01-3","t":"국가경찰은 자치경찰과 비교하여 다른 행정부문과의 긴밀한 협조·조정이 어렵다.","ox":"X","m":"③","c":"A","tp":"국가경찰과 자치경찰"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_1-01-4","t":"국가경찰은 자치경찰과 비교하여 신속한 업무수행으로 인해 인권과 민주성이 보장되어 주민들의 지지를 받기 쉽다.","ox":"X","m":"④","c":"A","tp":"국가경찰과 자치경찰"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_1-04-1","t":"국회의장은 필요할 때에는 경위나 경찰공무원으로 하여금 방청인의 신체를 검사하게 할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰의 관할"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_1-04-2","t":"국회의 경호업무는 국회의장의 지휘를 받아 수행하되, 경위는 회의장 건물 밖에서, 경찰공무원은 회의장 건물 안에서 경호한다.","ox":"X","m":"②","c":"A","tp":"경찰의 관할"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_1-04-3","t":"국회의장은 국회의 경호를 위하여 필요할 때에는 국회사무처의 동의를 받아 일정한 기간을 정하여 경찰공무원의 파견을 요구 할 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰의 관할"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_1-04-4","t":"재판장은 법정에서의 질서유지를 위하여 필요하다고 인정할 때에는 개정 전후에 상관없이 시‧ 도경찰청장에게 경찰공무원의 파견을 요구할 수 있다.","ox":"X","m":"④","c":"A","tp":"경찰의 관할"},{"y":2025,"e":"경찰 공채","qn":6,"i":"PO2025_1-06","t":"다음 사례에 해당하는 ‘위험의 인식’에 관한 설명으로 가장 적절한 것은?","c":"A","mc":{"s":"다음 사례에 해당하는 ‘위험의 인식’에 관한 설명으로 가장 적절한 것은?","d":"전날 악몽을 꾼 경찰관 A는 경찰관 B와 순찰 중에 주택에서 은은한 클래식 음악이 들리자 위험한 상황이라고 판단하고, 자신을 제지하는 경찰관 B를 밀친 후 혼자 현관문을 부수고 들어갔는데 실제로는 임신부가 태교음악을 듣고 있었다.","o":["경찰관 A의 경우 의무에 합당한 사려 깊은 판단을 하였고 실제로 위험의 발생 가능성은 있으나, 현관문을 부수고 진입한 행위는 위험의 존재 여부를 확인하기 위한 예비적 조치로는 적합하지 않다.","경찰에게 있어 위험의 개념은 사실에 기인하여 향후 발생할 사건에 관한 주관적 추정을 포함하므로, 경찰관 B는 ‘외관적 위험’이 발생하였음에도 개입하지 않아 합리적인 상황 판단을 하지 못한 경우이다.","경찰관 A의 행위는 위험의 외관이나 혐의가 정당화되지 아니 함에도 불구하고 잘못된 주관적 판단에 따라 위험의 존재를 잘못 추정한 위법한 경찰개입이므로, 경찰관 A에게는 민‧ 형사상 책임이 발생할 수 있으며 국가 역시 국가배상책임이 발생될 수 있다.","해당 사례는 결과적으로 위험이 존재하지 않았고 경찰개입 시점에도 경찰상 위험이 없다고 판단되므로, 부순 현관문에 대해서는 원칙적으로 국가는 손실보상책임이 있다."],"a":3}},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_2-01-1","t":"예방경찰과 진압경찰은 경찰권 발동 시점에 따라 구분한 것이다.","ox":"O","m":"①","c":"A","tp":"경찰의 분류"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_2-01-2","t":"행정 경찰과 사법 경찰은 경찰 활동의 목적 및 임무에 따라·구분한 것이다.","ox":"O","m":"②","c":"A","tp":"경찰의 분류"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_2-01-3","t":"보안경찰과 협의의 행정경찰은 행정경찰을 업무의 독자성에 따라 구분한 것이다.","ox":"O","m":"③","c":"A","tp":"경찰의 분류"},{"y":2025,"e":"경찰 공채","qn":1,"i":"PO2025_2-01-4","t":"질서경찰과 봉사경찰은 실질적 의미의 경찰을 경찰활동의 질과 내용에 따라 구분한 것이다.","ox":"X","m":"④","c":"A","tp":"경찰의 분류"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_2-02-1","t":"실질적 의미의 경찰은 조직중심적인 개념이고, 형식적 의미의 경찰은 작용중심적인 개념이다.","ox":"X","m":"①","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_2-02-2","t":"「국회법」 에 따라 국회 회의장 건물 안에서 의장의 지휘를 받아 경호업무를 수행하는 경위(警衛)는 실질적 의미의 경찰에 해당한다.","ox":"X","m":"②","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_2-02-3","t":"「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 에 따른 정보경찰의 활동은 형식적 의미의 경찰에 해당한다.","ox":"O","m":"③","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2025,"e":"경찰 공채","qn":2,"i":"PO2025_2-02-4","t":"「형사소송법」 에 따라 범죄를 수사하는 사법경찰의 활동은 실질적 의미의 경찰에 해당한다.","ox":"X","m":"④","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2025,"e":"경찰 공채","qn":3,"i":"PO2025_2-03","t":"영미법계와 대륙법계 경찰개념에 관한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"영미법계와 대륙법계 경찰개념에 관한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["우리나라의 경찰개념은 대륙법계와 영미법계의 경찰개념을 모두 반영하고 있다.","1953년 12월에 제정된 ｢경찰관 직무집행법｣ 제1조는 ‘국민의 생명‧ 신체 및 재산의 보호’를 경찰의 직무로 규정하여 치안유지를 중심으로 하는 대륙법계의 행정경찰적 개념이 강조되었다.","우리나라는 영미법계 경찰개념의 영향으로 범죄수사를 경찰의 사물관할로 인정하고 있다.","대륙법계에서는 영미법계와 비교하여 경찰통제를 위한 방법으로 행정소송이나 국가배상 등의 사법적 통제가 주로 발달하였다."],"a":2}},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_2-04-1","t":"공공의 안녕은 국민의 생명‧ 신체 및 재산보호를 포함하는 상위 개념이다.","ox":"O","m":"①","c":"A","tp":"경찰의 임무를 ‘공공의 안녕과 공공의 질서"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_2-04-2","t":"공공의 안녕의 요소 중 법질서의 불가침성은 사법(私法)규범을 제외한 공법(公法)규범을 대상으로 한다.","ox":"X","m":"②","c":"A","tp":"경찰의 임무를 ‘공공의 안녕과 공공의 질서"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_2-04-3","t":"공공의 질서란 시대에 따라 변화하는 상대적이고 유동적인 개념이다.","ox":"O","m":"③","c":"A","tp":"경찰의 임무를 ‘공공의 안녕과 공공의 질서"},{"y":2025,"e":"경찰 공채","qn":4,"i":"PO2025_2-04-4","t":"공공의 질서란 당시의 지배적인 윤리와 가치관을 기준으로 판단할 때 그것을 준수하는 것이 시민으로서 원만한 공동체 생활을 위한 필수적인 전제조건이 되고, 공공사회에서 개인의 행동에 대한 불문규범의 총체가 되는 것을 의미한다.","ox":"O","m":"④","c":"A","tp":"경찰의 임무를 ‘공공의 안녕과 공공의 질서"},{"y":2025,"e":"경찰 공채","qn":6,"i":"PO2025_2-06","t":"국가경찰제도와 비교하여 자치경찰제도가 가지는 특징에 관한 설명이다. 옳은 것으로 묶인 것은?","c":"A","mc":{"s":"국가경찰제도와 비교하여 자치경찰제도가 가지는 특징에 관한 설명이다. 옳은 것으로 묶인 것은?","d":"㉠ 조직의 관료화로 인해 국민에 대한 봉사의식이 저하될 수 있다. ㉡ 지역주민의 경찰활동 참여를 활성화 할 수 있다. ㉢ 능률성보다 민주성이 확보된다. ㉣ 전국적으로 균등한 치안서비스를 제공할 수 있다.","o":["㉠㉡","㉠㉣","㉡㉢","㉢㉣"],"a":3}},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_1-01-1","t":"1953년 국민의 생명‧ 신체 및 재산보호라는 대륙법계의 사고가 최초로 반영된 「경찰관 직무집행법」 이 제정되었다.","ox":"X","m":"①","c":"A","tp":"경찰의 개념과 분류"},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_1-01-2","t":"국가경찰과 자치경찰은 경찰의 조직권, 인사권, 비용부담권에 따라 구분한 것으로, 국가경찰은 광역 범죄에 효과적으로 대응하기 어렵고 경찰기관 간의 협조가 어렵다는 단점을 가지고 있다.","ox":"X","m":"②","c":"A","tp":"경찰의 개념과 분류"},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_1-01-3","t":"실질적 의미의 경찰개념은 경찰작용의 성질에 따른 것으로서 학문적으로 정립된 개념인 반면, 형식적 의미의 경찰개념은 실정법상 개념으로 보통경찰기관에 분배되어 있는 임무를 위한 경찰작용을 의미한다.","ox":"O","m":"③","c":"A","tp":"경찰의 개념과 분류"},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_1-01-4","t":"블랑코(Blanco) 판결은 경찰관청이 일반수권규정에 근거하여 법규명령을 발할 수 있는 분야가 소극적 위험방지에 한정되도록 확정되는 계기를 마련하였다.","ox":"X","m":"④","c":"A","tp":"경찰의 개념과 분류"},{"y":2026,"e":"경찰 공채","qn":2,"i":"PO2026_1-02","t":"경찰의 기본적 임무를 ‘공공의 안녕과 질서에 대한 위험 방지’라고 정의할 때, 이에 관한 설명으로 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰의 기본적 임무를 ‘공공의 안녕과 질서에 대한 위험 방지’라고 정의할 때, 이에 관한 설명으로 옳지 않은 것은 모두 몇 개인가?","d":"㉠ 경찰이 의무에 합당한 사려 깊은 판단을 하여 개입하였으나 실제로는 위험이 없는 경우를 위험 혐의라고 하며, 이때 경찰의 개입은 적법하더라도 특별한 희생이 있는 경우 국가에게 손실보상의 의무를 발생시키게 된다. ㉡ 국민의 생명‧ 신체 및 재산보호는 공공의 안녕을 포함하는 상위 개념이다. ㉢ 공공의 질서는 지배적인 사회‧ 윤리관에 비추어 그것을 준수 하는 것이 원만한 공동생활을 위한 전제조건으로 간주되는 성문규범의 총체를 의미하며, 이 개념의 사용 분야는 오늘날 점차 확대되고 있다. ㉣ 위험은 보호를 받게 되는 법익에 대해 필수적으로 존재해야 하는 것은 아니나, 경찰관의 개입은 구체적 위험이 존재할 때만 가능하다. ㉤ 오상위험에 대한 경찰의 개입은 위법하나, 국가에게는 손해 배상의 책임이 발생하지 않는다.","o":["2개","3개","4개","5개"],"a":4}},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_2-01-1","t":"실질적 의미의 경찰 개념과 형식적 의미의 경찰 개념은 상호 배타적인 개념이다.","ox":"X","m":"①","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_2-01-2","t":"「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 에 따른 자치경찰의 교통법규 위반에 대한 지도‧ 단속 활동은 형식적 의미의 경찰 개념에 해당한다.","ox":"O","m":"②","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_2-01-3","t":"사법경찰은 직접적인 목적이 사회공공의 안녕과 질서유지라는 점에서 실질적 의미의 경찰에 해당한다.","ox":"X","m":"③","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2026,"e":"경찰 공채","qn":1,"i":"PO2026_2-01-4","t":"실질적 의미의 경찰 개념은 공공복리의 증진과 같은 소극적 목적을 위한 작용을 의미한다.","ox":"X","m":"④","c":"A","tp":"형식적 의미의 경찰과 실질적 의미의 경찰"},{"y":2026,"e":"경찰 공채","qn":2,"i":"PO2026_2-02","t":"다음에서 설명하는 경찰의 분류에 관한 내용과 가장 관계가 깊은 것은?","c":"A","mc":{"s":"다음에서 설명하는 경찰의 분류에 관한 내용과 가장 관계가 깊은 것은?","d":"다른 행정작용과 결합하여 특별한 사회적 이익의 보호를 목적으로 하면서 사회공공의 안녕과 질서를 유지하기 위하여 위해를 예방하고 제거하는 경찰작용으로 위생경찰, 산림경찰, 보건경찰 등이 이에 해당한다.","o":["협의의 행정경찰","예방경찰","질서경찰","고등경찰"],"a":1}},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_2-04-1","t":"「국회법」 상 경위나 경찰공무원은 국회 안에 현행범인이 있을 때에는 체포한 후 의장의 지시를 받아야 한다. 다만, 회의장 안에서는 의장의 명령 없이 의원을 체포할 수 없다.","ox":"O","m":"①","c":"A","tp":"경찰의 관할"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_2-04-2","t":"「법원조직법」 상 재판장은 법정에서의 질서유지를 위하여 필요 하다고 인정할 때에는 개정 전후에 상관없이 관할 경찰서장에게 경찰공무원의 파견을 요구할 수 있다. 파견된 경찰공무원은 법정 내외의 질서유지에 관하여 재판장의 지휘를 받는다.","ox":"O","m":"②","c":"A","tp":"경찰의 관할"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_2-04-3","t":"경찰의 사물관할은 「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 뿐만 아니라 「경찰관 직무집행법」 에도 규정되어 있다.","ox":"O","m":"③","c":"A","tp":"경찰의 관할"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_2-04-4","t":"우리나라는 대륙법계 경찰 개념의 영향으로 범죄수사에 관한 임무가 경찰의 사물관할로서 인정되어 있다.","ox":"X","m":"④","c":"A","tp":"경찰의 관할"}],"3":[{"y":2022,"e":"경찰 공채","qn":5,"i":"PO2022_1-05-1","t":"‘Dirty Harry 문제’는 도덕적으로 선한 목적을 위해 윤리적, 정치적, 혹은 법적으로 더러운 수단을 동원하는 것이 적절한가와 관련된 딜레마적 상황이다.","ox":"O","m":"①","c":"A","tp":"경찰의 부패"},{"y":2022,"e":"경찰 공채","qn":5,"i":"PO2022_1-05-2","t":"구조화된 조직적 부패는 서로가 문제점을 알면서도 눈감아주는 침묵의 규범 형성의 가능성을 높인다.","ox":"O","m":"②","c":"A","tp":"경찰의 부패"},{"y":2022,"e":"경찰 공채","qn":5,"i":"PO2022_1-05-3","t":"셔먼(1985)의 미끄러운 경사(slippery slope) 개념은 작은 호의를 받는 것에 익숙해진 경찰관들이 결국 부패에 연루될 수 있음을 경고한다.","ox":"O","m":"③","c":"A","tp":"경찰의 부패"},{"y":2022,"e":"경찰 공채","qn":5,"i":"PO2022_1-05-4","t":"전체사회가설은 신임경찰관이 조직의 부패 전통 내에서 고참 동료들에 의해 사회화됨으로써 부패의 길로 들어선다는 입장이다.","ox":"X","m":"④","c":"A","tp":"경찰의 부패"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_1-06-1","t":"공무원은 범죄수사규칙 제30조에 따른 경찰관서 내 수사 지휘에 대한 이의제기와 관련하여 행동강령책임관에게 상담을 요청할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_1-06-2","t":"공무원이 상담, 절차 및 규정 안내, 각종 증명서 발급, 기타 이에 준하는 단순 민원업무를 수행하는 경우를 제외하고, 직무 관련자와 100만원 이상의 금전거래가 있는 경우에는 소속관서 행동강령책임관에게 해당 사실을 별지 제3호서식에 따라 서면 (전자문서를 포함)으로 신고하여야 한다.","ox":"X","m":"②","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_1-06-3","t":"공무원은 동창회 등 친목단체에 직무관련자가 있어 부득이 골프를 하는 경우에는 소속관서 행동강령책임관에게 사전에 신고하여야 하며 사전에 신고하기 어려운 특별한 사유가 있는 경우에는 사후에 즉시 신고하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_1-06-4","t":"공무원은 직무관련자나 직무관련공무원에게 경조사를 알려서는 아니 되나, 공무원 자신이 소속된 종교단체 친목단체 등의 회원에게 알리는 경우에는 경조사를 알릴 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2022,"e":"경찰 공채","qn":9,"i":"PO2022_1-09-1","t":"‘인권침해’란 경찰관등이 직무를 수행하는 과정에서 모든 사람에게 보장된 인권을 침해하는 것을 말한다.","ox":"O","m":"①","c":"A","tp":"경찰 인권보호 규칙"},{"y":2022,"e":"경찰 공채","qn":9,"i":"PO2022_1-09-2","t":"경찰 활동 전반에 걸친 민주적 통제를 구현하여 경찰력 오 남용을 예방하고, 경찰 행정의 인권지향성을 높여 인권을 존중하는 경찰 활동을 정립하기 위해 시 도경찰청장 및 경찰서의 심의 의결기구로서 각각 시 도경찰청 인권위원회, 경찰서 인권위원회를 설치하여 운영한다.","ox":"X","m":"②","c":"A","tp":"경찰 인권보호 규칙"},{"y":2022,"e":"경찰 공채","qn":9,"i":"PO2022_1-09-3","t":"경찰청장은 경찰관등이 근무하는 동안 지속적 체계적으로 교육을 받을 수 있도록 3년 단위로 인권교육종합계획을 수립하여 시행 하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰 인권보호 규칙"},{"y":2022,"e":"경찰 공채","qn":9,"i":"PO2022_1-09-4","t":"인권보호담당관은 인권침해를 예방하고 제도를 개선하기 위해 연 1회 이상 인권 관련 정책 이행 실태, 인권교육 추진 현황, 경찰청과 소속기관의 청사 및 부속 시설 전반의 인권침해적 요소의 존재 여부를 진단하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰 인권보호 규칙"},{"y":2022,"e":"경찰 공채","qn":5,"i":"PO2022_2-05","t":"다음은 경찰활동의 기본이념과 관련된 법적 근거를 제시한 것이다. 이와 관련하여","c":"A","mc":{"s":"다음은 경찰활동의 기본이념과 관련된 법적 근거를 제시한 것이다. 이와 관련하여","d":"<보기 1>과 <보기 2>의 내용이 가장 적절하게 연결된 것은? <보기 1> (가) 헌법 제1조 제2항에서는 “대한민국 주권은 국민에게 있고, 모든 권력은 국민으로부터 나온다”라고 규정하고 있다. (나) 헌법 제37조 제1항에서는 “국민의 자유와 권리는 헌법에 열거되지 아니한 이유로 경시되지 아니한다”라고 규정하고 있다. (다) 국가공무원법 제65조 제1항에서는 “공무원은 정당이나 그 밖의 정치단체의 결성에 관여하거나 이에 가입할 수 없다” 라고 규정하고 있다. <보기 2> ㉠ 인권존중주의 ㉡ 민주주의 ㉢ 법치주의 ㉣ 정치적 중립주의 (가) (나) (다)","o":["㉡ ㉣ ㉠","㉢ ㉡ ㉣","㉡ ㉠ ㉣","㉢ ㉠ ㉣"],"a":3}},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_2-06-1","t":"공직자의 이해충돌 방지법상 부동산을 직접 또는 간접으로 취급하는 대통령령으로 정한 공공기관의 공직자가 소속 공공 기관의 업무와 관련된 부동산을 보유하고 있거나 매수하는 경우 소속기관장에게 그 사실을 구두 또는 서면으로 신고하여야 한다.","ox":"X","m":"①","c":"A","tp":"공직자의 이해충돌 방지법 과 부정청탁 및 금품등 수수의 금지"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_2-06-2","t":"부정청탁 및 금품등 수수의 금지에 관한 법률상 ‘공직자등’이 부정청탁을 받았을 때에는 부정청탁을 한 자에게 부정청탁임을 알리고 이를 거절하는 의사를 명확히 표시하여야 하며, 이러한 조치를 하였음에도 불구하고 동일한 부정청탁을 다시 받은 경우에는 이를 소속기관장에게 구두 또는 서면(전자서면을 포함)으로 신고하여야 한다.","ox":"X","m":"②","c":"A","tp":"공직자의 이해충돌 방지법 과 부정청탁 및 금품등 수수의 금지"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_2-06-3","t":"부정청탁 및 금품등 수수의 금지에 관한 법률에 따르면 OO경찰서 소속 경찰관 甲이 모교에서 자신의 직무와 관련된 강의를 요청받아 1시간 동안 강의를 하고 50만 원의 사례금을 받았다면 대통령령이 정하는 바에 따라 소속기관장에게 신고하고 그 초과금액을 소속기관장에게 지체없이 반환하여야 한다.","ox":"X","m":"③","c":"A","tp":"공직자의 이해충돌 방지법 과 부정청탁 및 금품등 수수의 금지"},{"y":2022,"e":"경찰 공채","qn":6,"i":"PO2022_2-06-4","t":"부정청탁 및 금품등 수수의 금지에 관한 법률상 국가공무원법 또는 지방공무원법에 따른 공무원과 그 밖에 다른 법률에 따라 그 자격 임용 교육훈련 복무 보수 신분보장 등에 있어서 공무원으로 인정된 사람은 ‘공직자등’ 개념에 포함된다.","ox":"O","m":"④","c":"A","tp":"공직자의 이해충돌 방지법 과 부정청탁 및 금품등 수수의 금지"},{"y":2022,"e":"경찰 공채","qn":7,"i":"PO2022_2-07","t":"다음은 경찰의 부정부패 이론(가설)에 관한 설명이다. 주장한 학자와 이론이 가장 적절하게 연결된 것은?","c":"A","mc":{"s":"다음은 경찰의 부정부패 이론(가설)에 관한 설명이다. 주장한 학자와 이론이 가장 적절하게 연결된 것은?","d":"㉠ 부패의 사회화를 통하여 신임경찰이 기존의 부패한 경찰에게 물들게 된다는 것으로 부패의 원인을 개인적 결함이 아닌 조직의 체계적 원인으로 보고 있다. ㉡ 시카고 경찰의 부패 원인 중 하나로 ‘시카고 시민이 경찰을 부패시켰다’라는 주장이 거론된 것처럼 시민사회가 경찰관의 부패를 묵인하거나 용인할 때 경찰관이 부패 행위에 빠져 들게 된다.","o":["㉠ 델라트르(Delattre)-미끄러지기 쉬운 경사로 이론 ㉡ 니더호퍼(Neiderhoffer), 로벅(Roebuck), 바커(Barker)-구조원인가설","㉠ 셔먼(Sherman)-구조원인가설 ㉡ 델라트르(Delattre)-미끄러지기 쉬운 경사로 이론","㉠ 니더호퍼(Neiderhoffer), 로벅(Roebuck), 바커(Barker)-구조원인가설 ㉡ 윌슨(Wilson)-전체사회가설","㉠ 윌슨(Wilson)-전체사회가설 ㉡ 펠드버그(Feldberg)-구조원인가설 【경 찰 학】(공 통) - 13 -"],"a":3}},{"y":2022,"e":"경찰 공채","qn":8,"i":"PO2022_2-08","t":"다음 사례에서 나타나는 전문직업인으로서 경찰의 윤리적 문제점으로 가장 적절한 것은?","c":"A","mc":{"s":"다음 사례에서 나타나는 전문직업인으로서 경찰의 윤리적 문제점으로 가장 적절한 것은?","d":"OO경찰서 경비과 소속 경찰관 甲은 집회 현장에서 시위대가 질서유지선을 침범해 경찰관을 폭행하자 교통, 정보, 생활안전 등 다른 전체적인 분야에 대한 고려 없이 경비분야만 생각하고 검거 결정을 하였다.","o":["부권주의","소외","차별","사적 이익을 위한 이용"],"a":2}},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_1-07-1","t":"윌슨은 ‘시카고 시민이 경찰을 부패시켰다’고 주장하였는데, 이는 시민사회의 부패가 경찰부패의 주원인이라고 보는 입장이다.","ox":"O","m":"①","c":"A","tp":"경찰부패의 원인"},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_1-07-2","t":"구조원인가설은 신임경찰관들이 그들의 선배경찰관들에 의해 조직의 부패한 전통 내에서 사회화됨으로써 부패의 길로 들어 선다는 이론이다.","ox":"O","m":"②","c":"A","tp":"경찰부패의 원인"},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_1-07-3","t":"‘미끄러운 경사로 이론’은 사회전체가 경찰의 부패를 묵인하거나 조장할 때 경찰관은 자연스럽게 부패행위를 하게 되며, 초기 단계에는 설령 불법적인 행위를 하지 않더라도 작은 호의에 길들여져 나중에는 명백한 부정부패로 빠져들게 된다는 것이다.","ox":"O","m":"③","c":"A","tp":"경찰부패의 원인"},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_1-07-4","t":"전체사회가설은 니더호퍼, 로벅, 바커 등이 주장한 가설이다.","ox":"X","m":"④","c":"A","tp":"경찰부패의 원인"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_1-08-1","t":"공무원은 상급자가 자기 또는 타인의 부당한 이익을 위하여 공정한 직무수행을 현저하게 해치는 지시를 하였을 때에는 그 사유를 상급자에게 소명하고 지시에 따르지 아니하거나 행동강령책임관과 상담할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_1-08-2","t":"공무원은 수사·단속의 대상이 되는 업소 중 경찰청장이 지정하는 유형의 업소 관계자와 부적절한 사적 접촉을 하여서는 아니 되며, 공적 또는 사적으로 접촉한 경우 경찰청장이 정하는 방법에 따라 신고하여야 한다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_1-08-3","t":"공무원은 직무수행 중 알게 된 정보를 이용하여 유가증권, 부동산 등과 관련된 재산상 거래 또는 투자를 하거나 타인에게 그러한 정보를 제공하여 재산상 거래 또는 투자를 돕는 행위를 해서는 아니 된다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_1-08-4","t":"경찰공무원은 정당이나 정치단체에 가입하거나 정치활동에 관여하는 행위를 하여서는 아니 된다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_1-33-1","t":"“경찰관등”이란 경찰청과 그 소속기관의 경찰공무원, 일반직 공무원을 말한다(단, 무기계약근로자 및 기간제근로자, 의무경찰은 제외한다).","ox":"X","m":"①","c":"A","tp":"경찰 인권보호 규칙"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_1-33-2","t":"경찰활동 전반에 걸친 민주적 통제를 구현하여 경찰력 오·남용을 예방하고, 경찰행정의 인권지향성을 높여 인권을 존중하는 경찰활동을 정립하기 위해 경찰청장 및 시·도경찰청장의 자문 기구로서 각각 경찰청 인권위원회, 시·도경찰청 인권위원회를 설치하여 운영한다.","ox":"O","m":"②","c":"A","tp":"경찰 인권보호 규칙"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_1-33-3","t":"경찰청장은 국민의 인권보호와 증진을 위하여 경찰 인권정책 기본계획을 5년마다 수립해야 한다.","ox":"O","m":"③","c":"A","tp":"경찰 인권보호 규칙"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_1-33-4","t":"인권보호담당관은 인권침해를 예방하고 제도를 개선하기 위해 연 1회 이상 인권 관련 정책 이행 실태, 인권교육 추진 현황, 경찰청과 소속기관의 청사 및 부속 시설 전반의 인권침해적 요소의 존재 여부를 진단하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰 인권보호 규칙"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_2-04-1","t":"니더호퍼(Niederhoffer)는 사회체계에 대한 기존의 신념체제가 붕괴된 후 새로운 신념체제에 의해 급하게 대체될 때 냉소주의가 나타날 수 있다고 하였다.","ox":"X","m":"①","c":"A","tp":"경찰조직의 냉소주의"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_2-04-2","t":"조직 내 팽배한 냉소주의는 경찰의 전문직업화를 저해하는 기제로 작동할 수 있다.","ox":"O","m":"②","c":"A","tp":"경찰조직의 냉소주의"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_2-04-3","t":"회의주의와 비교할 때, 냉소주의는 조직 내 특정한 대상을 합리적 의심을 통해 신뢰하지 않는 것과 관련이 있다.","ox":"X","m":"③","c":"A","tp":"경찰조직의 냉소주의"},{"y":2023,"e":"경찰 공채","qn":4,"i":"PO2023_2-04-4","t":"냉소주의 극복을 위한 가장 효과적인 조직관리방안은 인간을 본래 게으르고 생리적 욕구 또는 안전의 욕구에 자극을 주는 금전적 보상이나 제재 등 외재적 유인에 반응한다고 상정하여 조직이 권위적으로 관리할 필요가 있다는 맥그리거(McGregor)의 인간모형에 기초한다.","ox":"X","m":"④","c":"A","tp":"경찰조직의 냉소주의"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_2-05-1","t":"작은 호의를 제공받은 경찰관이 도덕적 부채를 느껴 이를 보충하기 위해 결과적으로 선한 후속행위를 하는 상황은 미끄러운 경사 (slippery slope) 가설의 맥락에서 이해할 수 있다.","ox":"X","m":"①","c":"A","tp":"부정부패"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_2-05-2","t":"대의명분 있는 부패(noble cause corruption)와 Dirty Harry 문제는 부패의 개념적 징표를 개인적 이익 추구를 넘어 조직 혹은 사회적 차원의 이익 추구로 확대하고자 하는 시도라고 볼 수 있다.","ox":"O","m":"②","c":"A","tp":"부정부패"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_2-05-3","t":"고객이 위험을 감수하고서라도 원하는 이익을 확실히 취하기 위해 높은 가격의 뇌물을 지불하는 상황을 부패로 이해한다면, 이는 하이덴하이머(Heidenheimer)가 제시한 세 가지 유형의 부정부패 정의 중 시장중심적 정의와 가장 관련이 크다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":5,"i":"PO2023_2-05-4","t":"공직자가 직무와 관련하여 그 지위 또는 권한을 남용하거나 법령을 위반하여 자기 또는 제3자의 이익을 도모하는 행위는 「부패방지 및 국민권익위원회의 설치와 운영에 관한 법률」 상 부패행위에 해당한다.","ox":"O","m":"④","c":"A","tp":"부정부패"},{"y":2023,"e":"경찰 공채","qn":6,"i":"PO2023_2-06","t":"코헨(Cohen)과 펠드버그(Feldberg)가 사회계약설로부터 도출한 경찰활동의 기준과 그 내용의 연결이 가장 적절하지 않은 것은?","c":"A","mc":{"s":"코헨(Cohen)과 펠드버그(Feldberg)가 사회계약설로부터 도출한 경찰활동의 기준과 그 내용의 연결이 가장 적절하지 않은 것은?","d":"","o":["생명과 재산의 안전보호 - 경찰활동은 시민의 생명과 재산의 보호가 궁극적인 목적이며 법집행 자체가 목적은 아니다.","냉정하고 객관적인 자세 - 과거 아버지의 가정폭력을 경험한 甲경찰관이 가정폭력 사건을 처리하면서 모든 문제는 남편에게 있다고 단정지어 생각하는 경우는 이 기준에 어긋난다.","공공의 신뢰 - 乙경찰관이 공명심이 앞서서 상부에 보고도 없이 탈주범을 혼자서 검거하려다 실패하였다면 이 기준에 어긋난다.","공정한 접근 보장 - 경찰의 법집행 과정에서 발생하는 차별과 편들기는 이 기준에 어긋난다."],"a":3}},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_2-07-1","t":"공직자등은 직무 관련 여부 및 기부·후원·증여 등 그 명목에 관계없이 동일인으로부터 1회에 100만 원 또는 매 회계연도에 300만 원을 초과하는 금품등을 받거나 요구 또는 약속해서는 아니 된다.","ox":"O","m":"①","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_2-07-2","t":"경찰청에서 근무하는 甲총경은 A전자회사의 요청으로 시간 당 30만 원의 사례금을 약속받고 A전자회사의 직원을 대상으로 자신의 직무와 관련된 3시간짜리 강의를 월 1회, 총 3개월간 진행하였다. 이 경우 甲총경이 지급받을 수 있는 최대사례금 총액은 270만 원이다.","ox":"X","m":"②","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_2-07-3","t":"B자동차회사의 요청으로 자신의 직무와 관련된 외부강의를 마치고 소정의 사례금을 약속받은 乙경무관은 대통령령으로 정하는 바에 따라 외부강의의 요청 명세 등을 소속기관장에게 그 외부강의를 마친 날부터 10일 이내에 서면으로 신고하여야 한다.","ox":"O","m":"③","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2023,"e":"경찰 공채","qn":7,"i":"PO2023_2-07-4","t":"사단법인 C학회가 주관 및 개최한 토론회에 참석하여 자신의 직무와 관련된 토론을 한 丙경감이 상한액을 초과하는 사례금을 받은 경우 초과사례금을 받은 사실을 안 날부터 2일 이내에 동법 시행령이 정한 사항을 적은 서면으로 소속기관장에게 신고 하여야 한다.","ox":"O","m":"④","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_2-08-1","t":"당연직 위원은 경찰청은 청문감사인권담당관, 시·도경찰청은 감사관으로 한다.","ox":"X","m":"①","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시･ 도경찰청 인권위원회"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_2-08-2","t":"경찰청 인권위원회와 시·도경찰청 인권위원회 각각의 위원장과 위촉 위원의 임기는 위촉된 날로부터 2년으로 하며 위원장의 직은 연임할 수 없고, 위촉 위원은 세 차례만 연임할 수 있다.","ox":"X","m":"②","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시･ 도경찰청 인권위원회"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_2-08-3","t":"경찰청 인권위원회와 시·도경찰청 인권위원회의 정기회의는 각각 분기 1회 개최한다.","ox":"X","m":"③","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시･ 도경찰청 인권위원회"},{"y":2023,"e":"경찰 공채","qn":8,"i":"PO2023_2-08-4","t":"경찰의 직에 있거나 그 직에서 퇴직한 날부터 3년이 지나지 아니한 사람은 경찰청 인권위원회나 시·도경찰청 인권위원회의 위촉 위원이 될 수 없다. 【경 찰학】(일반공채·101경비단·경행 경채)","ox":"O","m":"④","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시･ 도경찰청 인권위원회"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_1-04-1","t":"법적 강제력이 없기 때문에 위반했을 경우 제재할 방법이 미흡하다.","ox":"O","m":"①","c":"A","tp":"경찰윤리강령"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_1-04-2","t":"민주적 참여에 의한 제정보다는 상부에서 제정되고 일방적으로 하달되어 냉소주의를 불러일으키는 단점이 있다.","ox":"O","m":"②","c":"A","tp":"경찰윤리강령"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_1-04-3","t":"우리나라의 경찰윤리강령은 경찰윤리헌장 – 새경찰신조 – 경찰헌장 – 경찰서비스헌장 순서로 제정되었다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"경찰 공채","qn":4,"i":"PO2024_1-04-4","t":"1945년 10월 21일 국립경찰의 탄생 시 이념적 지표가 된 경찰정신은 대륙법계의 영향으로 ‘봉사’와 ‘질서’를 경찰의 행동강령으로 삼았다.","ox":"X","m":"④","c":"A","tp":"경찰윤리강령"},{"y":2024,"e":"경찰 공채","qn":5,"i":"PO2024_1-05-1","t":"내부고발자는 특별한 경우를 제외하고는 공표 전 자신의 이견을 표시하기 위한 내부적 채널을 모두 사용했어야 한다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"경찰 공채","qn":5,"i":"PO2024_1-05-2","t":"내부고발자는 부적절한 행동을 하도록 지시되었다는 자신의 신념이 합리적 증거에 근거하였는지 확인해야 한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"경찰 공채","qn":5,"i":"PO2024_1-05-3","t":"적절한 도덕적 동기에 의해 내부고발이 이루어져야 하며, 성공가능성은 불문한다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"경찰 공채","qn":5,"i":"PO2024_1-05-4","t":"도덕적 위반이 얼마나 중대한가, 도덕적 위반이 얼마나 급박한가 등에 대한 세심한 고려가 있어야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_1-06-1","t":"공직자등은 부정청탁을 받았을 때에는 부정청탁을 한 자에게 부정청탁임을 알리고 이를 거절하는 의사를 명확히 표시하여야 한다. 그럼에도 불구하고 동일한 부정청탁을 다시 받은 경우에는 이를 소속기관장에게 서면(전자문서를 포함한다)으로 신고하여야 한다.","ox":"O","m":"①","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_1-06-2","t":"누구든지 동법의 위반행위가 발생하였거나 발생하고 있다는 사실을 알게 된 때에는 자신의 인적사항을 밝히지 아니하고 변호사를 선임하여 신고를 대리하게 할 수 있다.","ox":"O","m":"②","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_1-06-3","t":"공직자등은 외부기관(국가 및 지방자치단체를 포함한다)의 요청으로 사례금을 받는 외부강의등을 할 때에는 소속기관장에게 그 외부강의등을 마친 날부터 10일 이내에 서면으로 신고하여야 한다.","ox":"X","m":"③","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2024,"e":"경찰 공채","qn":6,"i":"PO2024_1-06-4","t":"공공기관의 장은 공직자등에게 부정청탁 금지 및 금품등의 수수 금지에 관한 내용을 정기적으로 교육하여야 하며, 교육의 실시를 위하여 필요하면 국민권익위원회에 지원을 요청할 수 있다.","ox":"O","m":"④","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_1-07-1","t":"이 법은 공직자의 직무수행과 관련한 사적 이익추구를 금지 함으로써 공직자의 직무수행 중 발생할 수 있는 이해충돌을 방지하여 공정한 직무수행을 보장하고 공공기관에 대한 국민의 신뢰를 확보하는 것을 목적으로 한다.","ox":"O","m":"①","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_1-07-2","t":"「초·중등교육법」, 「고등교육법」 또는 그 밖의 다른 법령에 따라 설치된 각급 국립·공립학교는 ‘공공기관’에 해당한다.","ox":"O","m":"②","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_1-07-3","t":"경무관인 세종특별자치시경찰청장은 ‘고위공직자’에 해당하지 않는다.","ox":"X","m":"③","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_1-07-4","t":"최근 2년 이내에 퇴직한 공직자로서 퇴직일 전 2년 이내에 사적 이해관계 신고 대상 직무를 수행하는 공직자와 같은 부서에서 근무하였던 사람은 사적이해관계자에 포함된다.","ox":"O","m":"④","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_2-07-1","t":"법치주의: 자치경찰제도를 도입하여 중앙정부의 경찰권을 자치 단체에 위임하고, 국가경찰위원회 및 시·도자치경찰위원회 제도, 행정정보공개제도 등을 통해 경찰에 대한 민주적 통제와 참여 장치를 마련한다.","ox":"X","m":"①","c":"A","tp":"경찰의 기본이념"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_2-07-2","t":"정치적 중립주의: 공무원은 국민 전체의 봉사자이며 국민에 대하여 책임을 진다. 경찰공무원을 비롯한 공무원의 신분과 정치적 중립성은 제도적으로 보장된다.","ox":"O","m":"②","c":"A","tp":"경찰의 기본이념"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_2-07-3","t":"민주주의: 국민의 자유와 권리를 보호하고 공공의 안녕과 질서를 유지하는 경찰의 임무수행은 국민을 위하여 행하는 것이며, 경찰권은 국민에게서 부여받은 것이다.","ox":"O","m":"③","c":"A","tp":"경찰의 기본이념"},{"y":2024,"e":"경찰 공채","qn":7,"i":"PO2024_2-07-4","t":"인권 존중주의: 경찰은 직무를 수행할 때 헌법과 법률에 따라 국민의 자유와 권리 및 모든 개인이 가지는 불가침의 기본적 인권을 보호한다.","ox":"O","m":"④","c":"A","tp":"경찰의 기본이념"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_2-08-1","t":"백색부패는 선의의 목적으로 행해지는 부패행위를 말한다.","ox":"O","m":"①","c":"A","tp":"하이덴하이머(Heidenheimer)의 경찰부패"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_2-08-2","t":"회색부패는 사회 전체에 명백하고 심각한 해를 끼치는 부패이며 흑색부패로 악화될 수 있다.","ox":"X","m":"②","c":"A","tp":"하이덴하이머(Heidenheimer)의 경찰부패"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_2-08-3","t":"업무와 관련된 대가성 있는 뇌물을 받는 경우는 흑색부패에 해당한다.","ox":"O","m":"③","c":"A","tp":"하이덴하이머(Heidenheimer)의 경찰부패"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_2-08-4","t":"관직중심적 부패는 관료들이 직무를 수행하는 과정에서 사적 이익의 추구를 위하여 권한을 악용하여 조직의 규범을 일탈하는 행위를 말한다.","ox":"O","m":"④","c":"A","tp":"하이덴하이머(Heidenheimer)의 경찰부패"},{"y":2024,"e":"경찰 공채","qn":9,"i":"PO2024_2-09","t":"다음에서 설명하는 경찰문화를 극복하기 위한 방안으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"다음에서 설명하는 경찰문화를 극복하기 위한 방안으로 가장 적절하지 않은 것은?","d":"경찰청에서 새로운 성과평가 제도를 시행하겠다고 발표하자, A순경은 ‘나랑 상관없어. 이런 건 전시행정이야’라고 비웃었다. 평소 그는 기존의 사회체계에 대한 신뢰가 없으며 개선시키겠다는 의지도 없는 사람이다.","o":["의사결정과정에 일선 경찰관들의 참여를 확대시킨다.","업무량과 성과에 대한 적절한 보상을 강조하며, 관리층이 적극적 으로 개입하고 통제하는 임무를 맡아야 한다.","상사와 부하의 신뢰를 회복하기 위해 노력한다.","상급자의 일방적 지시와 명령을 줄이고 상의하달의 의사소통 과정을 개선한다."],"a":2}},{"y":2024,"e":"경찰 공채","qn":10,"i":"PO2024_2-10","t":"｢경찰청 공무원 행동강령｣ 제17조(경조사의 통지 제한)에 따르면 공무원은 직무관련자나 직무관련공무원에게 경조사를 알려서는 아니 된다. 다음 중 그 예외로 규정하지 않은 것은?","c":"A","mc":{"s":"｢경찰청 공무원 행동강령｣ 제17조(경조사의 통지 제한)에 따르면 공무원은 직무관련자나 직무관련공무원에게 경조사를 알려서는 아니 된다. 다음 중 그 예외로 규정하지 않은 것은?","d":"","o":["친족(｢민법｣ 제767조에 따른 친족)에게 알리는 경우","현재 근무하고 있거나 과거에 근무하였던 기관의 소속 직원에게 알리는 경우","공무원 자신의 배우자가 소속된 친목단체 회원에게 알리는 경우","신문, 방송 등을 통하여 알리는 경우 【경 찰 학】(일반공채･ 101경비단･ 경찰행정 경채) - 13 -"],"a":3}},{"y":2025,"e":"경찰 공채","qn":3,"i":"PO2025_1-03-1","t":"헌법상 공무원의 신분과 정치적 중립성은 법률이 정하는 바에 의하여 보장된다.","ox":"O","m":"①","c":"A","tp":"경찰의 기본이념"},{"y":2025,"e":"경찰 공채","qn":3,"i":"PO2025_1-03-2","t":"「경찰공무원법」 은 경찰공무원이 특정 정당이나 특정인의 선거 운동을 하거나 선거 관련 대책회의에 관여하는 행위를 정치활동에 관여하는 행위로 보지 않는다.","ox":"X","m":"②","c":"A","tp":"경찰의 기본이념"},{"y":2025,"e":"경찰 공채","qn":3,"i":"PO2025_1-03-3","t":"「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 과 「경찰관 직무집행법」 은 불가침의 기본적 인권보호를 명문화하고 있다.","ox":"O","m":"③","c":"A","tp":"경찰의 기본이념"},{"y":2025,"e":"경찰 공채","qn":3,"i":"PO2025_1-03-4","t":"「경찰관 직무집행법」 상 경찰관의 직권은 그 직무 수행에 필요한 최소한도에서 행사되어야 하며 남용되어서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"경찰의 기본이념"},{"y":2025,"e":"경찰 공채","qn":12,"i":"PO2025_1-12","t":"경찰의 윤리에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰의 윤리에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 셔먼(Sherman)의 미끄러지기 쉬운 경사로 이론은 사소한 부패가 습관화되면 나중에는 커다란 부패로 이어진다는 이론이다. ㉡ 클라이니히(Kleinig)는 내부고발의 윤리적 정당화 요건에 대해 내부고발자는 특별한 경우를 제외하고는 외부에 공표한 후 자신의 이견을 표시하기 위한 내부적 채널을 모두 사용하 여야 한다고 주장하였다. ㉢ 회의주의는 불특정대상에 대하여 합리적인 근거를 바탕으로 의심하고 비판하며 개선의 의지가 있다는 점에서 냉소주의와 차이가 있다. ㉣ 사회계약설을 토대로 코헨(Cohen)과 펠드버그(Feldberg)가 제시하는 경찰활동의 기준에 따르면, 오토바이로 도주하는 절도범이 전신주를 들이받자, 이를 발견한 경찰관이 도망가지 못하도록 총을 발사해 절도범을 사망하게 한 경우는 ‘공공의 신뢰 확보’에 위배된다.","o":["0개","1개","2개","3개"],"a":2}},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_1-32-1","t":"경찰 활동 전반에 걸친 민주적 통제를 구현하여 경찰력 오‧ 남용을 예방하고, 경찰 행정의 인권지향성을 높여 인권을 존중하는 경찰 활동을 정립하기 위해 경찰청장 및 시‧ 도경찰청장의 자문기구로서 각각 경찰청 인권위원회, 시‧ 도경찰청 인권위원회를 설치하여 운영한다.","ox":"O","m":"①","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시·도경찰청 인권위원회"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_1-32-2","t":"위원회의 당연직 위원은 경찰청은 감사관, 시‧ 도경찰청은 청문감사인권담당관으로 한다.","ox":"O","m":"②","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시·도경찰청 인권위원회"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_1-32-3","t":"위원장과 위촉 위원의 임기는 위촉된 날로부터 2년으로 하며 위원장과 위촉 위원은 한 차례만 연임할 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시·도경찰청 인권위원회"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_1-32-4","t":"회의에 출석한 위원에게는 예산의 범위 안에서 수당 또는 여비를 지급할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰 인권보호 규칙 상 경찰청 및 시·도경찰청 인권위원회"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_2-05-1","t":"인권존중주의는 「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 에는 관련된 규정이 없으나, 헌법 제10조와 제37조 제1항 등을 통하여 당연히 유추된다.","ox":"X","m":"①","c":"A","tp":"경찰 기본이념"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_2-05-2","t":"「경찰공무원법」 은 경찰공무원이 정당이나 정치단체의 결성 또는 가입을 지원하거나 방해하는 행위를 정치활동에 관여하는 행위로 본다.","ox":"O","m":"②","c":"A","tp":"경찰 기본이념"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_2-05-3","t":"「행정기본법」 제1조(목적)를 통하여 경영주의를 도출할 수 있다.","ox":"O","m":"③","c":"A","tp":"경찰 기본이념"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_2-05-4","t":"「부패방지 및 국민권익위원회의 설치와 운영에 관한 법률」 상 ‘국민감사청구제도’는 경찰의 대외적 민주화 방안이다.","ox":"O","m":"④","c":"A","tp":"경찰 기본이념"},{"y":2025,"e":"경찰 공채","qn":7,"i":"PO2025_2-07","t":"다음은 경찰의 전문직업화에 관한 설명이다. 이에 해당하는 전문직업화의 문제점으로 가장 적절한 것은?","c":"A","mc":{"s":"다음은 경찰의 전문직업화에 관한 설명이다. 이에 해당하는 전문직업화의 문제점으로 가장 적절한 것은?","d":"일반적으로 전문직은 장기간의 교육을 통해 역량이 함양되며 그로 인한 비용도 발생된다. 이러한 이유로 교육적‧ 경제적으로 불리한 위치에 있는 집단은 경찰직군으로 진입하는 기회가 박탈되는 문제가 있다.","o":["권위주의","차별","부권주의","사적인 이익을 위한 이용"],"a":2}},{"y":2025,"e":"경찰 공채","qn":8,"i":"PO2025_2-08-1","t":"공무원은 상급자가 자기 또는 타인의 부당한 이익을 위하여 공정한 직무수행을 현저하게 해치는 지시를 하였을 때에는 소속 기관의 장과 상담하여야 한다.","ox":"X","m":"①","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2025,"e":"경찰 공채","qn":8,"i":"PO2025_2-08-2","t":"공무원은 자신의 직무권한을 행사하거나 지위‧ 직책 등에서 유래 되는 사실상 영향력을 행사하여 직무관련자 또는 직무관련공무원 으로부터 사적 노무를 제공받거나 요구 또는 약속해서는 아니 된다. 다만, 다른 법령 또는 사회상규에 따라 허용되는 경우에는 그러 하지 아니하다.","ox":"O","m":"②","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2025,"e":"경찰 공채","qn":8,"i":"PO2025_2-08-3","t":"공무원은 다른 공무원에게 또는 그 공무원의 배우자나 직계 존속‧ 비속에게 수수 금지 금품등을 제공하거나 그 제공의 약속 또는 의사표시를 해서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2025,"e":"경찰 공채","qn":8,"i":"PO2025_2-08-4","t":"공무원이 대가를 받고 수행하는 외부강의등은 월 3회를 초과할 수 없다. 국가나 지방자치단체에서 요청하거나 겸직 허가를 받고 수행하는 외부강의등은 그 횟수에 포함하지 아니한다. 그럼에도 불구하고 월 3회를 초과하여 대가를 받고 외부강의등을 하려는 경우에는 미리 소속 기관의 장의 승인을 받아야 한다.","ox":"O","m":"④","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_2-09-1","t":"소속기관장은 부정청탁이 있었던 사실을 알게 된 경우 부정청탁을 받은 공직자등에 대하여 직무 참여 일시중지, 직무 대리자의 지정, 전보의 조치 등을 하여야 한다.","ox":"X","m":"①","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_2-09-2","t":"공직자등은 자신의 직무와 관련된 외부강의등의 대가로서 대통령령으로 정하는 금액을 초과하는 사례금을 받은 경우에는 대통령령으로 정하는 바에 따라 소속기관장에게 신고하고, 제공자에게 그 초과금액을 지체 없이 반환하여야 한다.","ox":"O","m":"②","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_2-09-3","t":"증여를 제외한 사적 거래로 인한 채무의 이행 등 정당한 권원에 의하여 제공되는 금품등은 이 법제8조에서 규정하는 수수가 금지된 금품 등에 해당하지 않는다.","ox":"O","m":"③","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_2-09-4","t":"공직자등의 직무와 관련된 공식적인 행사에서 주최자가 참석자에게 통상적인 범위에서 일률적으로 제공하는 교통, 숙박, 음식물 등의 금품등은 이 법제8조에서 규정하는 수수가 금지된 금품 등에 해당하지 않는다.","ox":"O","m":"④","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2025,"e":"경찰 공채","qn":25,"i":"PO2025_2-25","t":"｢공직자윤리법｣ 상 등록재산의 공개대상자에 해당하지 않는 경찰공무원은?","c":"A","mc":{"s":"｢공직자윤리법｣ 상 등록재산의 공개대상자에 해당하지 않는 경찰공무원은?","d":"","o":["충청북도경찰청장 치안감 A","세종특별자치시경찰청장 경무관 B","경찰청 국제협력관 경무관 C","경찰청 기획조정관 치안감 D"],"a":3}},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_1-03-1","t":"경찰청장 및 시‧ 도경찰청장은 국민의 인권보호와 증진을 위하여 경찰 인권정책 기본계획을 5년마다 수립해야 한다.","ox":"X","m":"①","c":"A","tp":"경찰 인권보호 규칙 상 경찰 인권정책 기본계획 및 인권 교육"},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_1-03-2","t":"경찰관등에게 실시하는 인권교육에 관하여 다양한 의견을 수렴하고 대내외 협력을 강화하기 위하여 경찰청에 경찰 인권교육 협의회를 둔다.","ox":"O","m":"②","c":"A","tp":"경찰 인권보호 규칙 상 경찰 인권정책 기본계획 및 인권 교육"},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_1-03-3","t":"경찰 인권교육협의회는 협의회장을 포함한 10명 이상 20명 이하의 위원으로 구성한다.","ox":"O","m":"③","c":"A","tp":"경찰 인권보호 규칙 상 경찰 인권정책 기본계획 및 인권 교육"},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_1-03-4","t":"경찰관등은 대면 교육, 사이버 교육 등 다양한 방법을 통해 교육을 이수할 수 있고, 학습자의 능동적인 학습권을 보장하기 위해 토론식, 참여식 교육을 권장한다.","ox":"O","m":"④","c":"A","tp":"경찰 인권보호 규칙 상 경찰 인권정책 기본계획 및 인권 교육"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_1-04-1","t":"홉스(Hobbes)는 그의 저서 리바이어던(Leviathan)에서 자연상태를 ‘만인에 대한 만인의 투쟁 상태’라고 하였으며, 개인의 자연권을 국왕에게 전부 양도하는 절대군주정치를 주장하였다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_1-04-2","t":"음주단속 경찰관이 동료 경찰관을 적발하고도 동료라는 이유로 눈감아주는 경우 ‘공정한 접근 보장’에 실패한 것이다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_1-04-3","t":"탈주범이 관내에 있다는 첩보를 입수한 경찰관이 상부에 보고하지 않고 단독으로 범인을 검거하려다가 실패한 경우에는 ‘협동’에 실패한 것이다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"경찰 공채","qn":4,"i":"PO2026_1-04-4","t":"P순경이 칼을 든 강도범을 추격 중에 도망가도록 내버려두었다면 이는 ‘냉정하고 객관적인 자세’에 실패한 것이다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_1-05-1","t":"공무원은 직무수행 중 알게 된 가상자산과 관련된 정보를 이용한 재산상 거래 또는 투자 행위를 해서는 아니 된다.","ox":"O","m":"①","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_1-05-2","t":"공무원은 직무관련자와는 비용 부담 여부와 관계없이 골프를 같이 하여서는 아니 된다. 다만, 부득이한 사정에 따라 골프를 같이 하는 경우에는 소속관서장에게 사전에 신고하여야 하며 사전에 신고하기 어려운 특별한 사유가 있는 경우에는 사후에 즉시 신고하여야 한다.","ox":"X","m":"②","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_1-05-3","t":"공무원은 직무관련자와 마작, 화투, 카드 등 우연의 결과나 불확실한 승패에 의하여 금품 등 경제적 이익을 취할 목적으로 하는 사행성 오락을 같이 하여서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_1-05-4","t":"공무원은 직무관련자나 직무관련공무원에게 경조사를 알려서는 아니 된다. 다만, 신문, 방송 또는 현재 근무하고 있거나 과거에 근무하였던 기관의 소속 직원에게만 열람이 허용되는 내부 통신망 등을 통하여 알리는 경우에는 경조사를 알릴 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_1-06-1","t":"공직자등은 사례금을 받는 외부강의등을 할 때에는 대통령령으로 정하는 바에 따라 외부강의등의 요청 명세 등을 소속기관장에게 그 외부강의등을 마친 날부터 10일 이내에 서면으로 신고하여야 한다. 다만, 외부강의등을 요청한 자가 국가나 지방자치단체인 경우에는 그러하지 아니하다.","ox":"O","m":"①","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_1-06-2","t":"소속기관장은 공직자등 또는 그 배우자가 수수 금지 금품등을 받거나 그 제공의 약속 또는 의사표시를 받은 사실을 알게 된 경우 수사의 필요성이 있다고 인정하는 때에는 그 내용을 수사기관에 통보할 수 있다.","ox":"X","m":"②","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_1-06-3","t":"국민권익위원회는 이 법에 따른 부정청탁 등에 관한 유형, 판단기준 및 그 예방 조치 등에 관한 기준의 작성 및 보급 업무를 관장한다.","ox":"O","m":"③","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_1-06-4","t":"공직자등은 직무 관련 여부 및 기부‧ 후원‧ 증여 등 그 명목에 관계없이 동일인으로부터 1회에 100만 원 또는 매 회계연도에 300만 원을 초과하는 금품등을 받거나 요구 또는 약속해서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"부정청탁 및 금품등 수수의 금지"},{"y":2026,"e":"경찰 공채","qn":7,"i":"PO2026_1-07-1","t":"치안감 이상의 경찰공무원 및 특별시‧ 광역시‧ 특별자치시‧ 도‧ 특별자치도의 시‧ 도경찰청장은 ‘고위공직자’에 포함된다.","ox":"O","m":"①","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2026,"e":"경찰 공채","qn":7,"i":"PO2026_1-07-2","t":"직무수행 중 알게 된 비밀 또는 소속 공공기관의 미공개정보를 사적 이익을 위하여 이용하거나 제3자로 하여금 이용하도록 한 공직자는 3년 이하의 징역 또는 3천만 원 이하의 벌금에 처한다.","ox":"O","m":"②","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2026,"e":"경찰 공채","qn":7,"i":"PO2026_1-07-3","t":"고위공직자는 그 직위에 임용되거나 임기를 개시하기 전 3년 이내에 민간 부문에서 업무활동을 한 경우, 그 활동내역을 그 직위에 임용되거나 임기를 개시한 날부터 30일 이내에 소속부서장에게 제출하여야 한다.","ox":"X","m":"③","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2026,"e":"경찰 공채","qn":7,"i":"PO2026_1-07-4","t":"이 법의 위반행위를 한 자가 위반사실을 자진하여 신고하거나 신고자등이 신고등을 함으로 인하여 자신이 한 이 법의 위반행위가 발견된 경우에는 그 위반행위에 대한 형사처벌, 과태료 부과, 징계처분, 그 밖의 행정처분 등을 감경하거나 면제할 수 있다.","ox":"O","m":"④","c":"A","tp":"공직자의 이해충돌 방지법"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_1-11-1","t":"델라트르(Delattre)는 작은 호의일지라도 그것이 반복되면 점점 더 멈추기 어려운 부패로 이어지므로 결코 이를 무시하거나 간과 하면 안 된다고 주장하였다.","ox":"O","m":"①","c":"A","tp":"경찰 윤리"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_1-11-2","t":"니더호퍼(Niederhoffer), 로벅(Roebuck), 바커(Barker)는 시민사회의 부패가 경찰 부패의 주원인이라고 주장하였다.","ox":"X","m":"②","c":"A","tp":"경찰 윤리"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_1-11-3","t":"고객이 위험을 감수하고 원하는 이익을 받는 것을 확실히 하기 위하여 높은 가격을 지불하는 상황은 룩셈버그(Luxemburger)가 제시한 세 가지 유형의 부패 중에서 ‘시장중심적 정의’와 관련이 깊다.","ox":"X","m":"③","c":"A","tp":"경찰 윤리"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_1-11-4","t":"내부고발(Whistleblowing)은 경찰관이 동료나 상사의 부정부패에 대하여 감찰에 알리거나 외부의 언론매체에 대하여 공표하는 것을 의미하며, 성공가능성은 존클라이니히(J. Kleinig)가 주장한 내부고발의 정당화 요건에 포함되지 않는다.","ox":"X","m":"④","c":"A","tp":"경찰 윤리"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_2-05-1","t":"‘절차적 정의에 기반한 경찰활동’은 시민의 신뢰를 형성하고 경찰의 민주성을 증진하지만, 적법성과는 충돌하여 경찰활동의 정당성을 저해한다.","ox":"X","m":"①","c":"A","tp":"민주적 경찰활동"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_2-05-2","t":"민주성은 사법경찰이 피의자 등을 대면하는 과정에서 가장 요구 된다고 할 수 있는 경찰이념이다.","ox":"X","m":"②","c":"A","tp":"민주적 경찰활동"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_2-05-3","t":"경찰의 이념 중 민주성은 「국가경찰과 자치경찰의 조직 및 운영에 관한 법률」 에는 명시되어 있지 않으나, 헌법상 기본권 조항 등을 통하여 당연히 유추된다.","ox":"X","m":"③","c":"A","tp":"민주적 경찰활동"},{"y":2026,"e":"경찰 공채","qn":5,"i":"PO2026_2-05-4","t":"국가경찰위원회와 시‧ 도자치경찰위원회는 경찰에 대한 민주적 통제를 강화하는 제도로서 영미법계 경찰 개념으로부터 근거를 찾을 수 있는 경찰의 외부통제 장치이다.","ox":"O","m":"④","c":"A","tp":"민주적 경찰활동"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_2-06-1","t":"인권보호담당관은 인권침해를 예방하고 제도를 개선하기 위해 연 1회 이상 경찰청과 소속기관의 청사 및 부속 시설 전반의 인권침해적 요소의 존재 여부를 진단하여야 한다.","ox":"O","m":"①","c":"A","tp":"경찰 인권보호 규칙 상 인권영향평가 및 인권진단"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_2-06-2","t":"진단은 대상 경찰관서를 방문하여 관찰, 서류 점검, 면담, 설문 등의 방법으로 실시하되, 방문 진단이 곤란하다고 인정하는 경우에는 서면으로 할 수 있다.","ox":"O","m":"②","c":"A","tp":"경찰 인권보호 규칙 상 인권영향평가 및 인권진단"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_2-06-3","t":"경찰청, 시‧ 도경찰청 및 경찰서의 인권업무 담당 부서장은 인권 침해 가능성이 높다고 판단되는 집회 및 시위에 대한 인권영향 평가의 원활한 실시를 위하여 집회시위 현장 점검단을 설치하여 운영하여야 한다.","ox":"X","m":"③","c":"A","tp":"경찰 인권보호 규칙 상 인권영향평가 및 인권진단"},{"y":2026,"e":"경찰 공채","qn":6,"i":"PO2026_2-06-4","t":"시‧ 도경찰청의 인권업무 담당 계장은 시‧ 도경찰청 인권위원회 간사로서 반기 1회 이상 인권영향평가의 이행 여부를 점검하고, 이를 소속 위원회에 제출해야 한다.","ox":"O","m":"④","c":"A","tp":"경찰 인권보호 규칙 상 인권영향평가 및 인권진단"},{"y":2026,"e":"경찰 공채","qn":7,"i":"PO2026_2-07","t":"다음 경찰부패 대응방안들의 근거가 되는 부패원인 가설이 가장 적절하게 짝지어진 것은?","c":"A","mc":{"s":"다음 경찰부패 대응방안들의 근거가 되는 부패원인 가설이 가장 적절하게 짝지어진 것은?","d":"㉠ 경찰관에게 부적절한 청탁을 하는 시민을 강력하게 처벌한다. ㉡ 윤리의식을 갖추지 못한 지원자를 배제할 수 있도록 경찰 채용 절차를 개선한다. ㉢ 다른 경찰관의 비위를 신고하는 내부 공익신고자에 대한 보호를 강화한다.","o":["","","",""],"a":4}},{"y":2026,"e":"경찰 공채","qn":8,"i":"PO2026_2-08-1","t":"공무원은 정치인이나 정당 등으로부터 부당한 직무수행을 강요 받거나 청탁을 받은 경우에는 별지 제9호 서식 또는 전자우편 등의 방법으로 행동강령책임관에게 보고하거나 소속 기관의 장과 상담하여야 한다.","ox":"X","m":"①","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":8,"i":"PO2026_2-08-2","t":"공무원은 자신의 임용‧ 승진‧ 전보 등 인사에 부당한 영향을 미치기 위하여 타인으로 하여금 인사업무 담당자에게 청탁을 하도록 해서는 아니 된다.","ox":"O","m":"②","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":8,"i":"PO2026_2-08-3","t":"공무원은 자신의 직위를 직접 이용하여 부당한 이익을 얻거나 타인이 부당한 이익을 얻도록 해서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"경찰청 공무원 행동강령"},{"y":2026,"e":"경찰 공채","qn":8,"i":"PO2026_2-08-4","t":"공무원은 직무의 범위를 벗어나 사적 이익을 위하여 소속기관의 명칭이나 직위를 공표‧ 게시하는 등의 방법으로 이용하거나 이용 하게 하여서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"경찰청 공무원 행동강령"}],"8":[{"y":2022,"e":"경찰 공채","qn":7,"i":"PO2022_1-07","t":"언론중재 및 피해구제 등에 관한 법률 에 관한 설명 중 가장 적절하지 않은 것은?","c":"A","mc":{"s":"언론중재 및 피해구제 등에 관한 법률 에 관한 설명 중 가장 적절하지 않은 것은?","d":"","o":["‘정정보도’란 언론의 보도 내용의 전부 또는 일부가 진실하지 아니한 경우 이를 진실에 부합되게 고쳐서 보도하는 것을 말한다.","언론중재 및 피해구제 등에 관한 법률 제16조 제1항, 제2항에 따르면, 사실적 주장에 관한 언론보도등으로 인하여 피해를 입은 자는 그 보도 내용에 관한 반론보도를 언론사등에 청구 할 수 있고, 이러한 청구에는 언론사등의 고의 과실이나 위법성을 필요로 하지 아니하며, 보도 내용의 진실 여부와 상관없이 그 청구를 할 수 있다.","언론중재 및 피해구제 등에 관한 법률 제19조 제3항에 따르면, 제2항의 출석요구를 받은 신청인이 2회에 걸쳐 출석하지 아니한 경우에는 조정신청을 취하한 것으로 보며, 피신청 언론사등이 2회에 걸쳐 출석하지 아니한 경우에는 조정신청 취지에 따라 정정보도등을 이행하기로 합의한 것으로 본다.","언론중재위원회는 40명 이상 90명 이내의 중재위원으로 구성 하며, 위원장 1명과 2명 이내의 부위원장 및 2명 이내의 감사를 두는데, 위원장 부위원장 감사 및 중재위원의 임기는 각각 3년 으로 하며, 연임할 수 없다. 【경 찰 학】 - 13 -"],"a":4}},{"y":2022,"e":"경찰 공채","qn":17,"i":"PO2022_1-17-1","t":"무기 탄약고 비상벨은 상황실과 숙직실 등 초동조치 가능장소와 연결하고, 외곽에는 철조망 장치와 조명등 및 순찰함을 설치 하여야 한다.","ox":"O","m":"①","c":"A","tp":"경찰장비관리규칙 상 무기고 및 탄약고 설치"},{"y":2022,"e":"경찰 공채","qn":17,"i":"PO2022_1-17-2","t":"탄약고 내에는 전기시설을 하는 것이 원칙이나, 조명은 건전지 등으로 하고 방화시설을 완비하여야 한다.","ox":"X","m":"②","c":"A","tp":"경찰장비관리규칙 상 무기고 및 탄약고 설치"},{"y":2022,"e":"경찰 공채","qn":17,"i":"PO2022_1-17-3","t":"무기고와 탄약고의 환기통 등에는 손이 들어가지 않도록 쇠창살 시설을 하고, 출입문은 2중으로 하여 각 1개소 이상씩 자물쇠를 설치하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰장비관리규칙 상 무기고 및 탄약고 설치"},{"y":2022,"e":"경찰 공채","qn":17,"i":"PO2022_1-17-4","t":"탄약고는 무기고와 분리되어야 하며 가능한 본 청사와 격리된 독립 건물로 하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰장비관리규칙 상 무기고 및 탄약고 설치"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_1-18-1","t":"각 중앙관서의 장은 제29조의 규정에 따른 예산안편성지침에 따라 그 소관에 속하는 당해 연도의 세입세출예산 계속비 명시 이월비 및 국고채무부담행위 요구서를 작성하여 매년 3월 31일까지 기획예산처장관에게 제출하여야 한다.","ox":"X","m":"①","c":"A","tp":"국가재정법 상 예산 편성 및 집행","t0":"각 중앙관서의 장은 제29조의 규정에 따른 예산안편성지침에 따라 그 소관에 속하는 당해 연도의 세입세출예산 계속비 명시 이월비 및 국고채무부담행위 요구서를 작성하여 매년 3월 31일까지 기획재정부장관에게 제출하여야 한다.","ox0":"X","rv":"개정 반영"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_1-18-2","t":"각 중앙관서의 장은 매년 1월 31일까지 해당 회계연도부터 5회계 연도 이상의 기간 동안의 신규사업 및 기획예산처장관이 정하는 주요 계속사업에 대한 중기사업계획서를 기획예산처장관에게 제출하여야 한다.","ox":"O","m":"②","c":"A","tp":"국가재정법 상 예산 편성 및 집행","t0":"각 중앙관서의 장은 매년 1월 31일까지 해당 회계연도부터 5회계 연도 이상의 기간 동안의 신규사업 및 기획재정부장관이 정하는 주요 계속사업에 대한 중기사업계획서를 기획재정부장관에게 제출하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_1-18-3","t":"기획예산처장관은 각 중앙관서의 장에게 예산을 배정한 때에는 감사원에 통지하여야 한다.","ox":"O","m":"③","c":"A","tp":"국가재정법 상 예산 편성 및 집행","t0":"기획재정부장관은 각 중앙관서의 장에게 예산을 배정한 때에는 감사원에 통지하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_1-18-4","t":"정부는 제32조의 규정에 따라 대통령의 승인을 얻은 예산안을 회계연도 개시 120일 전까지 국회에 제출하여야 한다.","ox":"O","m":"④","c":"A","tp":"국가재정법 상 예산 편성 및 집행"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_1-19-1","t":"Ⅱ급 비밀은 누설될 경우 국가안전보장에 막대한 지장을 끼칠 우려가 있는 비밀을 말한다.","ox":"O","m":"①","c":"A","tp":"보안업무규정 상 비밀"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_1-19-2","t":"비밀은 적절히 보호할 수 있는 최고등급으로 분류하되, 과도 하거나 과소하게 분류해서는 아니 된다.","ox":"X","m":"②","c":"A","tp":"보안업무규정 상 비밀"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_1-19-3","t":"비밀은 보관하고 있는 시설 밖으로 반출해서는 아니 된다. 다만, 공무상 반출이 필요할 때에는 소속 기관의 장의 승인을 받아야 한다.","ox":"O","m":"③","c":"A","tp":"보안업무규정 상 비밀"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_1-19-4","t":"비밀을 휴대하고 출장 중인 사람은 비밀을 안전하게 보호하기 위하여 국내 경찰기관 또는 재외공관에 보관을 위탁할 수 있으며, 위탁받은 기관은 그 비밀을 보관하여야 한다.","ox":"O","m":"④","c":"A","tp":"보안업무규정 상 비밀"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_1-28-1","t":"‘지시문서’란 훈령 지시 예규 일일명령 등 행정기관이 그 하급 기관이나 소속 공무원에 대하여 일정한 사항을 지시하는 문서를 말한다.","ox":"O","m":"①","c":"A","tp":"행정 효율과 협업 촉진"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_1-28-2","t":"‘공고문서’란 고시 공고 등 행정기관이 일정한 사항을 일반에게 알리는 문서를 말한다.","ox":"O","m":"②","c":"A","tp":"행정 효율과 협업 촉진"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_1-28-3","t":"‘일반문서’란 민원인이 행정기관에 허가, 인가, 그 밖의 처분 등 특정한 행위를 요구하는 문서와 그에 대한 처리문서를 말한다.","ox":"X","m":"③","c":"A","tp":"행정 효율과 협업 촉진"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_1-28-4","t":"‘법규문서’란 헌법 법률 대통령령 총리령 부령 조례 규칙 등에 관한 문서를 말한다.","ox":"O","m":"④","c":"A","tp":"행정 효율과 협업 촉진"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_2-21-1","t":"살아 있는 개인에 관한 정보로서 해당 정보만으로는 특정 개인을 알아볼 수 없더라도 다른 정보와 쉽게 결합하여 알아볼 수 있는 정보를 “개인정보”라 한다.","ox":"O","m":"①","c":"A","tp":"개인정보 보호법 상 정의 및 개념"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_2-21-2","t":"개인정보의 일부를 삭제하거나 일부 또는 전부를 대체하는 등의 방법으로 추가 정보가 없이는 특정 개인을 알아볼 수 없도록 처리하는 것을 “가명처리”라 한다.","ox":"O","m":"②","c":"A","tp":"개인정보 보호법 상 정의 및 개념"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_2-21-3","t":"정보처리 기술을 활용하여 기존의 다양한 정보를 가공해서 만들어 낸 새로운 정보에 관한 독점적 권리를 가지는 사람을 “정보주체”라 한다.","ox":"X","m":"③","c":"A","tp":"개인정보 보호법 상 정의 및 개념"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_2-21-4","t":"일정한 공간에 지속적으로 설치되어 사람 또는 사물의 영상 등을 촬영하거나 이를 유무선망을 통하여 전송하는 장치로서 네트워크 카메라와 같은 장치를 “영상정보처리기기”라 한다.","ox":"O","m":"④","c":"A","tp":"개인정보 보호법 상 정의 및 개념"},{"y":2022,"e":"경찰 공채","qn":29,"i":"PO2022_2-29","t":"동기부여이론에 관한 설명과 학자가 가장 적절하게 연결된 것은?","c":"A","mc":{"s":"동기부여이론에 관한 설명과 학자가 가장 적절하게 연결된 것은?","d":"㉠ 인간은 자신의 욕구를 충족시키기 위해서 노력하며 하위 단계의 욕구가 충족되어야 다음 단계로 발전되는 순차적 특성을 갖는다. ㉡ Y이론적 인간형은 부지런하고, 책임과 자율성 및 창의성을 발휘하기를 좋아하고, 스스로 통제와 발전이 가능하기 때문에 민주적이고 인간적인 동기유발 전략이 필요한 유형이다. ㉢ 인간의 개인적 성격과 성격의 성숙과정을 ‘미성숙에서 성숙 으로’라고 보고, 관리자는 조직 구성원을 최대의 성숙상태로 실현시켜야 한다고 하였다. ㉣ 위생요인을 제거해주는 것은 불만을 줄여주는 소극적 효과일 뿐이기 때문에, 근무태도 변화에 단기적 영향을 주어 사기는 높여줄 수 있으나 생산성을 높여주지는 못한다. 만족요인이 충족되면 자기실현욕구를 자극하여, 적극적 만족을 유발하고 동기유발에 장기적 영향을 준다.","o":["㉠ 매슬로우(Maslow) ㉡ 맥그리거(McGregor) ㉢ 아지리스(Argyris) ㉣ 허즈버그(Herzberg)","㉠ 매슬로우(Maslow) ㉡ 아지리스(Argyris) ㉢ 맥그리거(McGregor) ㉣ 허즈버그(Herzberg)","㉠ 매슬로우(Maslow) ㉡ 맥그리거(McGregor) ㉢ 허즈버그(Herzberg) ㉣ 아지리스(Argyris)","㉠ 맥그리거(McGregor) ㉡ 아지리스(Argyris) ㉢ 허즈버그(Herzberg) ㉣ 매슬로우(Maslow)"],"a":1}},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_2-30-1","t":"공무원에 대한 근무성적평정은 현대에 이르러 조직발전의 기초로 작용하는 공무원의 능력개발과 행정제도개선의 수단으로도 활용될 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰의 근무성적평정"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_2-30-2","t":"전통적 근무성적평정제도는 생산성과 능률성에 중점을 두어 공무원의 직무수행능력을 측정하고 이를 인사행정의 표준화와 직무수행의 통제를 위한 수단으로 활용하였다.","ox":"O","m":"②","c":"A","tp":"경찰의 근무성적평정"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_2-30-3","t":"근무성적평정과정에서 평정자에 의한 집중화 엄격화 등의 오류를 방지하기 위해 경찰서 수사과에서 고소 고발 등에 대한 조사업무를 직접 처리하는 경위 계급의 경찰공무원의 제2 평정요소에 따른 근무성적 평정은 수 20%, 우 40%, 양 30%, 가 10%로 분배해야 한다.","ox":"X","m":"③","c":"A","tp":"경찰의 근무성적평정"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_2-30-4","t":"총경에 대한 근무성적평정은 매년 하되, 근무실적, 직무수행능력 및 직무수행태도로만 평정한다.","ox":"O","m":"④","c":"A","tp":"경찰의 근무성적평정"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_1-30-1","t":"직위분류제는 사람 중심 분류로서 계급제보다 인사배치의 신축성 측면에서 유리하다.","ox":"X","m":"①","c":"A","tp":"계급제와 직위분류제"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_1-30-2","t":"우리나라의 공직분류는 계급제 위주에 직위분류제적 요소를 가미한 혼합 형태라고 할 수 있다.","ox":"O","m":"②","c":"A","tp":"계급제와 직위분류제"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_1-30-3","t":"직위분류제는 미국에서 실시된 후 다른 나라로 전파되었다.","ox":"O","m":"③","c":"A","tp":"계급제와 직위분류제"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_1-30-4","t":"직위분류제는 계급제에 비해서 보수결정의 합리적인 기준을 제시하는 것이 장점이다.","ox":"O","m":"④","c":"A","tp":"계급제와 직위분류제"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_1-31-1","t":"각 중앙관서의 장은 예산안편성지침에 따라 그 소관에 속하는 다음 연도의 세입세출예산·계속비·명시이월비 및 국고채무부담행위 요구서를 작성하여 매년 5월 31일까지 기획예산처장관에게 제출하여야 한다.","ox":"O","m":"①","c":"A","tp":"국가재정법 상 예산안의 편성과 집행","t0":"각 중앙관서의 장은 예산안편성지침에 따라 그 소관에 속하는 다음 연도의 세입세출예산·계속비·명시이월비 및 국고채무부담행위 요구서를 작성하여 매년 5월 31일까지 기획재정부장관에게 제출하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_1-31-2","t":"기획예산처장관은 예산요구서에 따라 예산안을 편성하여 국회 심의를 거친 후 대통령의 승인을 얻어야 한다.","ox":"X","m":"②","c":"A","tp":"국가재정법 상 예산안의 편성과 집행","t0":"기획재정부장관은 예산요구서에 따라 예산안을 편성하여 국회 심의를 거친 후 대통령의 승인을 얻어야 한다.","ox0":"X","rv":"개정 반영"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_1-31-3","t":"각 중앙관서의 장은 예산이 확정된 후 사업운영계획 및 이에 따른 세입세출예산·계속비와 국고채무부담행위를 포함한 예산 배정요구서를 기획예산처장관에게 제출하여야 한다.","ox":"O","m":"③","c":"A","tp":"국가재정법 상 예산안의 편성과 집행","t0":"각 중앙관서의 장은 예산이 확정된 후 사업운영계획 및 이에 따른 세입세출예산·계속비와 국고채무부담행위를 포함한 예산 배정요구서를 기획재정부장관에게 제출하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_1-31-4","t":"기획예산처장관은 각 중앙관서의 장에게 예산을 배정한 때에는 감사원에 통지하여야 한다.","ox":"O","m":"④","c":"A","tp":"국가재정법 상 예산안의 편성과 집행","t0":"기획재정부장관은 각 중앙관서의 장에게 예산을 배정한 때에는 감사원에 통지하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_1-32-1","t":"비밀은 그 중요성과 가치의 정도에 따라 구분되는데, 누설될 경우 대한민국과 외교관계가 단절되고 전쟁을 일으키며 국가의 방위계획·정보활동 및 국가방위에 반드시 필요한 과학과 기술의 개발을 위태롭게 하는 등의 우려가 있는 비밀은 ‘Ⅰ급비밀’ 에 속한다.","ox":"O","m":"①","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_1-32-2","t":"비밀은 해당 등급의 비밀취급 인가를 받은 사람만 취급할 수 있으며, 암호자재는 해당 등급의 비밀 소통용 암호자재취급 인가를 받은 사람만 취급할 수 있다.","ox":"O","m":"②","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_1-32-3","t":"검찰총장, 국가정보원장, 경찰청장은 Ⅰ급비밀 취급 인가권자와 Ⅰ급 및 Ⅱ급비밀 소통용 암호자재 취급 인가권자에 해당한다.","ox":"X","m":"③","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_1-32-4","t":"비밀은 적절히 보호할 수 있는 최저등급으로 분류하되, 과도 하거나 과소하게 분류해서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":25,"i":"PO2023_2-25-1","t":"살아 있는 개인에 관한 정보로서 성명, 주민등록번호 및 영상 등을 통하여 개인을 알아볼 수 있는 정보는 “개인정보”에 해당한다.","ox":"O","m":"①","c":"A","tp":"개인정보 보호법"},{"y":2023,"e":"경찰 공채","qn":25,"i":"PO2023_2-25-2","t":"“개인정보처리자”란 업무를 목적으로 개인정보파일을 운용하기 위하여 스스로 또는 다른 사람을 통하여 개인정보를 처리하는 공공기관, 법인, 단체 및 개인 등을 말한다.","ox":"O","m":"②","c":"A","tp":"개인정보 보호법"},{"y":2023,"e":"경찰 공채","qn":25,"i":"PO2023_2-25-3","t":"정보주체는 자신의 개인정보 처리와 관련하여 개인정보의 처리 정지, 정정·삭제 및 파기를 요구할 권리를 가진다.","ox":"O","m":"③","c":"A","tp":"개인정보 보호법"},{"y":2023,"e":"경찰 공채","qn":25,"i":"PO2023_2-25-4","t":"“익명처리”란 개인정보의 전부를 삭제하거나 일부를 대체하는 등의 방법으로 추가 정보가 없이는 특정 개인을 알아볼 수 없도록 처리하는 것을 말한다.","ox":"X","m":"④","c":"A","tp":"개인정보 보호법"},{"y":2023,"e":"경찰 공채","qn":29,"i":"PO2023_2-29","t":"동기부여이론 중 내용이론에 해당하는 것으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"동기부여이론 중 내용이론에 해당하는 것으로 가장 적절하지 않은 것은?","d":"","o":["매슬로우(Maslow)의 욕구단계이론","맥그리거(McGregor)의 X이론･ Y이론","포터와 롤러(Porter & Lawler)의 업적만족이론","허즈버그(Herzberg)의 욕구충족요인 이원론(동기위생이론)"],"a":3}},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_2-30-1","t":"영기준 예산제도는 전년도 예산을 기준으로 하여 점증적으로 예산액을 결정하는 데서 생기는 폐단을 시정하려고 개발한 것이다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_2-30-2","t":"품목별 예산제도는 일반 국민들이 정부사업에 대한 이해를 용이 하게 하지만 인건비 등 경직성 경비적용에 어려움이 있다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_2-30-3","t":"계획예산의 핵심은 프로그램 예산형식을 따르는 것으로서, 기획 (planning), 사업구조화(programming), 예산(budgeting)을 연계시킨 시스템적 예산제도이다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":30,"i":"PO2023_2-30-4","t":"준예산은 새로운 회계연도가 개시될 때까지 국회에서 예산안이 의결되지 못한 경우 예산안이 의결될 때까지 전년도 예산에 준하여 지출하는 예산이다.","ox":"O","m":"④","c":"A","tp":"예산제도"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_2-31-1","t":"간이무기고란 경찰인력 및 경찰기관별 무기책정기준에 따라 배정된 개인화기와 공용화기를 집중보관·관리하기 위하여 각 경찰기관에 설치된 시설을 말한다.","ox":"X","m":"①","c":"A","tp":"경찰장비관리규칙 상 무기 및 탄약관리"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_2-31-2","t":"무기·탄약을 대여 받은 자는 그 무기를 휴대하고 근무하는 경우를 제외하고는 무기고에 보관하여야 하며, 근무 종료시에는 감독자 입회아래 무기탄약 입출고부에 기재한 뒤 즉시 입고하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰장비관리규칙 상 무기 및 탄약관리"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_2-31-3","t":"경찰기관의 장은 무기를 휴대한 자가 형사사건의 조사의 대상이 된 때에는 즉시 대여한 무기·탄약을 회수하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰장비관리규칙 상 무기 및 탄약관리"},{"y":2023,"e":"경찰 공채","qn":31,"i":"PO2023_2-31-4","t":"경찰기관의 장은 무기를 휴대한 자가 상사의 사무실을 출입할 경우 대여한 무기·탄약을 무기고에 보관하도록 하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰장비관리규칙 상 무기 및 탄약관리"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_2-32-1","t":"각급기관의 장은 비밀의 작성·분류·접수·발송 및 취급 등에 필요한 모든 관리사항을 기록하기 위하여 비밀관리기록부를 작성하여 갖추어 두어야 한다. 다만, II급 이상 비밀관리기록부는 따로 작성하여 갖추어 두어야 한다.","ox":"X","m":"①","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_2-32-2","t":"각급기관의 장은 비밀문서의 접수·발송·복제·열람 및 반출 등의 통제에 필요한 규정을 따로 작성·운영할 수 있다.","ox":"O","m":"②","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_2-32-3","t":"각급기관의 장은 연 2회 비밀 소유 현황을 조사하여 국가정보원장에게 통보하여야 한다.","ox":"O","m":"③","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2023,"e":"경찰 공채","qn":32,"i":"PO2023_2-32-4","t":"중앙행정기관등의 장은 국가안전보장을 위하여 국민에게 긴급히 알려야 할 필요가 있다고 판단될 때에는 그가 생산한 비밀을 「보안업무규정」 제3조의3에 따른 보안심사위원회의 심의를 거쳐 공개할 수 있다. 다만, Ⅰ급비밀의 공개에 관하여는 국가정보원장과 미리 협의해야 한다.","ox":"O","m":"④","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_1-22-1","t":"개인정보처리자는 법령상 의무를 준수하기 위하여 불가피한 경우에는 개인정보를 수집할 수 있으며 그 수집 목적의 범위에서 이용할 수 있다.","ox":"O","m":"①","c":"A","tp":"개인정보 보호법"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_1-22-2","t":"인명의 구조·구급 등을 위하여 필요한 경우로서 대통령령으로 정하는 경우에는 불특정 다수가 이용하는 목욕실, 탈의실 등 개인의 사생활을 현저히 침해할 우려가 있는 장소의 내부를 볼 수 있는 곳에서 이동형 영상정보처리기기로 사람 또는 그 사람과 관련된 사물의 영상을 촬영할 수 있다.","ox":"O","m":"②","c":"A","tp":"개인정보 보호법"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_1-22-3","t":"개인정보처리자는 개인정보를 익명 또는 가명으로 처리하여도 개인정보 수집목적을 달성할 수 있는 경우 익명처리가 가능한 경우에는 익명에 의하여, 익명처리로 목적을 달성할 수 없는 경우에는 가명에 의하여 처리될 수 있도록 하여야 한다.","ox":"O","m":"③","c":"A","tp":"개인정보 보호법"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_1-22-4","t":"개인정보처리자는 통계작성, 과학적 연구, 공익적 기록보존 등을 위하여 가명정보를 처리하는 경우에 정보주체에게 이를 알리고 동의를 받아야 한다.","ox":"X","m":"④","c":"A","tp":"개인정보 보호법"},{"y":2024,"e":"경찰 공채","qn":30,"i":"PO2024_1-30-1","t":"경찰청장은 매년 1월 31일까지 해당 회계연도부터 5회계연도 이상의 기간 동안의 신규사업 및 경찰청장이 정하는 주요 계속사업에 대한 중기사업계획서를 기획예산처장관에게 제출 하여야 한다.","ox":"X","m":"①","c":"A","tp":"국가재정법 상 경찰예산","t0":"경찰청장은 매년 1월 31일까지 해당 회계연도부터 5회계연도 이상의 기간 동안의 신규사업 및 경찰청장이 정하는 주요 계속사업에 대한 중기사업계획서를 기획재정부장관에게 제출 하여야 한다.","ox0":"X","rv":"개정 반영"},{"y":2024,"e":"경찰 공채","qn":30,"i":"PO2024_1-30-2","t":"기획예산처장관은 국무회의의 심의를 거쳐 대통령의 승인을 얻은 다음 연도의 예산안편성지침을 매년 3월 31일까지 경찰청장에게 통보하여야 한다.","ox":"O","m":"②","c":"A","tp":"국가재정법 상 경찰예산","t0":"기획재정부장관은 국무회의의 심의를 거쳐 대통령의 승인을 얻은 다음 연도의 예산안편성지침을 매년 3월 31일까지 경찰청장에게 통보하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2024,"e":"경찰 공채","qn":30,"i":"PO2024_1-30-3","t":"감사원은 제출된 국가결산보고서를 검사하고 그 보고서를 다음 연도 5월 20일까지 재정경제부장관에게 송부하여야 한다.","ox":"O","m":"③","c":"A","tp":"국가재정법 상 경찰예산","t0":"감사원은 제출된 국가결산보고서를 검사하고 그 보고서를 다음 연도 5월 20일까지 기획재정부장관에게 송부하여야 한다.","ox0":"O","rv":"개정 반영"},{"y":2024,"e":"경찰 공채","qn":30,"i":"PO2024_1-30-4","t":"경찰청장은 예산이 확정된 후 예산배정요구서를 기획예산처장관에게 제출하여야 하고, 기획예산처장관은 제출된 예산배정 요구서에 따라 분기별 예산배정계획을 작성하여 국무회의의 심의를 거친 후 대통령의 승인을 얻어야 한다.","ox":"O","m":"④","c":"A","tp":"국가재정법 상 경찰예산","t0":"경찰청장은 예산이 확정된 후 예산배정요구서를 기획재정부장관에게 제출하여야 하고, 기획재정부장관은 제출된 예산배정 요구서에 따라 분기별 예산배정계획을 작성하여 국무회의의 심의를 거친 후 대통령의 승인을 얻어야 한다.","ox0":"O","rv":"개정 반영"},{"y":2024,"e":"경찰 공채","qn":31,"i":"PO2024_1-31","t":"｢경찰장비관리규칙｣ 상 무기관리에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"｢경찰장비관리규칙｣ 상 무기관리에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 무기고와 탄약고는 견고하게 만들고 환기･ 방습장치와 방화 시설 및 총가시설 등이 완비되어야 한다. ㉡ 간이무기고는 근무자가 24시간 상주하는 지구대, 파출소, 상황실 등 경찰기관의 장이 필요하다고 인정하는 상당한 이유가 있는 장소에 설치할 수 있다. ㉢ 집중무기･ 탄약고의 열쇠보관은 일과시간의 경우 무기 관리 부서의 장이, 일과시간 후에는 당직 업무(청사방호) 책임자 (상황관리관 등 당직근무자)가 한다. ㉣ 경찰기관의 장은 무기를 휴대한 자 중에서 ‘정신건강상 문제가 우려되어 치료가 필요한 자’가 있을 때에는 즉시 대여한 무기･ 탄약을 회수하여야 한다.","o":["1개","2개","3개","4개"],"a":3}},{"y":2024,"e":"경찰 공채","qn":32,"i":"PO2024_1-32","t":"｢보안업무규정｣ 에 따른 보호지역 중 비인가자가 비밀, 주요 시설 및 Ⅲ급 비밀 소통용 암호자재에 접근하는 것을 방지 하기 위하여 안내를 받아 출입하여야 하는 구역에 해당하는 장소는?","c":"A","mc":{"s":"｢보안업무규정｣ 에 따른 보호지역 중 비인가자가 비밀, 주요 시설 및 Ⅲ급 비밀 소통용 암호자재에 접근하는 것을 방지 하기 위하여 안내를 받아 출입하여야 하는 구역에 해당하는 장소는?","d":"","o":["작전･ 경호･ 정보･ 안보업무 담당부서 전역","무기고 및 탄약고","종합상황실","종합조회처리실"],"a":1}},{"y":2024,"e":"경찰 공채","qn":33,"i":"PO2024_1-33","t":"경찰과 대중매체 관계에 관한 내용과 인물을 바르게 연결한 것은?","c":"A","mc":{"s":"경찰과 대중매체 관계에 관한 내용과 인물을 바르게 연결한 것은?","d":"㉠ 경찰과 대중매체가 서로를 필요로 하기 때문에 둘 사이에는 공생관계가 발달한다고 주장하였다. ㉡ 경찰과 대중매체는 서로 연합하여 그 사회의 일탈에 대한 개념을 규정하며, 도덕성과 정의를 규정짓는 사회적 엘리트 집단을 구성한다. ㉢ 경찰과 대중매체의 관계를 “단란하고 행복스럽지는 않지만, 오래 지속되는 결혼생활”에 비유하였다.","o":["㉠ - G. Crandon ㉡ - R. Mark ㉢ - R. Ericson","㉠ - R. Ericson ㉡ - G. Crandon ㉢ - R. Mark","㉠ - R. Mark ㉡ - R. Ericson ㉢ - G. Crandon","㉠ - G. Crandon ㉡ - R. Ericson ㉢ - R. Mark - 16 -"],"a":4}},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_1-34-1","t":"직무분석과 직무평가의 충실한 수행을 강조하는 것은 직위분류제이다.","ox":"O","m":"①","c":"A","tp":"계급제와 직위분류제의 관계"},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_1-34-2","t":"계급제는 직업공무원제도 정착에 유리하다.","ox":"O","m":"②","c":"A","tp":"계급제와 직위분류제의 관계"},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_1-34-3","t":"양자는 양립할 수 없는 상호 배타적인 관계가 아니라 서로의 결함을 시정할 수 있는 상호 보완적인 관계이다.","ox":"O","m":"③","c":"A","tp":"계급제와 직위분류제의 관계"},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_1-34-4","t":"계급제는 ‘동일직무에 대한 동일보수의 원칙’을 확립함으로써 보수제도의 합리적 기준을 제시한다.","ox":"X","m":"④","c":"A","tp":"계급제와 직위분류제의 관계"},{"y":2024,"e":"경찰 공채","qn":29,"i":"PO2024_2-29","t":"정책결정자가 문제상황에 대해 완전한 정보를 갖고 있으며 고도의 합리성을 기반으로 최선의 대안을 결정하는 모델은 무엇인가?","c":"A","mc":{"s":"정책결정자가 문제상황에 대해 완전한 정보를 갖고 있으며 고도의 합리성을 기반으로 최선의 대안을 결정하는 모델은 무엇인가?","d":"","o":["합리 모델(Rational model)","만족 모델(Satisfying model)","엘리트 모델(Elite model)","쓰레기통 모델(Garbage can model)"],"a":1}},{"y":2024,"e":"경찰 공채","qn":31,"i":"PO2024_2-31-1","t":"개방형 충원체제로 넓은 시야를 가진 유능한 인재의 등용 및 분야별 전문인력을 확보하는 데 용이하다.","ox":"X","m":"①","c":"A","tp":"직업공무원제도"},{"y":2024,"e":"경찰 공채","qn":31,"i":"PO2024_2-31-2","t":"공무원의 일체감과 단결심 및 공직에 헌신하려는 정신을 강화 하는 데 불리한 제도이다.","ox":"X","m":"②","c":"A","tp":"직업공무원제도"},{"y":2024,"e":"경찰 공채","qn":31,"i":"PO2024_2-31-3","t":"연령제한이 필수적이나 직위분류제를 원칙으로 한다는 점에서 실적주의와 공통점이 있다.","ox":"X","m":"③","c":"A","tp":"직업공무원제도"},{"y":2024,"e":"경찰 공채","qn":31,"i":"PO2024_2-31-4","t":"공무원들의 성실한 직무수행과 장기근속을 유도하기 위한 제도와 원칙들을 토대로 한다.","ox":"O","m":"④","c":"A","tp":"직업공무원제도"},{"y":2024,"e":"경찰 공채","qn":32,"i":"PO2024_2-32-1","t":"영기준예산제도는 정부지출의 전체적인 성과파악이 곤란하고 예산운영의 신축성 부족 등이 단점으로 평가되고 있다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"경찰 공채","qn":32,"i":"PO2024_2-32-2","t":"성과주의예산제도는 정부가 무슨 일을 하느냐에 중점을 두는 제도로 관리지향성을 지닌다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"경찰 공채","qn":32,"i":"PO2024_2-32-3","t":"품목별예산제도는 정부지출 대상이 되는 물품, 품목 등을 기준으로 한 예산제도로서 예산의 남용이나 오용을 방지하는 데 도움이 된다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"경찰 공채","qn":32,"i":"PO2024_2-32-4","t":"계획예산제도는 의사결정을 일관성 있게 합리화하려는 제도 이지만 하향적(top-down)인 방식으로 집권화되어 있기 때문에 조직구성원들의 참여를 저해한다는 한계가 있다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"경찰 공채","qn":33,"i":"PO2024_2-33","t":"｢경찰장비관리규칙｣ 에 관한 설명으로 옳고 그름의 표시 (O, X)가 바르게 된 것은?","c":"A","mc":{"s":"｢경찰장비관리규칙｣ 에 관한 설명으로 옳고 그름의 표시 (O, X)가 바르게 된 것은?","d":"㉠ 경찰기관의 장은 무기를 휴대한 자 중에서 형사사건의 수사 대상이 된 자가 있을 때에는 무기 소지 적격 심의위원회 (이하 “심의위원회”라 한다)의 심의를 거쳐 대여한 무기･ 탄약을 회수할 수 있다. 다만, 심의위원회를 개최할 시간적 여유가 없거나 사고 방지 등을 위해 신속한 회수가 필요 하다고 인정되는 경우에는 대여한 무기･ 탄약을 즉시 회수할 수 있으며, 회수한 날부터 7일 이내에 심의위원회를 개최 하여 회수의 타당성을 심의하고 계속 회수 여부를 결정한다. ㉡ 심의위원회는 위원장 1명을 포함하여 총 5명 이상 7명 이내의 위원으로 구성하되 민간위원 1명 이상이 위원으로 참여하여야 한다. ㉢ 경찰기관의 장은 무기를 휴대한 자 중에서 정신건강상 문제가 우려되어 치료가 필요한 자의 경우 대여한 무기･ 탄약을 즉시 회수해야 한다. ㉣ 집중무기고란 경찰탄약을 집중 보관 및 관리하기 위해 각 경찰기관에 설치된 시설을 말한다.","o":["㉠(O) ㉡(O) ㉢(X) ㉣(X)","㉠(O) ㉡(X) ㉢(O) ㉣(X)","㉠(O) ㉡(X) ㉢(X) ㉣(O)","㉠(X) ㉡(O) ㉢(X) ㉣(O)"],"a":1}},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_2-34-1","t":"언론, 인터넷뉴스서비스 및 인터넷 멀티미디어 방송(이하 “언론등”이라 한다)은 타인의 생명, 자유, 신체, 건강, 명예, 사생활의 비밀과 자유, 초상, 성명, 음성, 대화, 저작물 및 사적 문서, 그 밖의 인격적 가치 등에 관한 권리를 침해하여서는 아니 된다.","ox":"O","m":"①","c":"A","tp":"언론중재 및 피해구제 등"},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_2-34-2","t":"반론보도청구에는 언론사, 인터넷뉴스서비스사업자 및 인터넷 멀티미디어 방송사업자(이하 “언론사등”이라 한다)의 고의·과실이나 위법성을 필요로 하지 아니하며, 보도 내용의 진실여부와 상관없이 그 청구를 할 수 있다.","ox":"O","m":"②","c":"A","tp":"언론중재 및 피해구제 등"},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_2-34-3","t":"언론등에 의하여 범죄혐의가 있거나 형사상의 조치를 받았다고 보도 또는 공표된 자는 그에 대한 형사절차가 무죄판결 또는 이와 동등한 형태로 종결되었을 때에는 그 사실을 안 날부터 3개월 이내에 언론사등에 이 사실에 관한 추후보도의 게재를 청구할 수 있다.","ox":"O","m":"③","c":"A","tp":"언론중재 및 피해구제 등"},{"y":2024,"e":"경찰 공채","qn":34,"i":"PO2024_2-34-4","t":"언론사등이 정정보도청구를 수용할 때에는 지체없이 피해자 또는 그 대리인과 정정보도의 내용·크기 등에 관하여 협의한 후, 그 협의가 있은 날부터 7일 내에 정정보도문을 방송하거나 게재 하여야 한다. 다만, 신문 및 잡지 등 정기간행물의 경우 이미 편집 및 제작이 완료되어 부득이할 때에는 게재하지 않을 수 있다.","ox":"X","m":"④","c":"A","tp":"언론중재 및 피해구제 등"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_1-23-1","t":"개인정보처리자는 개인정보의 처리 목적을 명확하게 하여야 하고 그 목적에 필요한 범위에서 최소한의 개인정보만을 적법 하고 정당하게 수집하여야 한다.","ox":"O","m":"①","c":"A","tp":"개인정보 보호법 상 ‘개인정보 보호 원칙’"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_1-23-2","t":"개인정보처리자는 개인정보의 처리 목적에 필요한 범위에서 개인정보의 완전성, 확장성 및 신속성이 보장되도록 하여야 한다.","ox":"X","m":"②","c":"A","tp":"개인정보 보호법 상 ‘개인정보 보호 원칙’"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_1-23-3","t":"개인정보처리자는 개인정보를 익명 또는 가명으로 처리하여도 개인정보 수집목적을 달성할 수 있는 경우 익명처리가 가능한 경우에는 익명에 의하여, 익명처리로 목적을 달성할 수 없는 경우에는 가명에 의하여 처리될 수 있도록 하여야 한다.","ox":"O","m":"③","c":"A","tp":"개인정보 보호법 상 ‘개인정보 보호 원칙’"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_1-23-4","t":"개인정보처리자는 개인정보의 처리 방법 및 종류 등에 따라 정보주체의 권리가 침해받을 가능성과 그 위험 정도를 고려하여 개인정보를 안전하게 관리하여야 한다.","ox":"O","m":"④","c":"A","tp":"개인정보 보호법 상 ‘개인정보 보호 원칙’"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_1-27-1","t":"매슬로(Maslow)는 다원적 인간욕구의 존재를 인정하고 가장 기본적인 욕구는 생리적 욕구라고 하였다.","ox":"O","m":"①","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_1-27-2","t":"브룸(Vroom)은 동기유발은 욕구충족이 아니라 과업에 대한 기대감, 수단성, 유의성에 의해 결정된다고 주장하였다.","ox":"O","m":"②","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_1-27-3","t":"앨더퍼(Alderfer)는 매슬로의 욕구계층이론을 수정하여 생존욕구, 관계욕구, 성장욕구로 구분하였다.","ox":"O","m":"③","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_1-27-4","t":"맥그리거(McGregor)는 전통적 조직이론의 인간관을 위생요인, 새로운 조직이론의 인간관을 동기요인으로 구분하였다.","ox":"X","m":"④","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_1-31-1","t":"Ⅰ급비밀은 누설될 경우 국가안전보장에 막대한 지장을 끼칠 우려가 있는 비밀을 말한다.","ox":"X","m":"①","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_1-31-2","t":"비밀은 해당 등급의 비밀취급 인가를 받은 사람만 취급할 수 있으며, 암호자재는 해당 등급의 비밀 소통용 암호자재취급 인가를 받은 사람만 취급할 수 있다.","ox":"O","m":"②","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_1-31-3","t":"비밀을 휴대하고 출장 중인 사람은 비밀을 안전하게 보호하기 위하여 국내 경찰기관 또는 재외공관에 보관을 위탁할 수 있으며, 위탁받은 기관은 그 비밀을 보관하여야 한다.","ox":"O","m":"③","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_1-31-4","t":"각급기관의 장은 연 2회 비밀 소유 현황을 조사하여 국가정보원장에게 통보하여야 한다.","ox":"O","m":"④","c":"A","tp":"보안업무규정 상 비밀보호"},{"y":2025,"e":"경찰 공채","qn":29,"i":"PO2025_2-29","t":"계급제와 직위분류제에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"계급제와 직위분류제에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 계급제는 사람중심의 분류방법으로 널리 일반적 교양과 능력을 가진 사람을 채용하여 신분보장과 함께 장기간에 걸쳐 능력이 키워지므로 공무원이 보다 종합적이며 신축적인 대응역량을 가질 수 있다. ㉡ 직위분류제는 공무원이 동일한 직무를 장기간 담당하게 되어 행정의 전문화에 유용하지만, 권한과 책임의 한계가 불명확하다. ㉢ 계급제는 폐쇄형 충원방식으로 공무원에 대한 인사배치가 자유롭지 않으나, 직위분류제는 개방형 충원방식으로 공무원에 대한 인사배치가 자유롭다. ㉣ 직위분류제는 계급제에 비해서 보수결정의 합리적인 기준을 제시할 수 있으며, 직무분석을 통해 부서 간, 기관 간 협조 및 조정이 용이하다.","o":["1개","2개","3개","4개"],"a":1}},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_2-30-1","t":"매슬로우(Maslow)의 욕구단계이론에 의하면 인간의 욕구는 우선순위의 계층을 이루며 상위욕구로부터 하위욕구로 욕구를 추구한다고 한다.","ox":"X","m":"①","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_2-30-2","t":"맥그리거(McGregor)의 X이론에 의하면 인간은 부지런하고 책임성과 자율성을 발휘하기를 좋아하므로 민주적이고 인간적인 동기유발전략이 필요하다고 한다.","ox":"X","m":"②","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_2-30-3","t":"동기부여 과정이론에는 아담스(Adams)의 공정성이론, 브룸 (Vroom)의 기대이론, 포터와 롤러(Porter & Lawler)의 업적 만족이론 등이 있다.","ox":"O","m":"③","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_2-30-4","t":"앨더퍼(Alderfer)는 매슬로우(Maslow)의 욕구단계이론을 수정하여 생존욕구, 존경욕구, 성장욕구로 구분하였다.","ox":"X","m":"④","c":"A","tp":"동기부여이론"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_2-31-1","t":"품목별 예산제도는 회계 집행내용과 책임이 명확하며, 인건비 등 경직성 경비에 적용이 용이하다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_2-31-2","t":"성과주의 예산제도는 자원배분의 합리성과 예산집행의 신축성을 기할 수 있으며 국민의 입장에서 행정기관의 활동을 이해하기 쉽다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_2-31-3","t":"계획예산제도는 장기적인 기획과 단기적인 예산편성을 유기적으로 연결하여 자원배분의 일관성과 합리성을 도모한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"경찰 공채","qn":31,"i":"PO2025_2-31-4","t":"일몰법 예산제도는 행정부가 제정한 법령에 의하여 특정 사업이 일정 기간이 경과하면 의무적·자동적으로 폐지되게 하는 예산 제도이며 행정부의 사업에 주로 사용된다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_2-32-1","t":"공무원의 장기근속을 유도하므로 행정의 안정성과 계속성을 유지하는데 유리하다.","ox":"O","m":"①","c":"A","tp":"직업공무원제도"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_2-32-2","t":"공무원이 환경변화에 민감하지 못하고 특권 집단화될 우려가 있다.","ox":"O","m":"②","c":"A","tp":"직업공무원제도"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_2-32-3","t":"연령 등으로 대상을 제한하는 경우도 있어 공직임용의 기회균등이 제약될 수 있다.","ox":"O","m":"③","c":"A","tp":"직업공무원제도"},{"y":2025,"e":"경찰 공채","qn":32,"i":"PO2025_2-32-4","t":"강력한 신분보장으로 공무원에 대한 행정통제와 책임 확보가 용이하다.","ox":"X","m":"④","c":"A","tp":"직업공무원제도"},{"y":2026,"e":"경찰 공채","qn":28,"i":"PO2026_1-28","t":"관료제의 주요 병리현상에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"관료제의 주요 병리현상에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ ‘변화에 대한 저항’이란 행정의 궁극적인 목적이 아닌 수많은 도장, 많은 문서 등 서류절차에 과도하게 집착하는 형식주의를 말한다. ㉡ ‘할거주의’란 행정관료들이 자기가 소속하고 있는 기관, 부처 등만을 중심으로 생각하는 소속 이기주의를 말한다. 소속기관이나 부서에만 충성함으로써 다른 조직이나 다른 부서와의 조정이나 협조가 곤란할 수 있다. ㉢ ‘번문욕례(Red Tape)’란 행정관료가 상관으로부터의 지시가 옳든 그르든 이에 영합하고, 선례에 따라 소극적으로 처리 하는 행동을 말한다. 소극적인 일 처리와 책임회피 현상이 나타날 수 있다. ㉣ ‘피터의 원리(Peter’s Principle)’란 조직구성원이 자신의 ‘무능력의 한계까지 승진’하여 관료조직의 전반적인 효율성이 저하되는 현상을 말한다.","o":["1개","2개","3개","4개"],"a":2}},{"y":2026,"e":"경찰 공채","qn":30,"i":"PO2026_1-30","t":"매슬로우(Maslow)의 욕구계층 이론에 관한 설명으로 아래","c":"A","mc":{"s":"매슬로우(Maslow)의 욕구계층 이론에 관한 설명으로 아래","d":"<보기>와 관련 용어를 가장 적절하게 연결한 것은? < 보기 > ㉠ 이 욕구는 동료, 상사, 조직 전체에 대한 친근감, 귀속감의 충족을 주요 내용으로 하며, 충족 방안으로는 인간관계의 개선 등이 있다. ㉡ 이 욕구는 창조적이고 잠재성을 실현시키고, 자기완성과 자기발전에 관련된 욕구이다.","o":["㉠ - 자아실현의 욕구(Self Actualization Needs)","㉠ - 사회적 욕구(애정의 욕구)(Love‧ Social Needs)","㉡ - 존경의 욕구(Self Esteem Needs)","㉡ - 안전의 욕구(Safety Needs)"],"a":2}},{"y":2026,"e":"경찰 공채","qn":31,"i":"PO2026_1-31-1","t":"직업공무원제도는 공직을 일생의 보람된 직장으로 생각하면서 일생을 거기에 기꺼이 바쳐 봉사할 수 있도록 인사업무를 조직하고 운영하는 공무원제도를 말한다.","ox":"O","m":"①","c":"A","tp":"인사관리"},{"y":2026,"e":"경찰 공채","qn":31,"i":"PO2026_1-31-2","t":"영국에서 발달된 엽관주의는 잭슨(Andrew Jackson) 수상 시대에 본격적으로 시작되었다.","ox":"X","m":"②","c":"A","tp":"인사관리"},{"y":2026,"e":"경찰 공채","qn":31,"i":"PO2026_1-31-3","t":"계급제는 직위분류제에 비해 개방형 충원방식을 취하고 있다.","ox":"X","m":"③","c":"A","tp":"인사관리"},{"y":2026,"e":"경찰 공채","qn":31,"i":"PO2026_1-31-4","t":"직위분류제는 계급제에 비해 인사배치에 있어서 신축적이다.","ox":"X","m":"④","c":"A","tp":"인사관리"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_1-32-1","t":"본예산은 정부가 매년 정기적으로 다음 연도의 세입과 세출을 예산안으로 편성한 후, 국회에서 심의‧ 의결하여 최초로 확정된 예산을 말한다.","ox":"O","m":"①","c":"A","tp":"예산관리"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_1-32-2","t":"영기준예산(Zero-Base Budget System)은 거대 정부시대에 각광받는 제도이다.","ox":"X","m":"②","c":"A","tp":"예산관리"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_1-32-3","t":"품목별 예산(Line-Item Budget System)은 ‘단위원가×업무량=예산액’ 으로 표시하는 제도이다.","ox":"X","m":"③","c":"A","tp":"예산관리"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_1-32-4","t":"추가경정예산은 예산불성립으로 인한 행정중단을 방지하기 위한 제도이다.","ox":"X","m":"④","c":"A","tp":"예산관리"},{"y":2026,"e":"경찰 공채","qn":33,"i":"PO2026_1-33","t":"보안관리에 관한 설명으로 아래","c":"A","mc":{"s":"보안관리에 관한 설명으로 아래","d":"<보기>에서 옳은 것은 모두 몇 개인가? < 보기 > ㉠ 보안의 원칙에는 과도 또는 과소분류 금지의 원칙, 독립 분류의 원칙, 외국비밀 존중의 원칙이 있다. ㉡ 비밀분류의 원칙은 알 사람만 알아야 하는 원칙(한정성의 원칙), 부분화의 원칙, 보안과 효율의 조화가 있다. ㉢ ｢보안업무규정｣ 상 비밀은 Ⅰ급 비밀, Ⅱ급 비밀, Ⅲ급 비밀로 구분한다. ㉣ ｢보안업무규정｣ 상 보호지역은 제한지역, 제한구역, 통제구역 으로 나눈다.","o":["1개","2개","3개","4개"],"a":2}},{"y":2026,"e":"경찰 공채","qn":29,"i":"PO2026_2-29-1","t":"매슬로우(Maslow)의 욕구단계이론 - 인간의 욕구는 5단계의 계층으로 이루어져 있으며, 하위단계의 욕구가 충족되어야 비로소 다음 단계의 욕구로 진행된다는 점을 전제로 한다.","ox":"O","m":"①","c":"A","tp":"동기부여이론"},{"y":2026,"e":"경찰 공채","qn":29,"i":"PO2026_2-29-2","t":"엘더퍼(Alderfer)의 ERG이론 – 매슬로우(Maslow)의 욕구단계를 3단계로 줄여서 제시한 이론으로, 인간의 욕구는 권력욕구, 친교 욕구, 성취욕구의 순으로 발달된다고 보았다.","ox":"X","m":"②","c":"A","tp":"동기부여이론"},{"y":2026,"e":"경찰 공채","qn":29,"i":"PO2026_2-29-3","t":"허츠버그(Herzberg)의 동기‧ 위생이론 – 만족과 관련된 요인을 동기요인, 불만족과 관련된 요인을 위생요인으로 분류했다.","ox":"O","m":"③","c":"A","tp":"동기부여이론"},{"y":2026,"e":"경찰 공채","qn":29,"i":"PO2026_2-29-4","t":"아지리스(Argyris)의 성숙‧ 미성숙이론 – 미성숙한 조직구성원이 성숙한 조직구성원으로 발전하려면 개인의 성격(Personality)에 7가지 변화가 일어나야 한다고 주장하였다.","ox":"O","m":"④","c":"A","tp":"동기부여이론"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_2-32-1","t":"총경의 근무성적은 제1 평정 요소로만 평정한다.","ox":"X","m":"①","c":"A","tp":"경찰공무원의 근무성적 평정"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_2-32-2","t":"경무관 이하의 경찰공무원에 대해서는 매년 근무성적을 평정 하여야 한다.","ox":"X","m":"②","c":"A","tp":"경찰공무원의 근무성적 평정"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_2-32-3","t":"제2 평정 요소는 경찰업무 발전에 대한 기여도, 직무수행능력, 직무수행태도로 구성되어 있다.","ox":"X","m":"③","c":"A","tp":"경찰공무원의 근무성적 평정"},{"y":2026,"e":"경찰 공채","qn":32,"i":"PO2026_2-32-4","t":"휴직‧ 직위해제 등의 사유로 해당 연도의 평정기관에서 6개월 이상 근무하지 아니한 경찰공무원에 대해서는 근무성적을 평정하지 않는다.","ox":"O","m":"④","c":"A","tp":"경찰공무원의 근무성적 평정"},{"y":2026,"e":"경찰 공채","qn":33,"i":"PO2026_2-33-1","t":"각급 경찰기관의 장 소속 하에 심의위원회를 둔다.","ox":"O","m":"①","c":"A","tp":"경찰장비관리규칙 상 무기 소지 적격 심의위원회"},{"y":2026,"e":"경찰 공채","qn":33,"i":"PO2026_2-33-2","t":"심의위원회에는 1명 이상의 민간위원이 참여하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰장비관리규칙 상 무기 소지 적격 심의위원회"},{"y":2026,"e":"경찰 공채","qn":33,"i":"PO2026_2-33-3","t":"심의위원회의 위원장은 위원중에서 호선한다.","ox":"X","m":"③","c":"A","tp":"경찰장비관리규칙 상 무기 소지 적격 심의위원회"},{"y":2026,"e":"경찰 공채","qn":33,"i":"PO2026_2-33-4","t":"심의위원회의 회의는 재적위원 과반수의 출석으로 개의하며, 출석위원 과반수의 찬성으로 의결한다.","ox":"O","m":"④","c":"A","tp":"경찰장비관리규칙 상 무기 소지 적격 심의위원회"},{"y":2026,"e":"경찰 공채","qn":34,"i":"PO2026_2-34","t":"보안관리에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"보안관리에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 보안업무의 3대 원칙은 부분화의 원칙, 보안과 효율의 조화의 원칙, 독립분류의 원칙이다. ㉡ 각급기관의 장은 비밀 분류를 통일성 있고 적절하게 하기 위하여 세부 분류지침을 작성하여 시행하여야 한다. 이 경우 세부 분류지침은 공개한다. ㉢ 누설될 경우 국가안전보장에 중대한 해를 끼칠 우려가 있는 비밀은 II급비밀이다. ㉣ 비밀을 생산하거나 관리하는 사람은 비밀의 작성을 완료하거나 비밀을 접수하는 즉시 그 비밀을 분류하거나 재분류할 책임이 있다. ㉤ 통제구역이란 보안상 매우 중요한 구역으로서 비인가자의 출입이 금지되는 구역이다. ㉥ I급비밀은 반드시 금고 또는 잠금장치가 있는 안전한 용기에 보관하여야 한다.","o":["2개","3개","4개","5개"],"a":2}}],"9":[{"y":2022,"e":"경찰 공채","qn":8,"i":"PO2022_1-08-1","t":"국회는 입법권과 예산심의권을 통해 경찰을 사전 통제할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰통제"},{"y":2022,"e":"경찰 공채","qn":8,"i":"PO2022_1-08-2","t":"부패방지 및 국민권익위원회의 설치와 운영에 관한 법률 및 동법 시행령에 따르면, 18세 이상의 국민은 경찰 등 공공기관의 사무처리가 법령위반 또는 부패행위로 인하여 공익을 현저히 해하는 경우, 100명 이상의 국민의 연서로 감사원에 감사를 청구할 수 있다.","ox":"X","m":"②","c":"A","tp":"경찰통제"},{"y":2022,"e":"경찰 공채","qn":8,"i":"PO2022_1-08-3","t":"상급자의 하급자에 대한 직무명령권은 내부적 통제의 일환이다.","ox":"O","m":"③","c":"A","tp":"경찰통제"},{"y":2022,"e":"경찰 공채","qn":8,"i":"PO2022_1-08-4","t":"경찰의 위법한 처분에 대한 행정소송제도는 사법통제로서 외부적 통제 장치이다.","ox":"O","m":"④","c":"A","tp":"경찰통제"},{"y":2022,"e":"경찰 공채","qn":10,"i":"PO2022_1-10","t":"경찰청 감사 규칙 상 감사결과의 처리기준에 관한 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰청 감사 규칙 상 감사결과의 처리기준에 관한 설명 중 옳은 것은 모두 몇 개인가?","d":"㉠ 변상명령: 감사결과 경미한 지적사항으로서 현지에서 즉시 시정 개선조치가 필요한 경우 ㉡ 경고 주의 요구: 감사결과 위법 또는 부당하다고 인정되는 사실이 있으나 그 정도가 징계 또는 문책사유에 이르지 아니할 정도로 경미하거나, 감사대상기관 또는 부서에 대한 제재가 필요한 경우 ㉢ 시정 요구: 감사결과 법령상 제도상 또는 행정상 모순이 있거나 그 밖에 개선할 사항이 있다고 인정되는 경우 ㉣ 개선 요구: 감사결과 문제점이 인정되는 사실이 있어 그 대안을 제시하고 감사대상기관의 장 등으로 하여금 개선방안을 마련하도록 할 필요가 있는 경우","o":["0개","1개","2개","3개"],"a":2}},{"y":2022,"e":"경찰 공채","qn":32,"i":"PO2022_2-32","t":"경찰작용 및 경찰공무원을 통제하는 행정기관의 역할과 기능에 관한 설명 중 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"경찰작용 및 경찰공무원을 통제하는 행정기관의 역할과 기능에 관한 설명 중 옳은 것을 모두 고른 것은?","d":"㉠ 행정심판위원회는 경찰관청의 위법한 처분 및 대통령의 부작위에 대해서 심리하여 침해된 국민의 권리를 구제하고 경찰행정의 적정한 운영을 도모한다. ㉡ 시 도자치경찰위원회는 자치경찰사무 담당 경찰공무원에 대한 징계를 요구할 수 있다. ㉢ 국민권익위원회는 누구든지 경찰공무원 등의 부패행위를 알게 된 때에는 무기명으로 신고할 수 있도록 하고 있다. ㉣ 인사혁신처에 소청심사위원회를 설치하여, 경찰공무원이 징계 처분, 그 밖에 그 의사에 반하는 불리한 처분이나 부작위를 구제받을 수 있도록 하고 있다. ㉤ 국가인권위원회는 경찰기관 및 경찰공무원 등에 의한 인권 침해행위 또는 차별행위에 대해 조사하고 구제할 수 있다. ㉥ 감사원은 국회 법원 및 헌법재판소를 포함한 모든 국가기관 및 그에 소속한 공무원의 사무를 감찰하여 비위를 적발하고 시정한다.","o":["㉠㉢㉤","㉡㉣㉤","㉡㉢㉣","㉢㉣㉥"],"a":2}},{"y":2023,"e":"경찰 공채","qn":35,"i":"PO2023_1-35","t":"다음 경찰통제의 유형 중 내부적 통제에 해당하는 것은 모두 몇 개인가?","c":"A","mc":{"s":"다음 경찰통제의 유형 중 내부적 통제에 해당하는 것은 모두 몇 개인가?","d":"㉠ 청문감사인권관제도 ㉢ 국가경찰위원회 ㉤ 경찰청장의 훈령권 ㉡ 국민권익위원회 ㉣ 소청심사위원회 ㉥ 국회의 입법권","o":["2개","3개","4개","5개"],"a":1}},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_2-09-1","t":"「적극행정 운영규정」 상 공무원이 적극행정을 추진한 결과에 대해 그의 행위에 고의 또는 중대한 과실이 없는 경우에는 징계 관련 법령에 따라 징계의결 또는 징계부가금 부과의결을 하지 않는다.","ox":"O","m":"①","c":"A","tp":"적극행정 운영규정 및 경찰청 적극행정 면책제도 운영 규정"},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_2-09-2","t":"「경찰청 적극행정 면책제도 운영규정」 에 의한 면책은 경찰청 및 그 소속기관의 공무원 또는 산하단체의 임·직원 등에게 적용된다.","ox":"O","m":"②","c":"A","tp":"적극행정 운영규정 및 경찰청 적극행정 면책제도 운영 규정"},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_2-09-3","t":"「경찰청 적극행정 면책제도 운영규정」 제5조 제1항 제3호의 요건을 적용하는 경우 자체감사를 받는 사람이 ‘대상 업무를 처리하면서 중대한 절차상의 하자가 없었을 것’과 ‘자체감사를 받는 사람과 대상 업무 사이에 사적인 이해관계가 없을 것’이라는 요건을 모두 갖추어 업무를 처리한 것으로 인정되는 경우에는 그 행위에 고의나 중대한 과실이 없는 경우에 해당하는 것으로 추정한다.","ox":"O","m":"③","c":"A","tp":"적극행정 운영규정 및 경찰청 적극행정 면책제도 운영 규정"},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_2-09-4","t":"「적극행정 운영규정」 제18조의3은 “누구든지 공무원의 소극행정을 국가인권위원회가 운영하는 소극행정 신고센터에 신고할 수 있다.”고 규정하고 있다.","ox":"X","m":"④","c":"A","tp":"적극행정 운영규정 및 경찰청 적극행정 면책제도 운영 규정"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_2-33-1","t":"“감찰”이란 복무기강 확립과 경찰행정의 적정성을 확보하기 위해 경찰기관 또는 소속공무원의 제반업무와 활동 등을 조사·점검·확인하고 그 결과를 처리하는 감찰관의 직무활동을 말한다.","ox":"O","m":"①","c":"A","tp":"경찰 감찰 규칙"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_2-33-2","t":"감찰부서장은 소속 감찰관에 대하여 감찰관 보직 후 3년마다 적격심사를 실시하여 인사에 반영하여야 한다.","ox":"X","m":"②","c":"A","tp":"경찰 감찰 규칙"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_2-33-3","t":"경찰기관의 장은 의무위반행위가 자주 발생하거나 그 발생 가능성이 높다고 인정되는 시기, 업무분야 및 경찰관서 등에 대하여는 일정기간 동안 전반적인 조직관리 및 업무추진 실태 등을 집중 점검할 수 있다.","ox":"O","m":"③","c":"A","tp":"경찰 감찰 규칙"},{"y":2023,"e":"경찰 공채","qn":33,"i":"PO2023_2-33-4","t":"감찰관은 감찰관 본인이 의무위반행위로 인해 감찰대상이 된 때에는 당해 감찰직무(감찰조사 및 감찰업무에 대한 지휘를 포함한다)에서 제척된다.","ox":"O","m":"④","c":"A","tp":"경찰 감찰 규칙"},{"y":2024,"e":"경찰 공채","qn":25,"i":"PO2024_2-25","t":"경찰통제에 관한 설명으로 옳지 않은 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰통제에 관한 설명으로 옳지 않은 것은 모두 몇 개인가?","d":"㉠ 경찰이 보유･ 관리하는 정보는 국민의 알권리 보장 등을 위하여 ｢공공기관의 정보공개에 관한 법률｣ 에서 정하는 바에 따라 적극적으로 공개하는 것이 기본 원칙이다. ㉡ 국회에 의한 입법통제 방식에는 사전통제 방식과 사후통제 방식이 존재한다. ㉢ 행정부에 의한 통제유형에는 중앙행정심판위원회에 의한 통제, 국정조사･ 감사권 등이 포함된다. ㉣ ｢경찰감찰규칙｣ 에서는 조사대상자가 영상녹화를 요청하는 경우에 감찰관이 재량적으로 판단할 수 있도록 하고 있다.","o":["없음","1개","2개","3개"],"a":3}},{"y":2025,"e":"경찰 공채","qn":11,"i":"PO2025_1-11-1","t":"“적극행정”이란 경찰청 및 그 소속기관의 공무원 또는 산하 단체의 임‧ 직원이 국가 또는 공공의 이익을 증진하기 위해 성실하고 능동적으로 업무를 처리하는 행위를 말한다.","ox":"O","m":"①","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":11,"i":"PO2025_1-11-2","t":"“사전컨설팅 감사”란 불합리한 제도 등으로 인해 적극적인 업무 수행이 어려운 경우, 해당 업무의 수행에 앞서 업무 처리 방향 등에 대하여 미리 감사의견을 듣고 이를 업무처리에 반영하여 적극 행정을 추진하는 것을 말한다.","ox":"O","m":"②","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":11,"i":"PO2025_1-11-3","t":"사전컨설팅 감사는 현지 확인 등 실지감사를 원칙으로 하되, 부득이한 사유가 발생할 경우 서면감사로 할 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":11,"i":"PO2025_1-11-4","t":"행정심판, 소송, 수사 또는 타 기관에서 감사 중인 사항, 타 법령에서 정하고 있는 재심의 절차를 거친 사항 등은 사전 컨설팅 감사 대상에서 제외한다.","ox":"O","m":"④","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_2-10-1","t":"이 규정에 의한 면책은 경찰청 및 그 소속기관의 공무원 또는 산하단체의 임‧ 직원 등에게 적용된다.","ox":"O","m":"①","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_2-10-2","t":"적극행정 면책심사의 신청은 감사 대상자만 가능하며, 면책사유에 해당하는 증빙자료를 구비하여 감사 책임자에게 면책심사를 신청할 수 있다.","ox":"O","m":"②","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_2-10-3","t":"적극행정 면책신청에 대한 심사를 위하여 경찰청에 적극행정 면책심사위원회를 둔다.","ox":"O","m":"③","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_2-10-4","t":"적극행정 면책심사위원회는 위원장 1명을 포함하여 5명 이상 7명 이내로 성별을 고려하여 구성하며 위원장은 감사관으로 한다. 【경 찰학】(일반공채·101경비단·경찰행정 경채)","ox":"X","m":"④","c":"A","tp":"경찰청 적극행정 면책제도 운영규정"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_2-20-1","t":"감찰관은 소속공무원의 의무위반사실에 대한 민원을 접수한 경우 접수일로부터 2개월 내에 신속히 처리하여야 한다. 다만, 부득이한 사유로 민원을 기한 내에 처리할 수 없을 때에는 소속 경찰기관의 감찰부서장에게 보고하여 그 처리 기간을 연장할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰 감찰 규칙"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_2-20-2","t":"감찰관은 감찰조사를 위해서 조사대상자의 출석을 요구할 때에는 조사기일 3일 전까지 출석요구서 또는 구두로 조사일시, 의무 위반행위사실 요지 등을 통지하여야 한다. 다만, 사안이 급박한 경우 또는 조사대상자의 요청이 있는 경우에는 즉시 조사에 착수할 수 있다.","ox":"O","m":"②","c":"A","tp":"경찰 감찰 규칙"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_2-20-3","t":"감찰정보심의회는 위원장을 포함한 5명 이상 7명 이하의 위원으로 구성하며, 위원장은 감찰부서장이 되고 위원은 감찰부서장이 소속 공무원 중에서 지명한다.","ox":"X","m":"③","c":"A","tp":"경찰 감찰 규칙"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_2-20-4","t":"감찰관은 검찰‧ 경찰, 그 밖의 수사기관으로부터 수사개시 통보를 받은 경우에는 징계의결요구권자의 결재를 받아 해당 기관으로부터 수사결과의 통보를 받을 때까지 감찰조사, 징계 의결요구 등의 절차를 진행하지 아니 할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰 감찰 규칙"},{"y":2025,"e":"경찰 공채","qn":33,"i":"PO2025_2-33-1","t":"경찰청장의 훈령권과 국회의 예산심의권은 사전통제이며 내부통제에 해당한다.","ox":"X","m":"①","c":"A","tp":"경찰통제"},{"y":2025,"e":"경찰 공채","qn":33,"i":"PO2025_2-33-2","t":"국가경찰위원회의 심의‧ 의결권은 외부통제이며 민주적 통제에 해당한다.","ox":"O","m":"②","c":"A","tp":"경찰통제"},{"y":2025,"e":"경찰 공채","qn":33,"i":"PO2025_2-33-3","t":"국회의 국정감사‧ 조사권은 사후통제인 동시에 외부통제에 해당한다.","ox":"O","m":"③","c":"A","tp":"경찰통제"},{"y":2025,"e":"경찰 공채","qn":33,"i":"PO2025_2-33-4","t":"경찰청장 및 국가경찰위원회 위원의 임명권, 총경 이상 경찰 공무원의 임명권 등 대통령에 의한 경찰통제는 행정통제이며 외부통제에 해당한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"경찰 공채","qn":8,"i":"PO2026_1-08","t":"｢적극행정 운영규정｣ 에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢적극행정 운영규정｣ 에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["‘적극행정’이란 공무원이 불합리한 규제를 개선하는 등 공공의 이익을 위해 창의성과 전문성을 바탕으로 적극적으로 업무를 처리하는 행위를 말한다.","중앙행정기관의 장은 소속 공무원을 대상으로 적극행정 관련 교육을 연 1회 이상 실시할 수 있다.","국민권익위원회는 중앙행정기관 소속 공무원의 소극행정 예방 및 근절을 위해 소극행정 신고센터를 운영하고, 중앙행정기관의 장에게 신고사항에 대해 적절한 조치를 하도록 권고할 수 있다.","중앙행정기관의 장은 적극행정 추진으로 인한 민‧ 형사상 책임과 관련하여 소속 공무원을 보호하기 위해 필요한 조치를 해야 한다. 【경 찰 학】 - 13 -"],"a":2}},{"y":2026,"e":"경찰 공채","qn":9,"i":"PO2026_2-09","t":"｢경찰청 적극행정 면책제도 운영규정｣ 상 사전컨설팅 감사에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢경찰청 적극행정 면책제도 운영규정｣ 상 사전컨설팅 감사에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["사전컨설팅 감사는 서면감사를 원칙으로 하되, 현지 확인 등 실지감사를 함께 할 수 있다. 【경 찰 학】(일반공채･ 101경비단･ 경찰행정 경채) ㉠ ㉡ ㉢ ① 윤리적 냉소주의 가설 전체사회 가설 썩은사과 가설","윤리적 냉소주의 가설 썩은사과 가설 전체사회 가설","전체사회 가설 윤리적 냉소주의 가설 구조원인 가설","전체사회 가설 썩은사과 가설 구조원인 가설 - 13 - ② 사전컨설팅 대상 기관 및 대상 부서의 장(이하 “사전컨설팅 대상 기관등의 장”이라 한다)은 불합리한 제도 등으로 인하여 공공의 이익이 훼손되는 일이 없도록 사전컨설팅 감사를 적극 활용하여야 한다. ③ 사전컨설팅 대상 기관등의 장은 인가‧ 허가‧ 승인 등 규제관련 업무를 수행하기 전에 감사관에게 사전컨설팅 감사를 신청할 수 있다. ④ 사전컨설팅 감사 의견을 반영하여 적극행정을 추진한 결과는 자체감사규정에 따른 감사의 대상이 되지 아니한다."],"a":4}}],"10":[{"y":2022,"e":"경찰 공채","qn":11,"i":"PO2022_1-11","t":"다음은 전통적 경찰활동과 지역사회 경찰활동에 관한 비교 설명이다(Sparrow, 1988). 질문과 답변의 연결이 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"다음은 전통적 경찰활동과 지역사회 경찰활동에 관한 비교 설명이다(Sparrow, 1988). 질문과 답변의 연결이 가장 적절 하지 않은 것은?","d":"","o":["경찰은 누구인가? - 전통적 경찰활동의 관점에서는 법집행을 주로 책임지는 정부기관이라고 답변할 것이며, 지역사회 경찰 활동의 관점에서는 경찰이 시민이고 시민이 경찰이라고 답변 할 것이다.","언론 접촉 부서의 역할은 무엇인가? - 전통적 경찰활동의 관점 에서는 현장경찰관들에 대한 비판적 여론을 차단하는 것이라고 답변할 것이며, 지역사회 경찰활동의 관점에서는 지역사회와의 원활한 소통창구라고 답변할 것이다.","경찰의 효과성은 무엇이 결정하는가? - 전통적 경찰활동의 관점 에서는 경찰의 대응시간이라고 답변할 것이며, 지역사회 경찰 활동의 관점에서는 시민의 협조라고 답변할 것이다.","가장 중요한 정보란 무엇인가? - 전통적 경찰활동의 관점에서는 범죄자 정보(개인 또는 집단의 활동사항 관련 정보)라고 답변할 것이며, 지역사회 경찰활동의 관점에서는 범죄사건 정보(특정 범죄사건 또는 일련의 범죄사건 관련 정보)라고 답변할 것이다."],"a":4}},{"y":2022,"e":"경찰 공채","qn":12,"i":"PO2022_1-12","t":"다음 경찰활동 예시의 근거가 되는 범죄원인론으로 가장 관련성이 높은 것은?","c":"A","mc":{"s":"다음 경찰활동 예시의 근거가 되는 범죄원인론으로 가장 관련성이 높은 것은?","d":"A경찰서는 관내에서 폭행으로 적발된 청소년을 형사입건하는 대신, 학교전담경찰관이 외부 전문가와 함께 3일 동안 다양한 활동으로 구성된 선도프로그램을 제공함으로써 해당 청소년에게 스스로 잘못을 뉘우치고 장차 지역사회로 다시 통합될 수 있는 기회를 제공하였다.","o":["낙인이론","일반긴장이론","깨진 유리창 이론","일상활동이론"],"a":1}},{"y":2022,"e":"경찰 공채","qn":13,"i":"PO2022_1-13","t":"뉴먼(1972)은 방어공간의 구성요소를 구분하였다. 이와 관련된","c":"A","mc":{"s":"뉴먼(1972)은 방어공간의 구성요소를 구분하였다. 이와 관련된","d":"<보기 1>의 설명과 <보기 2>의 구성요소가 가장 적절하게 연결된 것은? <보기 1> (가) 지역의 외관이 다른 지역과 고립되어 있지 않고, 보호 되고 있으며, 주민의 적극적 행동의지를 보여줌 (나) 지역에 대한 소유의식은 일상적이지 않은 일이 있을 때 주민으로 하여금 행동을 취하도록 자극함 (다) 특별한 장치의 도움 없이 실내와 실외의 활동을 관찰할 수 있는 능력임 <보기 2> ㉠ 영역성 ㉡ 자연적 감시 ㉢ 이미지 ㉣ 환경 (가) (나) (다)","o":["㉢ ㉣ ㉠","㉢ ㉠ ㉡","㉣ ㉠ ㉢","㉣ ㉢ ㉡"],"a":2}},{"y":2022,"e":"경찰 공채","qn":20,"i":"PO2022_1-20","t":"지역경찰의 조직 및 운영에 관한 규칙 에 관한 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"지역경찰의 조직 및 운영에 관한 규칙 에 관한 설명 중 옳은 것은 모두 몇 개인가?","d":"㉠ 시 도경찰청장은 인구, 면적, 행정구역, 교통 지리적 여건, 각종 사건사고 발생 등을 고려하여 경찰서의 관할구역을 나누어 지역경찰관서를 설치한다. ㉡ 관리팀원 및 순찰팀원에 대한 일일근무 지정 및 지휘 감독과 관내 중요 사건 발생시 현장 지휘는 순찰팀장의 직무이다. ㉢ 직주일체형 치안센터에 배치된 근무자는 근무 종료 후(휴무일 포함)에도 관할구역 내에 위치하며 지역경찰관서와 연락체계를 유지하여야 한다. ㉣ 지역경찰관서장은 관내 치안상황의 분석 및 대책을 수립하고 소속 지역경찰의 근무와 관련된 제반사항에 대해 지휘 및 감독한다. ㉤ 상황근무를 지정받은 지역경찰은 지역경찰관서 및 치안센터 내에서 방문민원 및 각종 신고사건의 접수 및 처리를 수행한다.","o":["5개","4개","3개","2개"],"a":2}},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_1-23-1","t":"‘스토킹범죄’란 지속적 또는 반복적으로 스토킹행위를 하는 것을 말한다.","ox":"O","m":"①","c":"A","tp":"스토킹범죄의 처벌 등"},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_1-23-2","t":"사법경찰관리는 진행 중인 스토킹행위에 대하여 신고를 받은 경우 즉시 현장에 나가 스토킹 행위의 제지, 스토킹행위자와 피해자 분리, 유치장 또는 구치소에의 유치 등의 조치를 할 수 있다.","ox":"X","m":"②","c":"A","tp":"스토킹범죄의 처벌 등"},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_1-23-3","t":"스토킹범죄를 저지른 사람은 3년 이하의 징역 또는 3천만원 이하의 벌금에 처한다.","ox":"O","m":"③","c":"A","tp":"스토킹범죄의 처벌 등"},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_1-23-4","t":"흉기 또는 그 밖의 위험한 물건을 휴대하거나 이용하여 스토킹 범죄를 저지른 사람은 5년 이하의 징역 또는 5천만원 이하의 벌금에 처한다.","ox":"O","m":"④","c":"A","tp":"스토킹범죄의 처벌 등"},{"y":2022,"e":"경찰 공채","qn":9,"i":"PO2022_2-09","t":"환경설계를 통한 범죄예방(CPTED)에 관한 설명이다. 이에 관한 ㉠부터 ㉣까지의 설명 중 옳고 그름의 표시(O, X)가 모두 바르게 된 것은?","c":"A","mc":{"s":"환경설계를 통한 범죄예방(CPTED)에 관한 설명이다. 이에 관한 ㉠부터 ㉣까지의 설명 중 옳고 그름의 표시(O, X)가 모두 바르게 된 것은?","d":"㉠ 건축물이나 시설물의 설계 시 가시권의 최대 확보, 외부침입에 대한 감시기능을 확대하여 범죄행위의 발견 가능성은 증가 시키고 범죄기회는 감소시킬 수 있다는 원리를 자연적 감시 라고 하며, 이에 대한 종류로는 조명, 조경, 가시권 확대를 위한 건물의 배치 등이 있다. ㉡ 지역사회의 설계 시 주민들이 모여서 상호의견을 교환하고 유대감을 증대할 수 있는 공공장소를 설치하고 이용하도록 함으로써 ‘거리의 눈’을 활용한 자연적 감시와 접근통제의 기능을 확대하는 원리를 활동의 활성화(활용성의 증대)라고 하며, 이에 대한 종류로는 놀이터 공원의 설치, 벤치 정자의 위치 및 활용성에 대한 설계, 통행로의 설계 등이 있다. ㉢ 사적 공간에 대한 경계를 표시하여 주민들의 책임의식과 소유의식을 증대함으로써 사적 공간에 대한 관리권과 권리를 강화시키고, 외부인들에게는 침입에 대한 불법사실을 인식 시켜 범죄기회를 차단하는 원리를 자연적 접근통제라고 하며, 이에 대한 종류로는 방범창, 출입구의 최소화 등이 있다. ㉣ 처음 설계된 대로 혹은 개선한 의도대로 기능을 지속적으로 유지하도록 관리함으로써 범죄예방을 위한 환경설계의 장기적 이고 지속적인 효과를 유지하는 원리를 유지관리라고 하며, 이에 대한 종류로는 청결유지, 파손의 즉시보수, 조명의 관리 등이 있다.","o":["㉠(O) ㉡(X) ㉢(X) ㉣(O)","㉠(O) ㉡(O) ㉢(X) ㉣(O)","㉠(X) ㉡(X) ㉢(O) ㉣(O)","㉠(O) ㉡(O) ㉢(O) ㉣(X)"],"a":1}},{"y":2022,"e":"경찰 공채","qn":26,"i":"PO2022_2-26","t":"경찰청과 그 소속기관 직제 상 경찰청 생활안전국장의 분장사항에 해당하지 않는 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰청과 그 소속기관 직제 상 경찰청 생활안전국장의 분장사항에 해당하지 않는 것은 모두 몇 개인가?","d":"㉠ 아동 청소년 대상 성매매 사범에 대한 지도 및 단속 ㉡ 경비업에 관한 연구 및 지도 ㉢ 아동학대 수사 및 피해자 보호에 관한 업무 ㉣ 청원경찰의 운영 및 지도 ㉤ 교통사고 교통범죄에 관한 수사 지휘 감독 ㉥ 각종 안전사고의 예방에 관한 사항","o":["2개","3개","4개","5개"],"a":3}},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_2-33-1","t":"시 도경찰청장 및 경찰서장이 112요원을 배치할 때에는 관할 구역 내 지리감각, 언어 능력 및 상황 대처능력이 뛰어난 경찰 공무원을 선발 배치하여야 하며, 근무기간은 1년 이상으로 한다.","ox":"X","m":"①","c":"A","tp":"112종합상황실 운영 및 신고처리 규칙"},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_2-33-2","t":"112요원은 접수한 신고의 내용이 code 3의 유형에 해당하는 경우에는 출동요소에 지령하지 않고 자체 종결하거나 소관기관이나 담당 부서에 신고내용을 통보하여 처리하도록 조치하여야 한다.","ox":"O","m":"②","c":"A","tp":"112종합상황실 운영 및 신고처리 규칙"},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_2-33-3","t":"112신고 이외 경찰관서별 일반전화 또는 직접 방문 등으로 경찰관의 현장출동을 필요로 하는 사건의 신고를 한 경우 해당 신고를 받은 자가 접수한다. 이때 접수한 자는 112시스템에 신고내용을 입력하여야 한다.","ox":"O","m":"③","c":"A","tp":"112종합상황실 운영 및 신고처리 규칙"},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_2-33-4","t":"112종합상황실 자료 중 접수처리 입력자료는 1년간 보존하고, 무선지령내용 녹음자료는 24시간 녹음하고 3개월간 보존한다.","ox":"O","m":"④","c":"A","tp":"112종합상황실 운영 및 신고처리 규칙"},{"y":2022,"e":"경찰 공채","qn":34,"i":"PO2022_2-34","t":"스토킹범죄의 처벌 등에 관한 법률 상 처리절차에 관한 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"스토킹범죄의 처벌 등에 관한 법률 상 처리절차에 관한 설명 중 옳은 것은 모두 몇 개인가?","d":"㉠ 사법경찰관은 스토킹행위 신고와 관련하여 스토킹행위가 지속적 또는 반복적으로 행하여질 우려가 있고 스토킹범죄의 예방을 위하여 긴급을 요하는 경우, 스토킹행위자에게 직권 으로 또는 스토킹행위의 상대방이나 그 법정대리인 또는 스토킹행위를 신고한 사람의 요청에 의하여, 스토킹행위의 상대방이나 그 주거등으로부터 100미터 이내의 접근 금지, 전기통신기본법 제2조 제1호의 전기통신을 이용한 접근 금지 등의 조치를 할 수 있다. ㉡ 사법경찰관은 긴급응급조치를 하였을 때에는 지체 없이 검사 에게 해당 긴급응급조치에 대한 사후승인을 지방법원 판사에게 청구하여 줄 것을 신청하여야 하며, 신청을 받은 검사는 긴급 응급조치가 있었던 때부터 48시간 이내에 지방법원 판사에게 해당 긴급응급조치에 대한 사후승인을 청구한다. ㉢ 긴급응급조치기간은 1개월을 초과할 수 없다. ㉣ 법원은 스토킹범죄의 원활한 조사 심리 또는 피해자 보호를 위하여 잠정조치가 필요하다고 인정하는 경우에는 결정으로 스토킹행위자를 경찰관서의 유치장 또는 구치소에 1개월을 초과하지 않는 범위에서 유치할 수 있다. 다만 법원은 피해자의 보호를 위하여 그 기간을 연장할 필요가 있다고 인정하는 경우에는 결정으로 2개월의 범위에서 연장할 수 있다.","o":["1개","2개","3개","4개"],"a":3}},{"y":2022,"e":"경찰 공채","qn":36,"i":"PO2022_2-36","t":"실종아동등의 보호 및 지원에 관한 법률 과 실종아동등 및 가출인 업무처리 규칙 에 관한 설명 중 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"실종아동등의 보호 및 지원에 관한 법률 과 실종아동등 및 가출인 업무처리 규칙 에 관한 설명 중 옳은 것은 모두 몇 개인가?","d":"㉠ ‘장기실종아동등’이라 함은 보호자로부터 이탈한지 48시간이 경과한 후에도 발견되지 않은 ‘찾는실종아동등’을 말한다. ㉡ 경찰관서의 장은 실종아동등의 발생 신고를 접수하면 24시간 이내에 수색 또는 수사의 실시여부를 결정하여야 한다. ㉢ 발견된 18세 미만 아동 및 가출인의 경우, 실종아동등 프로 파일링시스템에 등록된 자료는 수배 해제 후로부터 10년간 보관한다. ㉣ 실종아동등 프로파일링시스템에 등록된 미발견자의 자료는 소재 발견시까지 보관한다. ㉤ 경찰관서의 장은 실종아동등에 대하여 실종아동등 및 가출인 업무처리 규칙 제18조에 따른 현장 탐문 및 수색 후, 그 결과를 즉시 보호자에게 통보하여야 한다. 이후에는 실종 아동등 프로파일링시스템에 등록한 날로부터 1개월까지는 15일에 1회, 1개월이 경과한 후부터는 분기별 1회 보호자에게 추적 진행사항을 통보한다.","o":["1개","2개","3개","4개 - 17 -"],"a":2}},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_1-09-1","t":"초기 화이트칼라범죄를 정의한 학자는 서덜랜드(Sutherland)이다.","ox":"O","m":"①","c":"A","tp":"화이트칼라범죄(white-collar crimes)"},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_1-09-2","t":"화이트칼라범죄는 직업활동과 관련하여 높은 지위를 가지고 있는 사람에 의해 저질러지는 범죄이다.","ox":"O","m":"②","c":"A","tp":"화이트칼라범죄(white-collar crimes)"},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_1-09-3","t":"일반적으로 살인·강도·강간범죄는 화이트칼라범죄로 분류된다.","ox":"X","m":"③","c":"A","tp":"화이트칼라범죄(white-collar crimes)"},{"y":2023,"e":"경찰 공채","qn":9,"i":"PO2023_1-09-4","t":"화이트칼라범죄는 상류계층의 경제범죄에 대한 사회적 심각성을 연구하는 과정에서 등장한 개념이다.","ox":"O","m":"④","c":"A","tp":"화이트칼라범죄(white-collar crimes)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_1-10-1","t":"CPTED는 근본적이고 효과적인 범죄예방을 위한 방안으로 물리적 환경설계 또는 재설계를 통해 범죄 기회를 차단하는 것이 핵심이다.","ox":"O","m":"①","c":"A","tp":"환경설계를 통한 범죄예방(CPTED)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_1-10-2","t":"‘자연적 감시(natural surveillance)’는 건축물이나 시설물의 설계시 가시권을 확보하여 외부침입에 대한 감시기능을 확대함으로써 범죄행위 발견 가능성을 증가시켜 범죄의 기회를 감소시킬 수 있다는 원리이다.","ox":"O","m":"②","c":"A","tp":"환경설계를 통한 범죄예방(CPTED)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_1-10-3","t":"‘영역성 강화(territorial reinforcement)’는 사적공간에 대한 경계 표시로 주민들의 책임의식과 소유의식을 증대함으로써 사적공간에 대한 관리권과 권리를 강화시키는 원리이다.","ox":"O","m":"③","c":"A","tp":"환경설계를 통한 범죄예방(CPTED)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_1-10-4","t":"‘유지·관리(maintenance and management)’는 차단기, 방범창, 잠금장치의 파손을 수리하지 않고 유지하는 원리이다.","ox":"X","m":"④","c":"A","tp":"환경설계를 통한 범죄예방(CPTED)"},{"y":2023,"e":"경찰 공채","qn":11,"i":"PO2023_1-11-1","t":"사소한 무질서에 관대하게 대응했던 전통적 경찰활동의 전략을 계승하였다.","ox":"X","m":"①","c":"A","tp":"무관용 경찰활동(Zero Tolerance Policing)"},{"y":2023,"e":"경찰 공채","qn":11,"i":"PO2023_1-11-2","t":"무관용 경찰활동은 1990년대 뉴욕에서 본격적으로 시행되었다.","ox":"O","m":"②","c":"A","tp":"무관용 경찰활동(Zero Tolerance Policing)"},{"y":2023,"e":"경찰 공채","qn":11,"i":"PO2023_1-11-3","t":"윌슨(Wilson)과 켈링(Kelling)의 ‘깨어진 창 이론’에 기초하였다.","ox":"O","m":"③","c":"A","tp":"무관용 경찰활동(Zero Tolerance Policing)"},{"y":2023,"e":"경찰 공채","qn":11,"i":"PO2023_1-11-4","t":"경미한 비행자에 대한 무관용 개입은 낙인효과를 유발할 수 있다는 비판이 있다. 【경 찰학】(일반공채·101경비단·경행 경채)","ox":"O","m":"④","c":"A","tp":"무관용 경찰활동(Zero Tolerance Policing)"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_1-12-1","t":"경찰과 시민 모두 지역문제 해결을 위한 치안주체로서 인정하고 협력을 강조한다.","ox":"O","m":"①","c":"A","tp":"지역사회 경찰활동(COP)"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_1-12-2","t":"업무평가의 주요한 척도는 사전예방을 강조한 범죄나 무질서의 감소율이다.","ox":"O","m":"②","c":"A","tp":"지역사회 경찰활동(COP)"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_1-12-3","t":"프로그램으로는 전략지향적 경찰활동(Strategy Oriented Policing : SOP), 이웃지향적 경찰활동(Neighborhood Oriented Policing : NOP) 등이 있다.","ox":"O","m":"③","c":"A","tp":"지역사회 경찰활동(COP)"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_1-12-4","t":"범죄신고에 대한 출동소요시간을 바탕으로 효과성을 평가한다.","ox":"X","m":"④","c":"A","tp":"지역사회 경찰활동(COP)"},{"y":2023,"e":"경찰 공채","qn":34,"i":"PO2023_1-34","t":"｢경범죄 처벌법｣ 상 다음 () 안에 들어갈 숫자로 알맞은 것은?","c":"A","mc":{"s":"｢경범죄 처벌법｣ 상 다음 () 안에 들어갈 숫자로 알맞은 것은?","d":"㉠ 출판물의 부당게재 등 - 올바르지 아니한 이익을 얻을 목적으로 다른 사람 또는 단체의 사업이나 사사로운 일에 관하여 신문, 잡지, 그 밖의 출판물에 어떤 사항을 싣거나 싣지 아니할 것을 약속하고 돈이나 물건을 받은 사람은 (가) 만원 이하의 벌금, 구류 또는 과료의 형으로 처벌한다. ㉡ 거짓 광고 - 여러 사람에게 물품을 팔거나 나누어 주거나 일을 해주면서 다른 사람을 속이거나 잘못 알게 할 만한 사실을 들어 광고한 사람은 (나)만원 이하의 벌금, 구류 또는 과료의 형으로 처벌한다. ㉢ 업무방해 - 못된 장난 등으로 다른 사람, 단체 또는 공무 수행 중인 자의 업무를 방해한 사람은 (다)만원 이하의 벌금, 구류 또는 과료의 형으로 처벌한다. ㉣ 암표매매 - 흥행장, 경기장, 역, 나루터, 정류장, 그 밖에 정하여진 요금을 받고 입장시키거나 승차 또는 승선시키는 곳에서 웃돈을 받고 입장권･ 승차권 또는 승선권을 다른 사람에게 되판 사람은 (라)만원 이하의 벌금, 구류 또는 과료의 형으로 처벌한다. (가) (나) (다) (라)","o":["10 20 60 20","20 20 20 20","20 10 60 20","20 60 20 10"],"a":2}},{"y":2023,"e":"경찰 공채","qn":36,"i":"PO2023_1-36","t":"｢가정폭력범죄의 처벌 등에 관한 특례법｣ 상 가정폭력범죄에 대해 사법경찰관이 취할 수 있는 긴급임시조치로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢가정폭력범죄의 처벌 등에 관한 특례법｣ 상 가정폭력범죄에 대해 사법경찰관이 취할 수 있는 긴급임시조치로 가장 적절하지 않은 것은?","d":"","o":["국가경찰관서의 유치장 또는 구치소에의 유치","피해자 또는 가정구성원이나 그 주거･ 직장 등에서 100미터 이내의 접근금지","피해자 또는 가정구성원의 주거 또는 점유하는 방실로부터의 퇴거 등 격리","피해자 또는 가정구성원에 대한 ｢전기통신기본법｣ 제2조 제1호의 전기통신을 이용한 접근금지"],"a":1}},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_2-10-1","t":"범죄가 자주 발생하는 지점에 경찰력을 집중적으로 배치하여 범죄예방효과를 극대화하는 데 중점을 둔다.","ox":"X","m":"①","c":"A","tp":"‘지역사회경찰활동’(Community Policing)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_2-10-2","t":"경찰활동의 목적과 우선순위를 결정할 때 시민의 참여가 중요하다.","ox":"O","m":"②","c":"A","tp":"‘지역사회경찰활동’(Community Policing)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_2-10-3","t":"사후적 대응보다 사전적 예방 중심의 경찰활동 전개에 주력한다.","ox":"O","m":"③","c":"A","tp":"‘지역사회경찰활동’(Community Policing)"},{"y":2023,"e":"경찰 공채","qn":10,"i":"PO2023_2-10-4","t":"경찰은 지역사회 내 지방자치단체, 학교 등 공적 주체들은 물론 시민단체 등 사적 주체들과도 파트너십을 형성할 필요가 있다.","ox":"O","m":"④","c":"A","tp":"‘지역사회경찰활동’(Community Policing)"},{"y":2023,"e":"경찰 공채","qn":11,"i":"PO2023_2-11","t":"다음은 경찰이 수행하는 범죄예방활동 사례(","c":"A","mc":{"s":"다음은 경찰이 수행하는 범죄예방활동 사례(","d":"<보기 1>)와 톤리와 패링턴(Tonry & Farrington)의 구분에 따른 범죄예방 전략 유형(<보기 2>)이다. <보기 1>과 <보기 2>의 내용이 가장 적절하게 연결된 것은? <보 기 1> (가) 경찰서의 여성청소년 담당부서에서 운영하고 있는 학교전담 경찰관(SPO)은 학교에 배치되어 학교폭력예방교육 등 학교 폭력 관련 예방과 가해학생 선도 등 사후관리 역할을 담당하고, 학대예방경찰관(APO)은 미취학 혹은 장기결석 아동에 대해 점검하고 학대피해 우려가 높은 아동에 대해 지속적으로 모니터링을 실시함으로써 아동학대의 위험성을 감소시키고 아동의 안전 등을 확인하는 역할을 담당하고 있다. (나) 여성 1인 가구 밀집지역에 대한 경찰순찰을 확대함으로써 공식적 감시기능을 강화하거나 혹은 아파트 입구 현관문에 반사경을 부착함으로써 출입자의 익명성을 감소시켜 범행에 수반되는 발각 위험을 증대하기 위한 조치를 취하고 있다. (다) 위법행위에 대한 단속을 강화하는 무관용 경찰활동을 지향함으로써 처벌의 확실성을 높여 범죄를 억제하고자 노력하고 있다. <보 기 2> ㉠ 상황적 범죄예방 ㉡ 지역사회 기반 범죄예방 ㉢ 발달적 범죄예방 ㉣ 법집행을 통한 범죄억제 (가) (나) (다)","o":["㉡ ㉣ ㉠","㉢ ㉡ ㉣","㉡ ㉢ ㉠","㉢ ㉠ ㉣"],"a":4}},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_2-12-1","t":"조사단계(scanning)는 일반적으로 지역사회에서 일회적으로 발생하지만 대중의 이목을 집중시키는 심각한 중대범죄 사건을 우선적으로 조사대상화하는 데에서 출발한다.","ox":"X","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_2-12-2","t":"분석단계(analysis)에서는 각종 통계자료 등 수집된 자료를 활용하여 심층적인 분석을 실시하며, 당면 문제의 성격을 정확하게 파악하기 위해 문제분석 삼각모형(problem analysis triangle)을 유용한 분석도구로 활용할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_2-12-3","t":"대응단계(response)에서는 경찰이 보유한 자원과 역량만으로는 한계가 있으므로 지역사회 내의 여러 다른 기관들과의 협력을 통한 대응방안을 추구하며, 상황적 범죄예방에서 제시하는 25가지 범죄예방기술을 적용해 볼 수도 있다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":12,"i":"PO2023_2-12-4","t":"평가단계(assessment)는 과정평가와 효과평가의 두 단계로 구성되며, 이전 문제해결과정에의 환류를 통해 각 단계가 지속적인 순환 과정으로 작동할 수 있도록 한다는 점에서 중요한 의미를 가진다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":34,"i":"PO2023_2-34-1","t":"경찰청장은 인구, 면적, 행정구역, 교통·지리적 여건, 각종 사건사고 발생 등을 고려하여 경찰서의 관할구역을 나누어 지역경찰관서를 설치한다.","ox":"X","m":"①","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":34,"i":"PO2023_2-34-2","t":"순찰팀은 범죄예방 순찰, 각종 사건사고에 대한 초동조치 등 현장 치안활동을 담당한다.","ox":"O","m":"②","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":34,"i":"PO2023_2-34-3","t":"지역경찰관서장은 지역경찰관서의 운영에 관하여 총괄 지휘·감독한다.","ox":"X","m":"③","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":34,"i":"PO2023_2-34-4","t":"「지역경찰의 조직 및 운영에 관한 규칙」 제23조는 “행정근무를 지정받은 지역경찰은 지역경찰관서 및 치안센터 내에서 방문 민원 및 각종 신고사건의 접수 및 처리업무를 수행한다.”라고 규정하고 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":36,"i":"PO2023_2-36","t":"｢아동학대범죄의 처벌 등에 관한 특례법｣ 상 사법경찰관의 긴급임시조치로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢아동학대범죄의 처벌 등에 관한 특례법｣ 상 사법경찰관의 긴급임시조치로 가장 적절하지 않은 것은?","d":"","o":["피해아동등 또는 가정구성원의 주거로부터 퇴거 등 격리","경찰관서의 유치장 또는 구치소에의 유치","피해아동등 또는 가정구성원의 주거, 학교 또는 보호시설 등 에서 100미터 이내의 접근 금지","피해아동등 또는 가정구성원에 대한 ｢전기통신기본법｣ 제2조 제1호의 전기통신을 이용한 접근 금지"],"a":2}},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_1-08-1","t":"뒤르켐(Durkheim)은 사회규범이 붕괴되어 규범에 대한 억제력이 상실된 상태를 아노미(Anomie)라고 하고 이러한 무규범상태에서 범죄가 발생한다고 주장하였다.","ox":"O","m":"①","c":"A","tp":"범죄 원인"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_1-08-2","t":"글레이저(Glaser)는 차별적 동일시이론을 통해 범죄의 원인이 개인이 아닌 사회구조의 변화에 있다고 설명하였다.","ox":"X","m":"②","c":"A","tp":"범죄 원인"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_1-08-3","t":"탄넨바움(Tannenbaum)은 낙인이론을 통해 범죄자라는 낙인이 어떠한 결과를 낳는가에 관심을 가졌다.","ox":"O","m":"③","c":"A","tp":"범죄 원인"},{"y":2024,"e":"경찰 공채","qn":8,"i":"PO2024_1-08-4","t":"코헨(Cohen)은 목표와 수단이 괴리된 하류계층 청소년들이 중산층에 대한 저항으로 비행을 저지르며 목표달성의 어려움을 극복하기 위해 자신들의 하위문화를 만들게 된다고 주장하였다.","ox":"O","m":"④","c":"A","tp":"범죄 원인"},{"y":2024,"e":"경찰 공채","qn":9,"i":"PO2024_1-09","t":"고전주의 범죄학의 억제이론(Deterrence Theory)은 베카리아 (Beccaria)와 벤담(Bentham)의 주장에 근거한다. 기본전제는 인간이 자유의지를 가지고 합리적인 판단에 의해 행동한다는 것이다. 이를 기반으로 한 처벌은 계량된 처벌의 고통과 범죄로 인한 이익 사이의 함수관계로 설명되는데 이 이론의 핵심적인 내용에 해당되는 것은?","c":"A","mc":{"s":"고전주의 범죄학의 억제이론(Deterrence Theory)은 베카리아 (Beccaria)와 벤담(Bentham)의 주장에 근거한다. 기본전제는 인간이 자유의지를 가지고 합리적인 판단에 의해 행동한다는 것이다. 이를 기반으로 한 처벌은 계량된 처벌의 고통과 범죄로 인한 이익 사이의 함수관계로 설명되는데 이 이론의 핵심적인 내용에 해당되는 것은?","d":"","o":["처벌의 확실성, 처벌의 엄격성, 처벌의 신속성","처벌의 확실성, 처벌의 엄격성, 처벌의 신중성","처벌의 엄격성, 처벌의 신속성, 처벌의 신중성","처벌의 엄격성, 처벌의 신속성, 처벌의 지속성 【경 찰 학】 - 13 -"],"a":1}},{"y":2024,"e":"경찰 공채","qn":10,"i":"PO2024_1-10-1","t":"일상활동이론(Routine Activity Theory), 합리적 선택이론 (Rati onal Choi ce Theory), 범죄패턴이론(Cri me Pattern Theory) 등은 상황적 범죄예방(Situational Crime Prevention)의 중요한 이론적 배경이 되고 있다.","ox":"O","m":"①","c":"A","tp":"범죄예방이론"},{"y":2024,"e":"경찰 공채","qn":10,"i":"PO2024_1-10-2","t":"환경설계를 통한 범죄예방(CPTED: Crime Preventi on Through Environmental Design)은 물리적 환경설계 또는 재설계를 통해 범죄기회를 차단하고 시민의 범죄에 대한 불안을 감소시키는 전략이다.","ox":"O","m":"②","c":"A","tp":"범죄예방이론"},{"y":2024,"e":"경찰 공채","qn":10,"i":"PO2024_1-10-3","t":"특별예방이론이 잠재적 범죄자인 일반인에 대한 형벌의 예방 기능을 강조한 것이라면, 일반예방이론은 형벌을 구체적인 범죄자 개인에 대한 영향력의 행사라고 보고, 범죄자를 교화함으로써 재범하지 않도록 하는 것이다.","ox":"X","m":"③","c":"A","tp":"범죄예방이론"},{"y":2024,"e":"경찰 공채","qn":10,"i":"PO2024_1-10-4","t":"범죄예방에 질병의 예방과 치료의 개념을 도입하여 소개한 브랜팅햄(P. J. Brantingham)과 파우스트(F. L. Faust)는 범죄 예방을 1차적 범죄예방, 2차적 범죄예방, 3차적 범죄예방으로 나누고 있다. 1차적 범죄예방은 일반대중, 2차적 범죄예방은 범죄우범자나 집단, 그리고 3차적 범죄예방은 범죄자가 주요 대상이라고 할 수 있다.","ox":"O","m":"④","c":"A","tp":"범죄예방이론"},{"y":2024,"e":"경찰 공채","qn":11,"i":"PO2024_1-11","t":"멘델존(Mendelsohn)의 피해자 유형 분류 중 가해자와 같은 정도의 책임이 있는 피해자에 해당하는 사례로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"멘델존(Mendelsohn)의 피해자 유형 분류 중 가해자와 같은 정도의 책임이 있는 피해자에 해당하는 사례로 가장 적절하지 않은 것은?","d":"","o":["동반자살 피해자","부모에게 살해된 패륜아","자살미수 피해자","촉탁살인에 의한 피살자"],"a":2}},{"y":2024,"e":"경찰 공채","qn":12,"i":"PO2024_1-12","t":"지역사회경찰활동의 구성요소에 관한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"지역사회경찰활동의 구성요소에 관한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["지역중심적 경찰활동(COP: Community Oriented Policing) - 지역사회에서의 전반적인 삶의 질 향상을 목표로, 지역사회와 경찰 사이의 새로운 관계를 증진시키는 조직적인 전략원리를 말한다.","전략지향적 경찰활동(SOP: Strategic Oriented Policing) - 확인된 문제에 대한 전략적 대응을 위해 경찰자원을 배분하고, 전통적인 경찰활동과 절차를 통해 범죄적 요소나 사회무질서의 원인을 효과적으로 제거하는 경찰활동을 말한다.","이웃지향적 경찰활동(NOP: Neighborhood Oriented Policing) - 지역사회경찰활동을 위하여 경찰과 주민의 의사소통라인을 개설 하려는 모든 프로그램을 말한다.","문제지향적 경찰활동(POP: Problem Oriented Policing) - 지역 조직은 거주자들에게 지역에 관한 정보를 제공하며 경찰과 협동 하여 범죄를 억제하는 기능을 수행한다."],"a":4}},{"y":2024,"e":"경찰 공채","qn":37,"i":"PO2024_1-37","t":"｢가정폭력범죄의 처벌 등에 관한 특례법｣ 상 가정폭력범죄에 해당하지 않는 것은?","c":"A","mc":{"s":"｢가정폭력범죄의 처벌 등에 관한 특례법｣ 상 가정폭력범죄에 해당하지 않는 것은?","d":"","o":["甲의 아버지가 甲의 명예를 훼손한 경우","乙의 계모였던 사람이 乙의 재물을 손괴한 경우","丙과 같이 사는 사촌동생이 丙을 약취유인한 경우","丁이 이혼한 전 부인을 강간한 경우"],"a":3}},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_2-03-1","t":"조사단계(Scanning)는 지역에서 반복적으로 발생하고 있는 문제를 파악하는 데에서 출발하여 문제라고 여겨지는 개인과 관련된 사건을 분류하고, 정확하고 유용한 용어를 활용하여 이러한 문제를 조사한다.","ox":"O","m":"①","c":"A","tp":"문제해결과정인 ‘SARA 모형’"},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_2-03-2","t":"분석단계(Analysis)는 지역사회와 경찰이 협력하는 등의 방법으로 문제의 원인을 파악하고, 분석하는 단계이다.","ox":"O","m":"②","c":"A","tp":"문제해결과정인 ‘SARA 모형’"},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_2-03-3","t":"대응단계(Response)는 경찰이 보유한 자원과 역량만으로는 한계가 있기 때문에 경찰관은 지역사회 내의 여러 다른 기관들과 협력을 통한 대응방안을 추구한다.","ox":"O","m":"③","c":"A","tp":"문제해결과정인 ‘SARA 모형’"},{"y":2024,"e":"경찰 공채","qn":3,"i":"PO2024_2-03-4","t":"평가단계(Assessment)는 대응의 적절성을 평가하며, 효과평가와 결과평가의 두 단계로 이루어진다.","ox":"X","m":"④","c":"A","tp":"문제해결과정인 ‘SARA 모형’"},{"y":2024,"e":"경찰 공채","qn":11,"i":"PO2024_2-11-1","t":"접근통제(Access control) 전략의 주요 기능은 보행로, 조경 등을 통해 일정 공간으로 유도함과 동시에 허가받지 않은 사람들의 진·출입을 차단하여 목표물로의 접근을 막고 대상물의 강화를 통해 범죄자에게 심리적 부담과 위험을 인지시키는 것이다.","ox":"O","m":"①","c":"A"},{"y":2024,"e":"경찰 공채","qn":11,"i":"PO2024_2-11-2","t":"영역성(Territoriality) 전략의 물리적 디자인은 사용자들이 소유권과 점유권의 개념을 발전시키고 잠재적 범죄자들은 영역성의 영향을 인지하게 되어 정당한 사용자들의 권리와 재산권에 대한 관념을 강화하는 개념이다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"경찰 공채","qn":11,"i":"PO2024_2-11-3","t":"자연적 감시(Natural surveillance) 전략은 공공장소의 활발한 사용을 유도하여 일상활동의 활성화를 위해 거리에 더 많은 눈(more eyes)을 통해 자연스러운 감시 기능을 강화하여 범죄 위험을 감소시키고 주민들의 안전감을 향상시키는 것이다.","ox":"X","m":"③","c":"A"},{"y":2024,"e":"경찰 공채","qn":11,"i":"PO2024_2-11-4","t":"유지관리(Maintenance) 전략은 어떤 시설물이나 공공장소를 처음 디자인하거나 이를 개선한 의도대로 범죄예방 기능을 지속적으로 발휘하도록 하여, 공간을 의도한 목적에 맞게 지속적으로 사용하도록 하는 것이다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"경찰 공채","qn":12,"i":"PO2024_2-12-1","t":"사람들을 ‘잠재적 범죄자’로 간주하고 사회적 결속과 유대의 약화로 인해 비행이 발생한다고 주장한다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"경찰 공채","qn":12,"i":"PO2024_2-12-2","t":"하류계층 청소년들은 ‘지위좌절’이라는 갈등의 형태를 경험 하면서 중류계층의 가치관에 대한 적대적 반응을 갖게 되고, 목표달성의 어려움을 극복하기 위해 자신들만의 하위문화를 만들게 된다고 주장한다.","ox":"O","m":"②","c":"A"},{"y":2024,"e":"경찰 공채","qn":12,"i":"PO2024_2-12-3","t":"사회규범의 붕괴로 무규범 상태가 되고 이러한 무규범 상태에서 범죄가 발생한다고 주장한다.","ox":"O","m":"③","c":"A"},{"y":2024,"e":"경찰 공채","qn":12,"i":"PO2024_2-12-4","t":"산업화 및 도시화 과정에서 그 지역의 사회조직이 극도로 해체 되었기 때문에 범죄와 비행이 발생한다고 주장한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"경찰 공채","qn":13,"i":"PO2024_2-13","t":"지역사회 경찰활동에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"지역사회 경찰활동에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"㉠ 이웃지향적 경찰활동(NOP)은 경찰과 지역주민 사이에 좋은 관계를 유지하고 경찰활동을 널리 지역주민에게 이해시키고, 범죄예방활동에 지역주민을 적극적으로 참여시켜 협력해 주도록 하는 경찰활동을 말한다. ㉡ 문제지향적 경찰활동(POP)은 반복된 사건을 야기하는 근본적인 원인을 해결해야 한다고 주장하며, 현장 경찰관에게 자유재량을 부여하고, 범죄분석자료를 제공, 대중정보와 비평을 적극적으로 수용한다. ㉢ 전략지향적 경찰활동(SOP)은 치안유지를 위한 각 기관들의 정보 취합과 활용 그리고 지역사회 참여를 업무 처리 방식의 틀로 사용하고, 사건 분석을 위해 지리정보시스템을 활용하여 분석 기법을 사용한 법집행 위주의 경찰활동이다. ㉣ 증거기반 경찰활동(evidence-based policing)은 경찰정책과 의사결정에 있어서 과학적･ 의학적 증거에 기반하여 증거의 개발, 검토, 활용을 위해 경찰관 및 직원이 연구기관과 함께 활동하는 접근방법이다.","o":["㉠㉡","㉠㉢","㉡㉣","㉢㉣"],"a":3}},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_2-26-1","t":"경찰청장, 시·도경찰청장 및 경찰서장(이하 “경찰청장등”이라 한다)은 112신고를 받으면 「경찰관 직무집행법」 제2조에 따른 경찰사무의 구분이나 현장 출동이 필요한 지역의 관할의 관계를 고려하여 해당 112신고를 신속하게 접수하여 처리하여야 한다.","ox":"X","m":"①","c":"A","tp":"112신고의 운영 및 처리"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_2-26-2","t":"경찰청장등은 112신고를 처리하는 과정에서 재난·재해, 범죄 또는 그 밖의 위급한 상황이 발생하여 사람의 생명·신체를 위험 하게 할 것으로 인정할 때에는 일정한 구역을 정하여 그 구역에 있는 사람에게 그 구역 밖으로 피난할 것을 명할 수 있다.","ox":"O","m":"②","c":"A","tp":"112신고의 운영 및 처리"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_2-26-3","t":"112치안종합상황실은 경찰청, 시·도경찰청 및 경찰서에 설치한다.","ox":"O","m":"③","c":"A","tp":"112신고의 운영 및 처리"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_2-26-4","t":"112신고 접수 및 처리와 관련된 112시스템 입력자료는 3년간 보존한다. 다만, 단순 민원·상담 등 경찰청장이 정하는 경미한 내용의 112신고의 경우에는 1년으로 한다.","ox":"O","m":"④","c":"A","tp":"112신고의 운영 및 처리"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_2-35-1","t":"인터넷 중고거래 사이트를 통해 비대면으로 웃돈을 받고 유명 가수의 콘서트 티켓을 되판 사람은 이 법상 암표매매로 처벌된다.","ox":"X","m":"①","c":"A","tp":"경범죄 처벌법"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_2-35-2","t":"있지 아니한 범죄나 재해 사실을 공무원에게 거짓으로 신고한 사람은 주거가 분명하여도 현행범으로 체포할 수 있다.","ox":"O","m":"②","c":"A","tp":"경범죄 처벌법"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_2-35-3","t":"피해자가 있는 범칙행위를 한 사람은 범칙자에 해당하지 아니한다.","ox":"O","m":"③","c":"A","tp":"경범죄 처벌법"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_2-35-4","t":"주거 또는 신원이 확실하지 아니한 사람에게는 통고처분을 하지 아니한다.","ox":"O","m":"④","c":"A","tp":"경범죄 처벌법"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_1-05-1","t":"깨진 유리창 이론에 따르면 사소한 무질서라도 그대로 방치할 경우 주민들의 범죄에 대한 두려움이 증가하거나 범죄와 무질서가 더욱 심각해질 수 있다고 보기 때문에 낙인효과를 최소화하기 위한 무관용 경찰활동이 필요하다.","ox":"X","m":"①","c":"A","tp":"현대적 범죄예방이론"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_1-05-2","t":"일상활동이론에 의하면 범죄자가 범행을 결정하는 데 고려하는 4가지 요소(VIVA 모델)에는 대상의 가치(Value), 이동의 용이성 (Inertia), 가시성(Visibility), 보호자의 부재(Absence)가 있다.","ox":"X","m":"②","c":"A","tp":"현대적 범죄예방이론"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_1-05-3","t":"환경설계를 통한 범죄예방(CPTED) 전략은 제프리(C. R. Jeffery)의 범죄통제모델 3가지 중 범죄억제모델에 해당한다.","ox":"X","m":"③","c":"A","tp":"현대적 범죄예방이론"},{"y":2025,"e":"경찰 공채","qn":5,"i":"PO2025_1-05-4","t":"상황적 범죄예방이론의 경우 범죄를 예방하는 장치 또는 수단을 통해 범죄 기회를 줄여도, 풍선효과에 따라 범죄가 다른 곳으로 전이되어 결국 전체 범죄는 감소하지 않는다는 비판이 제기된다.","ox":"O","m":"④","c":"A","tp":"현대적 범죄예방이론"},{"y":2025,"e":"경찰 공채","qn":7,"i":"PO2025_1-07","t":"다음은 브랜팅햄(P. J. Brantingham)과 파우스트(F. L. Faust)의 3가지 범죄예방 접근법에 관한 내용이다.","c":"A","mc":{"s":"다음은 브랜팅햄(P. J. Brantingham)과 파우스트(F. L. Faust)의 3가지 범죄예방 접근법에 관한 내용이다.","d":"<보기 1>과 <보기 2>의 연결이 가장 적절한 것은? <보기 1> 주요대상 가. 범죄자 나. 우범자 다. 일반대중 <보기 2> 예방전략 및 내용 ㉠ 상습범 대책을 수립하거나 재범을 방지하는 전략 ㉡ 잠재적 범죄자를 초기에 발견하여 개입하는 전략 ㉢ 물리적·사회적 환경 중에서 범죄의 기회를 제공하는 원인 또는 조건을 찾아 개입하는 전략 ㉣ 지역사회 교정프로그램 ㉤ CCTV\n·비상벨 설치","o":["가 - ㉠, ㉣","나 - ㉢, ㉤","다 - ㉡, ㉣","다 - ㉡, ㉤"],"a":1}},{"y":2025,"e":"경찰 공채","qn":8,"i":"PO2025_1-08","t":"사이크스와 맛짜(Sykes & Matza)의 중화기술이론에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"사이크스와 맛짜(Sykes & Matza)의 중화기술이론에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["사회구조원인론 중에서도 사회학습이론에 해당하는 중화기술 이론은 인간에게 내면화되어 있는 합법적 규범이나 가치관을 중화시킴으로써 범죄에 이르게 된다는 이론을 말한다.","친구에게 돈을 빌려주었는데 돈을 갚지 않자 벌을 받아야 하는 사람이라고 정당화하며 폭력을 행사한 경우 ‘피해자의 부정’에 해당한다.","돈을 훔친 자신의 행위에 대해 “그들은 돈이 많으니 괜찮아” 라고 합리화하는 것은 ‘피해의 부정’에 해당한다.","중화기술이론은 비행청소년이 범행 전후를 기준으로 언제 중화를 하는지 설명이 어렵고, 설령 비행행위 이전에 중화를 한다고 주장하여도 이후 비행으로 나아가는 청소년과 그렇지 않은 청소년 간의 개인적 차이를 설명하지 못한다는 비판이 제기되고 있다. 【경 찰 학】 - 13 -"],"a":1}},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_1-09-1","t":"‘지역사회 경찰활동’은 이미 발생한 범죄를 사후 진압 및 검거 하는 역할에서 벗어나 사전적 예방과 지역사회 문제를 해결하는 문제해결자로서의 경찰 역할을 강조한다.","ox":"O","m":"①","c":"A","tp":"‘지역사회 경찰활동(Community Policing)’"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_1-09-2","t":"‘이웃 지향적 경찰활동’은 범죄 발생 원인에 대해 비공식적 사회통제의 약화 및 경제적 궁핍이 소외를 정당화하기 때문 이라고 보아, 경찰과 주민과의 의사소통 라인을 개방하고 서로를 위해 감시하는 민간순찰을 강조한다.","ox":"O","m":"②","c":"A","tp":"‘지역사회 경찰활동(Community Policing)’"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_1-09-3","t":"‘전략 지향적 경찰활동’은 전통적 관행과 절차를 배제하여 범죄 요인이나 사회 무질서의 원인을 제거하기 위해 경찰자원을 재분배하고 범죄나 무질서를 예방하는 경찰활동을 말한다.","ox":"X","m":"③","c":"A","tp":"‘지역사회 경찰활동(Community Policing)’"},{"y":2025,"e":"경찰 공채","qn":9,"i":"PO2025_1-09-4","t":"‘정보기반 경찰활동’은 경찰의 효과성 향상을 위한 전략으로 범죄자 정보 및 분석기법을 활용한 법집행 위주의 경찰활동을 말한다.","ox":"O","m":"④","c":"A","tp":"‘지역사회 경찰활동(Community Policing)’"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_1-10-1","t":"순찰은 노선에 따라 정선순찰, 난선순찰, 요점순찰, 구역순찰 등으로 구분할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_1-10-2","t":"캔자스(Kansas)시 예방순찰실험의 경우 도보순찰을 증가시켜도 실제 범죄는 감소하지 않아 도보순찰과 범죄율의 연관성에 대해 부정하는 결과가 도출되었다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_1-10-3","t":"플린트(Flint)시 도보순찰실험의 경우 도보순찰을 증가시켜도 실제 범죄는 감소하지 않았으나 오히려 시민들은 안전하다고 느꼈다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"경찰 공채","qn":10,"i":"PO2025_1-10-4","t":"해일(C. D. Hale)과 워커(S. Walker)는 순찰의 기능에 대민서비스 제공을 공통적으로 포함시켰다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":33,"i":"PO2025_1-33","t":"｢112신고의 운영 및 처리에 관한 법률｣ 및 동법 시행령상 ‘출동 현장의 촬영‧ 관리’에 관한 설명이다. 아래 ㉠, ㉡에 들어갈 내용으로 가장 적절한 것은?","c":"A","mc":{"s":"｢112신고의 운영 및 처리에 관한 법률｣ 및 동법 시행령상 ‘출동 현장의 촬영‧ 관리’에 관한 설명이다. 아래 ㉠, ㉡에 들어갈 내용으로 가장 적절한 것은?","d":"경찰청장등은 ｢112신고의 운영 및 처리에 관한 법률｣ 제11조 제1항에 따라 경찰차량 또는 무인비행장치에 영상촬영장치를 설치하거나 경찰관이 영상촬영장치를 착용 또는 휴대하도록 하여 출동 현장을 촬영할 수 있다. 이에 따라 수집된 영상정보의 보관기간은 촬영일부터 (㉠)일로 한다. 다만, 범죄 수사를 위해 영상정보의 보관이 필요한 경우 등 경찰청장등이 필요하다고 인정하는 경우에는 (㉡)일의 범위에서 보관기간을 연장할 수 있다. ㉠ ㉡ ㉠ ㉡","o":["20 20","20 30","30 30","30 60"],"a":3}},{"y":2025,"e":"경찰 공채","qn":34,"i":"PO2025_1-34","t":"｢풍속영업의 규제에 관한 법률｣ 상 풍속영업을 하는 자 및 대통령령으로 정하는 종사자가 풍속영업을 하는 장소에서 하여서는 아니 되는 행위로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢풍속영업의 규제에 관한 법률｣ 상 풍속영업을 하는 자 및 대통령령으로 정하는 종사자가 풍속영업을 하는 장소에서 하여서는 아니 되는 행위로 가장 적절하지 않은 것은?","d":"","o":["｢성매매알선 등 행위의 처벌에 관한 법률｣ 제2조 제1항 제2호에 따른 성매매알선등행위","음란행위를 하게 하거나 이를 알선 또는 제공하는 행위","음란한 문서‧ 도화‧ 영화‧ 음반‧ 비디오물, 그 밖의 음란한 물건에 대한 제작‧ 반포‧ 판매 및 이를 알선하는 행위","도박이나 그 밖의 사행행위를 하게 하는 행위"],"a":3}},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_1-35-1","t":"「사회복지사업법」 제14조에 따른 사회복지전담공무원은 그 직무를 수행하면서 실종아동등임을 알게 되었을 때에는 「실종아동등의 보호 및 지원에 관한 법률」 제3조 제2항 제1호에 따라 경찰청장이 구축하여 운영하는 신고체계로 지체 없이 신고하여야 한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_1-35-2","t":"경찰청장은 실종아동등의 조속한 발견과 복귀를 위하여 아동 등의 보호자가 신청하는 경우 아동등의 지문 및 얼굴 등에 관한 정보를 「실종아동등의 보호 및 지원에 관한 법률」 제8조의2에 따른 정보시스템에 등록하고 아동등의 보호자에게 사전신고증을 발급할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_1-35-3","t":"경찰청장은 실종아동등의 발견을 위하여 실종아동등을 찾고자 하는 가족으로부터 유전자검사대상물을 채취할 수 있다.","ox":"O","m":"③","c":"A","tp":"실종아동등의 보호 및 지원"},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_1-35-4","t":"경찰관서의 장과 경찰관서에 종사하거나 종사하였던 자는 실종 아동등을 찾기 위한 목적으로 제공받은 개인위치정보등을 실종 아동등을 찾기 위한 목적 외의 용도로 이용하여서는 아니 되며, 경찰관서의 장은 목적을 달성하였을 때에는 1년 간 보관하여야 한다.","ox":"X","m":"④","c":"A","tp":"실종아동등의 보호 및 지원"},{"y":2025,"e":"경찰 공채","qn":11,"i":"PO2025_2-11","t":"범죄예방에 관한 설명으로 옳고 그름의 표시(O, X)가 바르게 된 것은?","c":"A","mc":{"s":"범죄예방에 관한 설명으로 옳고 그름의 표시(O, X)가 바르게 된 것은?","d":"<보기> ㉠ 브랜팅햄(Brantingham)과 파우스트(Faust)의 2차적 범죄예방은 범죄자들이 더 이상 범죄를 저지르지 못하도록 상습범 대책 및 재범억제를 지향하는 범죄예방 전략을 말하며, 교화‧ 개선‧ 전환 제도에 중점을 둔다. ㉡ 뉴먼(Newman)이 주장한 방어공간이론은 영역성, 감시, 이미지, 입지조건(환경)을 구성요소로 하고 있다. ㉢ 샘슨 등(Sampson et al.)이 주장한 집합효율성이론은 공식적 사회통제, 즉 경찰 등 법집행기관의 중요성을 간과하고 있다는 한계가 있다. ㉣ 코헨(Cohen)과 펠슨(Felson)의 일상활동이론에서는 동기가 부여된 잠재적 범죄자, 범행의 기술, 보호자(감시자)의 부재를 범행발생의 3요소로 하고 있다.","o":["","","",""],"a":4}},{"y":2025,"e":"경찰 공채","qn":12,"i":"PO2025_2-12-1","t":"지역사회 경찰활동은 범죄 및 무질서에 대한 문제를 해결함에 있어서 경찰과 지역사회 양자를 참여시키는 협력관계를 중요 하게 여긴다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":12,"i":"PO2025_2-12-2","t":"지역사회 경찰활동은 지역사회와의 협력, 경찰조직의 분권화 등을 중요하게 여긴다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"경찰 공채","qn":12,"i":"PO2025_2-12-3","t":"지역사회 경찰활동 프로그램에는 경찰과 주민 사이에 의사 소통을 강화하는 이웃지향적 경찰활동이 있다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"경찰 공채","qn":12,"i":"PO2025_2-12-4","t":"지역사회 경찰활동의 효과성은 신고에 대한 경찰의 출동시간으로 결정하며, 능률성은 체포율과 적발건수로 결정한다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":34,"i":"PO2025_2-34-1","t":"화약류를 운반하려는 사람은 행정안전부령으로 정하는 바에 따라 도착지를 관할하는 경찰서장에게 신고하여야 한다. 다만, 대통령령으로 정하는 수량 이하의 화약류를 운반하는 경우에는 그러하지 아니하다.","ox":"X","m":"①","c":"A","tp":"총포･ 도검･ 화약류 등의 안전관리"},{"y":2025,"e":"경찰 공채","qn":34,"i":"PO2025_2-34-2","t":"화약류를 폐기하려는 자는 행정안전부령으로 정하는 바에 따라 그 폐기하려는 곳을 관할하는 경찰서장에게 신고하여야 한다. 다만, 제조업자가 제조과정에서 생긴 화약류를 그 제조소 안에서 폐기하는 경우에는 그러하지 아니하다.","ox":"O","m":"②","c":"A","tp":"총포･ 도검･ 화약류 등의 안전관리"},{"y":2025,"e":"경찰 공채","qn":34,"i":"PO2025_2-34-3","t":"금고 이상의 실형을 선고받고 그 집행이 끝나거나 집행을 받지 아니하기로 확정된 후 3년이 지나지 아니한 자는 총포‧ 도검‧ 화약류‧ 분사기‧ 전자충격기‧ 석궁 제조업의 허가를 받을 수 없다.","ox":"O","m":"③","c":"A","tp":"총포･ 도검･ 화약류 등의 안전관리"},{"y":2025,"e":"경찰 공채","qn":34,"i":"PO2025_2-34-4","t":"총포‧ 도검‧ 화약류‧ 분사기‧ 전자충격기‧ 석궁의 판매업을 하려는 자는 판매소마다 행정안전부령으로 정하는 바에 따라 판매소의 소재지를 관할하는 시‧ 도경찰청장의 허가를 받아야 한다.","ox":"O","m":"④","c":"A","tp":"총포･ 도검･ 화약류 등의 안전관리"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_2-36-1","t":"“아동학대행위자”란 아동학대범죄를 범한 사람 및 그 공범을 말하고, “피해아동”이란 아동학대범죄로 인하여 직접적으로 피해를 입은 아동을 말한다.","ox":"O","m":"①","c":"A","tp":"아동학대범죄의 처벌 등"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_2-36-2","t":"아동학대범죄 신고를 접수한 사법경찰관리나 아동학대전담공무원은 지체 없이 아동학대범죄의 현장에 출동하여야 한다. 이 경우 수사기관의 장이나 시‧ 도지사 또는 시장‧ 군수‧ 구청장은 서로 동행하여줄 것을 요청할수 있으며, 그 요청을 받은수사기관의 장이나 시‧ 도지사 또는 시장‧ 군수‧ 구청장은 정당한 사유가 없으면 사법경찰관리나 아동학대전담공무원이 아동학대범죄 현장에 동행하도록 조치하여야 한다.","ox":"O","m":"②","c":"A","tp":"아동학대범죄의 처벌 등"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_2-36-3","t":"사법경찰관리 또는 아동학대전담공무원이 응급조치를 한 경우에는 즉시 응급조치결과보고서를 작성하여야 한다. 이 경우 사법 경찰관리가 응급조치를 한 경우에는 관할 경찰관서의 장이 시‧ 도지사 또는 시장‧ 군수‧ 구청장에게, 아동학대전담공무원이 응급조치를 한 경우에는 소속 시‧ 도지사 또는 시장‧ 군수‧ 구청장이 관할 경찰관서의 장에게 작성된 응급조치결과보고서를 10일 이내에 송부하여야 한다.","ox":"X","m":"③","c":"A","tp":"아동학대범죄의 처벌 등"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_2-36-4","t":"“아동학대행위자를 피해아동등으로부터 격리”하는 응급조치는 72시간을 넘을 수 없다. 다만, 본문의 기간에 공휴일이나 토요일이 포함되는 경우로서 피해아동등의 보호를 위하여 필요하다고 인정되는 경우에는 48시간의 범위에서 그 기간을 연장할 수 있다.","ox":"O","m":"④","c":"A","tp":"아동학대범죄의 처벌 등"},{"y":2026,"e":"경찰 공채","qn":9,"i":"PO2026_1-09-1","t":"고전주의 범죄학에 따르면, 모든 인간은 자유의지의 합리적 행사를 통해 결정하고 행동하며, 범죄 억제를 위해서는 처벌의 엄격성, 확실성, 신속성이 필요하다고 하였다.","ox":"O","m":"①","c":"A","tp":"범죄원인론"},{"y":2026,"e":"경찰 공채","qn":9,"i":"PO2026_1-09-2","t":"허쉬(Hirschi)는 사회에 대한 개인의 유대가 약하거나 깨졌을 때 비행이나 범죄가 발생하며, 이러한 유대를 구성하는 요인으로 애착(Attachment), 전념(Commitment), 참여(Involvement), 신념(Belief)을 제시하였다.","ox":"O","m":"②","c":"A","tp":"범죄원인론"},{"y":2026,"e":"경찰 공채","qn":9,"i":"PO2026_1-09-3","t":"쇼(Shaw)와 맥케이(McKay)는 전이지역(Transitional Zone)에서 범죄 수준이 높다는 것을 발견하였으며, 이 지역은 빈곤, 민족적 동질성, 거주불안정성의 특징을 가진다고 주장한다.","ox":"X","m":"③","c":"A","tp":"범죄원인론"},{"y":2026,"e":"경찰 공채","qn":9,"i":"PO2026_1-09-4","t":"코헨(Cohen)과 펠슨(Felson)은 일상활동이론에서 범죄의 3요소로 동기가 부여된 범죄자(Motivated Offender), 적절한 범행대상 (Sui tabl e Target), 보호자의 부재(Absence of Capabl e Guardian)를 제시하였다.","ox":"O","m":"④","c":"A","tp":"범죄원인론"},{"y":2026,"e":"경찰 공채","qn":10,"i":"PO2026_1-10-1","t":"허만 골드슈타인(Herman Goldstein)은 기존의 수동적이고 사건 대응적인 전통적 경찰활동을 대체할 새로운 경찰활동 전략으로 문제지향적 경찰활동을 제시하였다.","ox":"O","m":"①","c":"A","tp":"문제지향적 경찰활동(Problem Oriented Policing)"},{"y":2026,"e":"경찰 공채","qn":10,"i":"PO2026_1-10-2","t":"문제지향적 경찰활동의 능률성은 체포율과 적발건수로, 효과성은 현장 대응 시간으로 측정될 수 있다.","ox":"X","m":"②","c":"A","tp":"문제지향적 경찰활동(Problem Oriented Policing)"},{"y":2026,"e":"경찰 공채","qn":10,"i":"PO2026_1-10-3","t":"문제해결을 위해 ‘조사(Scanning) - 분석(Analysis) - 대응 (Response) - 평가(Assessment)’의 과정을 사용한다.","ox":"O","m":"③","c":"A","tp":"문제지향적 경찰활동(Problem Oriented Policing)"},{"y":2026,"e":"경찰 공채","qn":10,"i":"PO2026_1-10-4","t":"허만 골드슈타인은 형법의 적용이 문제에 대응하기 위한 여러 대응 수단 중 하나에 불과하다고 주장하였다.","ox":"O","m":"④","c":"A","tp":"문제지향적 경찰활동(Problem Oriented Policing)"},{"y":2026,"e":"경찰 공채","qn":34,"i":"PO2026_1-34-1","t":"지역경찰관서의 순찰팀은 범죄예방 순찰, 각종 사건사고에 대한 초동조치 등 현장 치안활동을 담당하며, 팀장은 경위 또는 경사로 보한다.","ox":"X","m":"①","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":34,"i":"PO2026_1-34-2","t":"지역경찰관서의 관리팀 및 순찰팀 인원은 지역 치안수요 및 인력여건 등을 고려하여 시‧ 도경찰청장이 결정한다.","ox":"X","m":"②","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":34,"i":"PO2026_1-34-3","t":"경찰청장은 지역치안을 효율적으로 수행하기 위하여 지역경찰 관서장 소속하에 치안센터를 설치할 수 있다.","ox":"X","m":"③","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":34,"i":"PO2026_1-34-4","t":"경찰서장은 지역 치안여건 및 인원여건을 고려하여 치안센터의 운영시간을 탄력적으로 조정할 수 있다.","ox":"O","m":"④","c":"A","tp":"지역경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":10,"i":"PO2026_2-10","t":"다음 사례에서 제시하는 A경찰서의 범죄예방활동의 근거가 되는 범죄학 이론으로 가장 관계가 깊은 것은?","c":"A","mc":{"s":"다음 사례에서 제시하는 A경찰서의 범죄예방활동의 근거가 되는 범죄학 이론으로 가장 관계가 깊은 것은?","d":"A경찰서는 반복적으로 발생하는 B아파트 단지의 자전거 절도 사건을 분석하여, 범인은 자전거 절도를 목적으로 타지역에서 온 소년들임을 확인하였다. 이들은 B아파트 자전거 거치대 인근을 배회하며 잠금장치가 해제되어 있는 자전거를 훔치고, 이러한 범행 기술을 또래들과 공유하였다. 이에 A경찰서는 인적이 드문 장소에 설치되었던 자전거 거치대를 주민들의 여가활동 거점인 커뮤니티 센터 앞으로 이동하게 하여 상시적인 감시가 가능하게 하였다.","o":["일상활동이론","범죄패턴이론","집합효율성이론","차별적접촉이론"],"a":1}},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_2-11-1","t":"범죄 뿐만 아니라 지역사회의 무질서 문제에 대한 적극적인 개입으로 인하여 주민에 대한 사생활 침해 문제가 발생할 수 있다.","ox":"O","m":"①","c":"A","tp":"지역사회 경찰활동"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_2-11-2","t":"지역주민을 활용한 협력치안을 통하여 무질서 문제에 개입함으로써, 전통적인 경찰활동과 비교할 때 경찰관의 업무 부담이 경감되었다.","ox":"X","m":"②","c":"A","tp":"지역사회 경찰활동"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_2-11-3","t":"일선 경찰관의 재량이 증가하여 지역 단위에서의 경찰국가화 현상이 발생할 수 있다.","ox":"O","m":"③","c":"A","tp":"지역사회 경찰활동"},{"y":2026,"e":"경찰 공채","qn":11,"i":"PO2026_2-11-4","t":"이웃감시(Neighborhood Watch) 및 자율방범대 등 다양한 협력 치안활동의 이론적 배경이 되어 왔다.","ox":"O","m":"④","c":"A","tp":"지역사회 경찰활동"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_2-12-1","t":"셔먼(Sherman)은 사법경찰의 기능 강화를 위하여 범죄수사상 과학적 증거수집을 강조하는 증거기반 경찰활동을 제안하였다.","ox":"X","m":"①","c":"A","tp":"경찰활동의 전략"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_2-12-2","t":"전통적 경찰활동은 경찰을 범죄해결사로 간주하며 범죄의 사후 진압을 강조한다.","ox":"O","m":"②","c":"A","tp":"경찰활동의 전략"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_2-12-3","t":"문제지향 경찰활동에 따르면 형법의 사용은 문제 해결 수단의 하나에 불과하다.","ox":"O","m":"③","c":"A","tp":"경찰활동의 전략"},{"y":2026,"e":"경찰 공채","qn":12,"i":"PO2026_2-12-4","t":"무관용 경찰활동은 윌슨(Wilson)과 켈링(Kelling)이 주장한 깨진 유리창 이론의 영향을 받았다.","ox":"O","m":"④","c":"A","tp":"경찰활동의 전략"},{"y":2026,"e":"경찰 공채","qn":35,"i":"PO2026_2-35-1","t":"「112신고의 운영 및 처리에 관한 법률」 제8조 제1항에 따라 출동한 경찰관이 112신고에 대한 현장조치를 할 때, 구급차‧ 소방차의 투입 등 112신고 관계 기관의 협력이 필요한 사안은 출동 경찰관이 112신고 관계 기관에 직접 이를 요청할 수 있다.","ox":"O","m":"①","c":"A","tp":"112치안종합상황실 운영 및 신고처리 규칙 상 현장보고 및 현장조치"},{"y":2026,"e":"경찰 공채","qn":35,"i":"PO2026_2-35-2","t":"출동 경찰관은 112치안종합상황실에 최초보고, 수시보고 및 종결보고를 하여야 하지만, 현장 상황이 급박하여 신속한 현장 조치가 필요한 경우 우선 조치 후 보고할 수 있다. 다만 최초 보고의 경우에는 그러하지 아니하다.","ox":"X","m":"②","c":"A","tp":"112치안종합상황실 운영 및 신고처리 규칙 상 현장보고 및 현장조치"},{"y":2026,"e":"경찰 공채","qn":35,"i":"PO2026_2-35-3","t":"「112신고의 운영 및 처리에 관한 법률」 제8조 제1항에 따라 출동한 경찰관이 112신고에 대한 현장조치를 할 때, 다수의 경찰관이 필요하다고 판단되는 경우 인접 경찰관에게 직접 지원요청 할 수 있으며, 이에 따른 지원 요청을 받은 경찰관은 특별한 사유가 없는 한 신속히 현장으로 출동하여 현장조치 중인 출동 경찰관을 지원해야 한다.","ox":"O","m":"③","c":"A","tp":"112치안종합상황실 운영 및 신고처리 규칙 상 현장보고 및 현장조치"},{"y":2026,"e":"경찰 공채","qn":35,"i":"PO2026_2-35-4","t":"종결보고란 현장 초동조치가 종결된 경우 확인된 사건의 진상, 사건의 처리내용 및 결과 등을 상세히 보고하는 것을 말한다.","ox":"O","m":"④","c":"A","tp":"112치안종합상황실 운영 및 신고처리 규칙 상 현장보고 및 현장조치"}],"4":[{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_1-14-1","t":"‘통솔의 범위’는 한 사람의 상관이 효과적으로 감독할 수 있는 최대한의 부하의 수를 말한다.","ox":"O","m":"①","c":"A","tp":"경찰조직편성의 원리"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_1-14-2","t":"‘계층제’는 권한과 책임의 정도에 따라 직무를 등급화 함으로써 상하계층 간 직무상 지휘 감독관계에 놓이게 하는 것을 말한다.","ox":"O","m":"②","c":"A","tp":"경찰조직편성의 원리"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_1-14-3","t":"‘명령통일의 원리’는 조직구성원들은 한 사람의 상관으로부터만 명령을 받고, 보고도 그 상관에게만 하여야 한다는 것을 의미한다.","ox":"O","m":"③","c":"A","tp":"경찰조직편성의 원리"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_1-14-4","t":"‘할거주의’는 타기관 및 타부처에 대한 횡적인 조정과 협조를 용이하게 만드는 대표적인 요인으로 조정 통합의 원리에 필수 적인 요소이다.","ox":"X","m":"④","c":"A","tp":"경찰조직편성의 원리"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_1-27-1","t":"공무원이 아닌 위원에 대해서는 국가공무원법 제55조 및 제57조를 준용한다.","ox":"X","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_1-27-2","t":"위원 중 1명은 인권문제에 관하여 전문적인 지식과 경험이 있는 사람이 임명될 수 있도록 노력하여야 한다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_1-27-3","t":"위원은 정치적 중립을 지켜야 하며, 권한을 남용하여서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_1-27-4","t":"시 도자치경찰위원회는 합의제 행정기관으로서 그 권한에 속하는 업무를 독립적으로 수행한다.","ox":"O","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_2-02-1","t":"생활안전을 위한 순찰 및 시설의 운영, 주민참여 방범활동의 지원 및 지도, 주민의 일상생활과 관련된 사회질서의 유지 및 그 위반행위의 지도 단속 등 지역 내 주민의 생활안전 활동에 관한 사무는 자치경찰의 사무에 포함된다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_2-02-2","t":"교통법규 위반에 대한 지도 단속, 교통안전시설 및 무인 교통 단속용 장비의 심의 설치 관리 등 지역 내 교통활동에 관한 사무는 자치경찰사무에 포함된다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_2-02-3","t":"학교폭력 등 소년범죄, 가정폭력, 아동학대 범죄, 형법 제245조에 따른 공연음란 및 성폭력범죄의 처벌 등에 관한 특례법 제11조에 따른 공중밀집 장소에서의 추행행위에 관한 범죄는 자치경찰사무에 포함된다.","ox":"X","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":2,"i":"PO2022_2-02-4","t":"지역 내 주민의 생활안전 활동에 관한 사무, 지역 내 교통활동에 관한 사무, 지역 내 다중운집 행사 관련 혼잡 교통 및 안전 관리의 자치경찰사무에 관한 구체적인 사항 및 범위 등은 대통령령으로 정하는 기준에 따라 시 도조례로 정한다.","ox":"O","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_2-03-1","t":"위원장 및 1명의 위원은 상임위원으로 하고 나머지 5명의 위원은 비상임으로 한다.","ox":"X","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_2-03-2","t":"경찰의 직에서 퇴직한 날로부터 3년이 지나지 아니한 사람은 위원이 될 수 없다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_2-03-3","t":"위원 2명이 회의를 요구하는 경우 임시회의를 개최할 수 있다.","ox":"X","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":3,"i":"PO2022_2-03-4","t":"보궐위원은 전임자의 남은 임기가 1년 미만인 경우 한 차례에 한해서 연임할 수 있다.","ox":"X","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_2-28-1","t":"권한을 위임받은 수임청은 자기의 이름 및 자기의 책임으로 권한을 행사한다.","ox":"O","m":"①","c":"A","tp":"경찰관청의 ‘권한의 대리’와 ‘권한의 위임’"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_2-28-2","t":"수임청 및 피대리관청은 항고소송에서 피고가 된다.","ox":"O","m":"②","c":"A","tp":"경찰관청의 ‘권한의 대리’와 ‘권한의 위임’"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_2-28-3","t":"법정대리의 경우 피대리관청이 사고 등으로 인해 공석이므로 대리의 법적 효과는 대리관청에 귀속된다.","ox":"X","m":"③","c":"A","tp":"경찰관청의 ‘권한의 대리’와 ‘권한의 위임’"},{"y":2022,"e":"경찰 공채","qn":28,"i":"PO2022_2-28-4","t":"국가경찰과 자치경찰의 조직 및 운영에 관한 법률상 “경찰 청장이 부득이한 사유로 직무를 수행할 수 없을 때에는 경찰청 차장이 그 직무를 대행한다”는 대리방식을 ‘협의의 법정대리’ 라고 한다.","ox":"O","m":"④","c":"A","tp":"경찰관청의 ‘권한의 대리’와 ‘권한의 위임’"},{"y":2023,"e":"경찰 공채","qn":15,"i":"PO2023_1-15","t":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 제10조에 따른 국가경찰위원회의 심의･ 의결 사항에 관한 내용으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 제10조에 따른 국가경찰위원회의 심의･ 의결 사항에 관한 내용으로 가장 적절하지 않은 것은?","d":"","o":["국가경찰사무에 관한 인사, 예산, 장비, 통신 등에 관한 주요 정책 및 경찰 업무 발전에 관한 사항","국가경찰사무에 관한 인권보호와 관련되는 경찰의 운영･ 개선에 관한 사항","지방행정과 치안행정의 업무조정에 관한 사항","제주특별자치도의 자치경찰에 대한 경찰의 지원･ 협조 및 협약 체결의 조정 등에 관한 주요 정책사항"],"a":3}},{"y":2023,"e":"경찰 공채","qn":29,"i":"PO2023_1-29-1","t":"할거주의는 조정과 통합의 원리를 실현시키는 필수적 요소이다.","ox":"X","m":"①","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":29,"i":"PO2023_1-29-2","t":"계층제는 조직의 경직화를 초래하여 환경변화에 대한 조직의 신축적 대응을 어렵게 한다.","ox":"O","m":"②","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":29,"i":"PO2023_1-29-3","t":"명령통일의 원리는 부하직원이 한 사람의 상관으로부터만 명령을 받고, 보고도 그 상관에게만 하도록 하는 것을 의미한다.","ox":"O","m":"③","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":29,"i":"PO2023_1-29-4","t":"통솔의 범위는 한 사람의 상관이 효과적으로 감독할 수 있는 최대한의 부하의 수를 의미한다.","ox":"O","m":"④","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":3,"i":"PO2023_2-03-1","t":"동법 제18조 제1항 단서에 따라 2개의 시·도자치경찰위원회를 두는 경우 해당 시·도자치경찰위원회의 명칭, 관할구역, 사무분장, 그 밖에 필요한 사항은 행정안전부령으로 정한다.","ox":"X","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":3,"i":"PO2023_2-03-2","t":"시·도자치경찰위원회 비상임 위원은 특정 성(性)이 10분의 6을 초과하지 아니해야 한다.","ox":"X","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":3,"i":"PO2023_2-03-3","t":"시·도자치경찰위원회 위원장과 위원의 임기는 3년으로 하되, 위원만 한 차례 연임할 수 있다.","ox":"X","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":3,"i":"PO2023_2-03-4","t":"시·도자치경찰위원회의 회의는 정기적으로 개최하여야 한다. 다만 위원장이 필요하다고 인정하는 경우, 위원 2명 이상이 요구하는 경우 및 시·도지사가 필요하다고 인정하는 경우에는 임시회의를 개최할 수 있다.","ox":"O","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_2-16-1","t":"“위임”이란 법률에 규정된 행정기관의 장의 권한 중 일부를 다른 행정기관의 장에게 맡겨 그의 권한과 책임 아래 행사하도록 하는 것을 말한다.","ox":"X","m":"①","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_2-16-2","t":"위임 및 위탁기관은 수임 및 수탁기관의 수임 및 수탁사무 처리에 대하여 지휘·감독하고, 그 처리가 위법하거나 부당하다고 인정될 때에는 이를 취소하거나 정지시킬 수 있다.","ox":"O","m":"②","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_2-16-3","t":"행정기관의 장은 행정권한을 위임 및 위탁할 때에는 위임 및 위탁하기 전에 단순한 사무인 경우를 제외하고는 수임 및 수탁기관에 대하여 수임 및 수탁사무 처리에 필요한 교육을 하여야 하며, 수임 및 수탁사무의 처리지침을 통보하여야 한다.","ox":"O","m":"③","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_2-16-4","t":"수임 및 수탁사무의 처리가 부당한지 여부의 판단은 위법성 판단과 달리 합목적적·정책적 고려도 포함되므로, 위임 및 위탁기관이 그 사무처리에 관하여 일반적인 지휘·감독을 하는 경우는 물론이고 나아가 수임 및 수탁사무의 처리가 부당하다는 이유로 그 사무처리를 취소하는 경우에도 광범위한 재량이 허용된다고 보아야 한다.","ox":"O","m":"④","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_2-18-1","t":"국가수사본부장은 치안정감으로 보한다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_2-18-2","t":"국가수사본부장을 경찰청 외부를 대상으로 모집하여 임용하는 경우 정당의 당원이거나 당적을 이탈한 날부터 3년이 지나지 아니한 사람은 국가수사본부장이 될 수 없다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_2-18-3","t":"국가수사본부장이 직무를 집행하면서 헌법이나 법률을 위배하였을 때에는 국회는 대통령에게 해임을 건의할 수 있다.","ox":"X","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_2-18-4","t":"국가수사본부장의 임기는 2년으로 하며, 중임할 수 없다.","ox":"O","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_2-28-1","t":"분업의 원리 - 가급적 한 사람에게 동일한 업무를 분담시킴으로써 특정 분야에 대한 업무의 전문화 확보를 가능하게 한다.","ox":"O","m":"①","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_2-28-2","t":"계층제의 원리 - 권한과 책임의 정도에 따라 직무를 계층화 함으로써 상·하 계층 간에 직무상 지휘·감독 관계에 있도록 한다.","ox":"O","m":"②","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_2-28-3","t":"조정과 통합의 원리 - 구성원의 노력과 행동을 질서있게 배열하고 통일시키는 작용을 함으로써 경찰행정의 목표를 효율적으로 달성할 수 있게 한다.","ox":"O","m":"③","c":"A","tp":"경찰조직편성의 원리"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_2-28-4","t":"통솔범위의 원리 - 1인의 상관 또는 감독자가 직접 통솔할 수 있는 부하직원의 수를 의미하며, 무니(Mooney)는 이러한 통솔 범위의 원리를 조직편성 제1의 원리라고 하였다.","ox":"X","m":"④","c":"A","tp":"경찰조직편성의 원리"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_1-16-1","t":"합의제 행정기관으로서 그 권한에 속하는 업무를 독립적으로 수행한다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_1-16-2","t":"위원은 시·도의회가 추천하는 2명, 국가경찰위원회가 추천하는 1명, 해당 시·도 교육감이 추천하는 1명, 시·도자치경찰위원회 위원추천위원회가 추천하는 2명, 시·도지사가 지명하는 1명의 사람을 시·도지사가 임명한다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_1-16-3","t":"시·도지사는 시·도자치경찰위원회의 의결이 적정하지 아니하다고 판단할 때에는 재의를 요구할 수 있다.","ox":"O","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_1-16-4","t":"경찰청장은 시·도자치경찰위원회의 의결이 적정하지 아니하다고 판단되면 국가경찰위원회와 행정안전부장관을 거쳐 시·도지사에게 재의를 요구하게 할 수 있다.","ox":"X","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_1-21-1","t":"행정청은 다른 행정청의 응원을 받아 처리하는 것이 보다 능률적이고 경제적인 경우 다른 행정청에 행정응원을 요청할 수 있다.","ox":"O","m":"①","c":"A","tp":"행정절차법 제8조에 따른 행정응원"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_1-21-2","t":"행정응원을 요청받은 행정청은 행정응원으로 인하여 고유의 직무 수행이 현저히 지장받을 것으로 인정되는 명백한 이유가 있는 경우에는 응원을 거부할 수 있다.","ox":"O","m":"②","c":"A","tp":"행정절차법 제8조에 따른 행정응원"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_1-21-3","t":"행정응원을 위하여 파견된 직원은 다른 법령 등에 특별한 규정이 있는 경우를 제외하고는 원소속 행정청의 지휘·감독을 받는다.","ox":"X","m":"③","c":"A","tp":"행정절차법 제8조에 따른 행정응원"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_1-21-4","t":"행정응원에 드는 비용은 응원을 요청한 행정청이 부담하며, 그 부담금액 및 부담방법은 응원을 요청한 행정청과 응원을 하는 행정청이 협의하여 결정한다.","ox":"O","m":"④","c":"A","tp":"행정절차법 제8조에 따른 행정응원"},{"y":2024,"e":"경찰 공채","qn":29,"i":"PO2024_1-29","t":"다음에서 설명하는 조직편성의 원리와 가장 관계가 깊은 것은?","c":"A","mc":{"s":"다음에서 설명하는 조직편성의 원리와 가장 관계가 깊은 것은?","d":"∙업무를 그 종류와 성질별로 구분하여 구성원에게 가능한 한 한가지의 주된 업무를 부담시킴으로써 조직 관리상의 능률을 향상시키려는 원리이다.\n∙한 사람이 수행할 수 있는 업무의 양과 시간에는 한계가 있고, 서로 다른 특성을 가진 업무를 한 사람이 맡아서 하는 것은 비효율적이다.\n∙다수가 일을 함에 있어서 각자의 임무를 나누어서 분명하게 부과하고 협력을 하도록 하는 것으로, 인간능력의 한계를 극복하고 업무를 효율적으로 수행하기 위한 것이다.","o":["이 원리는 구조조정의 문제와 깊은 관련성이 있다.","이 원리에 따르면 업무에 대한 신속결단과 결단내용의 지시가 단일한 명령계통이어야 한다.","이 원리의 장점은 권한과 책임을 계층에 따라 분배하여 의사결정의 검토가 이루어져 신중한 업무처리가 가능하다는 것이다.","이 원리의 단점은 정형적･ 반복적 업무수행에 기인하여 작업에 대한 흥미 상실과 노동의 소외화나 인간기계화를 심화시키며, 부처간의 할거주의가 초래될 수 있다는 것이다."],"a":4}},{"y":2024,"e":"경찰 공채","qn":24,"i":"PO2024_2-24","t":"다음 경찰과 관련한 대화 중 가장 적절하지 않은 설명을 하고 있는 사람은?","c":"A","mc":{"s":"다음 경찰과 관련한 대화 중 가장 적절하지 않은 설명을 하고 있는 사람은?","d":"","o":["민희: “우리 지역에 파출소 하나만 생기면 밤길이 안전할 거 같은데, 파출소 설치의 승인권자는 경찰청장이라고 하네.”","지율: “경찰청장, 국가수사본부장, 국가경찰위원회 위원, 시･ 도 자치경찰위원회 위원 모두 연임이 불가능해. 단, 시･ 도자치경찰 위원회 보궐위원의 경우 전임자의 남은 임기가 1년 미만인 경우 한 차례만 연임할 수 있어.”","수연: “우리 동네에 요즘 가정폭력사건이 자주 발생하네. ｢국가 경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 을 보면 가정 폭력의 예방은 자치경찰사무에 해당하여 시･ 도자치경찰위원회의 소관사무이지만, 가정폭력범죄의 수사사무는 국가경찰사무로 규정되어 있어.”","윤우: “한국의 자치경찰제도는 법률에서 자치경찰사무와 국가 경찰사무를 구분하고 있지만, 자치경찰사무를 담당하는 경찰관의 신분은 기존 그대로 국가공무원이더라고. 단, 제주특별자치도 자치경찰단 소속의 자치경찰공무원은 지방공무원이야.”"],"a":3}},{"y":2024,"e":"경찰 공채","qn":30,"i":"PO2024_2-30","t":"다음에서 설명하는 조직편성원리에 관한 내용과 가장 관계가 깊은 것은?","c":"A","mc":{"s":"다음에서 설명하는 조직편성원리에 관한 내용과 가장 관계가 깊은 것은?","d":"한 사람이 직접적으로 감독할 수 있는 부하의 수는 업무의 성질, 고용기술, 작업성과 기준에 달려 있으며, 모든 조직은 일반적 으로 상관보다 부하가 더 많다. 이러한 이유 때문에 경찰 조직은 사다리 모양보다는 피라미드 모양을 취하고 있다.","o":["조직의 경직화를 초래하여 환경변화에 따른 새로운 기술의 신속한 도입이 어렵다.","부하들을 직접 감독하지 않는 참모 및 계선조직이 부하들에게 유익한 자문을 하는 것을 허용하지 않는다.","경과 제도를 통한 특정업무의 세분화 및 시간과 경비를 절약 할 수 있다.","구조조정의 문제와 깊은 관련성이 있다."],"a":4}},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_1-15-1","t":"시‧ 도자치경찰위원회는 위원장 1명을 포함한 7명의 위원으로 구성하되, 위원장과 1명의 위원은 상임으로 하고, 5명의 위원은 비상임으로 한다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_1-15-2","t":"시‧ 도자치경찰위원회 위원장은 위원 중에서 시‧ 도지사가 임명하고, 상임위원은 시‧ 도자치경찰위원회의 의결을 거쳐 위원 중에서 위원장의 제청으로 시‧ 도지사가 임명한다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_1-15-3","t":"시‧ 도자치경찰위원회 위원장과 위원의 임기는 3년으로 하며, 연임할 수 없다. 다만, 보궐위원의 임기는 전임자 임기의 남은 기간으로 하되, 전임자의 남은 임기가 1년 미만인 경우에는 한 차례만 연임할 수 있다.","ox":"O","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_1-15-4","t":"시‧ 도자치경찰위원회의 위원장은 재의요구를 받은 날부터 7일 이내에 회의를 소집하여 재의결하여야 한다. 이 경우 재적위원 과반수의 출석과 출석위원 과반수 이상의 찬성으로 전과 같은 의결을 하면 그 의결사항은 확정된다.","ox":"X","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_1-16-1","t":"경찰공무원은 상관의 지휘‧ 감독을 받아 직무를 수행하고, 그 직무수행에 관하여 서로 협력하여야 한다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_1-16-2","t":"국가는 지방자치단체가 이관받은 사무를 원활히 수행할 수 있도록 인력, 장비 등에 소요되는 비용에 대하여 재정적 지원을 하여야 한다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_1-16-3","t":"경찰공무원은 구체적 사건수사와 관련된 상관의 지휘‧ 감독의 정당성에 대하여 이견이 있더라도 이의를 제기할 수 없다.","ox":"X","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_1-16-4","t":"국가와 지방자치단체는 국민의 생명‧ 신체 및 재산을 보호하고 공공의 안녕과 질서유지에 필요한 시책을 수립‧ 시행하여야 한다.","ox":"O","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_1-28-1","t":"계층제 원리 – 권한과 책임의 배분을 통해 신중한 업무처리가 가능하며, 수직적 분화와 집권화 현상이 나타나 구성원의 동기부여를 향상시킨다.","ox":"X","m":"①","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_1-28-2","t":"통솔범위의 원리 – 업무의 종류가 단순할수록 통솔의 범위는 넓어지며, 계층의 수가 많아질수록 통솔의 범위가 좁아진다.","ox":"O","m":"②","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_1-28-3","t":"분업의 원리 – 분업의 원리는 업무를 그 종류와 성질별로 구분 하여 구성원에게 가능한 한 한가지의 주된 업무를 분담시킴으로써 조직 관리상의 능률을 향상시키려는 것을 말한다.","ox":"O","m":"③","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_1-28-4","t":"조정과 통합의 원리 – 구성원의 노력과 행동을 질서있게 배열 하고 통일시키는 작용을 함으로써 경찰행정의 목표를 효율적으로 달성할 수 있게 한다.","ox":"O","m":"④","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":18,"i":"PO2025_2-18","t":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 상 시･ 도자치경찰위원회의 소관 사무로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 상 시･ 도자치경찰위원회의 소관 사무로 가장 적절하지 않은 것은?","d":"","o":["자치경찰사무에 관한 인사, 예산, 장비, 통신 등에 관한 주요 정책 및 그 운영지원","자치경찰사무 담당 공무원의 부패 방지와 청렴도 향상에 관한 주요 정책 및 인권침해 또는 권한남용 소지가 있는 규칙, 제도, 정책, 관행 등의 개선","시‧ 도경찰청장의 임용과 관련한 시‧ 도지사와의 협의","정기적으로 경찰서장의 자치경찰사무 수행에 관한 평가결과를 경찰청장에게 통보"],"a":3}},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_2-28-1","t":"계층제의 원리에 의하면 계층이 많을수록 업무처리가 신속하고 계층 간의 갈등이 감소한다.","ox":"X","m":"①","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_2-28-2","t":"통솔범위의 원리에 의하면 계층의 수, 업무의 복잡성 및 조직 규모의 크기와 통솔의 범위는 정비례 관계이다.","ox":"X","m":"②","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_2-28-3","t":"분업의 원리에 의하면 분업화가 안 될수록 조정과 통합이 어려워지며 할거주의를 초래할 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰조직편성의 원리"},{"y":2025,"e":"경찰 공채","qn":28,"i":"PO2025_2-28-4","t":"조정과 통합의 원리에 의하면 조직의 조정과 통합은 집단적 노력을 질서있게 배열하고 조직 및 구성원의 행동을 통일시키는 작용을 함으로써 경찰행정의 목표를 달성할 수 있게 한다.","ox":"O","m":"④","c":"A","tp":"경찰조직편성의 원리"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_1-16-1","t":"훈령은 상급관청이 하급관청의 권한행사를 지휘하기 위하여 발하는 명령이다.","ox":"O","m":"①","c":"A","tp":"훈령과 직무명령"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_1-16-2","t":"훈령은 하급관청의 권한행사의 독립된 범위에 속하는 사항이 아니어야 한다.","ox":"O","m":"②","c":"A","tp":"훈령과 직무명령"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_1-16-3","t":"훈령은 직무명령으로서의 성질을 가질 수 있으나, 직무명령이 훈령으로서의 성질을 당연히 가지는 것은 아니다.","ox":"O","m":"③","c":"A","tp":"훈령과 직무명령"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_1-16-4","t":"직무명령은 상관이 부하직원에 대하여 발하는 명령이며, 상위 법령의 법적 근거가 필요하다.","ox":"X","m":"④","c":"A","tp":"훈령과 직무명령"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_1-17-1","t":"수임 및 수탁사무의 처리에 관하여 위임 및 위탁기관은 수임 및 수탁기관에 대하여 사전승인을 받거나 협의를 할 것을 요구 할 수 있다.","ox":"X","m":"①","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_1-17-2","t":"위임 및 위탁기관은 수임 및 수탁기관의 수임 및 수탁사무 처리에 대하여 지휘‧ 감독하고, 그 처리가 위법하거나 부당하다고 인정될 때에는 이를 취소하거나 정지시킬 수 있다.","ox":"O","m":"②","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_1-17-3","t":"‘위탁기관’이란 자기의 권한을 위탁한 해당 행정기관의 장을 말하고, ‘수탁기관’이란 행정기관의 권한을 위탁받은 다른 행정 기관의 장과 사무를 위탁받은 지방자치단체가 아닌 법인‧ 단체 또는 그 기관이나 개인을 말한다.","ox":"O","m":"③","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_1-17-4","t":"위임 및 위탁기관은 위임 및 위탁사무 처리의 적정성을 확보하기 위하여 필요한 경우에는 수임 및 수탁기관의 수임 및 수탁사무 처리 상황을 수시로 감사할 수 있다.","ox":"O","m":"④","c":"A","tp":"행정권한의 위임 및 위탁"},{"y":2026,"e":"경찰 공채","qn":20,"i":"PO2026_1-20","t":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 에 대한 설명으로 아래","c":"A","mc":{"s":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 에 대한 설명으로 아래","d":"<보기>에서 옳지 않은 것은 모두 몇 개인가? < 보기 > ㉠ 국가경찰위원회 위원의 임기는 3년으로 하며, 연임할 수 없다. 이 경우 보궐위원의 임기는 전임자 임기의 남은 기간으로 한다. ㉡ 자치경찰사무의 수행에 필요한 예산은 시‧ 도자치경찰위원회의 심의‧ 의결을 거쳐 시‧ 도지사가 수립한다. 이 경우 시‧ 도 자치경찰위원회는 시‧ 도경찰청장의 의견을 들어야 한다. ㉢ 국가수사본부장은 ｢형사소송법｣ 에 따른 경찰의 수사에 관하여 각 시‧ 도경찰청장과 경찰서장 및 수사부서 소속 공무원을 지휘‧ 감독한다. ㉣ 시‧ 도자치경찰위원회 위원의 임기는 3년이며, 국가경찰위원회 위원장이 임명한다.","o":["1개","2개","3개","4개"],"a":2}},{"y":2026,"e":"경찰 공채","qn":29,"i":"PO2026_1-29","t":"경찰조직의 편성원리에 관한 설명으로 가장 적절한 것은?","c":"A","mc":{"s":"경찰조직의 편성원리에 관한 설명으로 가장 적절한 것은?","d":"","o":["명령통일의 원리: 조직 구성원에게 가능한 한 한가지의 주된 업무를 분담시키는 원리","계층제의 원리: 권한과 책임의 정도에 따라 직무를 등급화하여야 한다는 원리","조정과 통합의 원리: 한 사람이 직접적으로 감독할 수 있는 부하의 수를 정하는 원리","통솔범위의 원리: 무니(Mooney)가 주장하는 조직편성의 원리 중 제1의 원리"],"a":2}},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_2-03-1","t":"자치경찰사무 중 학교폭력 등 소년범죄, 가정폭력, 아동학대 범죄, 교통사고 및 교통 관련 범죄, 「형법」 제245조에 따른 공연음란 및 「성폭력범죄의 처벌 등에 관한 특례법」 제12조에 따른 성적 목적을 위한 다중이용장소 침입행위에 관한 범죄, 경범죄 및 기초질서 관련 범죄, 가출인 및 「실종아동등의 보호 및 지원에 관한 법률」 제2조 제2호에 따른 실종아동등 관련 수색 및 범죄에 해당하는 수사사무에 관한 구체적인 사항 및 범위 등은 대통령령으로 정하는 기준에 따라 시‧ 도조례로 정한다.","ox":"X","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_2-03-2","t":"자치경찰사무와 관련하여 해당 시‧ 도의 경찰력으로는 국민의 생명‧ 신체‧ 재산의 보호 및 공공의 안녕과 질서유지가 어려워 경찰청장의 지원‧ 조정이 필요하다고 인정할 만한 충분한 사유가 있는 경우, 경찰청장은 자치경찰사무를 수행하는 경찰공무원 (제주특별자치도의 자치경찰공무원을 포함한다)을 직접 지휘‧ 명령할 수 있다. 다만, 미리 국가경찰위원회의 의결을 거쳐야 하며 긴급한 경우에는 우선 조치 후 지체 없이 국가경찰위원회의 의결을 거쳐야 한다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_2-03-3","t":"시‧ 도자치경찰위원회는 정기적으로 경찰서장의 자치경찰사무 수행에 관한 평가결과를 경찰청장에게 통보하여야 하며 경찰청장은 이를 반영하여야 한다.","ox":"O","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":3,"i":"PO2026_2-03-4","t":"시‧ 도자치경찰위원회는 합의제 행정기관으로서 그 권한에 속하는 업무를 독립적으로 수행한다.","ox":"O","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_2-17-1","t":"행정안전부장관은 국가경찰위원회에서 심의‧ 의결된 내용이 적정 하지 아니하다고 판단할 때에는 재의를 요구할 수 있다.","ox":"O","m":"①","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_2-17-2","t":"국가경찰위원회 위원장은 위원회의 심의를 위하여 필요한 경우에는 관계공무원 또는 관계전문가의 출석‧ 발언이나 자료의 제출을 요구할 수 있다.","ox":"O","m":"②","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_2-17-3","t":"국가경찰위원회에 출석한 관계공무원 또는 관계전문가에 대하여는 예산의 범위안에서 수당과 여비를 지급할 수 있다. 다만, 공무원이 그 소관업무와 직접적으로 관련되어 출석하는 경우에는 그러하지 아니한다.","ox":"O","m":"③","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":17,"i":"PO2026_2-17-4","t":"국가경찰위원회 위원은 경찰청장의 제청으로 국무총리를 거쳐 대통령이 임명한다.","ox":"X","m":"④","c":"A","tp":"국가경찰과 자치경찰의 조직 및 운영"},{"y":2026,"e":"경찰 공채","qn":18,"i":"PO2026_2-18","t":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 에서 명시하고 있는 시･ 도자치경찰위원회의 소관 사무에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢국가경찰과 자치경찰의 조직 및 운영에 관한 법률｣ 에서 명시하고 있는 시･ 도자치경찰위원회의 소관 사무에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["자치경찰사무 담당 공무원의 임용, 평가 및 인사위원회 운영","자치경찰사무에 대한 주요 법령‧ 정책 등에 관한 사항","국가경찰사무‧ 자치경찰사무의 협력‧ 조정과 관련하여 경찰청장과 협의","자치경찰사무에 관한 규칙의 제정‧ 개정 또는 폐지"],"a":2}}],"5":[{"y":2022,"e":"경찰 공채","qn":15,"i":"PO2022_1-15-1","t":"경찰공무원의 승진임용은 심사승진임용 시험승진임용 및 특별 승진임용으로 구분한다.","ox":"O","m":"①","c":"A","tp":"경찰공무원 승진임용 규정 상 승진"},{"y":2022,"e":"경찰 공채","qn":15,"i":"PO2022_1-15-2","t":"경찰공무원 승진임용 규정 제6조 제1항 제2호에 따르면 소극 행정으로 감봉에 해당하는 징계처분을 받은 경찰공무원은 징계 처분의 집행이 끝난 날부터 18개월이 지나지 아니하면 심사승진 임용될 수 없다.","ox":"O","m":"②","c":"A","tp":"경찰공무원 승진임용 규정 상 승진"},{"y":2022,"e":"경찰 공채","qn":15,"i":"PO2022_1-15-3","t":"임용권자나 임용제청권자는 시험승진후보자 명부에 기록된 사람이 승진임용되기 전에 감봉 이상의 징계처분을 받은 경우에는 시험 승진후보자 명부에서 그 사람을 제외하여야 한다.","ox":"X","m":"③","c":"A","tp":"경찰공무원 승진임용 규정 상 승진"},{"y":2022,"e":"경찰 공채","qn":15,"i":"PO2022_1-15-4","t":"총경 이하의 경찰공무원에 대해서는 매년 근무성적을 평정하여야 하나 휴직 직위해제 등의 사유로 해당 연도의 평정기관에서 6개월 이상 근무하지 아니한 경찰공무원에 대해서는 근무성적을 평정 하지 아니한다.","ox":"O","m":"④","c":"A","tp":"경찰공무원 승진임용 규정 상 승진"},{"y":2022,"e":"경찰 공채","qn":16,"i":"PO2022_1-16","t":"경찰공무원법 상 경찰공무원의 직권면직사유 중 직권면직 처분을 위해 징계위원회의 동의가 필요한 사유로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰공무원법 상 경찰공무원의 직권면직사유 중 직권면직 처분을 위해 징계위원회의 동의가 필요한 사유로 옳은 것은 모두 몇 개인가?","d":"㉠ 해당 경과에서 직무를 수행하는 데 필요한 자격증의 효력이 상실되거나 면허가 취소되어 담당 직무를 수행할 수 없게 되었을 때 ㉡ 직무를 수행하는 데에 위험을 일으킬 우려가 있을 정도의 성격적 또는 도덕적 결함이 있는 사람으로서 대통령령으로 정하는 사유에 해당된다고 인정될 때 ㉢ 경찰공무원으로는 부적합할 정도로 직무 수행능력이나 성실성이 현저하게 결여된 사람으로서 대통령령으로 정하는 사유에 해당된다고 인정될 때 ㉣ 휴직 기간이 끝나거나 휴직 사유가 소멸된 후에도 직무에 복귀하지 아니하거나 직무를 감당할 수 없을 때","o":["1개","2개","3개","4개"],"a":2}},{"y":2022,"e":"경찰 공채","qn":13,"i":"PO2022_2-13-1","t":"OO경찰서 소속 지구대장 경감 甲과 동일한 지구대 소속 순경 乙이 관련된 징계등 사건(甲의 감독상 과실책임만으로 관련된 경우, 관련자에 대한 징계등 사건을 분리하여 심의 의결하는 것이 타당하다고 인정되는 경우는 제외)은 OO경찰서에 설치된 징계 위원회에서 심의 의결한다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":13,"i":"PO2022_2-13-2","t":"경찰공무원 임용 당시 임용결격사유가 있었더라도 국가의 과실에 의해 임용결격자임을 밝혀내지 못했다면, 그 임용행위는 당연무효로 볼 수 없다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"경찰 공채","qn":13,"i":"PO2022_2-13-3","t":"국가경찰사무를 담당하는 OO경찰서 소속 경사 丙에 대한 정직처분은 소속기관장인 OO경찰서장이 행하지만, 그 처분에 대한 행정소송의 피고는 경찰청장이다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":13,"i":"PO2022_2-13-4","t":"징계의결이 요구된 경정 丁에게 국무총리 표창을 받은 공적이 있는 경우에 징계위원회는 징계를 감경할 수 있지만, 그 표창이 丁에게 수여된 표창이 아니라 丁이 속한 OO경찰서에 수여된 단체표창이라면 감경할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_2-14-1","t":"OO지구대에 근무하는 순경 甲이 승진후보자명부에 등재된 후 경장으로 승진임용되기 전에 정직 3개월의 징계처분을 받아 임용권자가 순경 甲을 승진후보자명부에서 삭제함으로써 순경 甲이 승진임용의 대상에서 제외되었다면, 임용권자의 승진 후보자명부에서의 삭제 행위 그 자체는 행정처분에 해당한다.","ox":"X","m":"①","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 승진"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_2-14-2","t":"만 7세인 초등학교 1학년 외동딸을 양육하기 위하여 1년간 휴직한 경사 乙의 위 휴직기간 1년은 승진소요 최저근무연수에 포함된다.","ox":"O","m":"②","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 승진"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_2-14-3","t":"통상적인 근무시간보다 짧은 시간을 근무하는 시간선택제전환 경찰공무원으로 경위 계급에서 1년간 근무한 경위 丙의 위 근무기간 1년은 승진소요 최저근무연수에 포함된다.","ox":"O","m":"③","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 승진"},{"y":2022,"e":"경찰 공채","qn":14,"i":"PO2022_2-14-4","t":"위법 부당한 처분과 직접적 관계없이 50만 원의 향응을 받아 감봉 1개월의 징계처분을 받은 경감 丁이 그 징계처분을 받은 후 해당 계급에서 경찰청장 표창을 받은 경우(그 외 일체의 포상을 받은 사실 없음)에는 징계처분의 집행이 끝난 날부터 18개월이 지나면 승진임용될 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 승진"},{"y":2022,"e":"경찰 공채","qn":15,"i":"PO2022_2-15","t":"국가공무원법 및 관련 법령에 따를 때, 소청심사와 관련 하여 아래 사례에 관한 설명 중 가장 적절하지 않은 것은?","c":"A","mc":{"s":"국가공무원법 및 관련 법령에 따를 때, 소청심사와 관련 하여 아래 사례에 관한 설명 중 가장 적절하지 않은 것은?","d":"OO경찰서 소속 지구대에서 근무하는 순경 甲이 법령준수 의무 위반 등 각종 비위행위로 인하여 관련 절차를 거쳐 징계권자로 부터 해임의 징계처분을 받았다. 이에 순경 甲은 소청심사를 제기하고자 한다.","o":["소청심사위원회는 소청심사 결과 甲의 비위행위의 정도에 비해 해임의 징계처분이 경미하다는 판단에 이르더라도 파면의 징계처분으로 변경하는 결정을 할 수 없다.","소청심사위원회에서 해임처분 취소명령결정을 내릴 경우, 그 해임의 징계처분은 소청심사위원회의 결정에 따른 징계나 그 밖의 처분이 있기 전에 당연히 효력을 상실한다.","소청심사위원회에서 해임처분을 취소 또는 변경하고자 할 경우 에는 재적 위원 3분의 2 이상의 출석과 출석 위원 3분의 2 이상의 합의가 있어야 한다.","甲이 징계처분사유 설명서를 받은 날부터 30일 이내(甲에게 책임이 없는 사유로 소청심사를 청구할 수 없는 기간은 없다고 전제한다) 소청심사를 제기하지 않은 경우에는 행정소송을 제기할 수 없다."],"a":2}},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_2-31-1","t":"중징계 의결이 요구 중인 경찰공무원 甲에 대해 직위해제처분을 할 경우, 임용권자는 3개월의 범위 내에서 대기를 명하고 능력 회복이나 근무성적의 향상을 위한 교육훈련 또는 특별한 연구 과제의 부여 등 필요한 조치를 하여야 한다.","ox":"X","m":"①","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 경찰공무원의 신분변동"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_2-31-2","t":"위원장 포함 12명이 출석하여 구성된 징계위원회에서 정직 3월 2명, 정직 1월 2명, 감봉 3월 1명, 감봉 2월 1명, 감봉 1월 3명, 견책 3명으로 의견이 나뉜 경우, 감봉 1월로 의결해야 한다.","ox":"X","m":"②","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 경찰공무원의 신분변동"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_2-31-3","t":"자치경찰사무를 담당하는 OO경찰서 소속 경위 乙의 경감으로의 승진임용을 시 도지사가 하므로, 경위 乙에 대한 휴직이나 복직도 시 도지사가 한다.","ox":"O","m":"③","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 경찰공무원의 신분변동"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_2-31-4","t":"순경 채용후보자 명부에 등재된 채용후보자 丙이 학업을 계속 하고자 이를 증명할 수 있는 자료를 첨부하여 임용권자가 정하는 기간 내에 원하는 유예기간을 적어 신청할 경우, 임용권자는 채용후보자 명부의 유효기간 범위에서 기간을 정하여 임용을 유예해야 한다.","ox":"X","m":"④","c":"A","tp":"경찰공무원 관련 법령에 따를 때, 경찰공무원의 신분변동"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_1-16-1","t":"총경 이상 경찰공무원은 경찰청장 또는 해양경찰청장의 추천을 받아 행정안전부장관 또는 해양수산부장관의 제청으로 국무총리를 거쳐 대통령이 임용한다.","ox":"O","m":"①","c":"A","tp":"경찰공무원법 제7조에 따른 임용권자"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_1-16-2","t":"총경의 전보, 휴직, 직위해제, 강등, 정직 및 복직은 행정안전부 장관 또는 해양수산부장관이 임용한다.","ox":"X","m":"②","c":"A","tp":"경찰공무원법 제7조에 따른 임용권자"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_1-16-3","t":"경정 이하의 경찰공무원은 경찰청장 또는 해양경찰청장이 임용한다. 다만, 경정으로의 신규채용, 승진임용 및 면직은 경찰청장 또는 해양경찰청장의 제청으로 국무총리를 거쳐 대통령이 한다.","ox":"O","m":"③","c":"A","tp":"경찰공무원법 제7조에 따른 임용권자"},{"y":2023,"e":"경찰 공채","qn":16,"i":"PO2023_1-16-4","t":"경찰청장은 대통령령으로 정하는 바에 따라 경찰공무원의 임용에 관한 권한의 일부를 특별시장ㆍ광역시장ㆍ도지사ㆍ특별자치시장 또는 특별자치도지사, 국가수사본부장, 소속 기관의 장, 시·도 경찰청장에게 위임할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰공무원법 제7조에 따른 임용권자"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_1-17-1","t":"임용권자는 직무수행 능력이 부족하거나 근무성적이 극히 나쁜 자에게 직위를 부여하지 아니할 수 있다.","ox":"O","m":"①","c":"A","tp":"국가공무원법 상 직위해제"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_1-17-2","t":"형사사건으로 기소된 자(약식명령이 청구된 자는 제외한다)에게는 직위를 부여하지 아니할 수 있다.","ox":"O","m":"②","c":"A","tp":"국가공무원법 상 직위해제"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_1-17-3","t":"제73조의3 제1항에 따라 직위를 부여하지 아니한 경우에 그 사유가 소멸되면 임용권자는 7일 이내에 직위를 부여할 수 있다.","ox":"X","m":"③","c":"A","tp":"국가공무원법 상 직위해제"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_1-17-4","t":"임용권자는 제1항 제2호에 따라 직위해제된 자에게 3개월의 범위에서 대기를 명한다.","ox":"O","m":"④","c":"A","tp":"국가공무원법 상 직위해제"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_2-19-1","t":"공무원인 피징계자에게 징계사유가 있어서 징계처분을 하는 경우 어떠한 처분을 할 것인가는 징계권자의 재량에 맡겨진 것이고, 다만 징계권자가 재량권의 행사로서 한 징계처분이 사회통념상 현저하게 타당성을 잃어 징계권자에게 맡겨진 재량권을 남용한 것이라고 인정되는 경우에 한하여 그 처분을 위법하다고 할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰공무원의 징계"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_2-19-2","t":"동료 경찰관에 대한 성희롱을 이유로 징계에 의하여 해임처분을 받은 경찰관은 해임처분을 받은 때부터 3년이 지나면 경찰 공무원으로 임용될 수 있다.","ox":"X","m":"②","c":"A","tp":"경찰공무원의 징계"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_2-19-3","t":"징계등 의결 요구를 받은 징계위원회는 그 요구서를 받은 날부터 30일 이내에 징계등에 관한 의결을 하여야 하나, 부득이한 사유가 있을 때에는 해당 징계등 의결을 요구한 경찰기관의 장의 승인을 받아 30일 이내의 범위에서 그 기한을 연기할 수 있다.","ox":"O","m":"③","c":"A","tp":"경찰공무원의 징계"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_2-19-4","t":"징계위원회는 징계등 의결을 하였을 때에는 지체 없이 징계등 의결을 요구한 자에게 의결서 정본(正本)을 보내어 통지하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰공무원의 징계"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_2-23-1","t":"「경찰공무원 임용령」 과 「경찰공무원 임용령 시행규칙」 에서는 경과별 직무의 종류를 규정하고 있으며, 수사경과·안보수사경과·항공경과·정보통신경과에 속하지 아니하는 직무를 일반경과의 직무로 구분하고 있다.","ox":"O","m":"①","c":"A","tp":"경찰공무원의 분류 및 관계"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_2-23-2","t":"「국적법」 제11조의2 제1항에 따른 복수국적자는 「경찰공무원법」 에 규정된 임용의 결격사유에 해당한다.","ox":"O","m":"②","c":"A","tp":"경찰공무원의 분류 및 관계"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_2-23-3","t":"「경찰공무원법」 에 따르면 경정 이하의 경찰공무원은 경찰청장 또는 해양경찰청장이 임용한다. 다만, 경정으로의 신규채용, 승진임용 및 면직은 경찰청장 또는 해양경찰청장의 제청으로 국무총리를 거쳐 대통령이 한다.","ox":"O","m":"③","c":"A","tp":"경찰공무원의 분류 및 관계"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_2-23-4","t":"「경찰공무원 임용령」 에 따르면 임용권자 또는 임용제청권자는 시보임용경찰공무원의 생활기록이 극히 불량할 경우 정규임용 심사위원회의 심사를 거쳐 면직시킬 수 있으나, 징계사유에 해당하는 경우에는 그러하지 아니한다.","ox":"X","m":"④","c":"A","tp":"경찰공무원의 분류 및 관계"},{"y":2025,"e":"경찰 공채","qn":29,"i":"PO2025_1-29-1","t":"채용후보자 등록을 하지 아니한 사람은 경찰공무원으로 임용될 의사가 없는 것으로 본다.","ox":"O","m":"①","c":"A","tp":"경찰공무원법 및 경찰공무원 임용령 상 경찰공무원 채용"},{"y":2025,"e":"경찰 공채","qn":29,"i":"PO2025_1-29-2","t":"경찰청장 또는 해양경찰청장은 채용후보자 명부의 유효기간을 연장하기로 결정한 경우에는 그 사실을 공고하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰공무원법 및 경찰공무원 임용령 상 경찰공무원 채용"},{"y":2025,"e":"경찰 공채","qn":29,"i":"PO2025_1-29-3","t":"경찰청장 또는 해양경찰청장은 경찰공무원의 신규채용시험에서 대통령령으로 정하는 부정행위를 한 사람에 대하여 부정행위자에 대한 제재로서 해당 시험의 정지‧ 무효 또는 합격 취소 처분을 할 때에는 미리 그 처분의 내용과 사유를 당사자에게 통지하여 소명할 기회를 주어야 한다.","ox":"X","m":"③","c":"A","tp":"경찰공무원법 및 경찰공무원 임용령 상 경찰공무원 채용"},{"y":2025,"e":"경찰 공채","qn":29,"i":"PO2025_1-29-4","t":"경찰공무원의 신규채용시험은 계급별로 실시한다. 다만, 결원 보충을 원활히 하기 위하여 필요하다고 인정될 때에는 직무 분야별‧ 근무예정지역 또는 근무예정기관별로 구분하여 실시할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰공무원법 및 경찰공무원 임용령 상 경찰공무원 채용"},{"y":2025,"e":"경찰 공채","qn":19,"i":"PO2025_2-19","t":"｢경찰공무원 징계령 세부시행규칙｣ 에 관한 설명으로 가장 적절한 것은?","c":"A","mc":{"s":"｢경찰공무원 징계령 세부시행규칙｣ 에 관한 설명으로 가장 적절한 것은?","d":"","o":["징계의결요구권자는 공금횡령‧ 유용 및 업무상 배임의 금액이 100만원 이상일 경우에는 중징계 의결을 요구하여야 한다.","징계요구권자 또는 징계위원회는 감독자가 부임기간이 3개월 미만으로 부하직원에 대한 실질적인 감독이 곤란하다고 인정된 때에는 징계책임을 감경하여 징계의결 요구 또는 징계의결하거나 징계책임을 묻지 아니할 수 있다.","징계의결요구권자 또는 징계위원회는 서로 관련이 없는 2개 이상의 의무위반행위가 경합될 때에는 그 중 책임이 중한 의무위반행위에 해당하는 징계보다 2단계 위의 징계의결 요구 또는 징계의결을 할 수 있다.","징계위원회는 징계의결이 요구된 자가 ｢모범공무원규정｣ 에 따라 모범공무원으로 선발된 공적이 있어도 징계의결이 요구된 자의 의무위반행위가 직무상 미공개 정보를 이용한 부당행위에 해당 하는 경우는 징계를 감경할 수 없다. ㉠ ㉡ ㉢ ㉣ ① (X) (O) (O) (X) ② (X) (O) (X) (X) ③ (O) (O) (O) (X) ④ (O) (X) (X) (O) - 14 -"],"a":3}},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_1-21-1","t":"대한민국 국적을 가지지 아니한 사람도 경찰공무원으로 임용 될 수 있다.","ox":"X","m":"①","c":"A","tp":"경찰공무원법 상 경찰공무원의 임용자격 및 결격사유"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_1-21-2","t":"피성년후견인 또는 피한정후견인은 경찰공무원으로 임용될 수 있다.","ox":"X","m":"②","c":"A","tp":"경찰공무원법 상 경찰공무원의 임용자격 및 결격사유"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_1-21-3","t":"금고 이상의 형의 선고유예를 선고받고 그 유예기간 중에 있는 사람은 경찰공무원으로 임용될 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰공무원법 상 경찰공무원의 임용자격 및 결격사유"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_1-21-4","t":"파산선고를 받고 복권되지 아니한 사람은 경찰공무원으로 임용 될 수 없다.","ox":"O","m":"④","c":"A","tp":"경찰공무원법 상 경찰공무원의 임용자격 및 결격사유"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_2-19-1","t":"경찰공무원은 직위 또는 직권을 이용하여 부당하게 타인의 민사 분쟁에 개입하여서는 아니된다.","ox":"O","m":"①","c":"A","tp":"경찰공무원의 의무"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_2-19-2","t":"경찰공무원은 근무시간중 음주를 하여서는 아니된다. 다만, 특별한 사정이 있는 경우에는 예외로 하되, 이 경우 주기가 있는 상태에서 직무를 수행하여서는 아니된다.","ox":"O","m":"②","c":"A","tp":"경찰공무원의 의무"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_2-19-3","t":"경찰공무원은 휴무일 또는 근무시간외에 2시간 이내에 직무에 복귀하기 어려운 지역으로 여행을 하고자 할 때에는 소속 경찰 기관의 장에게 신고를 하여야 하나, 치안상 특별한 사정이 있어 경찰청장, 해양경찰청장 또는 경찰기관의 장이 지정하는 기간중에는 소속 경찰기관의 장의 허가를 받아야 한다.","ox":"O","m":"③","c":"A","tp":"경찰공무원의 의무"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_2-19-4","t":"경찰공무원으로서 정치 관여 금지를 위반하여 정당이나 정치단체에 가입하거나 정치활동에 관여하는 행위를 한 사람은 5년 이하의 징역과 5년 이하의 자격정지에 처하고, 그 죄에 대한공소시효의 기간은 「형사소송법」 제249조 제1항에도 불구하고 7년으로 한다.","ox":"X","m":"④","c":"A","tp":"경찰공무원의 의무"},{"y":2026,"e":"경찰 공채","qn":30,"i":"PO2026_2-30-1","t":"경찰공무원은 임용장이나 임용통지서에 적힌 날짜에 임용된 것으로 본다.","ox":"O","m":"①","c":"A","tp":"경찰공무원 임용령"},{"y":2026,"e":"경찰 공채","qn":30,"i":"PO2026_2-30-2","t":"종전의 재직기관에서 경징계 이상의 징계처분을 받은 사람은 경력경쟁채용등의 대상이 될 수 없다.","ox":"X","m":"②","c":"A","tp":"경찰공무원 임용령"},{"y":2026,"e":"경찰 공채","qn":30,"i":"PO2026_2-30-3","t":"수사경과, 안보수사경과는 경정 이하 경찰공무원에게만 부여한다.","ox":"O","m":"③","c":"A","tp":"경찰공무원 임용령"},{"y":2026,"e":"경찰 공채","qn":30,"i":"PO2026_2-30-4","t":"경위 이상으로 신규채용된 경찰공무원은 관리능력을 배양할 수 있도록 전공 및 적성을 고려하여 합리적으로 보직하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰공무원 임용령"},{"y":2026,"e":"경찰 공채","qn":31,"i":"PO2026_2-31","t":"경찰징계 중에서 중징계인 동시에 교정징계에 해당하는 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰징계 중에서 중징계인 동시에 교정징계에 해당하는 것은 모두 몇 개인가?","d":"㉠ 파면 ㉡ 해임 ㉢ 강등 ㉣ 정직 ㉤ 감봉 ㉥ 견책","o":["2개","3개","4개","5개"],"a":1}}],"12":[{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_1-21-1","t":"‘시설경비업무’란 경비를 필요로 하는 시설 및 장소(이하 “경비 대상시설” 이라 한다)에서의 도난 화재 그 밖의 혼잡 등으로 인한 위험발생을 방지하는 업무를 말한다.","ox":"O","m":"①","c":"A","tp":"경비업법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_1-21-2","t":"‘호송경비업무’란 운반중에 있는 현금 유가증권 귀금속 상품 그 밖의 물건에 대하여 도난 화재 등 위험발생을 방지하는 업무를 말한다.","ox":"O","m":"②","c":"A","tp":"경비업법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_1-21-3","t":"‘신변보호업무’란 사람의 생명 신체 재산에 대한 위해의 발생을 방지하고 그 신변을 보호하는 업무를 말한다.","ox":"X","m":"③","c":"A","tp":"경비업법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":21,"i":"PO2022_1-21-4","t":"‘기계경비업무’란 경비대상시설에 설치한 기기에 의하여 감지 송신된 정보를 그 경비대상시설외의 장소에 설치한 관제시설의 기기로 수신하여 도난 화재 등 위험발생을 방지하는 업무를 말한다.","ox":"O","m":"④","c":"A","tp":"경비업법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_1-24-1","t":"‘테러위험인물’이란 테러를 실행 계획 준비하거나 테러에 참가할 목적으로 국적국이 아닌 국가의 테러단체에 가입하거나 가입 하기 위하여 이동 또는 이동을 시도하는 외국인을 말한다.","ox":"X","m":"①","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_1-24-2","t":"‘대테러활동’이란 제1호의 테러 관련 정보의 수집, 테러위험 인물의 관리, 테러에 이용될 수 있는 위험물질 등 테러수단의 안전관리, 인원 시설 장비의 보호, 국제행사의 안전확보, 테러 위협에의 대응 및 무력진압 등 테러 예방과 대응에 관한 제반 활동을 말한다.","ox":"O","m":"②","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_1-24-3","t":"‘테러단체’란 국제연합(UN)이 지정한 테러단체를 말한다.","ox":"O","m":"③","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_1-24-4","t":"‘대테러조사’란 대테러활동에 필요한 정보나 자료를 수집하기 위하여 현장조사 문서열람 시료채취 등을 하거나 조사대상자에게 자료제출 및 진술을 요구하는 활동을 말한다.","ox":"O","m":"④","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법 제2조 정의"},{"y":2022,"e":"경찰 공채","qn":38,"i":"PO2022_2-38-1","t":"밀도의 희박화 - 제한된 면적의 특정한 지역에 사람이 많이 모이면 상호간에 충돌현상이 나타나고 혼잡이 야기되므로, 차분한 목소리로 안내방송을 진행함으로써 사전에 혼잡상황을 대비하여 사고를 방지할 수 있다.","ox":"X","m":"①","c":"A","tp":"행사안전경비에서 군중정리의 원칙"},{"y":2022,"e":"경찰 공채","qn":38,"i":"PO2022_2-38-2","t":"이동의 일정화 - 군중은 현재의 자기 위치와 갈 곳을 잘 몰라 불안감과 초조감을 갖게 되므로 일정방향과 속도로 이동을 시켜 주위의 상황을 파악할 수 있는 여건을 조성시킴으로써 심리적 안정감을 갖도록 하는 것이다.","ox":"O","m":"②","c":"A","tp":"행사안전경비에서 군중정리의 원칙"},{"y":2022,"e":"경찰 공채","qn":38,"i":"PO2022_2-38-3","t":"경쟁적 사태의 해소 - 다른 사람보다 먼저 가려는 심리상태를 억제시켜 질서 있게 행동하면 모든 일이 잘 될 수 있다는 것을 납득시키는 것이다. 이 경우 질서를 지키면 오히려 손해를 본다는 심리상태가 형성되지 않도록 주의하여야 한다.","ox":"O","m":"③","c":"A","tp":"행사안전경비에서 군중정리의 원칙"},{"y":2022,"e":"경찰 공채","qn":38,"i":"PO2022_2-38-4","t":"지시의 철저 - 분명하고 자세한 안내방송을 계속함으로써 혼잡한 사태를 회피하고 사고를 방지할 수 있다.","ox":"O","m":"④","c":"A","tp":"행사안전경비에서 군중정리의 원칙"},{"y":2022,"e":"경찰 공채","qn":39,"i":"PO2022_2-39-1","t":"집회의 신고가 경합할 경우, 먼저 신고된 집회의 목적, 장소 및 시간, 참여예정인원, 집회 신고인이 기존에 신고한 집회 건수와 실제로 집회를 개최한 비율 등 먼저 신고된 집회의 실제 개최 가능성 여부와 양 집회의 상반 또는 방해가능성 등 제반 사정을 확인하여 먼저 신고된 집회가 다른 집회의 개최를 봉쇄하기 위한 허위 또는 가장 집회신고에 해당함이 객관적으로 분명해 보이는 경우라도 관할 경찰관서장이 뒤에 신고된 집회에 대하여 금지통고를 했다면, 이러한 금지통고에 위반하여 집회를 개최한 행위는 집회 및 시위에 관한 법률에 위배된다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":39,"i":"PO2022_2-39-2","t":"질서유지선이 집회 및 시위의 보호와 공공의 질서유지를 위하여 필요하다고 인정되는 최소한의 범위를 정하여 설정되고 집회 및 시위에 관한 법률 시행령 관련 조항에서 정한 사유에 해당한다면, 집회 또는 시위가 이루어지는 장소 외곽의 경계 지역뿐 아니라 집회 또는 시위의 장소 안에도 설정할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"경찰 공채","qn":39,"i":"PO2022_2-39-3","t":"경찰관들이 옥외집회 또는 시위 장소에서 줄지어 서는 등의 방법으로 소위 ‘사실상 질서유지선’의 역할을 수행한다고 하더 라도 이를 가리켜 집회 및 시위에 관한 법률에서 정한 질서 유지선이라고 할 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":39,"i":"PO2022_2-39-4","t":"집회·시위 참가자들이 관할 경찰관서에 신고하지 않고 집회를 개최한 경우, 그 옥외집회 또는 시위로 인하여 타인의 법익이나 공공의 안녕질서에 대한 직접적인 위험이 명백하게 초래되지 않은 상황에서 경찰이 ‘미신고집회’라는 사유로 자진 해산 요청을 한 후, ‘불법적인 행진시도’, ‘불법 도로 점거로 인한 도로교통법 제68조 제3항 제2호 위반’이라는 사유로 3회에 걸쳐 해산명령을 하였더라도 정당한 해산명령에 해당하지 않는다.","ox":"O","m":"④","c":"A","tp":"집회 및 시위"},{"y":2023,"e":"경찰 공채","qn":38,"i":"PO2023_1-38","t":"｢재난 및 안전관리 기본법｣ 에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢재난 및 안전관리 기본법｣ 에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["“재난”이란 국민의 생명･ 신체･ 재산과 국가에 피해를 주거나 줄 수 있는 것으로서 사회재난과 자연재난으로 구분한다.","“재난관리”란 재난의 예방･ 대비･ 대응 및 복구를 위하여 하는 모든 활동을 말한다.","경찰청장은 국가 및 지방자치단체가 행하는 재난 및 안전관리 업무를 총괄･ 조정한다.","대통령령으로 정하는 대규모 재난의 대응･ 복구 등에 관한 사항을 총괄･ 조정하고, 필요한 조치를 하기 위하여 행정안전부에 중앙재난안전대책본부를 둔다. ① ㉠ - ⓓ ㉡ - ⓒ ㉢ - ⓐ ㉣ - ⓑ ② ㉠ - ⓓ ㉡ - ⓐ ㉢ - ⓒ ㉣ - ⓑ ③ ㉠ - ⓒ ㉡ - ⓑ ㉢ - ⓓ ㉣ - ⓐ ④ ㉠ - ⓓ ㉡ - ⓐ ㉢ - ⓑ ㉣ - ⓒ - 16 -"],"a":3}},{"y":2023,"e":"경찰 공채","qn":38,"i":"PO2023_2-38-1","t":"「여권법」 제17조 제1항 단서에 따른 외교부장관의 허가를 받지 아니하고 방문 및 체류가 금지된 국가 또는 지역을 방문·체류한 사람이 테러로 인해 생명의 피해를 입은 경우, 그 사람의 유족에 대해 특별위로금을 지급할 수 있다.","ox":"X","m":"①","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2023,"e":"경찰 공채","qn":38,"i":"PO2023_2-38-2","t":"「국민보호와 공공안전을 위한 테러방지법」 에서 말하는 “테러 단체”란 국제형사경찰기구(ICPO)가 지정한 테러단체를 말한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"경찰 공채","qn":38,"i":"PO2023_2-38-3","t":"대테러활동을 수행하는 국가기관, 지방자치단체, 그 밖에 대통령령으로 정하는 기관의 대테러활동으로 인한 국민의 기본권 침해 방지를 위하여 국가테러대책위원회 소속으로 대테러 인권보호관 1명을 둔다.","ox":"O","m":"③","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2023,"e":"경찰 공채","qn":38,"i":"PO2023_2-38-4","t":"테러로 인하여 신체·재산·명예의 피해를 입은 국민은 관계기관에 즉시 신고하여야 한다. 다만, 인질 등 부득이한 사유로 신고 할 수 없을 때에는 법률관계 또는 계약관계에 의하여 보호 의무가 있는 사람이 이를 알게 된 때에 즉시 신고하여야 한다.","ox":"X","m":"④","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2023,"e":"경찰 공채","qn":39,"i":"PO2023_2-39","t":"｢집회 및 시위에 관한 법률｣ 에 관한 설명으로 옳은 것을 모두 고른 것은?","c":"A","mc":{"s":"｢집회 및 시위에 관한 법률｣ 에 관한 설명으로 옳은 것을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함) ㉠ “질서유지인”이란 관할 경찰서장이 집회 또는 시위의 질서를 유지하게 할 목적으로 임명한 자를 말한다. ㉡ 집회의 자유가 가지는 헌법적 가치와 기능, 집회에 대한 허가 금지를 선언한 헌법정신, 신고제도의 취지 등을 종합하여 보면, 신고는 행정관청에 집회에 관한 구체적인 정보를 제공 함으로써 공공질서의 유지에 협력하도록 하는 데 의의가 있는 것으로 집회의 허가를 구하는 신청으로 변질되어서는 아니 되므로, 신고를 하지 아니하였다는 이유만으로 옥외집회 또는 시위를 헌법의 보호 범위를 벗어나 개최가 허용되지 않는 집회 내지 시위라고 단정할 수 없다. ㉢ 관할경찰관서장은 옥외집회 및 시위에 관한 신고서의 기재 사항에 미비한 점을 발견하면 접수증을 교부한 때부터 24시간 이내에 주최자에게 48시간을 기한으로 그 기재 사항을 보완할 것을 통고할 수 있다. ㉣ ｢집회 및 시위에 관한 법률｣ 에 따른 신고 없이 이루어진 집회에 참석한 참가자들이 차로 위를 행진하는 등 도로교통을 방해함으로써 통행을 불가능하게 하거나 현저하게 곤란하게 하는 경우라도 참가자 모두에게 당연히 일반교통방해죄가 성립하는 것은 아니다.","o":["㉠㉡","㉡㉢","㉡㉣","㉢㉣"],"a":3}},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_2-39-1","t":"확성기등의 소음은 관할 경찰서장(현장 경찰공무원)과 주최자가 임명한 자가 함께 측정한다.","ox":"X","m":"①","c":"A","tp":"집회 및 시위"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_2-39-2","t":"등가소음도와 최고소음도를 측정하는 데 있어서 대상 지역을 주거지역·학교·종합병원, 공공도서관, 그 밖의 지역으로 구분 하고 시간대를 주간과 야간으로만 구분하여 각기 차별적인 등가 소음도와 최고소음도 기준을 적용한다.","ox":"X","m":"②","c":"A","tp":"집회 및 시위"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_2-39-3","t":"등가소음도는 10분간(소음 발생 시간이 10분 이내인 경우에는 그 발생 시간 동안을 말한다) 측정한다. 다만, 주거지역, 학교, 종합 병원, 공공도서관의 경우에는 등가소음도를 5분간(소음 발생 시간이 5분 이내인 경우에는 그 발생 시간 동안을 말한다) 측정한다.","ox":"O","m":"③","c":"A","tp":"집회 및 시위"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_2-39-4","t":"확성기등 사용을 제한하는 규정 도입 취지에 따라 신고대상 집회·시위가 아닌 경우뿐만 아니라 1인 시위의 경우에도 소음 제한 규정을 동일하게 적용한다.","ox":"X","m":"④","c":"A","tp":"집회 및 시위"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_1-36-1","t":"‘외국인테러전투원’이란 테러를 실행‧ 계획‧ 준비하거나 테러에 참가할 목적으로 국적국이 아닌 국가의 테러단체에 가입하거나 가입하기 위하여 이동 또는 이동을 시도하는 내국인‧ 외국인을 말한다.","ox":"O","m":"①","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_1-36-2","t":"관계기관의 대테러활동으로 인한 국민의 기본권 침해 방지를 위하여 국가테러대책위원회 소속으로 대테러 인권보호관 1명을 둔다.","ox":"O","m":"②","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_1-36-3","t":"대테러활동과 관련하여 장단기 국가대테러활동 지침 작성·배포 등을 수행하기 위하여 국무총리 소속으로 관계기관 공무원 및 민간위원으로 구성되는 대테러센터를 둔다.","ox":"X","m":"③","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2025,"e":"경찰 공채","qn":36,"i":"PO2025_1-36-4","t":"관계기관의 장은 대통령령으로 정하는 국가중요시설과 많은 사람이 이용하는 시설 및 장비에 대한 테러예방대책과 테러의 수단으로 이용될 수 있는 폭발물‧ 총기류‧ 화생방물질, 국가 중요 행사에 대한 안전관리대책을 수립하여야 한다.","ox":"O","m":"④","c":"A","tp":"국민보호와 공공안전을 위한 테러방지법"},{"y":2025,"e":"경찰 공채","qn":38,"i":"PO2025_1-38","t":"｢집회 및 시위에 관한 법률｣ 에 대한 설명이다. ㉠～㉢에 들어갈 내용으로 가장 적절한 것은?","c":"A","mc":{"s":"｢집회 및 시위에 관한 법률｣ 에 대한 설명이다. ㉠～㉢에 들어갈 내용으로 가장 적절한 것은?","d":"“옥외집회”란 (㉠)이 없거나 사방이 폐쇄되지 아니한 장소 에서 여는 집회를 말한다. “(㉡)”란 자기 이름으로 자기 책임 아래 집회나 시위를 여는 사람이나 단체를 말한다. “(㉢)”(이)란 국가경찰관서를 말한다. ㉠ ㉡ ㉢","o":["천장 주최자 경찰기관","천장 주최자 경찰관서","지붕 주최자 경찰관서","지붕 주관자 경찰기관"],"a":2}},{"y":2025,"e":"경찰 공채","qn":37,"i":"PO2025_2-37-1","t":"“필수요원”이란 모든 경찰공무원 및 일반직공무원 중 경찰기관의 장이 지정한 사람으로 비상소집 시 1시간 이내에 응소해야 할 사람을 말한다.","ox":"O","m":"①","c":"A","tp":"경찰 비상업무 규칙"},{"y":2025,"e":"경찰 공채","qn":37,"i":"PO2025_2-37-2","t":"비상근무의 발령권자는 비상상황이 종료되는 즉시 비상근무를 해제한다.","ox":"O","m":"②","c":"A","tp":"경찰 비상업무 규칙"},{"y":2025,"e":"경찰 공채","qn":37,"i":"PO2025_2-37-3","t":"작전준비태세가 발령되면 작전경력을 동원하고 지휘관과 참모는 정위치 근무를 원칙으로 한다.","ox":"X","m":"③","c":"A","tp":"경찰 비상업무 규칙"},{"y":2025,"e":"경찰 공채","qn":37,"i":"PO2025_2-37-4","t":"비상근무 대상은 경비‧ 작전‧ 재난‧ 안보‧ 수사‧ 교통 업무와 관련한 비상상황에 국한한다. 다만, 두 종류 이상의 비상상황이 동시에 발생한 경우에는 긴급성 또는 중요도가 상대적으로 더 큰 비상상황의 비상근무로 통합하여 실시한다.","ox":"O","m":"④","c":"A","tp":"경찰 비상업무 규칙"},{"y":2026,"e":"경찰 공채","qn":35,"i":"PO2026_1-35","t":"｢경비업법｣ 에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"｢경비업법｣ 에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ ‘혼잡‧ 교통유도 경비업무’란 도로에 접속한 공사현장 및 사람과 차량의 통행에 위험이 있는 장소 또는 도로를 점유 하는 행사장 등에서 교통사고나 그 밖의 혼잡 등으로 인한 위험발생을 방지하는 업무를 말한다. ㉡ ｢도시 및 주거환경정비법｣ 에 따른 정비사업과 관련하여 이해대립이 있어 다툼이 있는 장소는 ‘집단민원현장’에 해당한다. ㉢ 경비업자는 허가받은 경비업무외의 업무에 경비원을 종사하게 하여서는 아니된다. 다만, 경비업무의 목적 달성을 침해하지 아니하는 범위에서 행정안전부령으로 정하는 업무에 대하여는 경비원을 종사하게 할 수 있다. ㉣ 경비업을 영위하고자 하는 법인은 도급받아 행하고자 하는 경비업무를 특정하여 그 법인의 주사무소의 소재지를 관할 하는 시‧ 도경찰청장의 허가를 받아야 한다. ㉤ 경비업의 허가를 받은 법인이 영업을 폐업하거나 휴업한 때에는 시‧ 도경찰청장에게 신고하여야 한다.","o":["2개","3개","4개","5개"],"a":3}},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_1-38-1","t":"제3조 제4호에서는 재난이나 그 밖의 각종 사고로부터 사람의 생명 및 신체의 안전을 확보하기 위하여 하는 모든 활동을 ‘안전 관리’로 정의하고 있다.","ox":"X","m":"①","c":"A","tp":"재난 및 안전관리 기본법"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_1-38-2","t":"재난 및 안전관리에 관한 중요 정책과 관련된 사항 등을 심의하기 위하여 행정안전부장관 소속으로 중앙안전관리위원회를 둔다.","ox":"X","m":"②","c":"A","tp":"재난 및 안전관리 기본법"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_1-38-3","t":"행정안전부장관은 국가 및 지방자치단체가 행하는 재난 및 안전관리 업무를 총괄‧ 조정한다.","ox":"O","m":"③","c":"A","tp":"재난 및 안전관리 기본법"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_1-38-4","t":"재난관리 체계 중 재난피해 신고 및 조사, 응급조치, 특별재난 지역의 선포 등은 복구 단계에서의 활동이다.","ox":"X","m":"④","c":"A","tp":"재난 및 안전관리 기본법"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_2-37-1","t":"「테러취약시설 안전활동에 관한 규칙」 상 A급 다중이용건축물등은 테러에 의하여 파괴되거나 기능 마비시 광범위한 지역의 대테러 진압작전이 요구되고, 국민생활에 결정적인 영향을 미칠 수 있는 건축물 또는 시설을 말한다.","ox":"O","m":"①","c":"A","tp":"대테러경찰활동"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_2-37-2","t":"「테러취약시설 안전활동에 관한 규칙」 에 따라, 경찰서장은 분기 1회 이상 권역별로 대테러 훈련을 실시하여야 한다. 이 경우 연 1회 이상은 관계기관 합동으로 실시한다.","ox":"X","m":"②","c":"A","tp":"대테러경찰활동"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_2-37-3","t":"「국민보호와 공공안전을 위한 테러방지법」 에 따라, 관계기관의 장은 외국인테러전투원으로 출국하려 한다고 의심할 만한 상당한 이유가 있는 외국인에 대하여 일시 출국금지를 법무부장관에게 요청할 수 있다.","ox":"O","m":"③","c":"A","tp":"대테러경찰활동"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_2-37-4","t":"「국민보호와 공공안전을 위한 테러방지법」 에 따르면, 테러에 이용될 수 있는 위험물질 등 테러수단의 안전관리는 “대테러 활동”에 해당한다.","ox":"O","m":"④","c":"A","tp":"대테러경찰활동"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_2-39-1","t":"“질서유지선”이란 관할 경찰서장이나 시‧ 도경찰청장이 집회 및 시위를 효율적으로 지휘‧ 조정‧ 통제 및 관리하기 위하여 집회 또는 시위의 장소나 행진 구간을 일정하게 구획하여 설정한 띠, 방책 (防柵), 차선(車線) 등의 경계 표지(標識)를 말한다.","ox":"X","m":"①","c":"A"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_2-39-2","t":"「집회 및 시위에 관한 법률」 제6조 제1항에 따른 신고를 받은 관할 경찰관서장은 집회 및 시위의 보호와 공공의 질서 유지를 위하여 필요하다고 인정하면 최소한의 범위를 정하여 질서유지선을 설정할 수 있다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_2-39-3","t":"관할 경찰관서장은 집회 및 시위의 보호와 공공의 질서 유지를 위하여 집회‧ 시위의 장소를 한정하거나 집회‧ 시위의 참가자와 일반인을 구분할 필요가 있을 경우 「집회 및 시위에 관한 법률」 제13조 제1항에 따라 질서유지선을 설정할 수 있다.","ox":"O","m":"③","c":"A"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_2-39-4","t":"「집회 및 시위에 관한 법률」 제13조 제2항에 따른 질서유지선의 설정 고지는 서면으로 하여야 한다. 다만, 집회 또는 시위 장소의 상황에 따라 질서유지선을 새로 설정하거나 변경하는 경우에는 집회 또는 시위의 장소에 있는 경찰공무원이 구두로 알릴 수 있다.","ox":"O","m":"④","c":"A"}],"11":[{"y":2022,"e":"경찰 공채","qn":22,"i":"PO2022_1-22-1","t":"‘범죄피해자’란 타인의 범죄행위로 피해를 당한 사람과 그 배우자, 직계친족 및 형제자매를 말한다. 다만, 배우자의 경우 사실상의 혼인관계는 제외한다.","ox":"X","m":"①","c":"A","tp":"범죄피해자 보호법"},{"y":2022,"e":"경찰 공채","qn":22,"i":"PO2022_1-22-2","t":"국가는 범죄피해자가 해당 사건과 관련하여 수사담당자와 상담하거나 재판절차에 참여하여 진술하는 등 형사절차상의 권리를 행사할 수 있도록 보장하여야 한다.","ox":"O","m":"②","c":"A","tp":"범죄피해자 보호법"},{"y":2022,"e":"경찰 공채","qn":22,"i":"PO2022_1-22-3","t":"국가는 범죄피해자가 요청하면 가해자에 대한 수사 결과, 공판기일, 재판 결과, 형 집행 및 보호관찰 집행 상황 등 형사 절차 관련 정보를 대통령령으로 정하는 바에 따라 제공할 수 있다.","ox":"O","m":"③","c":"A","tp":"범죄피해자 보호법"},{"y":2022,"e":"경찰 공채","qn":22,"i":"PO2022_1-22-4","t":"국가 및 지방자치단체는 범죄피해자가 형사소송절차에서 한 진술이나 증언과 관련하여 보복을 당할 우려가 있는 등 범죄 피해자를 보호할 필요가 있을 경우에는 적절한 조치를 마련 하여야 한다.","ox":"O","m":"④","c":"A","tp":"범죄피해자 보호법"},{"y":2022,"e":"경찰 공채","qn":35,"i":"PO2022_2-35-1","t":"사법경찰관리는 아동 청소년의 성보호에 관한 법률 제11조 및 제15조의2의 죄, 아동 청소년에 대한 성폭력범죄의 처벌 등에 관한 특례법 제14조 제2항 및 제3항의 죄에 해당하는 ‘디지털 성범죄’에 대하여 신분을 비공개하고 범죄현장(정보통신망 포함) 또는 범인으로 추정되는 자들에게 접근하여 범죄행위의 증거 및 자료 등을 수집할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":35,"i":"PO2022_2-35-2","t":"사법경찰관리가 신분비공개수사를 진행하고자 할 때에는 사전에 상급 경찰관서 수사부서의 장의 승인을 받아야 한다. 이 경우 그 수사기간은 1개월을 초과할 수 없다.","ox":"X","m":"②","c":"A","tp":"아동 청소년의 성보호"},{"y":2022,"e":"경찰 공채","qn":35,"i":"PO2022_2-35-3","t":"사법경찰관리는 신분위장수사를 하려는 경우에는 검사에게 신분위장수사에 대한 허가를 신청하고, 검사는 법원에 그 허가를 청구한다. 다만 신분위장수사 절차를 거칠 수 없는 긴급을 요하는 때에는 동법 제25조의2 제2항의 요건을 구비하고 법원의 허가 없이 신분위장수사를 할 수 있다. 이 경우, 사법경찰관리는 신분위장수사 개시 후 지체 없이 검사에게 허가를 신청하여야 하고, 48시간 이내에 법원의 허가를 받지 못한 때에는 즉시 신분위장수사를 중지하여야 한다.","ox":"O","m":"③","c":"A","tp":"아동 청소년의 성보호"},{"y":2022,"e":"경찰 공채","qn":35,"i":"PO2022_2-35-4","t":"국가수사본부장은 신분비공개수사가 종료된 즉시 대통령령으로 정하는 바에 따라 국가경찰위원회에 수사 관련 자료를 보고하여야 하며, 국가수사본부장은 대통령령으로 정하는 바에 따라 국회 소관 상임위원회에 신분비공개수사 관련 자료를 반기별로 보고하여야 한다.","ox":"O","m":"④","c":"A","tp":"아동 청소년의 성보호"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_2-37-1","t":"경찰관은 성폭력범죄의 피해자가 13세 미만이거나 신체적인 또는 정신적인 장애로 사물을 변별하거나 의사를 결정할 능력이 미약한 경우에는 통합지원센터나 성폭력 전담의료기관과 연계하여 치료, 상담 및 조사를 병행한다. 다만, 피해자가 원하지 않는 경우에는 그러하지 아니하다.","ox":"O","m":"①","c":"A","tp":"성폭력범죄의 수사 및 피해자 보호"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_2-37-2","t":"경찰서장은 특별한 사정이 없는 한 성폭력 피해여성을 여성 성폭력범죄 전담조사관이 조사하도록 하여야 한다. 다만, 피해자가 원하는 경우에는 신뢰관계자, 진술조력인 또는 다른 경찰관으로 하여금 입회하게 하고 ‘피해자 조사 동의서’에 서면으로 동의를 받아 남성 성폭력범죄 전담조사관으로 하여금 조사하게 할 수 있다.","ox":"O","m":"②","c":"A","tp":"성폭력범죄의 수사 및 피해자 보호"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_2-37-3","t":"경찰관은 영상녹화를 할 때에는 피해자등에게 영상녹화의 취지 등을 설명하고 동의 여부를 확인하여야 하며, 피해자등이 녹화를 원하지 않는 의사를 표시한 때에는 촬영을 하여서는 아니 된다. 다만, 가해자가 친권자 중 일방인 경우에는 그러하지 아니하다.","ox":"O","m":"③","c":"A","tp":"성폭력범죄의 수사 및 피해자 보호"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_2-37-4","t":"경찰관은 성폭력범죄의 피해자가 13세 미만이거나 신체적인 또는 정신적인 장애로 의사소통이나 의사표현에 어려움이 있는 경우 진술조력인을 조사과정에 반드시 참여시켜야 한다.","ox":"X","m":"④","c":"A","tp":"성폭력범죄의 수사 및 피해자 보호"},{"y":2023,"e":"경찰 공채","qn":37,"i":"PO2023_1-37","t":"다음은 ｢마약류 관리에 관한 법률 및 동법 시행령｣ 상 마약류에 관한 설명이다. <보기 1>의 설명과 <보기 2> 마약류의 품명이 가장 적절하게 연결된 것은?","c":"A","mc":{"s":"다음은 ｢마약류 관리에 관한 법률 및 동법 시행령｣ 상 마약류에 관한 설명이다. <보기 1>의 설명과 <보기 2> 마약류의 품명이 가장 적절하게 연결된 것은?","d":"<보기 1> ㉠ 진해거담제로서 의사의 처방이 있으면 약국에서 구입 가능 하고, 도취감과 환각작용을 느끼기 위해 사용량의 수십 배를 남용하는 경우도 있다. 청소년들이 소주에 타서 마시기도 하여 흔히 ‘정글주스’라고도 불린다. ㉡ 골격근 이완의 효과가 있는 근골격계 질환 치료제이며, 과다복용 시 인사불성, 혼수쇼크, 호흡저하, 사망에까지 이를 수 있다. ㉢ 곡물의 곰팡이, 보리 맥각에서 추출･ 합성한 무색･ 무취･ 무미의 매우 강력한 환각제로, 내성은 있으나 금단증상은 일으키지 않는다고 알려져 있다. ㉣ 페놀계 화합물로 흔히 수면마취제라고 불리는 정맥마취제로서 수면내시경검사 마취 등에 사용되고, 환각제 대용으로 오남용되는 사례가 있으며, 정신적 의존성을 유발하기도 한다. <보기 2> ⓐ 카리소프로돌(S정) ⓒ LSD ⓑ 프로포폴 ⓓ 덱스트로메트로판(러미나)","o":["","","",""],"a":2}},{"y":2023,"e":"경찰 공채","qn":35,"i":"PO2023_2-35-1","t":"“아동·청소년”이란 19세 미만의 자를 말한다. 다만, 19세에 도달 하는 연도의 1월 1일을 맞이한 자는 제외한다.","ox":"O","m":"①","c":"A","tp":"아동･ 청소년의 성보호"},{"y":2023,"e":"경찰 공채","qn":35,"i":"PO2023_2-35-2","t":"위계(僞計) 또는 위력으로써 아동·청소년을 추행한 자에 대한 미수범 처벌규정을 두고 있다.","ox":"O","m":"②","c":"A","tp":"아동･ 청소년의 성보호"},{"y":2023,"e":"경찰 공채","qn":35,"i":"PO2023_2-35-3","t":"사법경찰관리는 19세 이상의 사람이 성적 착취를 목적으로 정보 통신망을 통하여 아동·청소년에게 성적 욕망이나 수치심 또는 혐오감을 유발할 수 있는 대화를 지속적 또는 반복적으로 하거나 그러한 대화에 지속적 또는 반복적으로 참여시키는 행위를 한 범죄에 대하여 신분을 비공개하고 범인으로 추정되는 자들에게 접근하여 범죄행위의 증거 및 자료 등을 수집할 수 있다.","ox":"O","m":"③","c":"A","tp":"아동･ 청소년의 성보호"},{"y":2023,"e":"경찰 공채","qn":35,"i":"PO2023_2-35-4","t":"사법경찰관리가 디지털 성범죄에 대한 신분위장수사를 할 때 신분을 위장하기 위한 문서, 도화 및 전자기록 등의 작성, 변경 또는 행사는 가능하지만, 아동·청소년성착취물을 소지, 판매 또는 광고할 수 없다.","ox":"X","m":"④","c":"A","tp":"아동･ 청소년의 성보호"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_1-35-1","t":"외표검사란 죄질이 경미하고 동작과 언행에 특이사항이 없으며 위험물 등을 은닉하고 있지 않다고 판단되는 유치인에 대하여는 신체 등의 외부를 눈으로 확인하고 손으로 가볍게 두드려 만져 검사하는 것을 말한다.","ox":"O","m":"①","c":"A","tp":"피의자 유치 및 호송규칙"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_1-35-2","t":"동시에 2명 이상의 피의자를 입감시킬 때에는 경위 이상 경찰관이 입회하여 순차적으로 입감시켜야 한다.","ox":"X","m":"②","c":"A","tp":"피의자 유치 및 호송규칙"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_1-35-3","t":"신체 등의 검사는 동성의 유치인보호관이 실시하여야 한다. 다만, 여성유치인보호관이 없을 경우에는 미리 지정하여 신체 등의 검사방법을 교양 받은 여성경찰관으로 하여금 대신하게 할 수 있다.","ox":"O","m":"③","c":"A","tp":"피의자 유치 및 호송규칙"},{"y":2024,"e":"경찰 공채","qn":35,"i":"PO2024_1-35-4","t":"호송은 원칙적으로 일출전 또는 일몰후에 할 수 없다.","ox":"O","m":"④","c":"A","tp":"피의자 유치 및 호송규칙"},{"y":2024,"e":"경찰 공채","qn":36,"i":"PO2024_1-36","t":"｢아동･ 청소년의 성보호에 관한 법률｣ 에 대한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"｢아동･ 청소년의 성보호에 관한 법률｣ 에 대한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 아동･ 청소년성착취물을 제작한 자에 대한 미수범 처벌규정이 있다. ㉡ 폭행 또는 협박으로 아동･ 청소년을 강간할 목적으로 예비 또는 음모한 자에 대한 처벌규정이 있다. ㉢ 아동･ 청소년의 성을 사는 행위를 한 자에 대한 미수범 처벌 규정이 있다. ㉣ 13세 미만의 사람에 대하여 강간죄를 범한 경우에는 공소시효를 적용하지 않는다.","o":["1개","2개","3개","4개"],"a":3}},{"y":2024,"e":"경찰 공채","qn":36,"i":"PO2024_2-36","t":"향정신성의약품 중 LSD에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"향정신성의약품 중 LSD에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 근육강화 호르몬 분비효과가 있으며, 소다수 등에 타서 타인 에게 복용하게 하여 성범죄 등에 악용한다. ㉡ 곡물의 곰팡이, 보리 맥각에서 추출한 물질을 인공적으로 합성시켜 만들어낸 것으로 무색･ 무취･ 무미하다. ㉢ 미량을 우편, 종이 등의 표면에 묻혔다가 뜯어서 입에 넣는 방법으로 복용하기도 한다. ㉣ 강한 중추신경 억제성 진해작용이 있으며 코데인 대용으로 시판되고 있다. ㉤ 일부 남용자들은 실제로 사용하지 않는데도 환각현상을 경험 하는 ‘플래쉬백 현상’을 일으키기도 한다.","o":["1개","2개","3개","4개 - 16 -"],"a":3}},{"y":2024,"e":"경찰 공채","qn":37,"i":"PO2024_2-37","t":"｢특정중대범죄 피의자 등 신상정보 공개에 관한 법률｣ 에 대한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"｢특정중대범죄 피의자 등 신상정보 공개에 관한 법률｣ 에 대한 설명으로 옳은 것은 모두 몇 개인가?","d":"㉠ 검사와 사법경찰관은 이 법상 신상정보 공개 요건을 모두 갖춘 특정중대범죄사건의 피의자의 얼굴, 성명 및 나이를 공개할 수 있다. 다만, 피의자가 미성년자인 경우에는 공개 하지 아니할 수 있다. ㉡ 검사와 사법경찰관은 이 법상 신상정보 공개를 결정할 때에는 범죄의 중대성, 범행 후 정황, 피해자 보호 필요성, 피해자 (피해자가 사망한 경우 피해자의 유족을 포함한다)의 의사 등을 종합적으로 고려하여야 한다. ㉢ 법무부장관은 이 법상 신상정보 공개 여부에 관한 사항을 심의하기 위하여 신상정보공개심의위원회를 둘 수 있다. ㉣ 수사 및 재판 단계에서 신상정보의 공개에 대하여는 다른 법률의 규정이 있는 경우 그 법률에 따른다.","o":["없음","1개","2개","3개"],"a":2}},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_2-35-1","t":"“범죄피해자”란 타인의 범죄행위로 피해를 당한 사람과 그 배우자 (사실상의 혼인관계를 포함한다), 직계친족 및 형제자매를 말한다.","ox":"O","m":"①","c":"A","tp":"범죄피해자 보호법"},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_2-35-2","t":"구조금은 유족구조금‧ 장해구조금 및 중상해구조금으로 구분한다.","ox":"O","m":"②","c":"A","tp":"범죄피해자 보호법"},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_2-35-3","t":"범죄행위 당시 구조피해자와 가해자 사이가 4촌 이내의 친족인 경우에는 구조금을 지급하지 아니한다.","ox":"O","m":"③","c":"A","tp":"범죄피해자 보호법"},{"y":2025,"e":"경찰 공채","qn":35,"i":"PO2025_2-35-4","t":"구조피해자가 과도한 폭행‧ 협박 또는 중대한 모욕 등 해당 범죄행위를 유발하는 행위를 한 때에는 구조금의 일부를 지급 하지 아니한다.","ox":"X","m":"④","c":"A","tp":"범죄피해자 보호법"},{"y":2026,"e":"경찰 공채","qn":36,"i":"PO2026_1-36","t":"수사실행을 위한 5대 원칙에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","c":"A","mc":{"s":"수사실행을 위한 5대 원칙에 관한 설명으로 옳지 않은 것을 모두 고른 것은?","d":"㉠ 사실판단 증명의 원칙: 수사경찰의 판단을 형사사법절차에 올려놓기 위해서는 수사경찰의 주관적인 판단이 객관적으로 증명되어야 한다. ㉡ 수사자료 감식‧ 검토의 원칙: 여러 가지 추측 중에서 어떤 추측이 정당한 것인가를 가리기 위해서는 그들 추측 하나 하나를 모든 각도에서 검토하여야 한다. ㉢ 검증적 수사의 원칙: ‘수사방법의 결정’ → ‘수사사항의 결정’ → ‘수사실행’이라는 순서에 따라 사건에 대한 추리를 검증 하여야 한다. ㉣ 수사자료 완전수집의 원칙: 수사의 제1원칙으로서 기초수사를 통해 수사자료를 완전히 수집하여 문제를 명확하게 하고자 노력하여야 한다.","o":["㉠㉡","㉠㉢","㉡㉢","㉡㉣ - 16 -"],"a":3}},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_1-37-1","t":"검사와 사법경찰관은 신상정보 공개를 결정할 때에는 범죄의 중대성, 범행 후 정황, 피해자 보호 필요성, 피해자(피해자가 사망한 경우 피해자의 유족을 포함한다)의 의사 등을 종합적으로 고려하여야 한다.","ox":"O","m":"①","c":"A","tp":"특정중대범죄 피의자 등 신상정보 공개"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_1-37-2","t":"공개하는 피의자의 얼굴은 특별한 사정이 없으면 공개 결정일 전후 30일 이내의 모습으로 한다. 이 경우 검사와 사법경찰관은 다른 법령에 따라 적법하게 수집‧ 보관하고 있는 사진, 영상물 등이 있는 때에는 이를 활용하여 공개할 수 있다.","ox":"O","m":"②","c":"A","tp":"특정중대범죄 피의자 등 신상정보 공개"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_1-37-3","t":"검사와 사법경찰관은 피의자의 얼굴을 공개하기 위하여 필요한 경우 피의자를 식별할 수 있도록 피의자의 얼굴을 촬영할 수 있다. 이 경우 피의자는 이에 따라야 한다.","ox":"O","m":"③","c":"A","tp":"특정중대범죄 피의자 등 신상정보 공개"},{"y":2026,"e":"경찰 공채","qn":37,"i":"PO2026_1-37-4","t":"검사와 사법경찰관은 피의자의 신상정보 공개가 결정된 날부터 3일 이상의 유예기간을 두고 신상정보를 공개하여야 한다. 다만, 피의자가 신상정보 공개 결정에 대하여 서면으로 이의 없음을 표시한 때에는 유예기간을 두지 아니할 수 있다.","ox":"X","m":"④","c":"A","tp":"특정중대범죄 피의자 등 신상정보 공개"},{"y":2026,"e":"경찰 공채","qn":36,"i":"PO2026_2-36","t":"｢아동･ 청소년의 성보호에 관한 법률｣ 상 미수범을 처벌하는 경우만을 모두 고른 것은?","c":"A","mc":{"s":"｢아동･ 청소년의 성보호에 관한 법률｣ 상 미수범을 처벌하는 경우만을 모두 고른 것은?","d":"㉠ 위계(僞計) 또는 위력으로써 아동‧ 청소년을 간음하거나 아동‧ 청소년을 추행한 자 ㉡ 아동‧ 청소년성착취물을 제작‧ 수입 또는 수출한 자 ㉢ 아동‧ 청소년을 아동‧ 청소년성착취물의 제작자에게 알선한 자 ㉣ 아동‧ 청소년성착취물을 이용한 협박으로 그 아동‧ 청소년의 권리행사를 방해하거나 의무 없는 일을 하게 한 자 ㉤ 영업으로 아동‧ 청소년을 아동‧ 청소년의 성을 사는 행위의 상대방이 되도록 유인‧ 권유한 자","o":["㉠㉡㉤","㉡㉢㉣","㉠㉡㉣㉤","㉠㉢㉣㉤ - 16 -"],"a":3}},{"y":2026,"e":"경찰 공채","qn":40,"i":"PO2026_2-40-1","t":"“범죄피해자 보호‧ 지원”이란 범죄피해자의 손실 복구, 정당한 권리 행사 및 복지 증진에 기여하는 행위를 말한다. 다만, 수사‧ 변호 또는 재판에 부당한 영향을 미치는 행위는 포함되지 아니한다.","ox":"O","m":"①","c":"A","tp":"범죄피해자 보호법"},{"y":2026,"e":"경찰 공채","qn":40,"i":"PO2026_2-40-2","t":"구조금은 유족구조금‧ 장해구조금 및 중상해구조금으로 구분한다.","ox":"O","m":"②","c":"A","tp":"범죄피해자 보호법"},{"y":2026,"e":"경찰 공채","qn":40,"i":"PO2026_2-40-3","t":"장해구조금 및 중상해구조금은 해당 구조피해자에게 지급한다. 다만, 장해구조금 또는 중상해구조금의 지급을 신청한 구조피해자가 장해구조금 또는 중상해구조금을 지급받기 전에 해당 구조대상 범죄피해의 원인이 된 범죄행위로 사망한 경우에는 제18조(유족의 범위 및 순위)에 따라 맨 앞의 순위인 유족에게 지급하되, 순위가 같은 유족이 2명 이상이면 똑같이 나누어 지급한다.","ox":"X","m":"③","c":"A","tp":"범죄피해자 보호법"},{"y":2026,"e":"경찰 공채","qn":40,"i":"PO2026_2-40-4","t":"유족이 구조피해자가 사망하기 전에 그가 사망하면 유족구조금 등을 받을 수 있는 선순위 또는 같은 순위의 유족이 될 사람을 고의로 사망하게 한 경우에 해당하면 유족구조금등을 받을 수 있는 유족으로 보지 아니한다.","ox":"O","m":"④","c":"A","tp":"범죄피해자 보호법"}],"13":[{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_1-25-1","t":"술에 취해 자동차 안에서 잠을 자다가 추위를 느껴 히터를 가동 시키기 위하여 시동을 걸었고, 실수로 자동차의 제동장치 등을 건드렸거나 처음 주차할 때 안전조치를 제대로 취하지 아니한 탓으로 원동기의 추진력에 의하여 자동차가 약간 경사진 길을 따라 앞으로 움직여 피해자의 차량 옆면을 충격한 사실은 엿볼 수 있으나 이를 두고 피고인이 자동차를 운전하였다고 할 수는 없다.","ox":"O","m":"①","c":"A","tp":"음주운전 관련 판례"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_1-25-2","t":"운전자가 경찰공무원으로부터 음주측정을 요구받고 호흡측정기에 숨을 내쉬는 시늉만 하는 등 형식적으로 음주측정에 응하였을 뿐 경찰공무원의 거듭된 요구에도 불구하고 호흡측정기에 음주 측정수치가 나타날 정도로 숨을 제대로 불어넣지 아니하였다면 이는 실질적으로 음주측정에 불응한 것과 다를 바 없다.","ox":"O","m":"②","c":"A","tp":"음주운전 관련 판례"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_1-25-3","t":"음주운전과 관련한 도로교통법 위반죄의 범죄수사를 위하여 미성년자인 피의자의 혈액채취가 필요한 경우에도 피의자에게 의사능력이 있다면 피의자 본인만이 혈액채취에 관한 유효한 동의를 할 수 있고, 피의자에게 의사능력이 없는 경우 명문의 규정이 없더라도 법정대리인이 피의자를 대리하여 동의할 수 있다.","ox":"X","m":"③","c":"A","tp":"음주운전 관련 판례"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_1-25-4","t":"특별한 이유 없이 호흡측정기에 의한 측정에 불응하는 운전자에게 경찰공무원이 혈액채취에 의한 측정방법이 있음을 고지 하고 그 선택 여부를 물어야 할 의무가 있다고는 할 수 없다.","ox":"O","m":"④","c":"A","tp":"음주운전 관련 판례"},{"y":2022,"e":"경찰 공채","qn":40,"i":"PO2022_2-40-1","t":"운전자가 음주운전으로 교통사고를 야기한 후, 차에서 내려 피해자(진단 3주)에게 ‘왜 와서 들이받냐’라는 말을 하고, 교통 사고 조사를 위해 경찰서에 가자는 경찰관의 지시에 순순히 응하여 순찰차에 스스로 탑승하여 경찰서까지 갔을 뿐 아니라 경찰서에서 조사받으면서 사고 당시 상황에 대한 자신의 주장을 정확하게 진술하였다면, 비록 경찰관이 작성한 주취운전자 정황진술보고서에는 ‘언행상태’란에 ‘발음 약간 부정확’, ‘보행 상태’란에 ‘비틀거림이 없음’, ‘운전자 혈색’란에 ‘안면 홍조 및 눈 충혈’이라고 기재되어 있다고 하더라도 음주로 인한 특정 범죄 가중처벌 등에 관한 법률 위반(위험운전치사상)이 아니라 도로교통법 위반(음주운전)으로 처벌해야 한다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":40,"i":"PO2022_2-40-2","t":"도로교통법 및 관련 법령에는 연습운전면허를 발급받은 사람이 본인에게 귀책사유(歸責事由)가 없는 경우 등 대통령령으로 정하는 경우를 제외하고, 운전 중 고의 또는 과실로 교통사고를 일으키거나 도로교통법이나 동법에 따른 명령 또는 처분을 위반한 경우에 시 도경찰청장은 연습운전면허를 취소하여야 한다고 규정하고 있으므로, 연습운전면허를 받은 사람이 운전을 함에 있어 주행연습 외의 목적으로 운전하여서는 아니된다는 준수사항을 지키지 않았다고 하더라도 무면허운전으로 처벌할 수는 없다.","ox":"O","m":"②","c":"A"},{"y":2022,"e":"경찰 공채","qn":40,"i":"PO2022_2-40-3","t":"도로교통법상 도로가 아닌 곳에서 술에 취한 상태에서의 운전은 음주운전으로는 처벌할 수 있지만 운전면허의 정지 또는 취소처분을 부과할 수는 없다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":40,"i":"PO2022_2-40-4","t":"개인형 이동장치를 타고 신호위반, 중앙선 침범과 진로변경 금지 위반행위를 연달아 하여 다른 사람에게 위협 또는 위해를 가할 뿐 아니라 교통상의 위험을 발생하게 한 운전자에 대해 난폭운전으로 처벌할 수 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":39,"i":"PO2023_1-39","t":"음주운전 관련 판례에 관한 설명 중 가장 적절하지 않은 것은?","c":"A","mc":{"s":"음주운전 관련 판례에 관한 설명 중 가장 적절하지 않은 것은?","d":"","o":["경찰관이 술에 취한 상태에서 자동차를 운전한 것으로 보이는 피고인을 ｢경찰관 직무집행법｣ 에 따른 보호조치 대상자로 보아 경찰관서로 데려온 직후 음주측정을 요구하였는데 피고인이 불응하여 음주측정불응죄로 기소된 사안에서, 위법한 보호조치 상태를 이용하여 음주측정 요구가 이루어졌다는 등의 특별한 사정이 없는 한 피고인의 행위는 음주측정불응죄에 해당한다.","술에 취해 자동차 안에서 잠을 자다가 추위를 느껴 히터를 가동시키기 위하여 시동을 걸었고, 실수로 자동차의 제동장치 등을 건드렸거나 처음 주차할 때 안전조치를 제대로 취하지 아니한 탓으로 원동기의 추진력에 의하여 자동차가 약간 경사진 길을 따라 앞으로 움직여 피해자의 차량 옆면을 충격하게 된 경우는 자동차의 운전에 해당한다.","음주측정 요구 당시 운전자가 술에 취한 상태에서 자동차를 운전하였다고 인정할 만한 상당한 이유가 있었으며, 음주운전 종료 후 별도의 음주 사실이 없었음이 증명된 경우, 경찰관이 음주 및 음주운전 종료로부터 약 5시간 후 집에서 자고 있는 피고인을 연행하여 음주측정을 요구한 데에 대하여 피고인이 불응하였다면, ｢도로교통법｣ 상의 음주측정불응죄가 성립한다.","특별한 이유 없이 호흡측정기에 의한 측정에 불응하는 운전자에게 경찰공무원이 혈액채취에 의한 측정방법이 있음을 고지하고 그 선택 여부를 물어야 할 의무는 없다."],"a":2}},{"y":2023,"e":"경찰 공채","qn":37,"i":"PO2023_2-37","t":"｢도로교통법｣ 에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢도로교통법｣ 에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["모든 차의 운전자는 예외 없이 터널 안에 차를 주차해서는 아니 된다.","긴급자동차에 대하여는 동법 제23조에 따른 끼어들기의 금지를 적용하지 아니한다.","“정차”란 운전자가 5분을 초과하지 아니하고 차를 정지시키는 것으로서 주차 외의 정지 상태를 말한다.","물로 입 안을 헹굴 기회를 달라는 피고인의 요구를 무시한 채 호흡측정기로 측정한 혈중알코올 농도 수치가 0.05%로 나타난 사안에서, 피고인이 당시 혈중알코올 농도 0.05% 이상의 술에 취한 상태에서 운전하였다고 단정할 수 없다."],"a":1}},{"y":2024,"e":"경찰 공채","qn":40,"i":"PO2024_1-40","t":"제2종 보통면허만을 취득한 자가 운전할 경우, 무면허운전이 되는 것은?","c":"A","mc":{"s":"제2종 보통면허만을 취득한 자가 운전할 경우, 무면허운전이 되는 것은?","d":"","o":["원동기장치자전거","화물자동차(적재중량 3톤)","승합자동차(승차정원 8명)","특수자동차(총중량 4톤)"],"a":4}},{"y":2024,"e":"경찰 공채","qn":38,"i":"PO2024_2-38","t":"다음 중 ｢도로교통법｣ 제32조(정차 및 주차의 금지)에 규정된 장소를 모두 고른 것은?","c":"A","mc":{"s":"다음 중 ｢도로교통법｣ 제32조(정차 및 주차의 금지)에 규정된 장소를 모두 고른 것은?","d":"(다만, 이 법이나 이 법에 따른 명령 또는 경찰공무원의 지시를 따르는 경우와 위험방지를 위하여 일시정지하는 경우는 고려하지 않는다) ㉠ 터널 안 및 다리 위 ㉡ 교차로의 가장자리나 도로의 모퉁이로부터 5미터 이내인 곳 ㉢ 시장등이 제12조 제1항에 따라 지정한 어린이 보호구역 ㉣ 교차로･ 횡단보도･ 건널목이나 보도와 차도가 구분된 도로의 보도(｢주차장법｣ 에 따라 차도와 보도에 걸쳐서 설치된 노상 주차장은 제외한다) ㉤ 도로공사를 하고 있는 경우에는 그 공사 구역의 양쪽 가장 자리로부터 5미터 이내인 곳","o":["㉠㉡㉢","㉠㉣㉤","㉡㉢㉣","㉢㉣㉤"],"a":3}},{"y":2025,"e":"경찰 공채","qn":37,"i":"PO2025_1-37","t":"｢도로교통법｣ 상 운전자의 의무에 관한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"｢도로교통법｣ 상 운전자의 의무에 관한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["누구든지 술에 취한 상태에서 자동차등(｢건설기계관리법｣ 제26조 제1항 단서에 따른 건설기계 외의 건설기계를 포함), 노면전차 또는 자전거를 운전하여서는 아니 된다.","경찰공무원은 교통의 안전과 위험방지를 위하여 필요하다고 인정하는 경우에는 운전자가 술에 취하였는지를 호흡조사로 측정할 수 있으며, 이 경우 운전자는 경찰공무원의 측정에 응하여야 한다.","운전이 금지되는 술에 취한 상태의 기준은 운전자의 혈중알코올 농도가 0.03퍼센트 이상인 경우로 한다.","개인형 이동장치의 운전자는 대통령령으로 정하는 승차정원을 초과하여 동승자를 태우고 개인형 이동장치를 운전하여서는 아니 된다."],"a":4}},{"y":2025,"e":"경찰 공채","qn":38,"i":"PO2025_2-38","t":"다음 중 ｢도로교통법｣ 및 동법 시행령상 자동차를 사용하는 사람 또는 기관 등의 신청에 의하여 시·도경찰청장이 지정 하는 긴급자동차로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"다음 중 ｢도로교통법｣ 및 동법 시행령상 자동차를 사용하는 사람 또는 기관 등의 신청에 의하여 시·도경찰청장이 지정 하는 긴급자동차로 옳은 것은 모두 몇 개인가?","d":"㉠ 경찰용 자동차 중 범죄수사, 교통단속, 그 밖의 긴급한 경찰업무 수행에 사용되는 자동차 ㉡ 민방위업무를 수행하는 기관에서 긴급예방을 위한 출동에 사용되는 자동차 ㉢ 도로관리를 위하여 사용되는 자동차 중 운행이 제한되는 자동차를 단속하기 위하여 사용되는 자동차 ㉣ 교도소의 자동차 중 수용자의 호송‧ 경비를 위하여 사용되는 자동차 ㉤ 국내외 요인에 대한 경호업무 수행에 공무로 사용되는 자동차","o":["2개","3개","4개","5개"],"a":1}},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_1-39-1","t":"‘음주운전 방지장치’란 술에 취한 상태에서 자동차등을 운전하려는 경우 시동이 걸리지 아니하도록 하는 것으로서 행정안전부령으로 정하는 것을 말하며, 음주운전 방지장치 부착 조건부 운전면허를 받은 사람은 음주운전 방지장치가 설치되지 아니하거나 설치기준에 적합하지 아니한 음주운전 방지장치가 설치된 자동차등을 운전 하여서는 아니 된다.","ox":"O","m":"①","c":"A","tp":"도로교통법 상 음주운전 방지장치 부착 조건부 운전면허"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_1-39-2","t":"「여객자동차 운수사업법」 에 따른 여객자동차 운수사업자의 사업용 자동차, 「화물자동차 운수사업법」 에 따른 화물자동차 운수사업자의 사업용 자동차 및 그 밖에 대통령령으로 정하는 자동차등에 음주운전 방지장치를 설치한 자는 시‧ 도경찰청장에게 등록하여야 한다.","ox":"O","m":"②","c":"A","tp":"도로교통법 상 음주운전 방지장치 부착 조건부 운전면허"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_1-39-3","t":"누구든지 음주운전 방지장치 부착 조건부 운전면허를 받은 사람을 대신하여 음주운전 방지장치가 설치된 자동차등을 운전할 수 있도록 해당 장치에 호흡을 불어넣거나 다른 부정한 방법으로 음주운전 방지장치가 설치된 자동차등에 시동을 거는 행위를 하여서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"도로교통법 상 음주운전 방지장치 부착 조건부 운전면허"},{"y":2026,"e":"경찰 공채","qn":39,"i":"PO2026_1-39-4","t":"「도로교통법」 제80조의2(음주운전 방지장치 부착 조건부 운전면허)는 개인형 이동장치를 포함한 자동차등 또는 노면전차를 운전한 경우에 적용되는 규정이다.","ox":"X","m":"④","c":"A","tp":"도로교통법 상 음주운전 방지장치 부착 조건부 운전면허"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_2-38-1","t":"자율주행시스템의 종류는 부분 자율주행시스템, 조건부 완전 자율주행시스템, 완전 자율주행시스템으로 세분할 수 있다.","ox":"O","m":"①","c":"A","tp":"도로교통법 및 동법 시행규칙상 자율주행자동차 및 운전자"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_2-38-2","t":"완전 자율주행시스템은 모든 영역에서 운전자의 개입 없이 자동차를 운행하는 자율주행시스템을 의미한다.","ox":"O","m":"②","c":"A","tp":"도로교통법 및 동법 시행규칙상 자율주행자동차 및 운전자"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_2-38-3","t":"완전 자율주행시스템에 해당하는 자율주행시스템을 갖춘 자동차의 운전자는 자율주행시스템의 직접 운전 요구에 주변 상황과 도로 정보 등을 스스로 인지하고 판단하여 자동차를 운행할 수 있게 하는 자동화 장비, 소프트웨어 및 이와 관련한 일체의 장치를 직접 조작하여 운전하여야 한다.","ox":"X","m":"③","c":"A","tp":"도로교통법 및 동법 시행규칙상 자율주행자동차 및 운전자"},{"y":2026,"e":"경찰 공채","qn":38,"i":"PO2026_2-38-4","t":"「자동차관리법」 제27조 제1항에 따른 임시운행허가를 받은 자율 주행자동차를 운전하려는 사람은 자율주행자동차의 안전운행 등에 관한 교육을 받아야 한다.","ox":"O","m":"④","c":"A","tp":"도로교통법 및 동법 시행규칙상 자율주행자동차 및 운전자"}],"16":[{"y":2022,"e":"경찰 공채","qn":26,"i":"PO2022_1-26","t":"범죄인 인도법 제7조에 따른 절대적 인도거절 사유에 해당하지 않는 것은?","c":"A","mc":{"s":"범죄인 인도법 제7조에 따른 절대적 인도거절 사유에 해당하지 않는 것은?","d":"","o":["대한민국 또는 청구국의 법률에 따라 인도범죄에 관한 공소시효 또는 형의 시효가 완성된 경우","인도범죄에 관하여 대한민국 법원에서 재판이 계속 중이거나 재판이 확정된 경우","인도범죄의 성격과 범죄인이 처한 환경 등에 비추어 범죄인을 인도하는 것이 비인도적이라고 인정되는 경우","범죄인이 인종, 종교, 국적, 성별, 정치적 신념 또는 특정 사회 단체에 속한 것 등을 이유로 처벌되거나 그 밖의 불리한 처분을 받을 염려가 있다고 인정되는 경우"],"a":3}},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_2-40-1","t":"경찰관은 대한민국의 영해에 있는 외국 선박 내에서 발생한 범죄로서 대한민국 육상이나 항내의 안전을 해할 때, 승무원 이외의 사람이나 대한민국의 국민에 관계가 있을 때 또는 중대한 범죄가 행하여졌을 때는 수사를 하여야 한다.","ox":"O","m":"①","c":"A","tp":"경찰수사규칙 과 범죄수사규칙 이 규정하고 있는 외국인"},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_2-40-2","t":"사법경찰관리는 외국인을 조사하는 경우에는 조사를 받는 외국인이 이해할 수 있는 언어로 통역해 주어야 한다.","ox":"O","m":"②","c":"A","tp":"경찰수사규칙 과 범죄수사규칙 이 규정하고 있는 외국인"},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_2-40-3","t":"사법경찰관은 주한 미합중국 군대의 구성원·외국인군무원 및 그 가족이나 초청계약자의 범죄 관련 사건을 인지하거나 고소·고발 등을 수리한 때에는 7일 이내에 한미행정협정사건 통보서를 미군 당국에게 통보해야 한다.","ox":"X","m":"③","c":"A","tp":"경찰수사규칙 과 범죄수사규칙 이 규정하고 있는 외국인"},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_2-40-4","t":"경찰관은 외국군함에 속하는 군인이나 군속이 그 군함을 떠나 대한민국의 영해 또는 영토 내에서 죄를 범한 경우에는 신속히 국가수사본부장에게 보고하여 그 지시를 받아야 한다. 다만, 현행범 그 밖의 급속을 요하는 때에는 체포 그 밖의 수사상 필요한 조치를 한 후 신속히 국가수사본부장에게 보고하여 그 지시를 받아야 한다.","ox":"O","m":"④","c":"A","tp":"경찰수사규칙 과 범죄수사규칙 이 규정하고 있는 외국인"},{"y":2024,"e":"경찰 공채","qn":38,"i":"PO2024_1-38","t":"｢범죄인 인도법｣ 에서 규정하는 절대적 인도거절 사유로 옳은 것만을 모두 고른 것은?","c":"A","mc":{"s":"｢범죄인 인도법｣ 에서 규정하는 절대적 인도거절 사유로 옳은 것만을 모두 고른 것은?","d":"㉠ 범죄인이 대한민국 국민인 경우 ㉡ 인도범죄의 전부 또는 일부가 대한민국 영역에서 범한 것인 경우 ㉢ 범죄인이 인종, 종교, 국적, 성별, 정치적 신념 또는 특정 사회단체에 속한 것 등을 이유로 처벌되거나 그 밖의 불리한 처분을 받을 염려가 있다고 인정되는 경우 ㉣ 인도범죄에 관하여 대한민국 법원에서 재판이 계속 중이거나 재판이 확정된 경우","o":["㉠㉡","㉢㉣","㉠㉡㉣","㉡㉢㉣"],"a":2}},{"y":2024,"e":"경찰 공채","qn":40,"i":"PO2024_2-40","t":"국제경찰공조에 관한 설명으로 가장 적절한 것은?","c":"A","mc":{"s":"국제경찰공조에 관한 설명으로 가장 적절한 것은?","d":"","o":["국제형사사법공조와 범죄인 인도는 동일한 법률에 근거하고 있다.","｢국제형사사법공조법｣ 에는 증거 수집, 압수･ 수색 또는 검증이 공조의 범위로 포함되어 있다.","국제형사경찰기구(인터폴)의 회원국은 자국 내 설치된 국가중앙 사무국을 통해 다른 나라의 국가중앙사무국과 국제범죄정보 및 자료를 교환하며, 임의적 협조라기보다는 강제적 협조의 성격을 가진다.","국제형사경찰기구는 국제형사공조기구로 분류되며, 예외적인 사안에서는 국제형사경찰기구 소속 수사관이 범인을 체포하거나 구속할 수도 있다."],"a":2}},{"y":2025,"e":"경찰 공채","qn":40,"i":"PO2025_2-40-1","t":"인도조약이 체결되어 있지 아니한 경우에도 범죄인의 인도를 청구하는 국가가 같은 종류 또는 유사한 인도범죄에 대한 대한민국의 범죄인 인도청구에 응한다는 보증을 하는 경우에는 이 법을 적용한다.","ox":"O","m":"①","c":"A","tp":"범죄인 인도법"},{"y":2025,"e":"경찰 공채","qn":40,"i":"PO2025_2-40-2","t":"대한민국과 청구국의 법률에 따라 인도범죄가 사형, 무기징역, 무기금고, 장기 3년 이상의 징역 또는 금고에 해당하는 경우에만 범죄인을 인도할 수 있다.","ox":"X","m":"②","c":"A","tp":"범죄인 인도법"},{"y":2025,"e":"경찰 공채","qn":40,"i":"PO2025_2-40-3","t":"인도범죄에 관하여 대한민국 법원에서 재판이 계속 중이거나 재판이 확정된 경우는 범죄인을 인도하여서는 아니 된다.","ox":"O","m":"③","c":"A","tp":"범죄인 인도법"},{"y":2025,"e":"경찰 공채","qn":40,"i":"PO2025_2-40-4","t":"범죄인이 인도범죄에 관하여 제3국(청구국이 아닌 외국을 말한다.)에서 재판을 받고 처벌되었거나 처벌받지 아니하기로 확정된 경우 범죄인을 인도하지 아니할 수 있다.","ox":"O","m":"④","c":"A","tp":"범죄인 인도법"}],"7":[{"y":2022,"e":"경찰 공채","qn":29,"i":"PO2022_1-29-1","t":"정보의 공개를 청구하는 자는 해당 정보를 보유하거나 관리하고 있는 공공기관에 정보공개 청구서를 제출하여 정보의 공개를 청구할 수 있으나, 말로써 정보의 공개를 청구할 수 없다.","ox":"X","m":"①","c":"A","tp":"공공기관의 정보공개"},{"y":2022,"e":"경찰 공채","qn":29,"i":"PO2022_1-29-2","t":"공공기관은 부득이한 사유로 공공기관의 정보공개에 관한 법률 제11조 제1항에 따른 기간 이내에 공개 여부를 결정할 수 없을 때에는 그 기간이 끝난 날부터 기산하여 10일의 범위에서 공개 여부 결정기간을 연장할 수 있다. 이 경우 공공기관은 연장된 사실과 연장 사유를 청구인에게 지체 없이 구두로 통지하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"경찰 공채","qn":29,"i":"PO2022_1-29-3","t":"공공기관은 전자적 형태로 보유 관리하는 정보에 대하여 청구 인이 전자적 형태로 공개하여 줄 것을 요청하는 경우에는 그 정보의 성질상 현저히 곤란한 경우를 제외하고는 청구인의 요청에 따라야 한다.","ox":"O","m":"③","c":"A","tp":"공공기관의 정보공개"},{"y":2022,"e":"경찰 공채","qn":29,"i":"PO2022_1-29-4","t":"정보의 공개 및 우송 등에 드는 비용은 실비의 범위에서 공공 기관이 부담한다.","ox":"X","m":"④","c":"A","tp":"공공기관의 정보공개"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_1-30-1","t":"행정지도는 그 목적 달성에 필요한 최소한도에 그쳐야 하며, 행정지도의 상대방의 의사에 반하여 부당하게 강요하여서는 아니 된다.","ox":"O","m":"①","c":"A","tp":"행정절차법 상 행정지도"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_1-30-2","t":"행정기관은 행정지도의 상대방이 행정지도에 따르지 아니하였 다는 것을 이유로 불이익한 조치를 하여서는 아니 된다.","ox":"O","m":"②","c":"A","tp":"행정절차법 상 행정지도"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_1-30-3","t":"행정지도가 말로 이루어지는 경우에 상대방이 행정지도의 취지 및 내용과 신분의 사항을 적은 서면의 교부를 요구하면 그 행정지도를 하는 자는 직무 수행에 특별한 지장이 없으면 이를 교부하여야 한다.","ox":"O","m":"③","c":"A","tp":"행정절차법 상 행정지도"},{"y":2022,"e":"경찰 공채","qn":30,"i":"PO2022_1-30-4","t":"행정지도의 상대방은 해당 행정지도의 방식 내용 등에 관하여 행정기관에 의견제출을 할 수 없다.","ox":"X","m":"④","c":"A","tp":"행정절차법 상 행정지도"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_1-31-1","t":"행정청의 과태료 처분이나 법원의 과태료 재판이 확정된 후 법률이 변경되어 그 행위가 질서위반행위에 해당하지 아니하게 된 때에는 변경된 법률에 특별한 규정이 없는 한 과태료의 징수 또는 집행을 면제한다.","ox":"O","m":"①","c":"A","tp":"질서위반행위규제법"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_1-31-2","t":"고의 또는 과실이 없는 질서위반행위는 과태료를 부과하지 아니한다.","ox":"O","m":"②","c":"A","tp":"질서위반행위규제법"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_1-31-3","t":"자신의 행위가 위법하지 아니한 것으로 오인하고 행한 질서 위반행위는 그 오인에 정당한 이유가 있는 때에도 과태료를 부과한다.","ox":"X","m":"③","c":"A","tp":"질서위반행위규제법"},{"y":2022,"e":"경찰 공채","qn":31,"i":"PO2022_1-31-4","t":"과태료는 행정청의 과태료 부과처분이나 법원의 과태료 재판이 확정된 후 5년간 징수하지 아니하거나 집행하지 아니하면 시효로 인하여 소멸한다.","ox":"O","m":"④","c":"A","tp":"질서위반행위규제법"},{"y":2022,"e":"경찰 공채","qn":39,"i":"PO2022_1-39","t":"행정소송법 상 항고소송에 해당하지 않는 것은?","c":"A","mc":{"s":"행정소송법 상 항고소송에 해당하지 않는 것은?","d":"","o":["국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때에 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 민중소송","행정청의 처분등의 효력 유무 또는 존재여부를 확인하는 무효 등 확인소송","행정청의 부작위가 위법하다는 것을 확인하는 부작위위법확인소송","행정청의 위법한 처분등을 취소 또는 변경하는 취소소송"],"a":1}},{"y":2022,"e":"경찰 공채","qn":17,"i":"PO2022_2-17","t":"행정청이 행하는 구체적 사실에 관한 법 집행으로서 공권력의 행사 또는 그 거부와 그 밖에 이에 준하는 행정작용에 해당하는 것은 모두 몇 개인가?","c":"A","mc":{"s":"행정청이 행하는 구체적 사실에 관한 법 집행으로서 공권력의 행사 또는 그 거부와 그 밖에 이에 준하는 행정작용에 해당하는 것은 모두 몇 개인가?","d":"(다툼이 있는 경우 판례에 의함) ㉠ 도로점용허가 ㉡ 주민등록번호 변경신청 거부 ㉢ 교통경찰관의 수신호 ㉣ 교통신호등에 의한 신호 ㉤ 경찰청장의 횡단보도 설치 기본계획 수립","o":["1개","2개","3개","4개"],"a":4}},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_2-24-1","t":"사정재결은 인용재결의 일종이다.","ox":"X","m":"①","c":"A","tp":"행정심판법 상 사정재결"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_2-24-2","t":"무효등확인심판에서는 사정재결을 할 수 없다.","ox":"O","m":"②","c":"A","tp":"행정심판법 상 사정재결"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_2-24-3","t":"사정재결을 하는 경우 반드시 재결주문에 그 처분 또는 부작위가 위법하다는 것을 명시해야 한다.","ox":"O","m":"③","c":"A","tp":"행정심판법 상 사정재결"},{"y":2022,"e":"경찰 공채","qn":24,"i":"PO2022_2-24-4","t":"사정재결 이후에도 행정심판의 대상인 처분등의 효력은 유지된다.","ox":"O","m":"④","c":"A","tp":"행정심판법 상 사정재결"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_2-25-1","t":"일반적으로 공무원이 직무를 집행함에 있어서 법령에 대한 해석이 그 문언 자체만으로는 명백하지 아니하여 여러 견해가 있을 수 있는 데다가 이에 대한 선례나 학설, 판례 등도 귀일된 바 없어 이의(異義)가 없을 수 없는 경우, 관계 국가공무원이 그 나름대로 신중을 다하여 합리적인 근거를 찾아 그 중 어느 한 견해를 따라 내린 해석이 후에 대법원이 내린 입장과 같지 않아 결과적으로 잘못된 해석에 돌아가고, 이에 따른 처리가 역시 결과적으로 위법하게 되어 그 법령의 부당집행이라는 결과를 가져오게 되었다고 하더라도 국가배상법상 공무원의 과실을 인정 할 수는 없다.","ox":"O","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_2-25-2","t":"국가공무원이 고의 또는 과실로 직무상 의무를 위반하였을 경우라고 하더라도 국가는 그러한 직무상의 의무 위반과 피해자가 입은 손해 사이에 상당인과관계가 인정되는 범위 내에서만 배상책임을 지는 것이고, 이 경우 상당인과관계가 인정되기 위하여는 공무원에게 부과된 직무상 의무의 내용이 단순히 공공 일반의 이익을 위한 것이거나 행정기관 내부의 질서를 규율하기 위한 것이 아니고 전적으로 또는 부수적으로 사회구성원 개인의 안전과 이익을 보호하기 위하여 설정된 것이어야 한다.","ox":"O","m":"②","c":"A","tp":"국가배상"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_2-25-3","t":"외국인이 피해자인 경우 국가배상청구권은 해당 국가와 상호 보증이 있을 때에만 인정되므로, 그 상호 보증은 외국의 법령, 판례 및 관례 등에 의한 발생요건을 비교하여 인정되는 것이 아니라 반드시 당사국과의 조약이 체결되어 있어야 한다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":25,"i":"PO2022_2-25-4","t":"국민의 생명, 신체 및 재산의 보호, 범죄의 예방 진압 및 수사, 기타 공공의 안녕과 질서유지 등의 직무를 수행하는 경찰은 경찰관 직무집행법, 형사소송법 등 관련 법령에서 부여한 여러 권한을 제반 상황에 대응하여 적절하게 행사하여 필요한 조치를 취할 수 있고, 그 권한은 일반적으로 경찰관의 전문적 판단에 기한 합리적인 재량에 위임되어 있지만, 경찰관에게 권한을 부여한 취지와 목적에 비추어 볼 때 구체적인 사정에 따라 경찰관이 그 권한을 행사하여 필요한 조치를 취하지 아니하는 것이 현저하게 불합리하다고 인정되는 경우에는 그러한 권한의 불행사는 직무상의 의무를 위반한 것이 되어 위법하게 된다.","ox":"O","m":"④","c":"A","tp":"국가배상"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_1-24-1","t":"청구인은 이의신청 절차를 거치지 아니하고 행정심판을 청구 할 수 없다.","ox":"X","m":"①","c":"A","tp":"공공기관의 정보공개"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_1-24-2","t":"“정보”란 공공기관이 직무상 작성 또는 취득하여 관리하고 있는 문서(전자문서를 포함한다) 및 전자매체를 비롯한 모든 형태의 매체 등에 기록된 사항을 말한다.","ox":"O","m":"②","c":"A","tp":"공공기관의 정보공개"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_1-24-3","t":"공공기관은 부득이한 사유로 법제11조 제1항에 따른 기간 이내에 공개 여부를 결정할 수 없을 때에는 그 기간이 끝나는 날의 다음 날부터 기산(起算)하여 10일의 범위에서 공개 여부 결정 기간을 연장할 수 있다. 이 경우 공공기관은 연장된 사실과 연장 사유를 청구인에게 지체 없이 문서로 통지하여야 한다.","ox":"O","m":"③","c":"A","tp":"공공기관의 정보공개"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_1-24-4","t":"공공기관은 청구인이 사본 또는 복제물의 교부를 원하는 경우에는 이를 교부하여야 한다.","ox":"O","m":"④","c":"A","tp":"공공기관의 정보공개"},{"y":2023,"e":"경찰 공채","qn":25,"i":"PO2023_1-25","t":"｢행정절차법｣ 상 행정청이 처분을 할 때 청문을 하여야 하는 경우가 아닌 것은?","c":"A","mc":{"s":"｢행정절차법｣ 상 행정청이 처분을 할 때 청문을 하여야 하는 경우가 아닌 것은?","d":"","o":["다른 법령등에서 청문을 하도록 규정하고 있는 경우","해당 처분의 영향이 광범위하여 널리 의견을 수렴할 필요가 있다고 행정청이 인정하는 경우","인허가 등의 취소의 처분을 하는 경우","법인이나 조합 등의 설립허가의 취소의 처분을 하는 경우"],"a":2}},{"y":2023,"e":"경찰 공채","qn":26,"i":"PO2023_1-26","t":"｢행정심판법｣ 상 재결에 관한 설명으로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢행정심판법｣ 상 재결에 관한 설명으로 가장 적절하지 않은 것은?","d":"","o":["재결은 서면으로 한다.","위원회는 심판청구가 이유가 없다고 인정하면 그 심판청구를 기각(棄却)한다.","위원회는 지체 없이 당사자에게 재결서의 등본을 송달하여야 하며, 재결서가 청구인에게 발송되었을 때에 그 효력이 생긴다.","재결의 기속력은 재결의 주문 및 그 전제가 된 요건사실의 인정과 판단, 즉 처분 등의 구체적 위법사유에 관한 판단에만 미친다고 할 것이고, 종전 처분이 재결에 의하여 취소되었다 하더라도 종전 처분시와는 다른 사유를 들어서 처분을 하는 것은 기속력에 저촉되지 않는다."],"a":3}},{"y":2023,"e":"경찰 공채","qn":26,"i":"PO2023_2-26-1","t":"대통령의 처분 또는 부작위에 대하여는 다른 법률에서 행정심판을 청구할 수 있도록 정한 경우 외에는 행정심판을 청구할 수 없다.","ox":"O","m":"①","c":"A","tp":"행정심판법"},{"y":2023,"e":"경찰 공채","qn":26,"i":"PO2023_2-26-2","t":"취소심판은 당사자의 신청에 대한 행정청의 위법 또는 부당한 거부처분이나 부작위에 대하여 일정한 처분을 하도록 하는 행정심판이다.","ox":"X","m":"②","c":"A","tp":"행정심판법"},{"y":2023,"e":"경찰 공채","qn":26,"i":"PO2023_2-26-3","t":"처분 또는 부작위에 대한 행정심판은 청구서를 제출하거나 말로써 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"행정심판법"},{"y":2023,"e":"경찰 공채","qn":26,"i":"PO2023_2-26-4","t":"행정심판위원회는 심판청구가 이유가 있다고 인정하는 경우에도 이를 인용(認容)하는 것이 공공복리에 크게 위배된다고 인정하면 그 심판청구를 기각하는 재결을 하여야 한다.","ox":"X","m":"④","c":"A","tp":"행정심판법"},{"y":2023,"e":"경찰 공채","qn":27,"i":"PO2023_2-27","t":"다음 빈칸에 들어갈 말로 가장 적절한 것은?","c":"A","mc":{"s":"다음 빈칸에 들어갈 말로 가장 적절한 것은?","d":"(다툼이 있는 경우 판례에 의함) 명예퇴직한 법관이 미지급 명예퇴직수당액에 대하여 가지는 권리는 명예퇴직수당 지급대상자 결정 절차를 거쳐 명예퇴직 수당규칙에 의하여 확정된 공법상 법률관계에 관한 권리로서, 그 지급을 구하는 소송은 ｢행정소송법｣ 의 ()에 해당하며, 그 법률관계의 당사자인 국가를 상대로 제기하여야 한다.","o":["취소소송","부작위위법확인소송","기관소송","당사자소송"],"a":4}},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_1-23-1","t":"직무를 수행한 공무원의 성명·직위 등 「개인정보 보호법」 제2조 제1호에 따른 개인정보로서 공개될 경우 사생활의 비밀 또는 자유를 침해할 우려가 있다고 인정되는 정보는 공개하지 않을 수 있다.","ox":"X","m":"①","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_1-23-2","t":"피의자신문조서 등 조서에 기재된 피의자 등의 인적사항 이외의 진술내용 역시 개인의 사생활의 비밀 또는 자유를 침해할 우려가 인정되는 경우에는 비공개대상정보에 해당한다.","ox":"O","m":"②","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_1-23-3","t":"수사기록 중 의견서, 보고문서, 메모, 법률검토 등은 그 실질적인 내용을 구체적으로 살펴 수사의 방법 및 절차 등이 공개됨으로써 수사기관의 직무수행을 현저히 곤란하게 한다고 인정할 만한 상당한 이유가 있어야만 비공개대상정보에 해당한다.","ox":"O","m":"③","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":23,"i":"PO2024_1-23-4","t":"의사결정 과정에 있는 사항으로서 공개될 경우 업무의 공정한 수행에 현저한 지장을 초래한다고 인정할 만한 상당한 이유가 있는 정보는 공개하지 않을 수 있다.","ox":"O","m":"④","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":25,"i":"PO2024_1-25-1","t":"경찰관의 부작위를 이유로 한 국가배상책임을 인정하기 위한 요건으로서의 ‘법령 위반’이란 형식적 의미의 법령에 명시적으로 공무원의 작위의무가 규정되어 있는데도 이를 위반하는 경우를 의미하며, 인권존중·권력남용금지·신의성실과 같이 공무원으로서 마땅히 지켜야 할 준칙이나 규범을 지키지 않고 위반한 경우는 포함하지 않는다.","ox":"X","m":"①","c":"A"},{"y":2024,"e":"경찰 공채","qn":25,"i":"PO2024_1-25-2","t":"경찰관의 직무집행이 법령이 정한 요건과 절차에 따라 이루어진 것이라면 특별한 사정이 없는 한 이는 법령에 적합한 것이고 그 과정에서 개인의 권리가 침해되었다고 하여 그 법령적합성이 곧바로 부정되는 것은 아니다.","ox":"O","m":"②","c":"A","tp":"국가배상"},{"y":2024,"e":"경찰 공채","qn":25,"i":"PO2024_1-25-3","t":"공무원에게 부과된 직무상 의무의 내용이 전적으로 또는 부수적으로 사회구성원 개인의 구체적 안전과 이익을 보호하기 위하여 설정된 것이라면, 공무원이 그와 같은 직무상 의무를 위반함으로써 개인이 입게 된 손해는 상당인과관계가 인정되는 범위 안에서 국가가 그에 대한 배상책임을 부담하여야 한다.","ox":"O","m":"③","c":"A","tp":"국가배상"},{"y":2024,"e":"경찰 공채","qn":25,"i":"PO2024_1-25-4","t":"시위진압이 불필요하거나 또는 불법시위의 태양 및 시위 장소의 상황 등에서 예측되는 피해 발생의 구체적 위험성의 내용에 비추어 시위진압의 계속 수행 내지 그 방법 등이 현저히 합리성을 결하였다면 경찰관의 직무집행이 법령에 위반한 것이라고 할 수 있다.","ox":"O","m":"④","c":"A","tp":"국가배상"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_1-26-1","t":"행정청의 처분에 이의가 있는 당사자는 처분을 받은 날부터 30일 이내에 해당 행정청에 이의신청을 할 수 있다.","ox":"O","m":"①","c":"A","tp":"행정기본법 상 이의신청"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_1-26-2","t":"행정청은 이의신청을 받으면 부득이한 사유가 있는 경우를 제외하고는 그 이의신청을 받은 날부터 14일 이내에 그 이의 신청에 대한 결과를 신청인에게 통지하여야 한다.","ox":"O","m":"②","c":"A","tp":"행정기본법 상 이의신청"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_1-26-3","t":"이의신청을 한 경우에도 그 이의신청과 관계없이 「행정심판법」 에 따른 행정심판 또는 「행정소송법」 에 따른 행정소송을 제기할 수 있다.","ox":"O","m":"③","c":"A","tp":"행정기본법 상 이의신청"},{"y":2024,"e":"경찰 공채","qn":26,"i":"PO2024_1-26-4","t":"이의신청에 대한 결과를 통지받은 후 행정심판 또는 행정소송을 제기하려는 자는 그 결과를 통지받은 날부터 60일 이내에 행정심판 또는 행정소송을 제기하여야 한다.","ox":"X","m":"④","c":"A","tp":"행정기본법 상 이의신청"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_1-27-1","t":"심판청구는 서면으로 하여야 하며, 심판청구서를 작성하여 피청구인 또는 행정심판위원회에 제출하여야 한다.","ox":"O","m":"①","c":"A","tp":"행정심판법 상 행정심판"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_1-27-2","t":"시·도경찰청장의 처분 또는 부작위에 대한 행정심판의 청구에 대해서는 경찰청에 두는 행정심판위원회에서 심리·재결한다.","ox":"X","m":"②","c":"A","tp":"행정심판법 상 행정심판"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_1-27-3","t":"행정심판위원회는 처분, 처분의 집행 또는 절차의 속행 때문에 중대한 손해가 생기는 것을 예방할 필요성이 긴급하다고 인정할 때에는 직권으로 또는 당사자의 신청에 의하여 처분의 효력, 처분의 집행 또는 절차의 속행의 전부 또는 일부의 정지를 결정 할 수 있다.","ox":"O","m":"③","c":"A","tp":"행정심판법 상 행정심판"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_1-27-4","t":"행정심판위원회는 심판청구가 이유가 있다고 인정하는 경우에도 이를 인용하는 것이 공공복리에 크게 위배된다고 인정하면 심판청구를 기각하는 재결을 할 수 있다.","ox":"O","m":"④","c":"A","tp":"행정심판법 상 행정심판"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_2-20-1","t":"의견제출기한에 따른 기한은 의견제출에 필요한 기간을 10일 이상으로 고려하여 정하여야 한다.","ox":"O","m":"①","c":"A","tp":"행정절차법 상 처분"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_2-20-2","t":"행정청이 정당한 처리기간 내에 처리하지 아니하였을 때에도 신청인은 해당 행정청 또는 그 감독 행정청에 신속한 처리를 요청할 수 없다.","ox":"X","m":"②","c":"A","tp":"행정절차법 상 처분"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_2-20-3","t":"행정청에 처분을 구하는 신청은 구두 또는 문서로 하여야 한다. 다만, 다른 법령등에 특별한 규정이 있는 경우와 행정청이 미리 다른 방법을 정한 경우에는 그러하지 아니하다.","ox":"X","m":"③","c":"A","tp":"행정절차법 상 처분"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_2-20-4","t":"행정청이 인허가 등의 취소처분을 하는 경우 공청회를 개최한다.","ox":"X","m":"④","c":"A","tp":"행정절차법 상 처분"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_2-21-1","t":"정보의 공개를 청구하는 자는 해당 정보를 보유하거나 관리하고 있는 공공기관에 정보공개 청구서를 제출하거나 말로써 정보의 공개를 청구할 수 있다.","ox":"O","m":"①","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_2-21-2","t":"공공기관은 전자적 형태로 보유·관리하는 정보에 대하여 청구인이 전자적 형태로 공개하여 줄 것을 요청하는 경우에는 그 정보의 성질상 현저히 곤란한 경우를 제외하고는 청구인의 요청에 따라야 한다.","ox":"O","m":"②","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_2-21-3","t":"정보의 공개 및 우송 등에 드는 비용은 실비의 범위에서 공공 기관이 부담한다.","ox":"X","m":"③","c":"A","tp":"공공기관의 정보공개"},{"y":2024,"e":"경찰 공채","qn":21,"i":"PO2024_2-21-4","t":"공공기관은 「공공기관의 정보공개에 관한 법률」 제11조에 따라 정보의 공개 결정을 한 경우에는, 청구인이 사본 또는 복제물의 교부를 원하는 경우에는 이를 교부하여야 한다.","ox":"O","m":"④","c":"A"},{"y":2024,"e":"경찰 공채","qn":28,"i":"PO2024_2-28-1","t":"군인·군무원·경찰공무원 또는 예비군대원이 전투·훈련 등 직무 집행과 관련하여 전사·순직하거나 공상을 입은 경우에 본인이나 그 유족이 다른 법령에 따라 재해보상금·유족연금·상이연금 등의 보상을 지급받을 수 있을 때에도 「국가배상법」 및 「행정기본법」 에 따른 손해배상을 청구할 수 있다.","ox":"X","m":"①","c":"A","tp":"국가배상법 상 손해배상"},{"y":2024,"e":"경찰 공채","qn":28,"i":"PO2024_2-28-2","t":"생명·신체에 대한 침해와 물건의 멸실·훼손으로 인한 손해 외의 손해는 불법행위와 상당한 인과관계가 있는 범위에서 배상한다.","ox":"O","m":"②","c":"A","tp":"국가배상법 상 손해배상"},{"y":2024,"e":"경찰 공채","qn":28,"i":"PO2024_2-28-3","t":"국가나 지방자치단체에 대한 배상신청사건을 심의하기 위하여 행정안전부에 본부심의회를 둔다. 다만, 군인이나 군무원이 타인에게 입힌 손해에 대한 배상신청사건을 심의하기 위하여 국방부에 특별심의회를 둔다.","ox":"X","m":"③","c":"A","tp":"국가배상법 상 손해배상"},{"y":2024,"e":"경찰 공채","qn":28,"i":"PO2024_2-28-4","t":"결정서의 송달에 관하여는 「행정소송법」 의 송달에 관한 규정을 준용한다.","ox":"X","m":"④","c":"A","tp":"국가배상법 상 손해배상"},{"y":2025,"e":"경찰 공채","qn":24,"i":"PO2025_1-24-1","t":"이 법은 행정절차에 관한 공통적인 사항을 규정하여 국민의 행정 참여를 도모함으로써 행정의 공정성‧ 투명성 및 신뢰성을 확보하고 국민의 권익을 보호함을 목적으로 한다.","ox":"O","m":"①","c":"A","tp":"행정절차법"},{"y":2025,"e":"경찰 공채","qn":24,"i":"PO2025_1-24-2","t":"행정청의 관할이 분명하지 아니한 경우에는 해당 행정청을 공통으로 감독하는 상급 행정청이 그 관할을 결정하며, 공통으로 감독하는 상급 행정청이 없는 경우에는 각 상급 행정청이 협의하여 그 관할을 결정한다.","ox":"O","m":"②","c":"A","tp":"행정절차법"},{"y":2025,"e":"경찰 공채","qn":24,"i":"PO2025_1-24-3","t":"송달은 우편 또는 정보통신망을 이용한 방법으로만 하되, 송달받을 자의 주소·거소·영업소·사무소 또는 전자우편주소로 한다.","ox":"X","m":"③","c":"A","tp":"행정절차법"},{"y":2025,"e":"경찰 공채","qn":24,"i":"PO2025_1-24-4","t":"행정청이 처분을 할 때에는 다른 법령등에 특별한 규정이 있는 경우를 제외하고는 문서로 하여야 하며, 당사자등의 동의가 있거나 당사자가 전자문서로 처분을 신청한 경우에는 전자문서로 할 수 있다.","ox":"O","m":"④","c":"A","tp":"행정절차법"},{"y":2025,"e":"경찰 공채","qn":25,"i":"PO2025_1-25-1","t":"행정심판위원회는 사정재결을 할 때에는 청구인에 대하여 상당한 구제방법을 취하거나 상당한 구제방법을 취할 것을 청구인과 피청구인에게 명한다.","ox":"X","m":"①","c":"A","tp":"행정심판법 상 재결"},{"y":2025,"e":"경찰 공채","qn":25,"i":"PO2025_1-25-2","t":"행정심판위원회는 무효등확인심판의 청구가 이유가 있다고 인정하면 처분의 효력 유무 또는 처분의 존재 여부를 확인한다.","ox":"O","m":"②","c":"A","tp":"행정심판법 상 재결"},{"y":2025,"e":"경찰 공채","qn":25,"i":"PO2025_1-25-3","t":"행정심판위원회는 의무이행심판의 청구가 이유가 있다고 인정 하면 지체 없이 신청에 따른 처분을 하거나 처분을 할 것을 피청구인에게 명한다.","ox":"O","m":"③","c":"A","tp":"행정심판법 상 재결"},{"y":2025,"e":"경찰 공채","qn":25,"i":"PO2025_1-25-4","t":"행정심판위원회는 심판청구가 이유가 있다고 인정하는 경우에도 이를 인용하는 것이 공공복리에 크게 위배된다고 인정하면 그 심판청구를 기각하는 재결을 할 수 있다.","ox":"O","m":"④","c":"A","tp":"행정심판법 상 재결"},{"y":2025,"e":"경찰 공채","qn":26,"i":"PO2025_1-26","t":"｢행정소송법｣ 상 행정소송의 종류에 관한 설명이다. 아래 ㉠～㉣에 들어갈 내용으로 가장 적절한 것은?","c":"A","mc":{"s":"｢행정소송법｣ 상 행정소송의 종류에 관한 설명이다. 아래 ㉠～㉣에 들어갈 내용으로 가장 적절한 것은?","d":"(㉠)소송: 행정청의 처분등이나 부작위에 대하여 제기하는 소송 (㉡)소송: 국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때에 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송 (㉢)소송: 행정청의 처분등을 원인으로 하는 법률관계에 관한 소송 그 밖에 공법상의 법률관계에 관한 소송으로서 그 법률 관계의 한쪽 (㉣)를 피고로 하는 소송 ㉠ ㉡ ㉢ ㉣","o":["항고 민중 당사자 대표자","부작위 항고 기관 대표자","항고 민중 당사자 당사자","항고 기관 민중 당사자"],"a":3}},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_2-23-1","t":"행정청은 신청에 구비서류의 미비 등 흠이 있는 경우에는 보완에 필요한 상당한 기간을 정하여 지체 없이 신청인에게 보완을 요구하여야 한다.","ox":"O","m":"①","c":"A","tp":"행정절차법 상 처분"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_2-23-2","t":"행정청은 당사자에게 의무를 부과하거나 권익을 제한하는 처분을 하는 경우에는 미리 당사자등에게 통지하여야 한다. 다만, 공공의 안전 또는 복리를 위하여 긴급히 처분을 할 필요가 있는 경우에는 통지하지 아니할 수 있다.","ox":"O","m":"②","c":"A","tp":"행정절차법 상 처분"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_2-23-3","t":"행정청은 처분 후 2년 이내에 당사자등이 요청하는 경우에는 청문‧ 공청회 또는 의견제출을 위하여 제출받은 서류나 그 밖의 물건을 반환할 수 있다.","ox":"X","m":"③","c":"A","tp":"행정절차법 상 처분"},{"y":2025,"e":"경찰 공채","qn":23,"i":"PO2025_2-23-4","t":"행정청은 청문‧ 공청회 또는 의견제출을 거쳤을 때에는 신속히 처분하여 해당 처분이 지연되지 아니하도록 하여야 한다.","ox":"O","m":"④","c":"A","tp":"행정절차법 상 처분"},{"y":2025,"e":"경찰 공채","qn":26,"i":"PO2025_2-26-1","t":"지방자치단체가 ‘교통할아버지 봉사활동 계획’을 수립한 후 관할 동장으로 하여금 ‘교통할아버지’를 선정하게 하여 어린이 보호, 교통안내, 거리질서 확립 등의 공무를 위탁하여 집행하게 하던 중 ‘교통할아버지’로 선정된 노인이 위탁받은 업무 범위를 넘어 교차로 중앙에서 교통정리를 하다가 교통사고를 발생시킨 경우, 지방자치단체가 「국가배상법」 제2조 소정의 배상책임을 부담한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":26,"i":"PO2025_2-26-2","t":"지방자치단체장이 설치하여 관할 시·도경찰청장에게 관리권한이 위임된 교통신호기의 고장으로 인하여 교통사고가 발생한 경우, 지방자치단체뿐만 아니라 경찰관들의 봉급을 부담하는 국가도 손해배상책임이 인정된다.","ox":"O","m":"②","c":"A","tp":"국가배상","t0":"지방자치단체장이 설치하여 관할 지방경찰청장에게 관리권한이 위임된 교통신호기의 고장으로 인하여 교통사고가 발생한 경우, 지방자치단체뿐만 아니라 경찰관들의 봉급을 부담하는 국가도 손해배상책임이 인정된다.","ox0":"O","rv":"관할 지방경찰청장에게 관리권한이 위임된→관할 시·도경찰청장에게 관리권한이 위임된"},{"y":2025,"e":"경찰 공채","qn":26,"i":"PO2025_2-26-3","t":"음주운전으로 적발된 주취운전자가 도로 밖으로 차량을 이동 하겠다며 단속경찰관으로부터 보관중이던 차량열쇠를 반환받아 몰래 차량을 운전하여 가던 중 사고를 일으킨 경우, 국가배상 책임을 인정한다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"경찰 공채","qn":26,"i":"PO2025_2-26-4","t":"군인‧ 군무원‧ 경찰공무원 또는 예비군대원이 전투‧ 훈련 등 직무 집행과 관련하여 전사‧ 순직하거나 공상을 입은 경우, 유족이 다른 법령에 따라 재해보상금‧ 유족연금‧ 상이연금 등의 보상을 지급받을 수 있을 때에는 「국가배상법」 및 「민법」 에 따른 손해배상 및 위자료를 청구할 수 없다.","ox":"X","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_2-27-1","t":"행정청의 처분 또는 부작위에 대하여는 다른 법률에 특별한 규정이 있는 경우 외에는 이 법에 따라 행정심판을 청구할 수 있다. 다만, 대통령의 처분 또는 부작위에 대하여는 다른 법률에 특별한 규정이 있는 경우 외에는 행정심판을 청구할 수 없다.","ox":"O","m":"①","c":"A","tp":"행정심판법"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_2-27-2","t":"행정심판위원회는 무효등확인심판의 청구가 이유가 있다고 인정 하면 처분의 효력 유무 또는 처분의 존재 여부를 확인한다.","ox":"O","m":"②","c":"A","tp":"행정심판법"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_2-27-3","t":"심판청구는 처분의 효력이나 그 집행 또는 절차의 속행에 영향을 주지 아니한다.","ox":"O","m":"③","c":"A","tp":"행정심판법"},{"y":2025,"e":"경찰 공채","qn":27,"i":"PO2025_2-27-4","t":"행정심판의 재결은 행정심판위원회 또는 피청구인의 행정청이 심판청구서를 받은 날부터 60일 이내에 하여야 한다. 다만, 부득이한 사정이 있는 경우에는 위원장이 직권으로 60일을 연장할 수 있다.","ox":"X","m":"④","c":"A","tp":"행정심판법"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_1-23-1","t":"행정청에 처분을 구하는 신청은 문서로 하여야 한다. 다만, 다른 법령등에 특별한 규정이 있는 경우와 행정청이 미리 다른 방법을 정하여 공시한 경우에는 그러하지 아니하다.","ox":"O","m":"①","c":"A","tp":"행정절차법 제17조(처분의 신청)"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_1-23-2","t":"행정청은 신청에 구비서류의 미비 등 흠이 있는 경우에 보완에 필요한 상당한 기간을 정하여 7일 이내에 신청인에게 보완을 요구하여야 한다.","ox":"X","m":"②","c":"A","tp":"행정절차법 제17조(처분의 신청)"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_1-23-3","t":"행정청은 신청에 필요한 구비서류, 접수기관, 처리기간, 그 밖에 필요한 사항을 게시(인터넷 등을 통한 게시를 포함한다)하거나 이에 대한 편람을 갖추어 두고 누구나 열람할 수 있도록 하여야 한다.","ox":"O","m":"③","c":"A","tp":"행정절차법 제17조(처분의 신청)"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_1-23-4","t":"행정청은 신청인의 편의를 위하여 다른 행정청에 신청을 접수하게 할 수 있다. 이 경우 행정청은 다른 행정청에 접수할 수 있는 신청의 종류를 미리 정하여 공시하여야 한다.","ox":"O","m":"④","c":"A","tp":"행정절차법 제17조(처분의 신청)"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_1-24-1","t":"모든 국민은 정보의 공개를 청구할 권리를 가지며, 외국인의 정보공개 청구에 관하여는 대통령령으로 정한다.","ox":"O","m":"①","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_1-24-2","t":"공공기관은 이 법제10조에 따라 정보공개의 청구를 받으면 그 청구를 받은 날부터 10일 이내에 공개 여부를 결정하여야 한다.","ox":"O","m":"②","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_1-24-3","t":"공공기관은 공개 청구된 공개 대상 정보의 전부 또는 일부가 제 3자와 관련이 있다고 인정할 때에는 그 사실을 제3자에게 3일 이내에 통지하여야 하며, 필요한 경우에는 그의 의견을 들을 수 있다.","ox":"X","m":"③","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_1-24-4","t":"청구인이 정보공개와 관련한 공공기관의 결정에 대하여 불복이 있거나 정보공개 청구 후 20일이 경과하도록 정보공개 결정이 없는 때에는 「행정소송법」 에서 정하는 바에 따라 행정소송을 제기할 수 있다.","ox":"O","m":"④","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_2-23-1","t":"행정지도란 행정기관이 그 소관 사무의 범위에서 일정한 행정목적을 실현하기 위하여 특정인에게 일정한 행위를 하거나 하지 아니하도록 지도, 권고, 조언 등을 하는 행정작용이다.","ox":"O","m":"①","c":"A","tp":"행정절차법 상 행정지도"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_2-23-2","t":"행정지도는 국민의 임의적 협력을 전제로 하는 강학상 행정행위에 해당한다.","ox":"X","m":"②","c":"A","tp":"행정절차법 상 행정지도"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_2-23-3","t":"행정지도의 상대방은 해당 행정지도의 방식‧ 내용 등에 관하여 행정기관에 의견제출을 할 수 있다.","ox":"O","m":"③","c":"A","tp":"행정절차법 상 행정지도"},{"y":2026,"e":"경찰 공채","qn":23,"i":"PO2026_2-23-4","t":"행정기관이 같은 행정목적을 실현하기 위하여 많은 상대방에게 행정지도를 하려는 경우에는 특별한 사정이 없으면 행정지도에 공통적인 내용이 되는 사항을 공표하여야 한다.","ox":"O","m":"④","c":"A","tp":"행정절차법 상 행정지도"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_2-24-1","t":"청구인이 정보공개와 관련한 공공기관의 비공개 결정 또는 부분 공개 결정에 대하여 불복이 있는 때에는 공공기관으로부터 정보 공개 여부의 결정 통지를 받은 날부터 30일 이내에 해당 공공 기관에 문서로 이의신청할 수 있다.","ox":"O","m":"①","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_2-24-2","t":"공공기관은 부득이한 사유로 정하여진 기간 이내에 결정할 수 없을 때를 제외하고는 이의신청을 받은 날부터 7일 이내에 그 이의신청에 대하여 결정하고 그 결과를 청구인에게 지체 없이 문서로 통지하여야 한다.","ox":"O","m":"②","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_2-24-3","t":"청구인은 「공공기관의 정보공개에 관한 법률」 제18조에 따른 이의신청 절차를 거치지 아니하고는 행정심판을 청구할 수 없다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"경찰 공채","qn":24,"i":"PO2026_2-24-4","t":"공공기관은 공개 청구된 공개 대상 정보의 전부 또는 일부가 제3자와 관련이 있다고 인정할 때에는 그 사실을 제3자에게 지체없이 통지하여야 하며, 공개 청구된 사실을 통지받은 제3자는 그 통지를 받은 날부터 3일 이내에 해당 공공기관에 대하여 자신과 관련된 정보를 공개하지 아니할 것을 요청할 수 있다.","ox":"O","m":"④","c":"A","tp":"공공기관의 정보공개"},{"y":2026,"e":"경찰 공채","qn":27,"i":"PO2026_2-27-1","t":"공무원이 직무수행 중 불법행위로 타인에게 손해를 입힌 경우, 피해자에게 손해를 직접 배상한 경과실이 있는 공무원은 특별한 사정이 없는 한 국가에 대하여 국가의 피해자에 대한 손해배상 책임의 범위 내에서 자신이 변제한 금액에 관하여 구상권을 취득한다.","ox":"O","m":"①","c":"A","tp":"국가배상"},{"y":2026,"e":"경찰 공채","qn":27,"i":"PO2026_2-27-2","t":"불법시위를 진압하는 경찰관들의 직무집행이 법령에 위반한 것 이라고 하기 위하여는 그 시위진압이 불필요하거나 또는 불법 시위의 태양 및 시위 장소의 상황 등에서 예측되는 피해 발생의 구체적 위험성의 내용에 비추어 시위진압의 계속 수행 내지 그 방법 등이 현저히 합리성을 결하여 이를 위법하다고 평가할 수 있는 경우이어야 한다.","ox":"O","m":"②","c":"A","tp":"국가배상"},{"y":2026,"e":"경찰 공채","qn":27,"i":"PO2026_2-27-3","t":"교차로 진행방향 신호기의 정지신호가 단선으로 소등되어 있는 상태에서 그대로 진행하다가 다른 방향의 진행신호에 따라 교차로에 진입한 차량과 충돌한 경우, 신호기의 적색신호가 소등된 기능상 결함이 있었다는 사정만으로도 신호기의 설치 또는 관리상의 하자를 인정할 수 있다.","ox":"X","m":"③","c":"A","tp":"국가배상"},{"y":2026,"e":"경찰 공채","qn":27,"i":"PO2026_2-27-4","t":"성폭력범죄의 수사를 담당하거나 수사에 관여하는 경찰관이 직무상 의무에 반하여 피해자의 인적사항 등을 공개 또는 누설 하였다면 국가는 그로 인하여 피해자가 입은 손해를 배상하여야 한다.","ox":"O","m":"④","c":"A","tp":"국가배상"},{"y":2026,"e":"경찰 공채","qn":28,"i":"PO2026_2-28-1","t":"의무이행심판은 행정청의 위법 또는 부당한 처분을 취소하거나 변경하는 행정심판이다.","ox":"X","m":"①","c":"A","tp":"행정심판법"},{"y":2026,"e":"경찰 공채","qn":28,"i":"PO2026_2-28-2","t":"경찰청장이 행한 행정처분에 대한 행정심판은 중앙행정심판 위원회가 심리‧ 재결한다.","ox":"O","m":"②","c":"A","tp":"행정심판법"},{"y":2026,"e":"경찰 공채","qn":28,"i":"PO2026_2-28-3","t":"행정심판을 청구하면 처분의 효력이나 그 집행 또는 절차의 속행은 정지된다.","ox":"X","m":"③","c":"A","tp":"행정심판법"},{"y":2026,"e":"경찰 공채","qn":28,"i":"PO2026_2-28-4","t":"행정심판위원회는 당사자가 주장하지 아니한 사실에 대하여 심리할 수 없다.","ox":"X","m":"④","c":"A","tp":"행정심판법"}],"6":[{"y":2022,"e":"경찰 공채","qn":32,"i":"PO2022_1-32","t":"행정상 즉시강제에 해당하는 것을 모두 고른 것은?","c":"A","mc":{"s":"행정상 즉시강제에 해당하는 것을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함) ㉠ 경찰관 직무집행법 제6조 범죄의 예방을 위한 제지 ㉡ 경찰관 직무집행법 제4조 제1항 제1호에서 규정하는 술에 취한 상태로 인하여 자기 또는 타인의 생명 신체와 재산에 위해를 미칠 우려가 있는 피구호자에 대한 보호조치 ㉢ 행정대집행법 제2조 대집행 ㉣ 국세징수법 제24조 강제징수","o":["㉠㉢","㉡㉢","㉠㉡","㉡㉣"],"a":3}},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_1-33-1","t":"권총 소총 기관총 함포 크레모아 수류탄 가스발사총은 무기에 해당한다.","ox":"X","m":"①","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_1-33-2","t":"경찰관은 14세 미만의 자 또는 임산부에 대하여 전자충격기 또는 전자방패를 사용하여서는 아니된다.","ox":"O","m":"②","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_1-33-3","t":"경찰관은 전극침(電極針) 발사장치가 있는 전자충격기를 사용하는 경우 상대방의 얼굴을 향하여 전극침을 발사하여서는 아니된다.","ox":"O","m":"③","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2022,"e":"경찰 공채","qn":33,"i":"PO2022_1-33-4","t":"경찰관(경찰공무원으로 한정한다)은 체포 구속영장을 집행하거나 신체의 자유를 제한하는 판결 또는 처분을 받은 자를 법률이 정한 절차에 따라 호송하거나 수용하기 위하여 필요한 때에는 최소한의 범위안에서 수갑 포승 또는 호송용포승을 사용할 수 있다.","ox":"O","m":"④","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2022,"e":"경찰 공채","qn":34,"i":"PO2022_1-34-1","t":"소속 경찰공무원의 직무집행으로 인하여 발생한 손실보상청구 사건을 심의하기 위하여 경찰청, 해양경찰청, 시 도경찰청 및 지방해양경찰청에 손실보상심의위원회를 설치한다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2022,"e":"경찰 공채","qn":34,"i":"PO2022_1-34-2","t":"손실보상을 청구할 수 있는 권리는 손실이 있음을 안 날부터 3년, 손실이 발생한 날부터 5년간 행사하지 아니하면 시효의 완성으로 소멸한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2022,"e":"경찰 공채","qn":34,"i":"PO2022_1-34-3","t":"손실보상금 지급 청구서를 받은 경찰청장등은 손실보상심의위 원회의 심의 의결에 따라 손실보상 여부 및 손실보상금액을 결정하되 손실보상 청구가 요건과 절차를 갖추지 못한 경우 (다만, 그 잘못된 부분을 시정할 수 있는 경우는 제외한다) 그 청구를 기각하는 결정을 하여야 한다.","ox":"X","m":"③","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2022,"e":"경찰 공채","qn":34,"i":"PO2022_1-34-4","t":"손실보상금은 일시불로 지급하되, 예산 부족 등의 사유로 일시금으로 지급할 수 없는 특별한 사정이 있는 경우에는 청구인의 동의를 받아 분할하여 지급할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2022,"e":"경찰 공채","qn":35,"i":"PO2022_1-35","t":"경찰 물리력 행사의 기준과 방법에 관한 규칙 제2장에 따른 대상자 행위에 대한 설명이다. 각 단계와 내용의 연결이 가장 적절하지 않은 것은?","c":"A","mc":{"s":"경찰 물리력 행사의 기준과 방법에 관한 규칙 제2장에 따른 대상자 행위에 대한 설명이다. 각 단계와 내용의 연결이 가장 적절하지 않은 것은?","d":"","o":["소극적 저항 - 대상자가 경찰관의 지시, 통제를 따르지 않고 비협조적이지만 경찰관 또는 제3자에 대해 직접적인 위해를 가하지 않는 상태","적극적 저항 - 대상자가 자신에 대한 경찰관의 체포 연행 등 정당한 공무집행을 방해하지만 경찰관 또는 제3자에 대해 위해 수준이 낮은 행위만을 하는 상태","폭력적 공격 - 대상자가 경찰관 또는 제3자에 대해 신체적 위해를 가하는 상태","치명적 공격 - 대상자가 경찰관에게 폭력을 행사하려는 자세를 취하여 그 행사가 임박한 상태, 주먹 발 등을 사용해서 경찰관에 대해 신체적 위해를 초래하고 있는 상태"],"a":4}},{"y":2022,"e":"경찰 공채","qn":36,"i":"PO2022_1-36","t":"<보기>의 내용 중 공통된 행정의 법 원칙은 무엇인가?","c":"A","mc":{"s":"<보기>의 내용 중 공통된 행정의 법 원칙은 무엇인가?","d":"<보 기> 행정기본법 제12조 제1항 “행정청은 공익 또는 제3자의 이익을 현저히 해칠 우려가 있는 경우를 제외하고는 행정에 대한 국민의 정당하고 합리적인 신뢰를 보호하여야 한다.” 행정절차법 제4조 제2항 “행정청은 법령등의 해석 또는 행정청의 관행이 일반적으로 국민들에게 받아들여졌을 때에는 공익 또는 제3자의 정당한 이익을 현저히 해칠 우려가 있는 경우를 제외하고는 새로운 해석 또는 관행에 따라 소급하여 불리하게 처리하여서는 아니 된다.”","o":["비례의 원칙","평등의 원칙","신뢰보호의 원칙","부당결부금지의 원칙"],"a":3}},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_1-37-1","t":"경찰관서의 장은 직무 수행에 필요하다고 인정되는 상당한 이유가 있을 때에는 국가기관이나 공사(公私) 단체 등에 직무 수행에 관련된 사실을 조회할 수 있다. 다만, 긴급한 경우에는 소속 경찰관으로 하여금 현장에 나가 해당 기관 또는 단체의 장의 협조를 받아 그 사실을 확인하게 할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_1-37-2","t":"국가경찰위원회 위원장은 경찰관이 경찰관 직무집행법 제2조 (직무의 범위) 각 호에 따른 직무의 수행으로 인하여 민형사상 책임과 관련된 소송을 수행할 경우 변호인 선임 등 소송 수행에 필요한 지원을 하여야 한다.","ox":"X","m":"②","c":"A"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_1-37-3","t":"경찰청장, 시 도경찰청장 또는 경찰서장은 경찰관 직무집행법 제11조의3 제2항에 따른 보상금심사위원회의 심사 의결에 따라 보상금을 지급하고, 거짓 또는 부정한 방법으로 보상금을 받은 사람에 대하여는 해당 보상금을 환수한다.","ox":"O","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":37,"i":"PO2022_1-37-4","t":"보상금심사위원회는 위원장 1명을 포함한 5명 이내의 위원으로 구성한다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법"},{"y":2022,"e":"경찰 공채","qn":38,"i":"PO2022_1-38","t":"다음 행정행위 중 강학상 특허에 해당하는 것은?","c":"A","mc":{"s":"다음 행정행위 중 강학상 특허에 해당하는 것은?","d":"","o":["자동차운전면허","재단법인의 정관변경 허가","한의사 면허","국유재산 등의 관리청이 행정재산의 사용 수익에 대하여 하는 허가"],"a":4}},{"y":2022,"e":"경찰 공채","qn":4,"i":"PO2022_2-04-1","t":"도로교통법상 교통단속임무를 수행하는 경찰공무원을 폭행한 사람의 운전면허를 취소하는 것은 행정청이 재량여지가 없으므로 재량권의 일탈 남용과는 관련이 없다.","ox":"O","m":"①","c":"A","tp":"경찰재량"},{"y":2022,"e":"경찰 공채","qn":4,"i":"PO2022_2-04-2","t":"재량을 선택재량과 결정재량으로 나눌 경우, 경찰공무원의 비위에 대해 징계처분을 하는 결정과 그 공무원의 건강 등 제반사정을 고려하여 징계처분을 하지 않는 결정 사이에서 선택권을 갖는 것을 결정재량이라 한다.","ox":"O","m":"②","c":"A","tp":"경찰재량"},{"y":2022,"e":"경찰 공채","qn":4,"i":"PO2022_2-04-3","t":"재량의 일탈 남용뿐만 아니라 단순히 재량권 행사에서 합리성을 결하는 등 재량을 그르친 경우에도 행정심판의 대상이 된다.","ox":"O","m":"③","c":"A","tp":"경찰재량"},{"y":2022,"e":"경찰 공채","qn":4,"i":"PO2022_2-04-4","t":"재량권의 일탈이란 재량권의 내적 한계(재량권이 부여된 내재적 목적)를 벗어난 것을 말하며, 재량권의 남용이란 재량권의 외적 한계(법적 객관적 한계)를 벗어난 것을 의미한다.","ox":"X","m":"④","c":"A","tp":"경찰재량"},{"y":2022,"e":"경찰 공채","qn":10,"i":"PO2022_2-10","t":"개인의 자유를 침해하거나 의무를 부과하는 행정은 반드시 법률의 근거가 있어야 한다는 원칙을 전제할 때, 법률의 근거 없이도 가능한 것을 모두 고른 것은?","c":"A","mc":{"s":"개인의 자유를 침해하거나 의무를 부과하는 행정은 반드시 법률의 근거가 있어야 한다는 원칙을 전제할 때, 법률의 근거 없이도 가능한 것을 모두 고른 것은?","d":"(다툼이 있는 경우 판례에 의함) ㉠ 경찰관의 학교 앞 등교지도 ㉡ 주민을 상대로 한 교통정책홍보 ㉢ 기초생활수급자에 대한 생계비지원 ㉣ 공무원에 대해 특정종교를 금지하는 훈령 ㉤ 자살을 시도하는 사람에 대한 경찰관서 보호 ㉥ 붕괴위험시설에 대한 예방적 출입금지","o":["㉠㉡㉢","㉠㉡㉤","㉠㉢㉤","㉡㉢㉣㉥"],"a":1}},{"y":2022,"e":"경찰 공채","qn":12,"i":"PO2022_2-12-1","t":"폐기물처리업에 대하여 사전에 관할 관청으로부터 적정통보를 받고 막대한 비용을 들여 허가요건을 갖춘 다음 허가신청을 하였음에도 관할 관청으로부터 ‘다수 청소업자의 난립으로 안정적이고 효율적인 청소업무의 수행에 지장이 있다’는 이유로 불허가처분을 받은 경우, 그 처분은 신뢰보호원칙 위반으로 인한 위법한 처분에 해당된다.","ox":"O","m":"①","c":"A","tp":"행정법의 일반원칙"},{"y":2022,"e":"경찰 공채","qn":12,"i":"PO2022_2-12-2","t":"지방자치단체장이 사업자에게 주택사업계획승인을 하면서 그 주택사업과는 아무런 관련이 없는 토지를 기부채납하도록 하는 부관을 주택사업계획승인에 붙인 경우, 그 부관은 부당 결부금지 원칙에 위반되어 위법하다.","ox":"O","m":"②","c":"A","tp":"행정법의 일반원칙"},{"y":2022,"e":"경찰 공채","qn":12,"i":"PO2022_2-12-3","t":"같은 정도의 비위를 저지른 자들 사이에 있어서도 그 직무의 특성, 비위의 성격 및 정도를 고려하여 징계종류의 선택과 양정을 차별적으로 취급하는 것은 합리적 차별로서 평등원칙에 반하지 아니한다.","ox":"O","m":"③","c":"A","tp":"행정법의 일반원칙"},{"y":2022,"e":"경찰 공채","qn":12,"i":"PO2022_2-12-4","t":"적법 및 위법을 불문하고 재량준칙에 따른 행정관행이 성립한 경우라면, 행정의 자기구속 원칙이 적용될 수 있다.","ox":"X","m":"④","c":"A","tp":"행정법의 일반원칙"},{"y":2022,"e":"경찰 공채","qn":16,"i":"PO2022_2-16","t":"다음은 경찰관 직무집행법 상 범죄의 예방과 제지에 관한 사례이다. 이와 관련한 설명 중 가장 적절한 것은?","c":"A","mc":{"s":"다음은 경찰관 직무집행법 상 범죄의 예방과 제지에 관한 사례이다. 이와 관련한 설명 중 가장 적절한 것은?","d":"(다툼이 있는 경우 판례에 의함) 甲은 평소 집에서 심한 고성과 욕설, 시끄러운 음악 소리 등으로 이웃 주민들로부터 수 회에 걸쳐 112신고가 있어 왔던 사람이다. 사건 당일에도 甲이 자정에 가까운 한밤중에 집 안에서 음악을 크게 켜놓고 심한 고성을 지른다는 112신고를 받고 경찰관이 출동하였다. 출동한 경찰관이 인터폰으로 甲에게 문을 열어달라고 하였으나, 甲은 심한 욕설을 할 뿐 출입문을 열어주지 않은 채, 소란행위를 멈추지 않았다. 이에 경찰관들이 甲을 만나기 위해 甲의 집으로 통하는 전기를 일시적으로 차단하여 甲이 집 밖으로 나오도록 유도하였다.","o":["경찰관 직무집행법 상 경찰관의 제지에 관한 부분은 눈앞의 급박한 경찰상 장해를 제거하여야 할 필요가 있고 의무를 명할 시간적 여유가 없거나 의무를 명하는 방법으로는 그 목적을 달성하기 어려운 상황에서 의무이행을 전제로 하지 않고 경찰이 직접 실력을 행사하여 경찰상 필요한 상태를 실현하는 비권력적 사실행위에 관한 근거조항이다.","甲의 행위는 경범죄처벌법 상 ‘인근소란 등’에 해당하고 이로 인하여 인근 주민들이 잠을 이루지 못할 수 있으며 출동한 경찰관들을 만나지 않고 소란행위를 지속하고 있으므로, 甲의 행위를 제지하는 것은 경찰관의 직무상 권한이자 의무로 볼 수 있다.","경찰관 직무집행법 상 경찰관의 제지 조치의 위법 여부는 사후적으로 순수한 객관적 기준에서 판단해야 하고 제지 조치 당시의 구체적 상황을 기초로 판단하는 것은 아니다.","경찰관의 조치는 사람의 생명·신체에 위해를 끼치거나 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우로 보기는 어려워 즉시강제가 아니라 직접강제의 요건에 부합한다."],"a":2}},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_2-18-1","t":"행정조사기본법상 조사대상자의 자발적 협조를 얻어 조사를 실시하는 경우에는 법령의 근거를 요하지 아니하며 조직법상의 권한 범위 밖에서도 가능하다.","ox":"X","m":"①","c":"A"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_2-18-2","t":"조사대상자의 자발적 협조로 조사가 이루어지는 경우일지라도 행정의 적법성 및 공공성 등을 높이기 위해서 조사목적 등을 반드시 서면으로 통보하여야 한다.","ox":"X","m":"②","c":"A","tp":"행정조사"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_2-18-3","t":"경찰작용은 행정작용의 일환이므로 경찰의 수사에도 행정조사 기본법이 적용되는 것이 원칙이다.","ox":"X","m":"③","c":"A"},{"y":2022,"e":"경찰 공채","qn":18,"i":"PO2022_2-18-4","t":"행정조사는 행정기관이 향후 행정작용에 필요한 자료 및 정보를 얻기 위한 준비적 보조적 작용이다.","ox":"O","m":"④","c":"A"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_2-19-1","t":"특별한 규정이 없는 한, 허가를 받게 되면 다른 법령상의 제한들도 모두 해제되는 것이 원칙이다.","ox":"X","m":"①","c":"A","tp":"강학상 경찰허가"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_2-19-2","t":"특별한 규정이 없는 한, 허가는 법령이 부과한 작위의무, 부작위 의무 및 급부의무를 모두 해제하는 것이다.","ox":"X","m":"②","c":"A","tp":"강학상 경찰허가"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_2-19-3","t":"강학상 허가와 강학상 특허는 당사자의 신청이 없어도 가능하다는 점에서 공통점이 있다.","ox":"X","m":"③","c":"A","tp":"강학상 경찰허가"},{"y":2022,"e":"경찰 공채","qn":19,"i":"PO2022_2-19-4","t":"일반적으로 영업허가를 받지 아니한 상태에서 행한 사법상 법률행위는 유효하다.","ox":"O","m":"④","c":"A","tp":"강학상 경찰허가"},{"y":2022,"e":"경찰 공채","qn":20,"i":"PO2022_2-20","t":"경찰관 직무집행법 상 즉시강제에 해당하는 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰관 직무집행법 상 즉시강제에 해당하는 것은 모두 몇 개인가?","d":"(다툼이 있는 경우 판례에 의함) ㉠ 주택가에서 흉기를 들고 난동을 부리며 경찰관의 중지명령에 항거하는 사람에 대해 전자충격기를 사용하여 강제로 제압 하는 것 ㉡ 음주운전 등 교통법규 위반자에 대해 운전면허를 취소하는 것 ㉢ 불법집회로 인한 공공시설의 안전에 대한 위해를 억제하기 위해 최루탄을 사용하는 것 ㉣ 위험물의 폭발로 인해 매우 긴급한 경우에 위해를 입을 우려가 있는 사람을 억류하거나 피난시키는 것 ㉤ 지정된 기한까지 체납액을 완납하지 않은 국세체납자의 재산을 압류하는 것 ㉥ 무허가건물의 철거 명령을 받고도 이를 불이행하는 사람의 불법건축물을 철거하는 것","o":["3개","4개","5개","6개"],"a":1}},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_2-23-1","t":"통고처분은 형식적 의미의 행정이며 실질적 의미의 사법이다.","ox":"O","m":"①","c":"A","tp":"행정의 실효성 확보수단"},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_2-23-2","t":"작위의무를 부과한 행정처분의 법적 근거가 있다면 행정대집행은 별도의 법적 근거를 요하지 아니하며, 즉시강제는 법률의 근거가 없더라도 일반긴급권에 기초하여 행사할 수 있다.","ox":"X","m":"②","c":"A","tp":"행정의 실효성 확보수단"},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_2-23-3","t":"행정대집행과 행정상 즉시강제는 제3자에 의해 집행될 수 없고 행정청이 직접 행사해야 한다.","ox":"X","m":"③","c":"A","tp":"행정의 실효성 확보수단"},{"y":2022,"e":"경찰 공채","qn":23,"i":"PO2022_2-23-4","t":"관세법상 통고처분 여부는 관세청장의 재량에 맡겨져 있지만, 경범죄처벌법 및 도로교통법상 통고처분은 재량의 여지가 없다.","ox":"X","m":"④","c":"A","tp":"행정의 실효성 확보수단"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_2-27-1","t":"법치행정의 원칙에 관한 전통적 견해는 ‘법률의 지배’, ‘법률의 우위’, ‘법률의 유보’를 내용으로 한다.","ox":"X","m":"①","c":"A","tp":"행정의 법률적합성 원칙(법치행정의 원칙)"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_2-27-2","t":"‘법률의 우위’에서의 법률에는 형식적 의미의 법률뿐만 아니라 그 밖에 성문법과 불문법이 포함된다.","ox":"O","m":"②","c":"A","tp":"행정의 법률적합성 원칙(법치행정의 원칙)"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_2-27-3","t":"법규명령에는 위임명령과 집행명령이 있으며, 모두 국민의 권리 의무에 관한 사항을 규정할 수 있다.","ox":"X","m":"③","c":"A","tp":"행정의 법률적합성 원칙(법치행정의 원칙)"},{"y":2022,"e":"경찰 공채","qn":27,"i":"PO2022_2-27-4","t":"법령의 구체적 위임 없이 최루액의 혼합 살수 방법 등을 규정한 경찰청장의 살수차운용지침 (2014. 4. 3.)은 법률유보의 원칙에 위배되는 측면이 있으나, 그 지침에 따라 살수한 경찰관의 행위는 집회를 해산하기 위한 불가피한 조치라는 점에서 반드시 위헌 위법이라 할 수 없다.","ox":"X","m":"④","c":"A","tp":"행정의 법률적합성 원칙(법치행정의 원칙)"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_1-18-1","t":"경찰행정법의 법원(法源)은 일반적으로 성문법원과 불문법원으로 나눌 수 있으며 헌법, 법률, 조례와 규칙은 성문법원에 해당한다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_1-18-2","t":"대통령령, 총리령 및 부령은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다.","ox":"O","m":"②","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_1-18-3","t":"지방자치단체의 장은 법령의 범위에서 그 사무에 관하여 조리 (條理)를 제정할 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2023,"e":"경찰 공채","qn":18,"i":"PO2023_1-18-4","t":"사회의 거듭된 관행으로 생성한 사회생활규범이 사회의 법적 확신과 인식에 의하여 법적 규범으로 승인·강행되기에 이른 것을 관습법이라 한다.","ox":"O","m":"④","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_1-19-1","t":"경찰비례의 원칙은 일반적 수권조항에 근거하여 경찰권을 발동하는 경우는 물론, 개별적 수권조항에 근거하여 경찰권을 발동하는 경우에도 적용된다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_1-19-2","t":"적합성의 원칙은 경찰기관의 어떤 조치가 경찰목적 달성을 위해 필요한 경우라고 하여도 그 조치에 따른 불이익이 그 조치로 인해 발생하는 이익보다 큰 경우에는 경찰권을 발동해서는 안된다는 원칙이다.","ox":"X","m":"②","c":"A","tp":"경찰비례의 원칙"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_1-19-3","t":"필요성의 원칙(최소침해의 원칙)은 목적을 달성할 수 있는 수단이 여러 가지가 있는 경우에 적합한 여러 가지 수단 중에서 가장 적게 침해를 가져오는 수단을 선택해야 한다는 원칙이다.","ox":"O","m":"③","c":"A","tp":"경찰비례의 원칙"},{"y":2023,"e":"경찰 공채","qn":19,"i":"PO2023_1-19-4","t":"경찰비례의 원칙은 「행정기본법」 제10조, 「경찰관 직무집행법」 제1조 제2항 등에서 근거를 찾아볼 수 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_1-20-1","t":"경찰하명은 경찰상의 목적을 위하여 국가의 일반통치권에 의거, 개인에게 특정한 작위·부작위·수인 또는 급부의 의무를 명하는 행정행위이다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_1-20-2","t":"부작위하명은 적극적으로 어떤 행위를 하지 말 것을 명하는 것으로 ‘면제’라 부르기도 한다.","ox":"X","m":"②","c":"A","tp":"경찰하명"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_1-20-3","t":"경찰하명에 위반한 행위는 강제집행이나 처벌의 대상이 되지만, 원칙적으로 사법(私法)상의 법률적 효력까지 부인하는 것은 아니다.","ox":"O","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_1-20-4","t":"위법한 경찰하명으로 인하여 권리·이익이 침해된 자는 행정쟁송 또는 손해배상을 청구할 수 있다.","ox":"O","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":21,"i":"PO2023_1-21-1","t":"행정청은 처분에 재량이 있는 경우에는 부관을 붙일 수 있다.","ox":"O","m":"①","c":"A","tp":"행정기본법 상 부관"},{"y":2023,"e":"경찰 공채","qn":21,"i":"PO2023_1-21-2","t":"행정청은 처분에 재량이 없는 경우에는 법률에 근거가 있는 경우에 부관을 붙일 수 있다.","ox":"O","m":"②","c":"A","tp":"행정기본법 상 부관"},{"y":2023,"e":"경찰 공채","qn":21,"i":"PO2023_1-21-3","t":"행정청은 부관을 붙일 수 있는 처분이 당사자의 동의가 있는 경우에는 그 처분을 한 후에도 부관을 새로 붙이거나 종전의 부관을 변경할 수 있다.","ox":"O","m":"③","c":"A","tp":"행정기본법 상 부관"},{"y":2023,"e":"경찰 공채","qn":21,"i":"PO2023_1-21-4","t":"부관은 해당 처분의 목적에 위배되지 아니하고, 실질적 관련이 없을 것을 요건으로 한다.","ox":"X","m":"④","c":"A","tp":"행정기본법 상 부관"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_1-22-1","t":"과징금은 원칙적으로 행정법상의 의무를 위반한 자에 대하여 당해 위반행위로 얻게 된 경제적 이익을 박탈하기 위한 목적으로 부과하는 금전적인 제재이다.","ox":"O","m":"①","c":"A","tp":"행정상 의무이행확보수단"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_1-22-2","t":"「경찰관 직무집행법」 제6조 “경찰관은 범죄행위가 목전에 행하여지려고 하고 있다고 인정될 때에는 이를 예방하기 위하여 관계인에게 필요한 경고를 하고, 그 행위로 인하여 사람의 생명·신체에 위해를 끼치거나 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우에는 그 행위를 제지할 수 있다” 규정은 행정상 즉시강제에 해당한다.","ox":"O","m":"②","c":"A","tp":"행정상 의무이행확보수단"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_1-22-3","t":"「경찰관 직무집행법」 제4조 제1항 제1호에서 규정하는 술에 취한 상태로 인하여 자기 또는 타인의 생명·신체와 재산에 위해를 미칠 우려가 있는 피구호자에 대한 보호조치는 행정상 강제 집행에 해당한다.","ox":"X","m":"③","c":"A","tp":"행정상 의무이행확보수단"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_1-22-4","t":"가산세는 개별 세법이 과세의 적정을 기하기 위하여 정한 의무의 이행을 확보할 목적으로 그 의무 위반에 대하여 세금의 형태로 가하는 행정상 제재이다.","ox":"O","m":"④","c":"A","tp":"행정상 의무이행확보수단"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_1-23-1","t":"행정청은 법제16조 제2항에 따라 당사자가 제출한 의견에 상당한 이유가 있는 경우에는 과태료를 부과하지 아니하거나 통지한 내용을 변경할 수 있다.","ox":"O","m":"①","c":"A","tp":"질서위반행위규제법 상 행정청의 과태료 부과 및 징수"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_1-23-2","t":"법제20조 제1항에 따른 이의제기가 있는 경우에는 행정청의 과태료 부과처분은 그 효력을 상실하지 않는다.","ox":"X","m":"②","c":"A","tp":"질서위반행위규제법 상 행정청의 과태료 부과 및 징수"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_1-23-3","t":"당사자가 법제18조 제1항에 따라 감경된 과태료를 납부한 경우에는 해당 질서위반행위에 대한 과태료 부과 및 징수절차는 종료한다.","ox":"O","m":"③","c":"A","tp":"질서위반행위규제법 상 행정청의 과태료 부과 및 징수"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_1-23-4","t":"행정청은 당사자가 납부기한까지 과태료를 납부하지 아니한 때에는 납부기한을 경과한 날부터 체납된 과태료에 대하여 100분의 3에 상당하는 가산금을 징수한다.","ox":"O","m":"④","c":"A","tp":"질서위반행위규제법 상 행정청의 과태료 부과 및 징수"},{"y":2023,"e":"경찰 공채","qn":27,"i":"PO2023_1-27-1","t":"긴급구호를 요청받은 공공보건의료기관이나 공공구호기관은 정당한 이유 없이 긴급구호를 거절할 수 있다.","ox":"X","m":"①","c":"A","tp":"경찰관 직무집행법 상 보호조치 등"},{"y":2023,"e":"경찰 공채","qn":27,"i":"PO2023_1-27-2","t":"경찰관은 보호조치를 하는 경우에 구호대상자가 휴대하고 있는 무기·흉기 등 위험을 일으킬 수 있는 것으로 인정되는 물건을 공공보건의료기관이나 공공구호기관에 임시로 영치하여 놓을 수 있다.","ox":"X","m":"②","c":"A","tp":"경찰관 직무집행법 상 보호조치 등"},{"y":2023,"e":"경찰 공채","qn":27,"i":"PO2023_1-27-3","t":"경찰관은 보호조치를 하였을 때에는 지체 없이 구호대상자의 가족, 친지 또는 그 밖의 연고자에게 그 사실을 알려야 하며, 연고자가 발견되지 아니할 때에는 구호대상자를 적당한 공공 보건의료기관이나 공공구호기관에 즉시 인계하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법 상 보호조치 등"},{"y":2023,"e":"경찰 공채","qn":27,"i":"PO2023_1-27-4","t":"구호대상자를 경찰관서에서 보호하는 기간은 48시간을 초과할 수 없고, 물건을 공공보건의료기관이나 공공구호기관에 임시로 영치하는 기간은 10일을 초과할 수 없다.","ox":"X","m":"④","c":"A","tp":"경찰관 직무집행법 상 보호조치 등"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_1-28-1","t":"협조적 통제는 ‘순응’ 이상의 상태인 대상자에 대해 사용할 수 있는 물리력 수준으로서, 대상자의 협조를 유도하거나 협조에 따른 물리력을 말한다.","ox":"O","m":"①","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_1-28-2","t":"접촉 통제는 ‘소극적 저항’ 이상의 상태인 대상자에 대해 사용 할 수 있는 물리력 수준으로서, 대상자 신체 접촉을 통해 경찰목적 달성을 강제하지만 신체적 부상을 야기할 가능성은 극히 낮은 물리력을 말한다.","ox":"O","m":"②","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_1-28-3","t":"저위험 물리력은 ‘적극적 저항’ 이상의 상태인 대상자에 대해 사용할 수 있는 물리력 수준으로서, 대상자가 통증을 느낄 수 있으나 신체적 부상을 당할 가능성은 낮은 물리력을 말한다.","ox":"O","m":"③","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2023,"e":"경찰 공채","qn":28,"i":"PO2023_1-28-4","t":"중위험 물리력은 ‘치명적 공격’ 상태의 대상자로 인해 경찰관 또는 제3자의 생명·신체에 급박하고 중대한 위해가 초래될 가능성이 있는 경우 최후의 수단으로 사용할 수 있는 물리력 수준으로서, 대상자의 사망 또는 심각한 부상을 초래할 수 있는 물리력을 말한다.","ox":"X","m":"④","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_2-14-1","t":"행정청은 행정작용을 할 때 상대방에게 해당 행정작용과 실질적인 관련이 없는 의무를 부과해서는 아니 된다는 원칙이다.","ox":"O","m":"①","c":"A","tp":"부당결부금지의 원칙"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_2-14-2","t":"현행법상 명시적인 규정은 없지만 법치국가의 원리와 자의금지의 원칙으로부터 도출되는 행정법의 일반원칙이다.","ox":"X","m":"②","c":"A","tp":"부당결부금지의 원칙"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_2-14-3","t":"지방자치단체장이 사업자에게 주택사업계획승인을 하면서 그 주택사업과는 아무런 관련이 없는 토지를 기부채납하도록 하는 부관을 붙인 경우에는, 기부채납한 토지 가액이 그 주택사업 계획의 100분의 1 상당의 금액에 불과하고 사업자가 이의를 제기하지 아니하다가 지방자치단체장이 업무착오로 기부채납한 토지에 대하여 보상협조요청서를 보내자 그 때서야 비로소 부관의 하자를 들고 나왔다고 하더라도 그 부관은 당연무효이다.","ox":"X","m":"③","c":"A","tp":"부당결부금지의 원칙"},{"y":2023,"e":"경찰 공채","qn":14,"i":"PO2023_2-14-4","t":"甲이 혈중알코올농도 0.140%의 주취상태로 배기량 125cc 이륜 자동차를 운전하였다는 이유로 甲의 자동차운전면허[제1종 대형, 제1종 보통, 제1종 특수(대형견인·구난), 제2종 소형]를 취소한 것은 甲이 음주상태에서 운전을 하지 않으면 안 되는 부득이한 사정이 없었더라도 재량권을 일탈·남용한 것이다.","ox":"X","m":"④","c":"A","tp":"부당결부금지의 원칙"},{"y":2023,"e":"경찰 공채","qn":15,"i":"PO2023_2-15-1","t":"행정에 관한 나이는 다른 법령등에 특별한 규정이 있는 경우에도 출생일을 산입하지 않고만(滿) 나이로 계산하고, 연수 (年數)로 표시하되, 1세에 이르지 아니한 경우에는 월수(月數)로 표시할 수 있다.","ox":"X","m":"①","c":"A","tp":"행정기본법"},{"y":2023,"e":"경찰 공채","qn":15,"i":"PO2023_2-15-2","t":"행정작용은 그 행정작용이 의도하는 공익이 행정작용으로 인한 국민의 이익 침해보다 크지 않아야 한다.","ox":"X","m":"②","c":"A","tp":"행정기본법"},{"y":2023,"e":"경찰 공채","qn":15,"i":"PO2023_2-15-3","t":"행정청은 법률로 정하는 바에 따라 완전히 자동화된 시스템 (인공지능 기술을 적용한 시스템을 포함)으로 처분을 할 수 있으나, 처분에 재량이 있는 경우는 그러하지 아니하다.","ox":"O","m":"③","c":"A","tp":"행정기본법"},{"y":2023,"e":"경찰 공채","qn":15,"i":"PO2023_2-15-4","t":"공익 또는 제3자의 이익을 현저히 해칠 우려가 있는 경우에도 행정청은 권한 행사의 기회가 있음에도 불구하고 장기간 권한을 행사하지 아니하여 국민이 그 권한이 행사되지 아니할 것으로 믿을 만한 정당한 사유가 있는 경우에는 그 권한을 행사해서는 아니 된다.","ox":"X","m":"④","c":"A","tp":"행정기본법"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_2-17-1","t":"국유재산의 관리청이 그 무단점유자에 대하여 하는 변상금부과 처분은 순전히 사경제 주체로서 행하는 사법상의 법률행위이다.","ox":"X","m":"①","c":"A","tp":"행정상 법률관계"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_2-17-2","t":"국가나 지방자치단체에 근무하는 청원경찰은 「국가공무원법」 이나 「지방공무원법」 상의 공무원은 아니지만 그 근무관계를 사법상의 고용계약관계로 보기는 어렵다.","ox":"O","m":"②","c":"A","tp":"행정상 법률관계"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_2-17-3","t":"원천징수의무자가 비록 과세관청과 같은 행정청이라 하더라도 그의 원천징수행위는 법령에서 규정된 징수 및 납부의무를 이행하기 위한 것에 불과한 것이지, 공권력의 행사로서의 행정 처분을 한 경우에 해당되지 아니한다.","ox":"O","m":"③","c":"A","tp":"행정상 법률관계"},{"y":2023,"e":"경찰 공채","qn":17,"i":"PO2023_2-17-4","t":"국립 교육대학 학생에 대한 퇴학처분은 행정처분이다.","ox":"O","m":"④","c":"A","tp":"행정상 법률관계"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_2-20-1","t":"일반수권조항이란 경찰권의 발동근거가 되는 개별적인 작용법적 근거가 없을 때 경찰권 발동의 일반적·보충적 근거가 될 수 있도록 개괄적으로 수권된 일반조항을 말한다.","ox":"O","m":"①","c":"A","tp":"경찰권 발동의 근거와 한계"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_2-20-2","t":"「경찰관 직무집행법」 제5조는 형식상 경찰관에게 재량에 의한 직무수행권한을 부여한 것처럼 되어 있으나, 경찰관에게 그러한 권한을 부여한 취지와 목적에 비추어 볼 때 구체적인 사정에 따라 경찰관이 그 권한을 행사하여 필요한 조치를 취하지 아니하는 것이 현저하게 불합리하다고 인정되는 경우에는 그러한 권한의 불행사는 직무상의 의무를 위반한 것이 되어 위법하게 된다.","ox":"O","m":"②","c":"A","tp":"경찰권 발동의 근거와 한계"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_2-20-3","t":"경찰청장과 해양경찰청장은 경찰관이 「경찰관 직무집행법」 제2조 각 호에 따른 직무의 수행으로 인하여 민·형사상 책임과 관련된 소송을 수행할 경우 변호인 선임 등 소송 수행에 필요한 지원을 할 수 있다.","ox":"O","m":"③","c":"A","tp":"경찰권 발동의 근거와 한계"},{"y":2023,"e":"경찰 공채","qn":20,"i":"PO2023_2-20-4","t":"「경찰관 직무집행법」 은 “경찰공무원은 직위 또는 직권을 이용 하여 부당하게 타인의 사생활에 개입하여서는 아니된다.”고 규정하고 있다.","ox":"X","m":"④","c":"A","tp":"경찰권 발동의 근거와 한계"},{"y":2023,"e":"경찰 공채","qn":21,"i":"PO2023_2-21","t":"행정행위의 부관은 ()인 경우를 제외하고는 독립하여 행정소송의 대상이 될 수 없다. 빈칸에 들어갈 말로 가장 적절한 것은?","c":"A","mc":{"s":"행정행위의 부관은 ()인 경우를 제외하고는 독립하여 행정소송의 대상이 될 수 없다. 빈칸에 들어갈 말로 가장 적절한 것은?","d":"","o":["부담","조건","기한","기간"],"a":1}},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_2-22-1","t":"질서위반행위에 대하여 과태료 부과의 근거 법률이 개정되어 행위 시의 법률에 의하면 과태료 부과대상이었지만 재판 시의 법률에 의하면 과태료 부과대상이 아니게 된 때에는 개정 법률의 부칙에서 종전 법률 시행 당시에 행해진 질서위반행위에 대해서는 행위 시의 법률을 적용하도록 특별한 규정을 두지 않은 이상 재판 시의 법률을 적용하여야 하므로 과태료를 부과할 수 없다.","ox":"O","m":"①","c":"A","tp":"행정상 의무이행 확보수단"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_2-22-2","t":"경찰서장이 범칙행위에 대하여 통고처분을 한 이상 통고처분에서 정한 범칙금 납부기간까지는 원칙적으로 경찰서장은 즉결심판을 청구할 수 없다.","ox":"O","m":"②","c":"A","tp":"행정상 의무이행 확보수단"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_2-22-3","t":"피고인이 즉결심판에 대하여 제출한 정식재판청구서에 피고인의 자필로 보이는 이름이 기재되어 있고 그 옆에 서명이 되어 있어 위 서류가 작성자 본인인 피고인의 진정한 의사에 따라 작성 되었다는 것을 명백하게 확인할 수 있더라도 피고인의 인장이나 지장이 찍혀 있지 않다면 정식재판청구는 부적법하다고 보아야 한다.","ox":"X","m":"③","c":"A","tp":"행정상 의무이행 확보수단"},{"y":2023,"e":"경찰 공채","qn":22,"i":"PO2023_2-22-4","t":"「질서위반행위규제법」 에 따르면 고의 또는 과실이 없는 질서 위반행위는 과태료를 부과하지 아니한다.","ox":"O","m":"④","c":"A","tp":"행정상 의무이행 확보수단"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_2-23-1","t":"「경찰관 직무집행법」 에 따르면 경찰관은 유실물을 인수할 권리자 확인의 직무를 수행하기 위하여 필요하면 관계인에게 출석하여야 하는 사유·일시 및 장소를 명확히 적은 출석 요구서를 보내 경찰관서에 출석할 것을 요구할 수 있다.","ox":"O","m":"①","c":"A"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_2-23-2","t":"「경찰관 직무집행법」 에 따르면 위해성 경찰장비의 종류 및 그 사용기준, 안전교육·안전검사의 기준 등은 행정안전부령으로 정한다.","ox":"X","m":"②","c":"A"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_2-23-3","t":"「경찰관 직무집행법」 제11조의2 제1항에 따른 손실보상을 청구할 수 있는 권리는 손실이 있음을 안 날부터 3년, 손실보상이 확정된 때부터 5년간 행사하지 아니하면 시효의 완성으로 소멸한다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":23,"i":"PO2023_2-23-4","t":"「경찰관 직무집행법」 제2조 직무의 범위에 “테러경보 발령·대테러 작전 수행”을 명시하고 있다.","ox":"X","m":"④","c":"A"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_2-24-1","t":"경찰 병력이 행정대집행 직후 “A자동차 희생자 추모와 해고자 복직을 위한 범국민대책위원회”(이하 ‘A차 대책위’라 함)가 또다시 같은 장소를 점거하고 물건을 다시 비치하는 것을 막기 위해 당해 사건 장소를 미리 둘러싼 뒤 ‘A차 대책위’가 같은 장소에서 기자회견 명목의 집회를 개최하려는 것을 불허하면서 소극적으로 제지한 것은 범죄행위 예방을 위한 경찰 행정상 즉시강제로서 적법한 공무집행에 해당한다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_2-24-2","t":"「아동학대범죄의 처벌 등에 관한 특례법」 에 따른 아동학대범죄가 행하여지려고 하거나 행하여지고 있어 타인의 생명·신체에 대한 위해 발생의 우려가 명백하고 긴급한 상황에서, 경찰관이 그 위해를 예방하거나 진압하기 위한 행위 또는 범인의 검거 과정에서 경찰관을 향한 직접적인 유형력 행사에 대응하는 행위를 하여 그로 인하여 타인에게 피해가 발생한 경우, 그 경찰관의 직무 수행이 불가피한 것이고 필요한 최소한의 범위에서 이루어졌으며 해당 경찰관에게 고의 또는 중대한 과실이 없는 때에는 형을 감경하거나 면제한다.","ox":"X","m":"②","c":"A","tp":"경찰관 직무집행법"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_2-24-3","t":"경찰관은 형사처벌의 대상이 되는 행위가 눈앞에서 막 이루어 지려고 하는 것이 주관적으로 인정될 수 있는 상황이고 그 행위를 당장 제지하지 않으면 곧 인명·신체에 중대한 위해를 미치거나 재산에 손해를 끼칠 우려가 있는 상황이어서, 직접 제지하는 방법 외에는 위와 같은 결과를 막을 수 없는 급박한 상태일 때에만 「경찰관 직무집행법」 제6조에 의하여 적법하게 그 행위를 제지할 수 있다.","ox":"X","m":"③","c":"A"},{"y":2023,"e":"경찰 공채","qn":24,"i":"PO2023_2-24-4","t":"「경찰관 직무집행법」 은제1조 제2항에서 “경찰관의 직권은 그 직무 수행에 필요한 최소한도에서 행사되어야 하며 남용되어서는 아니 된다.”라고 선언하여 경찰비례의 원칙을 명시적으로 규정하고 있는데, 이는 경찰행정 영역에서의 헌법상 과소보호 금지원칙을 표현한 것이다.","ox":"X","m":"④","c":"A"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_1-15-1","t":"법률우위원칙은 행정의 종류를 불문하고 모든 행정 영역에 적용된다.","ox":"O","m":"①","c":"A","tp":"법치행정의 원칙"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_1-15-2","t":"법률유보원칙은 법률에 의한 규율을 뜻하므로 위임입법에 의해 기본권 제한을 할 수 없다.","ox":"X","m":"②","c":"A","tp":"법치행정의 원칙"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_1-15-3","t":"헌법상 보장된 국민의 자유나 권리를 제한할 때에는 적어도 그 제한의 본질적인 사항에 관하여 국회가 법률로써 스스로 규율하여야 한다.","ox":"O","m":"③","c":"A","tp":"법치행정의 원칙"},{"y":2024,"e":"경찰 공채","qn":15,"i":"PO2024_1-15-4","t":"집회나 시위 해산을 위한 살수차 사용은 기본권에 대한 중대한 제한이므로, 살수차 사용요건이나 기준은 법률에 근거를 두어야 한다.","ox":"O","m":"④","c":"A","tp":"법치행정의 원칙"},{"y":2024,"e":"경찰 공채","qn":17,"i":"PO2024_1-17-1","t":"경찰관이 불심검문 대상자 해당 여부를 판단할 때에는 불심검문 당시의 구체적 상황은 물론 사전에 얻은 정보나 전문적 지식 등에 기초하여 불심검문 대상자인지를 객관적·합리적인 기준에 따라 판단하여야 하나, 반드시 불심검문 대상자에게 「형사소송법」 상 체포나 구속에 이를 정도의 혐의가 있을 것을 요한다고 할 수는 없다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법"},{"y":2024,"e":"경찰 공채","qn":17,"i":"PO2024_1-17-2","t":"술에 취한 상태로 인하여 자기 또는 타인의 생명·신체와 재산에 위해를 미칠 우려가 있는 피구호자에 대한 보호조치는 경찰 행정상 즉시강제에 해당하므로, 그 조치가 불가피한 최소한도 내에서만 행사되도록 발동·행사 요건을 신중하고 엄격하게 해석하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법"},{"y":2024,"e":"경찰 공채","qn":17,"i":"PO2024_1-17-3","t":"경찰관의 경고나 제지는 범죄행위가 목전에 행하여지려고 하고 있다고 인정될 때에 이를 예방하기 위하여 이루어지는 조치로서, 범죄행위가 계속되는 중 그 진압을 위해서는 행하여질 수 없다.","ox":"X","m":"③","c":"A","tp":"경찰관 직무집행법"},{"y":2024,"e":"경찰 공채","qn":17,"i":"PO2024_1-17-4","t":"경찰관은 「경범죄 처벌법」 상경범죄에 해당하는 행위에 대해서도 필요한 경우 제지할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법"},{"y":2024,"e":"경찰 공채","qn":18,"i":"PO2024_1-18-1","t":"경찰관은 경찰장비에 임의의 장비를 부착하여 일반적인 사용법과 달리 사용함으로써 다른 사람의 생명·신체에 위해를 끼쳐서는 안 된다.","ox":"O","m":"①","c":"A","tp":"경찰장비와 그 사용"},{"y":2024,"e":"경찰 공채","qn":18,"i":"PO2024_1-18-2","t":"경찰청장은 위해성 경찰장비를 새로 도입하려는 경우에는 대통령령으로 정하는 바에 따라 안전성 검사를 실시하여 그 안전성 검사의 결과보고서를 국회 소관 상임위원회에 제출하여야 한다. 이 경우 안전성 검사에는 외부 전문가를 참여시켜야 한다.","ox":"O","m":"②","c":"A","tp":"경찰장비와 그 사용"},{"y":2024,"e":"경찰 공채","qn":18,"i":"PO2024_1-18-3","t":"경찰관이 농성 진압 과정에서 경찰장비를 적법하게 사용하였더라도, 상대방이 그로 인한 생명·신체에 대한 위해를 면하기 위하여 대항하는 과정에서 경찰장비를 손상시켰다면 이는 현재의 부당한 침해에서 벗어나기 위한 행위로서 정당방위에 해당한다.","ox":"X","m":"③","c":"A","tp":"경찰장비와 그 사용"},{"y":2024,"e":"경찰 공채","qn":18,"i":"PO2024_1-18-4","t":"수사기관에서 구속된 피의자의 도주, 항거 등을 억제하는 데 필요하다고 인정할 상당한 이유가 있는 경우에는 필요한 한도 내에서 포승이나 수갑을 사용할 수 있으며, 이러한 조치가 무죄추정의 원칙에 위배되는 것이라고 할 수 없다.","ox":"O","m":"④","c":"A","tp":"경찰장비와 그 사용"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_1-20-1","t":"행정대집행은 대체적 작위의무 불이행에 대하여 다른 수단으로는 그 이행을 확보하기 곤란하고 불이행을 방치하면 공익을 크게 해칠 것으로 인정될 때에 행정청이 의무자가 하여야 할 행위를 스스로 하거나 제3자에게 하게 하고 그 비용을 의무자로부터 징수하는 것을 말한다.","ox":"O","m":"①","c":"A","tp":"경찰행정의 실효성 확보수단"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_1-20-2","t":"행정청은 의무자가 행정상 의무를 이행할 때까지 이행강제금을 반복하여 부과할 수 있으나, 의무자가 의무를 이행하면 이미 부과한 이행강제금을 징수하여서는 안 된다.","ox":"X","m":"②","c":"A","tp":"경찰행정의 실효성 확보수단"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_1-20-3","t":"직접강제는 행정대집행이나 이행강제금 부과로는 행정상 의무이행을 확보할 수 없거나 그 실현이 불가능한 경우에 실시하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰행정의 실효성 확보수단"},{"y":2024,"e":"경찰 공채","qn":20,"i":"PO2024_1-20-4","t":"경찰행정상 즉시강제는 눈앞의 급박한 경찰상 장해를 제거하여야 할 필요가 있고 의무를 명할 시간적 여유가 없거나 의무를 명하는 방법으로는 그 목적을 달성하기 어려운 상황에서 의무불이행을 전제로 하지 않고 경찰이 직접 실력을 행사하여 경찰상 필요한 상태를 실현하는 권력적 사실행위이다.","ox":"O","m":"④","c":"A","tp":"경찰행정의 실효성 확보수단"},{"y":2024,"e":"경찰 공채","qn":24,"i":"PO2024_1-24-1","t":"국가는 경찰관의 적법한 직무집행으로 인하여 손실발생의 원인에 대하여 책임이 있는 자가 자신의 책임에 상응하는 정도를 초과하는 생명·신체 또는 재산상의 손실을 입은 경우 정당한 보상을 하여야 한다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 및 경찰관 직무집행법 시행령 상 손실보상"},{"y":2024,"e":"경찰 공채","qn":24,"i":"PO2024_1-24-2","t":"경찰관의 적법한 직무집행으로 인하여 발생한 손실을 보상받으려는 사람은 보상금 지급 청구서에 손실내용과 손실금액을 증명할 수 있는 서류를 첨부하여 손실보상청구 사건발생지를 관할하는 국가경찰관서의 장에게 제출하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 경찰관 직무집행법 시행령 상 손실보상"},{"y":2024,"e":"경찰 공채","qn":24,"i":"PO2024_1-24-3","t":"보상금은 다른 법률에 특별한 규정이 있는 경우를 제외하고는 현금으로 지급하여야 한다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법 및 경찰관 직무집행법 시행령 상 손실보상"},{"y":2024,"e":"경찰 공채","qn":24,"i":"PO2024_1-24-4","t":"소속 경찰공무원의 직무집행으로 인하여 발생한 손실보상청구 사건을 심의하기 위하여 시·도경찰청, 지방해양경찰청, 경찰서 및 해양경찰서에 손실보상심의위원회를 설치한다.","ox":"X","m":"④","c":"A","tp":"경찰관 직무집행법 및 경찰관 직무집행법 시행령 상 손실보상"},{"y":2024,"e":"경찰 공채","qn":28,"i":"PO2024_1-28","t":"｢경찰 물리력 행사의 기준과 방법에 관한 규칙｣ 상 ‘적극적 저항’을 하는 대상자에 대하여 경찰관이 사용할 수 있는 물리력의 종류로 가장 적절하지 않은 것은?","c":"A","mc":{"s":"｢경찰 물리력 행사의 기준과 방법에 관한 규칙｣ 상 ‘적극적 저항’을 하는 대상자에 대하여 경찰관이 사용할 수 있는 물리력의 종류로 가장 적절하지 않은 것은?","d":"(규칙 제2장 2.2.의 설명에 따름)","o":["언어적 통제","체포 등을 위한 수갑 사용","손바닥, 주먹, 발 등 신체부위를 이용한 가격","분사기 사용"],"a":3}},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_2-16-1","t":"비례의 원칙이란 행정작용에 있어서 행정목적과 행정수단 사이에는 합리적인 비례관계가 있어야 한다는 원칙을 말한다.","ox":"O","m":"①","c":"A","tp":"행정법상 비례의 원칙"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_2-16-2","t":"비례의 원칙은 헌법 제37조 제2항, 「행정기본법」 제10조, 「경찰관 직무집행법」 제1조 제2항에서 근거를 찾을 수 있다.","ox":"O","m":"②","c":"A","tp":"행정법상 비례의 원칙"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_2-16-3","t":"적합성의 원칙은, 행정조치는 설정된 목적 달성을 위해 필요 최소한의 한도 내에서 이루어져야 한다는 것으로, 협의의 비례 원칙이라고도 한다.","ox":"X","m":"③","c":"A","tp":"행정법상 비례의 원칙"},{"y":2024,"e":"경찰 공채","qn":16,"i":"PO2024_2-16-4","t":"행정조치를 취함에 따른 불이익이 그것에 의해 달성되는 이익보다 심히 큰 경우에는 그 행정조치를 취해서는 아니된다는 원칙을 상당성의 원칙이라 한다.","ox":"O","m":"④","c":"A","tp":"행정법상 비례의 원칙"},{"y":2024,"e":"경찰 공채","qn":17,"i":"PO2024_2-17","t":"｢법령 등 공포에 관한 법률｣ 에 대한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"｢법령 등 공포에 관한 법률｣ 에 대한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["｢법령 등 공포에 관한 법률｣ 상 법률, 대통령령, 총리령 및 부령은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다.","｢국회법｣ 제98조 제3항 전단에 따라 하는 국회의장의 법률 공포는 서울특별시에서 발행되는 둘 이상의 일간신문에 게재함 으로써 한다.","법령 등의 공포일 또는 공고일은 해당 법령 등을 게재한 관보 또는 신문이 발행된 날로 한다.","헌법개정･ 법률･ 조약･ 대통령령･ 총리령 및 부령의 공포와 헌법 개정안･ 예산 및 예산 외 국고부담계약의 공고는 관보에 게재 함으로써 한다."],"a":1}},{"y":2024,"e":"경찰 공채","qn":18,"i":"PO2024_2-18","t":"다음 중 행정행위의 무효로 볼 수 있는 경우가 아닌 것은?","c":"A","mc":{"s":"다음 중 행정행위의 무효로 볼 수 있는 경우가 아닌 것은?","d":"","o":["음주운전을 단속한 경찰관 명의로 행한 운전면허정지처분의 효력","임용권자의 과실에 의한 임용결격자에 대한 경찰공무원 임용 행위의 효력","행정처분의 처분 방식에 관한 ｢행정절차법｣ 제24조 제1항을 위반한 처분의 효력","임면권자가 아닌 국가정보원장이 5급 이상의 국가정보원직원에 대하여 한 의원면직처분의 효력"],"a":4}},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_2-19-1","t":"행정청은 처분에 재량이 없는 경우에는 법률에 근거가 있더라도 부관을 붙일 수 없다.","ox":"X","m":"①","c":"A","tp":"행정행위의 부관"},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_2-19-2","t":"기한은 법률행위 효력의 발생 또는 소멸을 장래의 불확실한 사실의 성부에 의존하게 하는 법률행위의 부관이다.","ox":"X","m":"②","c":"A","tp":"행정행위의 부관"},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_2-19-3","t":"장래의 사실이더라도 그것이 장래 반드시 실현되는 사실이면 실현 되는 시기가 비록 확정되지 않더라도 이는 조건으로 보아야 한다.","ox":"X","m":"③","c":"A","tp":"행정행위의 부관"},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_2-19-4","t":"행정청이 종교단체에 대하여 기본재산전환인가를 함에 있어 인가조건을 부가하고 그 불이행시 인가를 취소할 수 있도록 한 경우, 그 인가조건의 의미를 철회권의 유보로 본다.","ox":"O","m":"④","c":"A","tp":"행정행위의 부관"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_2-22-1","t":"질서위반행위의 성립과 과태료 처분은 행위 시의 법률에 따른다.","ox":"O","m":"①","c":"A","tp":"질서위반행위규제법"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_2-22-2","t":"심신장애로 인하여 행위의 옳고 그름을 판단할 능력이 없거나 그 판단에 따른 행위를 할 능력이 없는 자의 질서위반행위는 과태료를 감경한다.","ox":"X","m":"②","c":"A","tp":"질서위반행위규제법"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_2-22-3","t":"이 법은 대한민국 영역 밖에서 질서위반행위를 한 대한민국의 국민에게 적용한다.","ox":"O","m":"③","c":"A","tp":"질서위반행위규제법"},{"y":2024,"e":"경찰 공채","qn":22,"i":"PO2024_2-22-4","t":"법률에 따르지 아니하고는 어떤 행위도 질서위반행위로 과태료를 부과하지 아니한다.","ox":"O","m":"④","c":"A","tp":"질서위반행위규제법"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_2-27-1","t":"“경찰장비”란 무기, 경찰장구, 경찰착용기록장치, 최루제와 그 발사 장치, 살수차, 감식기구, 해안 감시기구, 통신기기, 차량·선박·항공기 등 경찰이 직무를 수행할 때 필요한 장치와 기구를 말한다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 상 경찰장비와 장구"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_2-27-2","t":"“경찰착용기록장치”란 경찰관이 신체에 착용 또는 휴대하여 직무 수행 과정을 근거리에서 영상·음성으로 기록할 수 있는 기록장치 또는 그 밖에 이와 유사한 기능을 갖춘 기계장치를 말한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 상 경찰장비와 장구"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_2-27-3","t":"경찰청장, 시·도경찰청장 및 경찰서장은 경찰착용기록장치로 기록한 영상·음성을 저장하고 데이터베이스로 관리하는 영상 음성기록정보 관리체계를 구축·운영하여야 한다.","ox":"X","m":"③","c":"A","tp":"경찰관 직무집행법 상 경찰장비와 장구"},{"y":2024,"e":"경찰 공채","qn":27,"i":"PO2024_2-27-4","t":"경찰관은 경찰장비를 함부로 개조하거나 경찰장비에 임의의 장비를 부착하여 일반적인 사용법과 달리 사용함으로써 다른 사람의 생명·신체에 위해를 끼쳐서는 아니 된다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법 상 경찰장비와 장구"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_1-13-1","t":"행정작용은 법률에 위배되어서는 아니 되며, 국민의 권리를 제한하거나 의무를 부과하는 경우와 그 밖에 국민생활에 중요한 영향을 미치는 경우에는 법률에 근거하여야 한다.","ox":"O","m":"①","c":"A","tp":"법치행정의 원칙"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_1-13-2","t":"법률유보의 원칙에서 요구되는 법적 근거는 행정의 조직법적 근거이다.","ox":"X","m":"②","c":"A","tp":"법치행정의 원칙"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_1-13-3","t":"법률유보의 원칙은 ‘법률에 의한’ 규율만을 뜻하는 것이 아니라 ‘법률에 근거한’ 규율을 요청하는 것이다.","ox":"O","m":"③","c":"A","tp":"법치행정의 원칙"},{"y":2025,"e":"경찰 공채","qn":13,"i":"PO2025_1-13-4","t":"경찰행정은 법에 따라 행하여져야 하며, 경찰행정권에 의하여 국민의 권익이 침해된 경우에는 이에 대한 구제제도가 보장되어야 한다.","ox":"O","m":"④","c":"A","tp":"법치행정의 원칙"},{"y":2025,"e":"경찰 공채","qn":14,"i":"PO2025_1-14-1","t":"국무총리 또는 행정각부의 장은 소관사무에 관하여 법률이나 대통령령의 위임 또는 직권으로 총리령 또는 부령을 발할 수 있다.","ox":"O","m":"①","c":"A","tp":"행정입법"},{"y":2025,"e":"경찰 공채","qn":14,"i":"PO2025_1-14-2","t":"「도로교통법시행규칙」 제53조 제1항이 정한 [별표 16]의 운전 면허행정처분기준은 부령의 형식으로 되어 있으나, 행정청 내부의 사무처리준칙을 규정한 것에 지나지 아니하므로 대외적으로 국민이나 법원을 기속하는 효력이 없다.","ox":"O","m":"②","c":"A","tp":"행정입법"},{"y":2025,"e":"경찰 공채","qn":14,"i":"PO2025_1-14-3","t":"법규명령의 위임의 근거가 되는 법률에 대하여 위헌결정이 선고 되더라도 그 위임규정에 근거하여 제정된 법규명령은 원칙적으로 효력을 유지한다.","ox":"X","m":"③","c":"A","tp":"행정입법"},{"y":2025,"e":"경찰 공채","qn":14,"i":"PO2025_1-14-4","t":"국민의 권리 제한 또는 의무 부과와 직접 관련되는 대통령령, 총리령 및 부령은 긴급히 시행하여야 할 특별한 사유가 있는 경우를 제외하고는 공포일부터 적어도 30일이 경과한 날부터 시행되도록 하여야 한다.","ox":"O","m":"④","c":"A","tp":"행정입법"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_1-17-1","t":"경찰착용기록장치로 기록한 영상음성기록의 보관기간은 해당 기록을 법제10조의6 제3항에 따라 영상음성기록정보 데이터 베이스에 전송‧ 저장한 날부터 30일(해당 영상음성기록이 수사 중인 범죄와 관련된 경우 등 경찰청장 또는 해양경찰청장이 정하는 사항에 해당하는 경우에는 90일)로 한다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 및 경찰착용기록장치 운영 등"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_1-17-2","t":"경찰청장 및 해양경찰청장은 경찰착용기록장치로 기록한 영상‧ 음성을 저장하고 데이터베이스로 관리하는 영상음성기록정보 관리체계를 구축‧ 운영하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 경찰착용기록장치 운영 등"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_1-17-3","t":"경찰청장 또는 해양경찰청장은 경찰착용기록장치를 사용하는 경찰관을 대상으로 경찰착용기록장치 조작 방법, 사용 지침, 개인정보 보호 등에 관한 내용이 포함된 교육을 실시해야 한다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법 및 경찰착용기록장치 운영 등"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_1-17-4","t":"경찰착용기록장치로 기록을 마친 영상음성기록은 10일 이내로 영상음성기록정보 관리체계를 이용하여 영상음성기록정보 데이터베이스에 전송‧ 저장할 수 있으며, 영상음성기록을 임의로 편집‧ 복사하거나 삭제하여서는 아니 된다.","ox":"X","m":"④","c":"A","tp":"경찰관 직무집행법 및 경찰착용기록장치 운영 등"},{"y":2025,"e":"경찰 공채","qn":18,"i":"PO2025_1-18-1","t":"국가는 경찰관의 적법한 직무집행으로 인하여 손실발생의 원인에 대하여 책임이 없는 자가 생명‧ 신체 또는 재산상의 손실을 입은 경우 또는 손실발생의 원인에 대하여 책임이 있는 자가 자신의 책임에 상응하는 정도를 초과하는 생명‧ 신체 또는 재산상의 손실을 입은 경우에 정당한 보상을 하여야 한다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2025,"e":"경찰 공채","qn":18,"i":"PO2025_1-18-2","t":"경찰청장, 해양경찰청장, 시‧ 도경찰청장 또는 지방해양경찰청장은 손실보상심의위원회의 심의‧ 의결에 따라 보상금을 지급하고, 거짓 또는 부정한 방법으로 보상금을 받은 사람에 대하여는 해당 보상금을 환수하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2025,"e":"경찰 공채","qn":18,"i":"PO2025_1-18-3","t":"손실보상금이 지급된 경우 손실보상심의위원회는 국가경찰위원회 또는 해양경찰위원회에 심사자료와 결과를 반기별로 보고하여야 한다. 이 경우 국가경찰위원회 또는 해양경찰위원회는 손실보상의 적법성 및 적정성 확인을 위하여 필요한 자료의 제출을 요구할 수 있다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2025,"e":"경찰 공채","qn":18,"i":"PO2025_1-18-4","t":"손실보상심의위원회의 위원은 소속 경찰관과 판사‧ 검사 또는 변호사로 5년 이상 근무한 사람, 「고등교육법」 제2조에 따른 학교에서 법학, 행정학 및 경찰학을 가르치는 조교수 이상으로 5년 이상 재직한 사람, 경찰 업무와 손실보상에 관하여 학식과 경험이 풍부한 사람 중에서 위촉하거나 임명한다.","ox":"X","m":"④","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2025,"e":"경찰 공채","qn":19,"i":"PO2025_1-19-1","t":"행정청의 과태료 처분이나 법원의 과태료 재판이 확정된 후 법률이 변경되어 그 행위가 질서위반행위에 해당하지 아니하게 된 때에는 변경된 법률에 특별한 규정이 없는 한 과태료를 감경한다.","ox":"X","m":"①","c":"A","tp":"질서위반행위규제법"},{"y":2025,"e":"경찰 공채","qn":19,"i":"PO2025_1-19-2","t":"자신의 행위가 위법하지 아니한 것으로 오인하고 행한 질서 위반행위는 그 오인에 정당한 이유가 있는 때에 한하여 과태료를 감경한다.","ox":"X","m":"②","c":"A","tp":"질서위반행위규제법"},{"y":2025,"e":"경찰 공채","qn":19,"i":"PO2025_1-19-3","t":"행정청이 질서위반행위에 대하여 과태료를 부과하고자 하는 때에는 미리 당사자에게 대통령령으로 정하는 사항을 통지하고, 30일 이상의 기간을 정하여 의견을 제출할 기회를 주어야 한다.","ox":"X","m":"③","c":"A","tp":"질서위반행위규제법"},{"y":2025,"e":"경찰 공채","qn":19,"i":"PO2025_1-19-4","t":"행정청의 과태료 부과에 불복하는 당사자는 과태료 부과 통지를 받은 날부터 60일 이내에 해당 행정청에 서면으로 이의제기를 할 수 있다.","ox":"O","m":"④","c":"A","tp":"질서위반행위규제법"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_1-20-1","t":"처분은 권한이 있는 기관이 취소 또는 철회하거나 기간의 경과 등으로 소멸되기 전까지는 유효한 것으로 통용된다. 다만, 무효인 처분은 처음부터 그 효력이 발생하지 아니한다.","ox":"O","m":"①","c":"A","tp":"공정력"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_1-20-2","t":"연령미달의 결격자인 피고인이 소외인의 이름으로 운전면허시험에 응시, 합격하여 교부받은 운전면허는 취소되지 않는 한 유효 하므로 피고인의 운전행위는 무면허운전에 해당하지 아니한다.","ox":"O","m":"②","c":"A","tp":"공정력"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_1-20-3","t":"행정처분이 위법임을 이유로 배상을 청구하는 경우에는 미리 그 행정처분의 취소판결이 있어야만 그 행정처분의 위법임을 이유로 피고에게 배상을 청구할 수 있다.","ox":"X","m":"③","c":"A","tp":"공정력"},{"y":2025,"e":"경찰 공채","qn":20,"i":"PO2025_1-20-4","t":"과세처분이 당연무효라고 볼 수 없는 한 과세처분에 취소할 수 있는 위법사유가 있다 하더라도 그 과세처분은 행정행위의 공정력 또는 집행력에 의하여 그것이 적법하게 취소되기 전까지는 유효하다 할 것이므로, 민사소송절차에서 그 과세처분의 효력을 부인할 수 없다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_1-21-1","t":"하자 있는 행정처분이 당연무효가 되기 위하여는 그 하자가 법규의 중요한 부분을 위반한 중대한 것으로서 객관적으로 명백한 것이어야 하며, 하자가 중대하고 명백한 것인지 여부를 판별함에 있어서는 그 법규의 목적, 의미‧ 기능 등을 목적론적으로 고찰함과 동시에 구체적 사안 자체의 특수성에 관하여도 합리적으로 고찰함을 요한다.","ox":"O","m":"①","c":"A"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_1-21-2","t":"경찰공무원에 대한 징계위원회의 심의과정에 감경사유에 해당하는 공적 사항이 제시되지 아니한 경우에는 그 징계양정이 결과적으로 적정한지와 상관없이 이는 관계 법령이 정한 징계 절차를 지키지 아니한 것으로서 당연무효이다.","ox":"X","m":"②","c":"A"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_1-21-3","t":"임용 당시 공무원임용 결격사유가 있었다면 비록 국가의 과실에 의하여 임용결격자임을 밝혀 내지 못하였다고 하더라도 그 임용 행위는 당연무효이다.","ox":"O","m":"③","c":"A"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_1-21-4","t":"적법한 건축물에 대한 철거명령은 그 하자가 중대하고 명백하여 당연무효이고, 그 후행행위인 건축물철거 대집행계고처분 역시 당연무효이다.","ox":"O","m":"④","c":"A"},{"y":2025,"e":"경찰 공채","qn":22,"i":"PO2025_1-22","t":"｢행정기본법｣ 상 행정상 강제에 관한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"｢행정기본법｣ 상 행정상 강제에 관한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["행정상 직접강제란 의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 의무자의 신체나 재산에 실력을 행사하여 그 행정상 의무의 이행이 있었던 것과 같은 상태를 실현하는 것이다.","행정상 강제징수란 의무자가 행정상 의무 중 금전급부의무를 이행하지 아니하는 경우 행정청이 의무자의 재산에 실력을 행사 하여 그 행정상 의무가 실현된 것과 같은 상태를 실현하는 것이다.","행정상 즉시강제란 현재의 급박한 행정상의 장해를 제거하기 위한 경우로서 행정청이 미리 행정상 의무 이행을 명할 시간적 여유가 없는 경우 또는 그 성질상 행정상 의무의 이행을 명하는 것만으로는 행정목적 달성이 곤란한 경우에 행정청이 곧바로 국민의 신체 또는 재산에 실력을 행사하여 행정목적을 달성하는 것이다.","이행강제금의 부과란 의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 적절한 이행기간을 부여하고, 그 기한까지 행정상 의무를 이행하지 아니하면 금전급부의무를 부과하는 것으로서, 행정상 의무를 이행하지 않더라도 반복하여 부과할 수 없다."],"a":4}},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_1-30-1","t":"경찰관은 범인의 체포 또는 도주방지, 타인 또는 경찰관의 생명‧ 신체에 대한 방호, 공무집행에 대한 항거의 억제를 위하여 필요한 때에는 최소한의 범위안에서 가스발사총을 사용할 수 있다. 이 경우 경찰관은 1미터이내의 거리에서 상대방의 얼굴을 향하여 이를 발사하여서는 아니된다.","ox":"O","m":"①","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_1-30-2","t":"경찰관은 전극침 발사장치가 있는 전자충격기를 사용하는 경우 상대방의 신체 및 얼굴을 향하여 전극침을 발사할 수 있다.","ox":"X","m":"②","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_1-30-3","t":"경찰장구에는 수갑‧ 포승‧ 호송용포승‧ 경찰봉‧ 호신용경봉‧ 방패‧ 전자 방패‧ 근접분사기 및 가스분사기가 있다.","ox":"X","m":"③","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2025,"e":"경찰 공채","qn":30,"i":"PO2025_1-30-4","t":"기타장비에는 가스차·살수차·특수진압차·물포·석궁·다목적발사기·전자충격기 및 크레모아가 있다.","ox":"X","m":"④","c":"A","tp":"위해성 경찰장비의 사용기준 등"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_2-15-1","t":"지방자치단체의 장은 법령의 범위에서 그 사무에 관하여 조례를 제정할 수 있다. 다만, 주민의 권리 제한 또는 의무 부과에 관한 사항이나 벌칙을 정하는 때에는 법률의 위임이 있어야 한다.","ox":"X","m":"①","c":"A","tp":"지방자치법 상 자치법규"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_2-15-2","t":"지방자치단체는 조례를 위반한 행위에 대하여 조례로써 1천만원 이하의 벌금을 정할 수 있고, 해당 지방자치단체의 장이 부과‧ 징수한다.","ox":"X","m":"②","c":"A","tp":"지방자치법 상 자치법규"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_2-15-3","t":"조례안이 지방의회에서 의결되면 지방의회의 의장은 의결된 날부터 7일 이내에 그 지방자치단체의 장에게 이송하여야 한다.","ox":"O","m":"③","c":"A","tp":"지방자치법 상 자치법규"},{"y":2025,"e":"경찰 공채","qn":15,"i":"PO2025_2-15-4","t":"법령에서 조례로 정하도록 위임한 사항은 그 법령의 하위 법령에서 그 위임의 내용과 범위를 제한하거나 직접 규정할 수 없다.","ox":"X","m":"④","c":"A","tp":"지방자치법 상 자치법규"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_2-16-1","t":"헌법에 의하여 체결‧ 공포된 조약이나 일반적으로 승인된 국제 법규도 국내법과 같은 효력을 가지므로 경찰행정법의 법원이 된다.","ox":"O","m":"①","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_2-16-2","t":"법규명령은 국민과 행정청을 동시에 구속하는 양면적 구속력을 가짐으로써 재판규범성이 있다.","ox":"O","m":"②","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_2-16-3","t":"대통령령, 총리령 및 부령은 특별한 규정이 없으면 공포한 날부터 15일이 경과함으로써 효력이 발생한다.","ox":"O","m":"③","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2025,"e":"경찰 공채","qn":16,"i":"PO2025_2-16-4","t":"법규명령의 한계로 행정권에 대한 입법권의 일반적‧ 포괄적 위임은 인정될 수 없고, 국회 전속적 법률사항의 위임은 금지 되며 법률에 의하여 위임된 사항을 전부 하위명령으로 재위임 하는 것은 금지된다.","ox":"X","m":"④","c":"A","tp":"경찰행정법의 법원(法源)"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_2-17-1","t":"이 원칙은 법치국가의 원리 및 그 구성 부분으로서의 법적 안정성으로부터 이론적 근거를 도출할 수 있다.","ox":"O","m":"①","c":"A","tp":"행정법상 신뢰보호의 원칙"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_2-17-2","t":"신뢰보호의 원칙을 위반한 행정청의 행위는 위헌·위법의 문제가 발생하는데 위법의 효과는 해당 행정행위를 취소할 수 있으며 그 위법성이 중대‧ 명백한 경우 무효가 된다.","ox":"O","m":"②","c":"A","tp":"행정법상 신뢰보호의 원칙"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_2-17-3","t":"운전면허 취소사유에 해당하는 음주운전을 적발한 경찰관의 소속 경찰서장이 사무착오로 위반자에게 운전면허정지처분을 한 상태에서 위반자의 주소지 관할 시·도경찰청장이 위반자에게 운전면허취소처분을 한 것은 선행처분에 대한 당사자의 신뢰 및 법적 안정성을 저해하는 것으로서 허용될 수 없다.","ox":"X","m":"③","c":"A","tp":"행정법상 신뢰보호의 원칙","t0":"운전면허 취소사유에 해당하는 음주운전을 적발한 경찰관의 소속 경찰서장이 사무착오로 위반자에게 운전면허정지처분을 한 상태에서 위반자의 주소지 관할 지방경찰청장이 위반자에게 운전면허취소처분을 한 것은 선행처분에 대한 당사자의 신뢰 및 법적 안정성을 저해하는 것으로서 허용될 수 없다.","ox0":"X","rv":"주소지 관할 지방경찰청장이 위반자에게→주소지 관할 시·도경찰청장이 위반자에게"},{"y":2025,"e":"경찰 공채","qn":17,"i":"PO2025_2-17-4","t":"헌법재판소의 위헌결정은 신뢰의 대상이 되는 공적인 견해이므로 신뢰보호의 원칙이 적용된다.","ox":"O","m":"④","c":"A","tp":"행정법상 신뢰보호의 원칙"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_2-21-1","t":"경찰청장, 해양경찰청장, 시‧ 도경찰청장, 지방해양경찰청장, 경찰서장 또는 해양경찰서장은 범인 검거와 관련하여 경찰 수사 활동에 협조한 사람 중 보상금 지급 대상자에 해당한다고 보상금 심사위원회가 인정하는 사람에게 보상금을 지급할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 범인검거 등 공로자 보상"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_2-21-2","t":"경찰청장, 해양경찰청장, 시‧ 도경찰청장, 지방해양경찰청장, 경찰서장 또는 해양경찰서장은 보상금 지급사유가 발생한 경우에는 직권으로 또는 보상금을 지급받으려는 사람의 신청에 따라 소속 보상금심사위원회의 심사‧ 의결을 거쳐 보상금을 지급한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 범인검거 등 공로자 보상"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_2-21-3","t":"보상금심사위원회 위원의 과반수는 경찰관이 아닌 사람으로 해야 한다.","ox":"X","m":"③","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 범인검거 등 공로자 보상"},{"y":2025,"e":"경찰 공채","qn":21,"i":"PO2025_2-21-4","t":"경찰청장, 해양경찰청장, 시‧ 도경찰청장, 지방해양경찰청장, 경찰서장 또는 해양경찰서장은 보상금심사위원회의 심사‧ 의결에 따라 보상금을 지급하고, 거짓 또는 부정한 방법으로 보상금을 받은 사람에 대하여는 해당 보상금을 환수한다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 범인검거 등 공로자 보상"},{"y":2025,"e":"경찰 공채","qn":24,"i":"PO2025_2-24","t":"｢경찰관 직무집행법｣ 제11조의5에 따른 ‘직무 수행으로 인한 형의 감면’의 대상이 되는 범죄에 해당하는 것은 모두 몇 개인가?","c":"A","mc":{"s":"｢경찰관 직무집행법｣ 제11조의5에 따른 ‘직무 수행으로 인한 형의 감면’의 대상이 되는 범죄에 해당하는 것은 모두 몇 개인가?","d":"㉠ ｢형법｣ 제2편 제24장 살인의 죄 ㉡ ｢형법｣ 제2편 제32장 강간과 추행의 죄 중 강제추행에 관한 범죄 ㉢ ｢아동학대범죄의 처벌 등에 관한 특례법｣ 에 따른 아동학대범죄 ㉣ ｢가정폭력범죄의 처벌 등에 관한 특례법｣ 에 따른 가정폭력범죄","o":["1개","2개","3개","4개"],"a":3}},{"y":2026,"e":"경찰 공채","qn":14,"i":"PO2026_1-14-1","t":"행정의 자기구속원칙이란 행정청은 동일한 사안에 대하여 제3자에게 한 것과 동일한 결정을 상대방에게도 하도록 구속을 받는다는 원칙을 말한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"경찰 공채","qn":14,"i":"PO2026_1-14-2","t":"행정의 자기구속원칙은 일반적으로 재량행위에 적용된다.","ox":"O","m":"②","c":"A"},{"y":2026,"e":"경찰 공채","qn":14,"i":"PO2026_1-14-3","t":"평등의 원칙은 본질적으로 같은 것을 자의적으로 다르게 취급함을 금지하는 것이고, 위법한 행정처분이 수차례에 걸쳐 반복적으로 행하여졌다 하더라도 그러한 처분이 위법한 것인 때에는 행정청에 대하여 자기구속력을 갖게 된다고 할 수 없다.","ox":"O","m":"③","c":"A","tp":"행정의 자기구속원칙"},{"y":2026,"e":"경찰 공채","qn":14,"i":"PO2026_1-14-4","t":"행정의 자기구속원칙은 「행정기본법」 제8조에 명문의 규정이 있다.","ox":"X","m":"④","c":"A"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_1-15-1","t":"공정한 업무처리에 대한 사의로 두고 간 돈 30만 원이 든 봉투를 소지함으로써 피동적으로 금품을 수수하였다가 돌려 준 20여년 근속의 경찰공무원에 대한 해임처분이 사회통념상 현저하게 타당성을 잃어 재량권의 남용에 해당한다.","ox":"O","m":"①","c":"A","tp":"기속행위와 재량행위"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_1-15-2","t":"재량의 일탈‧ 남용뿐만 아니라 단순히 재량권 행사에서 합리성을 결하는 등 재량을 그르친 경우에도 행정심판의 대상이 된다.","ox":"O","m":"②","c":"A","tp":"기속행위와 재량행위"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_1-15-3","t":"재량권을 선택재량과 결정재량으로 나눌 경우, 경찰공무원의 비위에 대해 징계처분을 하는 결정과 그 공무원의 건강 등 제반 사정을 고려하여 징계처분을 하지 않는 결정 사이에서 선택권을 갖는 것을 선택재량이라 한다.","ox":"X","m":"③","c":"A","tp":"기속행위와 재량행위"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_1-15-4","t":"기속행위와 재량행위의 구분은 당해 행위의 근거가 된 법규의 체제‧ 형식과 그 문언, 당해 행위가 속하는 행정 분야의 주된 목적과 특성, 당해 행위 자체의 개별적 성질과 유형 등을 모두 고려하여 판단해야 한다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"경찰 공채","qn":18,"i":"PO2026_1-18-1","t":"부령의 위임을 받아 중앙행정기관(「정부조직법」 및 그 밖의 법률에 따라 설치된 중앙행정기관을 말한다)의 장이 정한 예규는 「행정기본법」 상의 ‘법령등’에 해당된다.","ox":"O","m":"①","c":"A","tp":"행정입법"},{"y":2026,"e":"경찰 공채","qn":18,"i":"PO2026_1-18-2","t":"집행명령은 상위법령의 명시적인 수권이 없는 경우에도 발할 수 있으나, 새로운 입법사항에 관하여는 규율할 수 없다.","ox":"O","m":"②","c":"A","tp":"행정입법"},{"y":2026,"e":"경찰 공채","qn":18,"i":"PO2026_1-18-3","t":"부령은 행정각부의 장관이 제정하는 것이므로, 법제처 심사와 국무회의 심의를 모두 거쳐야 한다.","ox":"X","m":"③","c":"A","tp":"행정입법"},{"y":2026,"e":"경찰 공채","qn":18,"i":"PO2026_1-18-4","t":"헌법이 법률로 정하도록 규정한 국회 입법전속사항은 원칙적으로 직접 법규명령으로 정할 수 없다.","ox":"O","m":"④","c":"A","tp":"행정입법"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_1-19-1","t":"「경찰관 직무집행법」 제1조 제2항, 「행정기본법」 제10조 등에 규정되어 있다.","ox":"O","m":"①","c":"A","tp":"경찰행정상 비례의 원칙"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_1-19-2","t":"경찰행정의 수단은 행정목적을 달성하기에 적합하여야 한다.","ox":"O","m":"②","c":"A","tp":"경찰행정상 비례의 원칙"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_1-19-3","t":"최소침해의 원칙은 협의의 비례원칙이라고도 한다.","ox":"X","m":"③","c":"A","tp":"경찰행정상 비례의 원칙"},{"y":2026,"e":"경찰 공채","qn":19,"i":"PO2026_1-19-4","t":"경찰행정작용으로 인한 국민의 이익 침해가 그 행정작용이 의도하는 공익보다 크지 아니하여야 한다.","ox":"O","m":"④","c":"A","tp":"경찰행정상 비례의 원칙"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_1-22-1","t":"경찰하명은 경찰행정청이 경찰상의 위해방지를 위하여 개인에게 특정한 작위‧ 부작위‧ 수인‧ 급부의 의무를 부과하는 경찰처분을 말한다.","ox":"O","m":"①","c":"A"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_1-22-2","t":"부작위하명은 소극적으로 어떤 행위를 하지 아니할 의무를 명하는 것으로 ‘경찰금지’라고도 한다.","ox":"O","m":"②","c":"A","tp":"경찰하명"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_1-22-3","t":"사실행위는 경찰하명의 대상이 될 수 없다.","ox":"X","m":"③","c":"A"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_1-22-4","t":"경찰하명에 위반하여 이루어진 행위는 원칙적으로 그 법적 효력에 아무런 영향을 받지 않는다.","ox":"O","m":"④","c":"A"},{"y":2026,"e":"경찰 공채","qn":25,"i":"PO2026_1-25-1","t":"경찰권 발동의 대상자(이하 ‘대상자’라고 한다)가 경찰관 또는 제3자에 대해 보일 수 있는 행위는 그 위해의 정도에 따라 순응, 소극적 저항, 적극적 저항, 폭력적 공격, 치사적 공격 등 다섯 단계로 구별한다.","ox":"X","m":"①","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2026,"e":"경찰 공채","qn":25,"i":"PO2026_1-25-2","t":"대상자 행위에 따른 경찰관의 대응 수준은 협조적 통제, 접촉 통제, 저위험 물리력, 중위험 물리력, 치명적 물리력 등 다섯 단계로 구별한다.","ox":"X","m":"②","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2026,"e":"경찰 공채","qn":25,"i":"PO2026_1-25-3","t":"대상자가 ‘순응’하는 경우, 손이나 팔을 힘을 주어 잡을 수 있고 대상자의 어깨 등 신체 일부를 힘을 주어 밀거나 잡아끌 수 있다.","ox":"X","m":"③","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2026,"e":"경찰 공채","qn":25,"i":"PO2026_1-25-4","t":"대상자 행위가 ‘폭력적 공격’인 경우, 목을 압박하여 제압하거나 관절을 꺾는 방법, 팔‧ 다리를 이용해 움직이지 못하도록 조르는 방법, 다리를 걸거나 들쳐 매는 등 균형을 무너뜨려 넘어뜨리는 방법, 대상자가 넘어진 상태에서 움직이지 못하게 위에서 눌러 제압하는 방법 등을 사용할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰 물리력 행사의 기준과 방법"},{"y":2026,"e":"경찰 공채","qn":26,"i":"PO2026_1-26-1","t":"경찰관은 범죄행위가 목전에 행하여지려고 하고 있다고 인정될 때에는 이를 예방하기 위하여 관계인에게 필요한 경고를 하고, 그 행위로 인하여 사람의 생명‧ 신체에 위해를 끼치거나 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우에는 그 행위를 제지하여야 한다.","ox":"X","m":"①","c":"A","tp":"경찰관 직무집행법"},{"y":2026,"e":"경찰 공채","qn":26,"i":"PO2026_1-26-2","t":"경찰관은 미아를 인수할 보호자 확인, 유실물을 인수할 권리자 확인, 사고로 인한 사상자 확인, 행정처분을 위한 교통사고 조사에 필요한 사실확인의 직무를 수행하기 위하여 필요하면 관계인에게 출석하여야 하는 사유‧ 일시 및 장소를 명확히 적은 출석 요구서를 보내 경찰관서에 출석할 것을 요구할 수 있다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법"},{"y":2026,"e":"경찰 공채","qn":26,"i":"PO2026_1-26-3","t":"이 법에 규정된 경찰관의 의무를 위반하거나 직권을 남용하여 다른 사람에게 해를 끼친 사람은 1년 이하의 징역이나 금고 또는 300만 원 이하의 벌금에 처한다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법"},{"y":2026,"e":"경찰 공채","qn":26,"i":"PO2026_1-26-4","t":"경찰관은 범인의 체포, 범인의 도주 방지, 자신이나 다른 사람의 생명‧ 신체의 방어 및 보호, 공무집행에 대한 항거의 제지를 위하여 필요하다고 인정되는 상당한 이유가 있을 때에는 그 사태를 합리적으로 판단하여 필요한 한도에서 무기를 사용할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법"},{"y":2026,"e":"경찰 공채","qn":27,"i":"PO2026_1-27","t":"｢경찰관 직무집행법｣ 제11조의5(직무수행으로 인한 형의 감면)에 관한 아래","c":"A","mc":{"s":"｢경찰관 직무집행법｣ 제11조의5(직무수행으로 인한 형의 감면)에 관한 아래","d":"<보기>의 설명 중 옳지 않은 것은 모두 몇 개인가? < 보기 > 형의 감면대상 범죄가 행하여지려고 하거나 행하여지고 있어, ㉠타인의 생명‧ 신체 및 재산에 대한 위해 발생의 우려가 명백하고 긴급한 상황에서 ㉡경찰관이 그 위해를 예방하거나 진압하기 위한 행위 또는 범인의 검거 과정에서 타인을 향한 직접적인 유형력 행사에 대응하는 행위를 하여 그로 인하여 경찰관에게 피해가 발생한 경우, ㉢그 경찰관의 직무수행이 불가피한 것이고 필요한 최소한의 범위에서 이루어졌으며 ㉣해당 경찰관에게 고의 또는 중대한 과실이 없는 때에는 ㉤그 정상을 참작하여 형을 감경 하거나 면제하여야 한다.","o":["1개","2개","3개","4개 - 15 -"],"a":3}},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_2-15-1","t":"헌법에 의하여 체결‧ 공포된 조약은 국내법과 같은 효력을 가진다.","ox":"O","m":"①","c":"A","tp":"경찰행정법의 법원"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_2-15-2","t":"법령의 위임이 없음에도 법령에 규정된 처분 요건에 해당하는 사항을 부령에서 변경하여 규정한 경우에는 그 부령의 규정은 행정청 내부의 사무처리 기준 등을 정한 것으로서 행정조직 내에서 적용되는 행정명령의 성격을 지닐 뿐 국민에 대한 대외적 구속력은 없다.","ox":"O","m":"②","c":"A","tp":"경찰행정법의 법원"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_2-15-3","t":"지방자치단체가 조례를 제정할 수 있는 사항은 지방자치단체의 고유사무인 자치사무와 개별 법령에 따라 지방자치단체에 위임된 기관위임사무에 한정된다.","ox":"X","m":"③","c":"A","tp":"경찰행정법의 법원"},{"y":2026,"e":"경찰 공채","qn":15,"i":"PO2026_2-15-4","t":"관습법이란 사회의 거듭된 관행으로 생성한 사회생활규범이 사회의 법적 확신과 인식에 의하여 법적 규범으로 승인‧ 강행 되기에 이른 것을 말한다.","ox":"O","m":"④","c":"A","tp":"경찰행정법의 법원"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_2-16-1","t":"행위자의 고의‧ 과실이 없는 경우에는 경찰책임이 인정되지 않는다.","ox":"X","m":"①","c":"A","tp":"경찰책임의 원칙"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_2-16-2","t":"형사미성년자의 경우에는 본인이 아닌 부모 등 보호의무자가 행위책임을 부담한다.","ox":"X","m":"②","c":"A","tp":"경찰책임의 원칙"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_2-16-3","t":"정당한 권리자의 의사에 반하여 사실상의 지배권을 행사하는 자도 상태책임을 부담한다.","ox":"O","m":"③","c":"A","tp":"경찰책임의 원칙"},{"y":2026,"e":"경찰 공채","qn":16,"i":"PO2026_2-16-4","t":"경찰긴급권은 법령상 근거가 없는 경우 예외적으로 인정되는 권한이다.","ox":"X","m":"④","c":"A","tp":"경찰책임의 원칙"},{"y":2026,"e":"경찰 공채","qn":20,"i":"PO2026_2-20-1","t":"집회장소 사용 승낙을 하지 않은 대학교 측의 집회 저지 협조 요청에 따라 경찰관들이 대학교 출입문에서 신고된 대학교 에서의 집회에 참가하려는 자의 출입을 저지한 것은 「경찰관 직무집행법」 제6조의 주거침입행위에 대한 사전 제지조치로 볼 수 없다.","ox":"X","m":"①","c":"A","tp":"경찰관 직무집행법 상 범죄의 예방과 제지"},{"y":2026,"e":"경찰 공채","qn":20,"i":"PO2026_2-20-2","t":"경찰관의 경고나 제지는 범죄의 예방을 위하여 범죄행위에 관한 실행의 착수 전에 행하여질 수 있을 뿐만 아니라, 이후 범죄 행위가 계속되는 중에 그 진압을 위하여도 행하여질 수 있다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 상 범죄의 예방과 제지"},{"y":2026,"e":"경찰 공채","qn":20,"i":"PO2026_2-20-3","t":"경찰관의 제지 조치가 적법한지 여부는 제지 조치 당시의 구체적 상황을 기초로 판단하여야 하고 사후적으로 순수한 객관적 기준에서 판단할 것은 아니다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법 상 범죄의 예방과 제지"},{"y":2026,"e":"경찰 공채","qn":20,"i":"PO2026_2-20-4","t":"경찰관의 제지는 범죄의 예방을 위한 행정상 즉시강제로서 경찰이 직접 실력을 행사하여 경찰상 필요한 상태를 실현하는 권력적 사실행위에 해당한다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법 상 범죄의 예방과 제지"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_2-21-1","t":"보상금 지급 청구서를 받은 손실보상 결정권자는 특별한 사유가 없으면 보상금 지급 청구서를 받은 날부터 60일 이내에 손실보상 심의위원회의 심의‧ 의결에 따라 보상 여부 및 보상금액을 결정 해야 한다. 다만, 부득이한 사유로 60일 이내에 결정할 수 없을 때에는 그 기간이 끝나는 날의 다음 날부터 20일의 범위에서 결정기간을 한 차례만 연장할 수 있다.","ox":"O","m":"①","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_2-21-2","t":"손실보상 결정권자는 청구인이 같은 청구 원인으로 보상신청을 하여 보상금 지급 여부에 대하여 결정을 받은 경우에는 그 청구를 각하하는 결정을 해야 한다. 다만, 기각 결정을 받은 청구인이 손실을 증명할 수 있는 새로운 증거가 발견되었음을 소명하는 경우는 제외한다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_2-21-3","t":"손실보상 결정권자는 보상 여부 및 보상금액 결정 또는 각하 결정에 대해서는 지체 없이 청구인에게 통지해야 한다.","ox":"X","m":"③","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2026,"e":"경찰 공채","qn":21,"i":"PO2026_2-21-4","t":"청구인은 위원에게 공정한 심의‧ 의결을 기대하기 어려운 사정이 있는 경우에는 손실보상심의위원회에 기피 신청을 할 수 있고, 위원회는 의결로 이를 결정한다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법 및 동법 시행령상 손실보상"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_2-22-1","t":"행정청은 당사자의 신뢰를 보호할 가치가 있는 등 정당한 사유가 있는 경우에는 위법 또는 부당한 처분의 전부나 일부를 장래를 향하여 철회할 수 있다.","ox":"X","m":"①","c":"A","tp":"행정기본법 상 처분"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_2-22-2","t":"처분은 무효인 경우를 제외하고는 권한이 있는 기관이 취소 또는 철회하거나 기간의 경과 등으로 소멸되기 전까지는 유효한 것으로 통용된다.","ox":"O","m":"②","c":"A","tp":"행정기본법 상 처분"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_2-22-3","t":"당사자의 신청에 따른 처분은 법령등에 특별한 규정이 있거나 처분 당시의 법령등을 적용하기 곤란한 특별한 사정이 있는 경우를 제외하고는 처분 당시의 법령등에 따른다.","ox":"O","m":"③","c":"A","tp":"행정기본법 상 처분"},{"y":2026,"e":"경찰 공채","qn":22,"i":"PO2026_2-22-4","t":"행정청은 당사자에게 권리나 이익을 부여하는 처분을 취소하려는 경우에는 취소로 인하여 당사자가 입게 될 불이익을 취소로 달성되는 공익과 비교‧ 형량하여야 하지만, 당사자가 처분의 위법성을 중대한 과실로 알지 못한 경우에는 그러하지 아니하다.","ox":"O","m":"④","c":"A","tp":"행정기본법 상 처분"},{"y":2026,"e":"경찰 공채","qn":25,"i":"PO2026_2-25","t":"경찰행정의 실효성 확보수단에 관한 설명으로 옳은 것은 모두 몇 개인가?","c":"A","mc":{"s":"경찰행정의 실효성 확보수단에 관한 설명으로 옳은 것은 모두 몇 개인가?","d":"(다툼이 있는 경우 판례에 의함) ㉠ 행정청이 행정대집행의 방법으로 건물철거의무의 이행을 실현할 수 있는 경우에는 건물철거 대집행 과정에서 부수적으로 건물의 점유자들에 대한 퇴거 조치를 할 수 있고, 필요한 경우에는 ｢경찰관 직무집행법｣ 에 근거한 위험발생 방지조치 또는 ｢형법｣ 상 공무집행방해죄의 범행방지 내지 현행범 체포의 차원에서 경찰의 도움을 받을 수도 있다. ㉡ ｢행정기본법｣ 상 직접강제란 의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 의무자의 신체나 재산에 실력을 행사하여 그 행정상 의무의 이행이 있었던 것과 같은 상태를 실현하는 것이다. ㉢ ｢행정기본법｣ 상 즉시강제는 다른 수단으로는 행정목적을 달성할 수 없는 경우에만 허용되며, 이 경우에도 최소한으로만 실시하여야 한다. ㉣ ｢경찰관 직무집행법｣ 상 경찰관은 불법집회‧ 시위로 인한 경찰관 자신이나 다른 사람의 생명‧ 신체와 재산 및 공공시설 안전에 대한 현저한 위해의 발생 억제의 직무를 수행하기 위하여 부득이한 경우, 현장책임자가 판단하여 필요한 최소한의 범위 에서 분사기(｢총포‧ 도검‧ 화약류 등의 안전관리에 관한 법률｣ 에 따른 분사기를 말하며, 그에 사용하는 최루 등의 작용제를 포함한다)를 사용할 수 있다. ㉤ ｢행정기본법｣ 상 행정대집행, 직접강제, 강제징수, 즉시강제는 의무자의 행정상 의무 불이행을 전제로 한다는 점에서 공통점을 갖는다.","o":["2개","3개","4개","5개"],"a":3}},{"y":2026,"e":"경찰 공채","qn":26,"i":"PO2026_2-26","t":"｢행정조사기본법｣ 상 행정조사에 관한 설명으로 가장 적절 하지 않은 것은?","c":"A","mc":{"s":"｢행정조사기본법｣ 상 행정조사에 관한 설명으로 가장 적절 하지 않은 것은?","d":"","o":["행정조사는 법령등의 위반에 대한 처벌보다는 법령등을 준수 하도록 유도하는 데 중점을 두어야 한다.","행정기관은 행정조사를 통하여 알게 된 정보를 다른 법률에 따라 내부에서 이용하거나 다른 기관에 제공하는 경우를 제외하고는 원래의 조사목적 이외의 용도로 이용하거나 타인에게 제공하여서는 아니 된다.","행정기관은 법령등에서 행정조사를 규정하고 있는 경우에 한하여 행정조사를 실시할 수 있으나, 조사대상자의 자발적인 협조를 얻어 실시하는 행정조사의 경우에는 그러하지 아니하다.","조사대상자는 조사원에게 공정한 행정조사를 기대하기 어려운 사정이 있다고 판단되는 경우에는 행정기관의 장에게 서면이나 구두로 당해 조사원의 교체를 신청할 수 있다."],"a":4}}],"14":[{"y":2022,"e":"경찰 공채","qn":22,"i":"PO2022_2-22","t":"경찰관 직무집행법 및 경찰관의 정보수집 및 처리 등에 관한 규정(대통령령) 상 경찰관이 정보활동을 위해 필요한 경우에 한정하여 일시적으로만 출입이 가능한 곳은 모두 몇 개인가?","c":"A","mc":{"s":"경찰관 직무집행법 및 경찰관의 정보수집 및 처리 등에 관한 규정(대통령령) 상 경찰관이 정보활동을 위해 필요한 경우에 한정하여 일시적으로만 출입이 가능한 곳은 모두 몇 개인가?","d":"㉠ 언론기관 ㉡ 종교시설 ㉢ 민간기업 ㉣ 정당의 사무소 ㉤ 시민사회 단체","o":["2개","3개","4개","5개 - 15 -"],"a":4}},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_1-19-1","t":"경찰관은 범죄·재난·공공갈등 등 공공안녕과 공공질서에 대한 위험의 예방과 대응을 위한 정보의 수집·작성·배포와 이에 수반되는 사실의 확인을 할 수 있다.","ox":"X","m":"①","c":"A","tp":"경찰관 직무집행법 및 경찰관의 정보수집 및 처리 등"},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_1-19-2","t":"경찰관은 정치에 관여하기 위해 정보를 수집·작성·배포하는 행위를 해서는 안 된다.","ox":"O","m":"②","c":"A","tp":"경찰관 직무집행법 및 경찰관의 정보수집 및 처리 등"},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_1-19-3","t":"경찰관은 민간기업에 상시적으로 출입해서는 안 되며, 정보활동을 위해 필요한 경우에 한정하여 일시적으로만 출입해야 한다.","ox":"O","m":"③","c":"A","tp":"경찰관 직무집행법 및 경찰관의 정보수집 및 처리 등"},{"y":2024,"e":"경찰 공채","qn":19,"i":"PO2024_1-19-4","t":"경찰관은 수집·작성한 정보가 그 목적이 달성되어 불필요하게 되었을 때에는 다른 법령에 따라 보존해야 하는 경우를 제외 하고는 지체 없이 그 정보를 폐기해야 한다.","ox":"O","m":"④","c":"A","tp":"경찰관 직무집행법 및 경찰관의 정보수집 및 처리 등"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_1-39-1","t":"필요성의 원칙은 알 필요가 있는 대상자에게 정보를 알려야 하고, 알 필요가 없는 대상자에게는 알려서는 안 된다는 것을 의미한다.","ox":"O","m":"①","c":"A","tp":"정보배포 원칙"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_1-39-2","t":"보안성의 원칙에 따라, 정보가 누설됨으로써 초래될 결과를 예방하기 위한 보안대책을 강구해야 한다.","ox":"O","m":"②","c":"A","tp":"정보배포 원칙"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_1-39-3","t":"적시성의 원칙에 따라, 먼저 생산된 정보를 우선적으로 배포한다.","ox":"X","m":"③","c":"A","tp":"정보배포 원칙"},{"y":2024,"e":"경찰 공채","qn":39,"i":"PO2024_1-39-4","t":"계속성의 원칙은 정보가 필요한 기관에 배포되었다면 그 주제와 관련된 새로운 정보는 그 기관에 계속 배포해 주어야 한다는 것을 의미한다.","ox":"O","m":"④","c":"A","tp":"정보배포 원칙"},{"y":2025,"e":"경찰 공채","qn":22,"i":"PO2025_2-22-1","t":"공공안녕에 대한 위험의 예방과 대응을 위한 정보의 수집‧ 작성‧ 배포와 이에 수반되는 사실의 확인을 위해 경찰관이 수행하는 활동은 국가의 존립과 기능을 보호하는 것을 목적으로 해야 하며, 필요 최소한의 범위에 그쳐야 한다.","ox":"X","m":"①","c":"A","tp":"경찰관의 정보수집 및 처리 등"},{"y":2025,"e":"경찰 공채","qn":22,"i":"PO2025_2-22-2","t":"경찰관이 「경찰관 직무집행법」 제8조의2 제1항에 따라 수집‧ 작성‧ 배포할 수 있는 정보의 구체적인 범위에는 도로 교통의 위해 방지‧ 제거 및 원활한 소통 확보를 위한 정보가 포함된다.","ox":"O","m":"②","c":"A","tp":"경찰관의 정보수집 및 처리 등"},{"y":2025,"e":"경찰 공채","qn":22,"i":"PO2025_2-22-3","t":"경찰관은 정보를 제공하거나 사실을 확인해 준 자가 신분이나 처우와 관련하여 불이익을 받지 않도록 비밀유지 등 필요한 조치를 해야 한다.","ox":"O","m":"③","c":"A","tp":"경찰관의 정보수집 및 처리 등"},{"y":2025,"e":"경찰 공채","qn":22,"i":"PO2025_2-22-4","t":"경찰관은 공공안녕에 대한 위험의 예방과 대응을 위해 필요한 경우에는 수집‧ 작성한 정보를 관계 기관 등에 통보할 수 있다.","ox":"O","m":"④","c":"A","tp":"경찰관의 정보수집 및 처리 등"},{"y":2026,"e":"경찰 공채","qn":40,"i":"PO2026_1-40","t":"정보요구의 방법에 관한 설명으로","c":"A","mc":{"s":"정보요구의 방법에 관한 설명으로","d":"<보기 1>과 <보기 2>의 내용이 가장 적절하게 연결된 것은? < 보기 1 > (가) 임시적‧ 돌발적이며, 단기적 문제해결을 위한 첩보요구 (나) 사전에 첩보수집계획서의 작성이 필요하며, 계속적‧ 반복적으로 수집할 사항 (다) 경찰청에서 정보활동을 계획할 때 가장 중요한 지침 < 보기 2 > ㉠ EEI ㉡ OIR ㉢ PNIO ㉣ SRI (가) (나) (다)","o":["㉢ ㉠ ㉡","㉢ ㉣ ㉠","㉣ ㉠ ㉢","㉣ ㉢ ㉡"],"a":3}}],"15":[{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_1-40-1","t":"“보안관찰처분대상자”라 함은 보안관찰해당범죄 또는 이와 경합된 범죄로 금고 이상의 형의 선고를 받고 그 형기 합계가 3년 이상인 자로서 형의 전부 또는 일부의 집행을 받은 사실이 있는 자를 말한다.","ox":"O","m":"①","c":"A","tp":"보안관찰법"},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_1-40-2","t":"보안관찰처분청구는 검사가 행한다.","ox":"O","m":"②","c":"A","tp":"보안관찰법"},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_1-40-3","t":"보안관찰처분을 받은 자는 이 법이 정하는 바에 따라 소정의 사항을 주거지 관할경찰서장에게 신고하고, 재범방지에 필요한 범위 안에서 그 지시에 따라 보안관찰을 받아야 한다.","ox":"O","m":"③","c":"A","tp":"보안관찰법"},{"y":2023,"e":"경찰 공채","qn":40,"i":"PO2023_1-40-4","t":"보안관찰처분의 기간은 3년으로 한다.","ox":"X","m":"④","c":"A","tp":"보안관찰법"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_2-39-1","t":"“북한이탈주민”이란 군사분계선 이북지역에 주소, 직계가족, 배우자, 직장 등을 두고 있는 사람으로서 북한을 벗어난 후 외국 국적을 취득하지 아니한 사람을 말한다.","ox":"O","m":"①","c":"A","tp":"북한이탈주민의 보호 및 정착지원"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_2-39-2","t":"국가안전보장에 현저한 영향을 줄 우려가 있는 보호신청자는 통일부장관이 그 보호 여부를 결정하고, 그 결과를 지체 없이 국가정보원장과 보호신청자에게 통보하거나 알려야 한다.","ox":"X","m":"②","c":"A","tp":"북한이탈주민의 보호 및 정착지원"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_2-39-3","t":"통일부장관은 보호대상자가 거주지로 전입한 후 그의 신변안전을 위하여 국방부장관이나 경찰청장에게 협조를 요청할 수 있으며, 협조요청을 받은 국방부장관이나 경찰청장은 이에 협조한다.","ox":"O","m":"③","c":"A","tp":"북한이탈주민의 보호 및 정착지원"},{"y":2025,"e":"경찰 공채","qn":39,"i":"PO2025_2-39-4","t":"보호신청자가 항공기 납치, 마약거래, 테러, 집단살해 등 국제 형사범죄자에 해당하면 보호대상자로 결정하지 아니할 수 있다.","ox":"O","m":"④","c":"A","tp":"북한이탈주민의 보호 및 정착지원"}]};
window.PAIRS=[{"n":2,"s":0.396,"o":{"i":"PO2025_1-39-3","t":"안종삼: 예비검속 된 보도연맹원들에 대한 총살명령에 대해 ‘내가 죽더라도 방면하겠으니 국가를 위해 충성해 달라’고 말한 후 전원 방면함","y":2025,"e":"경찰 공채"},"x":{"i":"PO2022_2-11-2","t":"이준규 서장은 보도연맹원들에 대한 총살명령이 내려오자 480명의 예비검속자 앞에서 “내가 죽더라도 방면하겠으니 국가를 위해 충성해 달라”라는 연설 후 전원 방면하였다.","y":2022,"e":"경찰 공채"}},{"n":1,"s":0.52,"o":{"i":"PO2026_2-04-2","t":"「법원조직법」 상 재판장은 법정에서의 질서유지를 위하여 필요 하다고 인정할 때에는 개정 전후에 상관없이 관할 경찰서장에게 경찰공무원의 파견을 요구할 수 있다. 파견된 경찰공무원은 법정 내외의 질서유지에 관하여 재판장의 지휘를 받는다.","y":2026,"e":"경찰 공채"},"x":{"i":"PO2024_2-06-2","t":"재판장은 법정에서의 질서유지를 위하여 필요하다고 인정할 때에는 개정 전에 한하여 관할 경찰서장에게 경찰공무원의 파견을 요구할 수 있다.","y":2024,"e":"경찰 공채"}},{"n":1,"s":0.476,"o":{"i":"PO2022_1-02-2","t":"법원조직법상 재판장은 법정에서의 질서유지를 위하여 필요 하다고 인정할 때에는 개정 전후에 상관없이 관할 경찰서장에게 경찰공무원의 파견을 요구할 수 있으며, 이에 따라 파견된 경찰 공무원은 법정 내외의 질서유지에 관하여 재판장의 지휘를 받는다.","y":2022,"e":"경찰 공채"},"x":{"i":"PO2025_1-04-4","t":"재판장은 법정에서의 질서유지를 위하여 필요하다고 인정할 때에는 개정 전후에 상관없이 시‧ 도경찰청장에게 경찰공무원의 파견을 요구할 수 있다.","y":2025,"e":"경찰 공채"}},{"n":1,"s":0.33,"o":{"i":"PO2023_1-01-3","t":"크로이쯔베르크(Kreuzberg) 판결에 의하면 경찰관청이 일반수권 규정에 근거하여 법규명령을 발할 수 있는 분야는 소극적 위험방지 분야에 한정된다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2026_1-01-4","t":"블랑코(Blanco) 판결은 경찰관청이 일반수권규정에 근거하여 법규명령을 발할 수 있는 분야가 소극적 위험방지에 한정되도록 확정되는 계기를 마련하였다.","y":2026,"e":"경찰 공채"}},{"n":1,"s":0.304,"o":{"i":"PO2023_1-04-3","t":"자치경찰은 지방세력의 간섭으로 인하여 정실주의에 대한 우려가 있다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2025_1-01-2","t":"국가경찰은 자치경찰과 비교하여 지방세력의 간섭으로 정실에 빠질 우려가 있다.","y":2025,"e":"경찰 공채"}},{"n":3,"s":0.678,"o":{"i":"PO2023_1-33-2","t":"경찰활동 전반에 걸친 민주적 통제를 구현하여 경찰력 오·남용을 예방하고, 경찰행정의 인권지향성을 높여 인권을 존중하는 경찰활동을 정립하기 위해 경찰청장 및 시·도경찰청장의 자문 기구로서 각각 경찰청 인권위원회, 시·도경찰청 인권위원회를 설치하여 운영한다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2022_1-09-2","t":"경찰 활동 전반에 걸친 민주적 통제를 구현하여 경찰력 오 남용을 예방하고, 경찰 행정의 인권지향성을 높여 인권을 존중하는 경찰 활동을 정립하기 위해 시 도경찰청장 및 경찰서의 심의 의결기구로서 각각 시 도경찰청 인권위원회, 경찰서 인권위원회를 설치하여 운영한다.","y":2022,"e":"경찰 공채"}},{"n":3,"s":0.65,"o":{"i":"PO2025_1-32-2","t":"위원회의 당연직 위원은 경찰청은 감사관, 시‧ 도경찰청은 청문감사인권담당관으로 한다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2023_2-08-1","t":"당연직 위원은 경찰청은 청문감사인권담당관, 시·도경찰청은 감사관으로 한다.","y":2023,"e":"경찰 공채"}},{"n":3,"s":0.538,"o":{"i":"PO2024_1-06-1","t":"공직자등은 부정청탁을 받았을 때에는 부정청탁을 한 자에게 부정청탁임을 알리고 이를 거절하는 의사를 명확히 표시하여야 한다. 그럼에도 불구하고 동일한 부정청탁을 다시 받은 경우에는 이를 소속기관장에게 서면(전자문서를 포함한다)으로 신고하여야 한다.","y":2024,"e":"경찰 공채"},"x":{"i":"PO2022_2-06-2","t":"부정청탁 및 금품등 수수의 금지에 관한 법률상 ‘공직자등’이 부정청탁을 받았을 때에는 부정청탁을 한 자에게 부정청탁임을 알리고 이를 거절하는 의사를 명확히 표시하여야 하며, 이러한 조치를 하였음에도 불구하고 동일한 부정청탁을 다시 받은 경우에는 이를 소속기관장에게 구두 또는 서면(전자서면을 포함)으로 신고하여야 한다.","y":2022,"e":"경찰 공채"}},{"n":3,"s":0.48,"o":{"i":"PO2023_1-08-1","t":"공무원은 상급자가 자기 또는 타인의 부당한 이익을 위하여 공정한 직무수행을 현저하게 해치는 지시를 하였을 때에는 그 사유를 상급자에게 소명하고 지시에 따르지 아니하거나 행동강령책임관과 상담할 수 있다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2025_2-08-1","t":"공무원은 상급자가 자기 또는 타인의 부당한 이익을 위하여 공정한 직무수행을 현저하게 해치는 지시를 하였을 때에는 소속 기관의 장과 상담하여야 한다.","y":2025,"e":"경찰 공채"}},{"n":8,"s":0.802,"o":{"i":"PO2022_1-18-2","t":"각 중앙관서의 장은 매년 1월 31일까지 해당 회계연도부터 5회계 연도 이상의 기간 동안의 신규사업 및 기획예산처장관이 정하는 주요 계속사업에 대한 중기사업계획서를 기획예산처장관에게 제출하여야 한다.","y":2022,"e":"경찰 공채"},"x":{"i":"PO2024_1-30-1","t":"경찰청장은 매년 1월 31일까지 해당 회계연도부터 5회계연도 이상의 기간 동안의 신규사업 및 경찰청장이 정하는 주요 계속사업에 대한 중기사업계획서를 기획예산처장관에게 제출 하여야 한다.","y":2024,"e":"경찰 공채"}},{"n":8,"s":0.689,"o":{"i":"PO2022_2-21-2","t":"개인정보의 일부를 삭제하거나 일부 또는 전부를 대체하는 등의 방법으로 추가 정보가 없이는 특정 개인을 알아볼 수 없도록 처리하는 것을 “가명처리”라 한다.","y":2022,"e":"경찰 공채"},"x":{"i":"PO2023_2-25-4","t":"“익명처리”란 개인정보의 전부를 삭제하거나 일부를 대체하는 등의 방법으로 추가 정보가 없이는 특정 개인을 알아볼 수 없도록 처리하는 것을 말한다.","y":2023,"e":"경찰 공채"}},{"n":8,"s":0.655,"o":{"i":"PO2023_1-31-1","t":"각 중앙관서의 장은 예산안편성지침에 따라 그 소관에 속하는 다음 연도의 세입세출예산·계속비·명시이월비 및 국고채무부담행위 요구서를 작성하여 매년 5월 31일까지 기획예산처장관에게 제출하여야 한다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2022_1-18-1","t":"각 중앙관서의 장은 제29조의 규정에 따른 예산안편성지침에 따라 그 소관에 속하는 당해 연도의 세입세출예산 계속비 명시 이월비 및 국고채무부담행위 요구서를 작성하여 매년 3월 31일까지 기획예산처장관에게 제출하여야 한다.","y":2022,"e":"경찰 공채"}},{"n":8,"s":0.561,"o":{"i":"PO2025_1-27-3","t":"앨더퍼(Alderfer)는 매슬로의 욕구계층이론을 수정하여 생존욕구, 관계욕구, 성장욕구로 구분하였다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2025_2-30-4","t":"앨더퍼(Alderfer)는 매슬로우(Maslow)의 욕구단계이론을 수정하여 생존욕구, 존경욕구, 성장욕구로 구분하였다.","y":2025,"e":"경찰 공채"}},{"n":10,"s":0.569,"o":{"i":"PO2023_2-34-2","t":"순찰팀은 범죄예방 순찰, 각종 사건사고에 대한 초동조치 등 현장 치안활동을 담당한다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2026_1-34-1","t":"지역경찰관서의 순찰팀은 범죄예방 순찰, 각종 사건사고에 대한 초동조치 등 현장 치안활동을 담당하며, 팀장은 경위 또는 경사로 보한다.","y":2026,"e":"경찰 공채"}},{"n":10,"s":0.409,"o":{"i":"PO2025_2-34-2","t":"화약류를 폐기하려는 자는 행정안전부령으로 정하는 바에 따라 그 폐기하려는 곳을 관할하는 경찰서장에게 신고하여야 한다. 다만, 제조업자가 제조과정에서 생긴 화약류를 그 제조소 안에서 폐기하는 경우에는 그러하지 아니하다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2025_2-34-1","t":"화약류를 운반하려는 사람은 행정안전부령으로 정하는 바에 따라 도착지를 관할하는 경찰서장에게 신고하여야 한다. 다만, 대통령령으로 정하는 수량 이하의 화약류를 운반하는 경우에는 그러하지 아니하다.","y":2025,"e":"경찰 공채"}},{"n":4,"s":0.419,"o":{"i":"PO2024_1-16-3","t":"시·도지사는 시·도자치경찰위원회의 의결이 적정하지 아니하다고 판단할 때에는 재의를 요구할 수 있다.","y":2024,"e":"경찰 공채"},"x":{"i":"PO2024_1-16-4","t":"경찰청장은 시·도자치경찰위원회의 의결이 적정하지 아니하다고 판단되면 국가경찰위원회와 행정안전부장관을 거쳐 시·도지사에게 재의를 요구하게 할 수 있다.","y":2024,"e":"경찰 공채"}},{"n":4,"s":0.333,"o":{"i":"PO2025_1-15-3","t":"시‧ 도자치경찰위원회 위원장과 위원의 임기는 3년으로 하며, 연임할 수 없다. 다만, 보궐위원의 임기는 전임자 임기의 남은 기간으로 하되, 전임자의 남은 임기가 1년 미만인 경우에는 한 차례만 연임할 수 있다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2023_2-03-3","t":"시·도자치경찰위원회 위원장과 위원의 임기는 3년으로 하되, 위원만 한 차례 연임할 수 있다.","y":2023,"e":"경찰 공채"}},{"n":4,"s":0.317,"o":{"i":"PO2025_1-15-1","t":"시‧ 도자치경찰위원회는 위원장 1명을 포함한 7명의 위원으로 구성하되, 위원장과 1명의 위원은 상임으로 하고, 5명의 위원은 비상임으로 한다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2022_2-03-1","t":"위원장 및 1명의 위원은 상임위원으로 하고 나머지 5명의 위원은 비상임으로 한다.","y":2022,"e":"경찰 공채"}},{"n":12,"s":0.645,"o":{"i":"PO2025_1-36-1","t":"‘외국인테러전투원’이란 테러를 실행‧ 계획‧ 준비하거나 테러에 참가할 목적으로 국적국이 아닌 국가의 테러단체에 가입하거나 가입하기 위하여 이동 또는 이동을 시도하는 내국인‧ 외국인을 말한다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2022_1-24-1","t":"‘테러위험인물’이란 테러를 실행 계획 준비하거나 테러에 참가할 목적으로 국적국이 아닌 국가의 테러단체에 가입하거나 가입 하기 위하여 이동 또는 이동을 시도하는 외국인을 말한다.","y":2022,"e":"경찰 공채"}},{"n":11,"s":0.532,"o":{"i":"PO2025_2-35-1","t":"“범죄피해자”란 타인의 범죄행위로 피해를 당한 사람과 그 배우자 (사실상의 혼인관계를 포함한다), 직계친족 및 형제자매를 말한다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2022_1-22-1","t":"‘범죄피해자’란 타인의 범죄행위로 피해를 당한 사람과 그 배우자, 직계친족 및 형제자매를 말한다. 다만, 배우자의 경우 사실상의 혼인관계는 제외한다.","y":2022,"e":"경찰 공채"}},{"n":7,"s":0.792,"o":{"i":"PO2026_1-23-1","t":"행정청에 처분을 구하는 신청은 문서로 하여야 한다. 다만, 다른 법령등에 특별한 규정이 있는 경우와 행정청이 미리 다른 방법을 정하여 공시한 경우에는 그러하지 아니하다.","y":2026,"e":"경찰 공채"},"x":{"i":"PO2024_2-20-3","t":"행정청에 처분을 구하는 신청은 구두 또는 문서로 하여야 한다. 다만, 다른 법령등에 특별한 규정이 있는 경우와 행정청이 미리 다른 방법을 정한 경우에는 그러하지 아니하다.","y":2024,"e":"경찰 공채"}},{"n":7,"s":0.75,"o":{"i":"PO2024_2-21-1","t":"정보의 공개를 청구하는 자는 해당 정보를 보유하거나 관리하고 있는 공공기관에 정보공개 청구서를 제출하거나 말로써 정보의 공개를 청구할 수 있다.","y":2024,"e":"경찰 공채"},"x":{"i":"PO2022_1-29-1","t":"정보의 공개를 청구하는 자는 해당 정보를 보유하거나 관리하고 있는 공공기관에 정보공개 청구서를 제출하여 정보의 공개를 청구할 수 있으나, 말로써 정보의 공개를 청구할 수 없다.","y":2022,"e":"경찰 공채"}},{"n":7,"s":0.743,"o":{"i":"PO2025_1-25-4","t":"행정심판위원회는 심판청구가 이유가 있다고 인정하는 경우에도 이를 인용하는 것이 공공복리에 크게 위배된다고 인정하면 그 심판청구를 기각하는 재결을 할 수 있다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2023_2-26-4","t":"행정심판위원회는 심판청구가 이유가 있다고 인정하는 경우에도 이를 인용(認容)하는 것이 공공복리에 크게 위배된다고 인정하면 그 심판청구를 기각하는 재결을 하여야 한다.","y":2023,"e":"경찰 공채"}},{"n":7,"s":0.732,"o":{"i":"PO2026_2-23-3","t":"행정지도의 상대방은 해당 행정지도의 방식‧ 내용 등에 관하여 행정기관에 의견제출을 할 수 있다.","y":2026,"e":"경찰 공채"},"x":{"i":"PO2022_1-30-4","t":"행정지도의 상대방은 해당 행정지도의 방식 내용 등에 관하여 행정기관에 의견제출을 할 수 없다.","y":2022,"e":"경찰 공채"}},{"n":6,"s":0.69,"o":{"i":"PO2023_1-22-2","t":"「경찰관 직무집행법」 제6조 “경찰관은 범죄행위가 목전에 행하여지려고 하고 있다고 인정될 때에는 이를 예방하기 위하여 관계인에게 필요한 경고를 하고, 그 행위로 인하여 사람의 생명·신체에 위해를 끼치거나 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우에는 그 행위를 제지할 수 있다” 규정은 행정상 즉시강제에 해당한다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2026_1-26-1","t":"경찰관은 범죄행위가 목전에 행하여지려고 하고 있다고 인정될 때에는 이를 예방하기 위하여 관계인에게 필요한 경고를 하고, 그 행위로 인하여 사람의 생명‧ 신체에 위해를 끼치거나 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우에는 그 행위를 제지하여야 한다.","y":2026,"e":"경찰 공채"}},{"n":6,"s":0.671,"o":{"i":"PO2022_1-34-1","t":"소속 경찰공무원의 직무집행으로 인하여 발생한 손실보상청구 사건을 심의하기 위하여 경찰청, 해양경찰청, 시 도경찰청 및 지방해양경찰청에 손실보상심의위원회를 설치한다.","y":2022,"e":"경찰 공채"},"x":{"i":"PO2024_1-24-4","t":"소속 경찰공무원의 직무집행으로 인하여 발생한 손실보상청구 사건을 심의하기 위하여 시·도경찰청, 지방해양경찰청, 경찰서 및 해양경찰서에 손실보상심의위원회를 설치한다.","y":2024,"e":"경찰 공채"}},{"n":6,"s":0.659,"o":{"i":"PO2025_1-17-2","t":"경찰청장 및 해양경찰청장은 경찰착용기록장치로 기록한 영상‧ 음성을 저장하고 데이터베이스로 관리하는 영상음성기록정보 관리체계를 구축‧ 운영하여야 한다.","y":2025,"e":"경찰 공채"},"x":{"i":"PO2024_2-27-3","t":"경찰청장, 시·도경찰청장 및 경찰서장은 경찰착용기록장치로 기록한 영상·음성을 저장하고 데이터베이스로 관리하는 영상 음성기록정보 관리체계를 구축·운영하여야 한다.","y":2024,"e":"경찰 공채"}},{"n":6,"s":0.625,"o":{"i":"PO2023_1-21-2","t":"행정청은 처분에 재량이 없는 경우에는 법률에 근거가 있는 경우에 부관을 붙일 수 있다.","y":2023,"e":"경찰 공채"},"x":{"i":"PO2024_2-19-1","t":"행정청은 처분에 재량이 없는 경우에는 법률에 근거가 있더라도 부관을 붙일 수 없다.","y":2024,"e":"경찰 공채"}}];
